ZoneLore.Subzones = {
	-- Durotar: 27 subzones
	[1411] = {
		["bladefist bay"] = {
			name = "Bladefist Bay",
			short = "The waters east of Orgrimmar carry the name of Kargath Bladefist, once chieftain of the Shattered Hand clan.",
			full = "The waters east of Orgrimmar carry the name of Kargath Bladefist, once chieftain of the Shattered Hand clan. Where the road runs past the Dranosh'ar Blockade and down to the sea, the bay opens onto Skull Rock, and across the water the southern coast of Azshara can be seen.\n\nThe port here is built of wood and steel, raised to take ships coming in off the Great Sea. It has earned a rough name among sailors, who call it the Great Sea's midden heap, for the rubble and wreckage the tide washes in without pause. Fishermen still work the pier, casting their lines into water that has carried both cargo and ruin.\n\nKargath Bladefist never ruled here himself. It is enough that the sea remembers him in name, while the docks below fill and empty with whatever the current decides to bring home.",
			source = "https://warcraft.wiki.gg/wiki/Bladefist_Bay",
		},
		["burning blade coven"] = {
			name = "Burning Blade Coven",
			short = "The cave that gives the Burning Blade Coven its name opens in the dusty red mountains along the northern edge of the Valley of Trials, a place meant only as a proving ground for young orcs and trolls.",
			full = "The cave that gives the Burning Blade Coven its name opens in the dusty red mountains along the northern edge of the Valley of Trials, a place meant only as a proving ground for young orcs and trolls. It no longer feels so contained.\n\nImps and lesser demons have spilled from its mouth, and those who look deeper say something worse waits inside: members of the Burning Blade cult, from whom the coven takes its name, led by a warlock called Yarrog Baneshadow.\n\nBefore the demons came, the cave was only stone. A foreman named Thazz'ril once surveyed it for minerals, then left before finishing. His pick still lies inside, abandoned with whatever plans he had for the place.",
			source = "https://warcraft.wiki.gg/wiki/Burning_Blade_Coven",
		},
		["darkspear strand"] = {
			name = "Darkspear Strand",
			short = "The Darkspear Strand is where the Darkspear trolls came ashore after fleeing the Echo Isles.",
			full = "The Darkspear Strand is where the Darkspear trolls came ashore after fleeing the Echo Isles. Just yards from the water sits Sen'jin Village, where the trolls gathered once they reached land, beginning their life on this new shore.",
			source = "https://warcraft.wiki.gg/wiki/Darkspear_Strand",
		},
		["deadeye shore"] = {
			name = "Deadeye Shore",
			short = "The shore takes its name from Kilrogg Deadeye, the orc hero who once led the Bleeding Hollow clan, though nothing of him remains here but the name.",
			full = "The shore takes its name from Kilrogg Deadeye, the orc hero who once led the Bleeding Hollow clan, though nothing of him remains here but the name. What draws the eye is the land itself: a great patch torn from the desert, bare sand shaped like a skull missing its eye.\n\nHere the fisherman Byrok was attacked by the Burning Blade, far from any watchful eye.",
			source = "https://warcraft.wiki.gg/wiki/Deadeye_Shore",
		},
		["den"] = {
			name = "The Den",
			short = "The Den is a cave in the Valley of Trials, sheltering young orcs as they take their first steps beyond childhood.",
			full = "The Den is a cave in the Valley of Trials, sheltering young orcs as they take their first steps beyond childhood. Its walls hold cages, and in them are kept Captured Northwatch Scouts, humans taken and held prisoner within the orc stronghold. Zekhan once came to see the captives himself, standing before the cages to look upon the enemies of his people.",
			source = "https://warcraft.wiki.gg/wiki/The_Den",
		},
		["drygulch ravine"] = {
			name = "Drygulch Ravine",
			short = "The only way into Drygulch Ravine, short of falling into it, is through a narrow cave from Razorwind Canyon. A river feeds down into the gulch, and orcs make their home along it.",
			full = "The only way into Drygulch Ravine, short of falling into it, is through a narrow cave from Razorwind Canyon. A river feeds down into the gulch, and orcs make their home along it.\n\nThree years after the Third War ended, thunder lizards broke loose from Thunder Ridge and threatened the ravine's people. A young orc messenger carried word of the danger to Warchief Thrall in Orgrimmar.\n\nNow the ravine belongs to the Dustwind harpies, who have turned to banditry, falling upon caravans and dragging their plunder up to nests on the high cliffs, where the strongest of them guard the eggs.",
			source = "https://warcraft.wiki.gg/wiki/Drygulch_Ravine",
		},
		["dustwind cave"] = {
			name = "Dustwind Cave",
			short = "In the cliffs of Razorwind Canyon, above Razor Hill, a small cave opens into the rock. Here the Burning Blade brings its newest members, setting them under the watch of the cult's cultists to be trained in its ways.",
			full = "In the cliffs of Razorwind Canyon, above Razor Hill, a small cave opens into the rock. Here the Burning Blade brings its newest members, setting them under the watch of the cult's cultists to be trained in its ways.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Cave",
		},
		["echo isles"] = {
			name = "Echo Isles",
			short = "The Darkspear trolls did not choose the Echo Isles so much as return to them, again and again.",
			full = "The Darkspear trolls did not choose the Echo Isles so much as return to them, again and again.\n\nTheir first homecoming came after Warchief Thrall pulled the tribe from ruin and led them to Kalimdor, where the islands became theirs to settle. That peace lasted only until Kul Tiras warships forced the trolls to flee. Only after their enemy's defeat could the Darkspear come back at all.\n\nThey had barely settled before betrayal came from within. Zalazane, a witch doctor of their own tribe, had somehow learned the secrets of undeath. He turned on his people with zombies and dark minions, seeding the main isle with tainted ju-ju heaps that corrupted the wildlife and warped the flow of magic across Durotar. From his stolen island he sent undead trolls to hex and drag away those who remained free. Attempt after attempt to slay him was fooled and turned false, until the tribe rallied together, aided by the loa Bwonsamdi, and cut him down for good. His remains lie now on the isle called Zalazane's Fall, where trolls still dance in memory of that day.\n\nThe Echo Isles have never once been given to the Darkspear without a price.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Isles",
		},
		["hidden path"] = {
			name = "Hidden Path",
			short = "The Hidden Path winds through the mountains walling off the Valley of Trials, known chiefly to those walking the shaman's road, for it leads to the Spirit Rock where the spirits are met.",
			full = "The Hidden Path winds through the mountains walling off the Valley of Trials, known chiefly to those walking the shaman's road, for it leads to the Spirit Rock where the spirits are met. Its highest point looks out over the whole of the Barrens. Lower down, the path opens toward Ratchet and Orgrimmar, a quiet way through unwatched enough for even the Alliance to slip in unseen.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Path",
		},
		["jaggedswine farm"] = {
			name = "Jaggedswine Farm",
			short = "Jaggedswine Farm sits near the gates of Orgrimmar, its storage house, pig pen, and pond ordinary enough for a working farm of Durotar.",
			full = "Jaggedswine Farm sits near the gates of Orgrimmar, its storage house, pig pen, and pond ordinary enough for a working farm of Durotar. Its swine feed the Horde.\n\nBut the ground remembers being used for something else. When battle came to the gates of Orgrimmar, the farm was seized as a staging point for the assault, held together by Varok Saurfang, Thrall, and Anduin Wrynn.",
			source = "https://warcraft.wiki.gg/wiki/Jaggedswine_Farm",
		},
		["kolkar crag"] = {
			name = "Kolkar Crag",
			short = "Kolkar Crag is a craggy gorge in southern Durotar, named for the Kolkar centaurs who made it their den.",
			full = "Kolkar Crag is a craggy gorge in southern Durotar, named for the Kolkar centaurs who made it their den.\n\nFrom this gorge, the Kolkar, led by Warlord Kolkanis, plotted to strike at Durotar itself: the Valley of Trials, Sen'jin Village, Razor Hill, even the gates of Orgrimmar. When word of the massing orc troops reached Theramore, reinforcements were sent to Northwatch Hold to answer the threat.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Crag",
		},
		["orgrimmar"] = {
			name = "Orgrimmar",
			short = "Warchief Thrall named this place for a friend he could no longer thank in person.",
			full = "Warchief Thrall named this place for a friend he could no longer thank in person. After Mount Hyjal, he led his people into a desert land he called Durotar, in memory of his father, and there raised a city he named Orgrimmar, in honor of Orgrim Doomhammer, the mentor who had shaped him. It rose quickly, walled and towered, part of it carved straight into the mountains that guard its back, built with the hands of goblins, tauren, trolls, and the Mok'Nathal Rexxar, in a Horde no longer bound by the bloodlust of its past but reaching, uncertainly, for peace.\n\nThat peace was tested when fire and earth turned against the city, tearing through its buildings until Thrall had the ruins rebuilt in iron and stone, harder to burn, harder to break. The city that emerged was more martial than the one before, its towers spiked, its banners red and black over every post.\n\nGrommash Hold still stands above it all, the seat from which each warchief has watched over the valleys below.",
			source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
		},
		["razor hill"] = {
			name = "Razor Hill",
			short = "Razor Hill stands at a crossroads in the heart of Durotar, where the road south runs down toward Sen'jin Village and the Valley of Trials, the road north climbs to Orgrimmar, and the western way once crossed the Southfury River toward the Northern Barrens, before the river's spreading waters washed much of it out.",
			full = "Razor Hill stands at a crossroads in the heart of Durotar, where the road south runs down toward Sen'jin Village and the Valley of Trials, the road north climbs to Orgrimmar, and the western way once crossed the Southfury River toward the Northern Barrens, before the river's spreading waters washed much of it out. The barracks that watches over the settlement is the town's most prominent structure, and a burrow lies within its bounds. Orgnil Soulscar keeps watch here still, tracking the movements of the Burning Blade cultists who trouble the region.\n\nNot long after the Third War, when Razor Hill was nothing more than a bare rise of ground, the forces of Kul Tiras proposed a summit there with Thrall. It was a trap, meant to kill him under the guise of parley. Rexxar, suspecting as much, refused to let the warchief walk into it, and went in his place. The assassins who lay in wait found Rexxar instead, and he cut them down.",
			source = "https://warcraft.wiki.gg/wiki/Razor_Hill",
		},
		["razor hill barracks"] = {
			name = "Razor Hill Barracks",
			short = "The barracks stands as the largest building in Razor Hill, its size alone marking the settlement as one of the true strongholds of Durotar, second only to Orgrimmar itself.",
			full = "The barracks stands as the largest building in Razor Hill, its size alone marking the settlement as one of the true strongholds of Durotar, second only to Orgrimmar itself.",
			source = "https://warcraft.wiki.gg/wiki/Razor_Hill_Barracks",
		},
		["razormane grounds"] = {
			name = "Razormane Grounds",
			short = "Bones of dead animals, stripped clean, litter the Razormane Grounds, and brambles tear out of the red mountains above.",
			full = "Bones of dead animals, stripped clean, litter the Razormane Grounds, and brambles tear out of the red mountains above. The orcs fight here to keep the Razormane quilboar from pushing out of the Barrens and into Durotar, but for every quilboar cut down, two more come out of the thickets. The encampment is led by Geolord Mottle, with Captain Flat Tusk commanding its Battleguard, and between them the line never moves.",
			source = "https://warcraft.wiki.gg/wiki/Razormane_Grounds",
		},
		["razorwind canyon"] = {
			name = "Razorwind Canyon",
			short = "The road between Razor Hill and Orgrimmar cuts through the Barrens, but the land to either side breaks into a canyon, split east and west, where the Dustwind harpies have made their nests.",
			full = "The road between Razor Hill and Orgrimmar cuts through the Barrens, but the land to either side breaks into a canyon, split east and west, where the Dustwind harpies have made their nests.\n\nThey are numerous here, thick among the rocks and ledges, and do not tolerate trespassers. Anyone who wanders off the road and down into their ground finds the air suddenly full of screeching wings, and more than one careless traveler has been dragged down before seeing where the attack came from.\n\nIn the eastern reaches a cave opens into Drygulch Ravine. The western side presses close against Tor'kren Farm and the Southfury Watershed, a reminder of what waits for anyone who strays from the road.",
			source = "https://warcraft.wiki.gg/wiki/Razorwind_Canyon",
		},
		["rocktusk farm"] = {
			name = "Rocktusk Farm",
			short = "Rocktusk Farm sits against the Dranosh'ar Blockade along the western road from Orgrimmar, its pig herds feeding the Horde under the watch of nearby soldiers.",
			full = "Rocktusk Farm sits against the Dranosh'ar Blockade along the western road from Orgrimmar, its pig herds feeding the Horde under the watch of nearby soldiers. During the Elemental Unrest, Twilight's Hammer cultists were seen lurking near its pens.",
			source = "https://warcraft.wiki.gg/wiki/Rocktusk_Farm",
		},
		["scuttle coast"] = {
			name = "Scuttle Coast",
			short = "The rocks along Scuttle Coast are still hung with wreckage, the ruin of Admiral Daelin Proudmoore's fleet, driven ashore in the battles fought here between Kul Tiras and the orcs.",
			full = "The rocks along Scuttle Coast are still hung with wreckage, the ruin of Admiral Daelin Proudmoore's fleet, driven ashore in the battles fought here between Kul Tiras and the orcs. What was a war fleet is now a graveyard of broken hulls.\n\nThe orcs comb the wrecks for gnome-built devices and stores, salvaging what the sea has not yet claimed. But the tide has brought in something else: angry sea elementals, prowling the beach and striking at anything that nears.",
			source = "https://warcraft.wiki.gg/wiki/Scuttle_Coast",
		},
		["senjin village"] = {
			name = "Sen'jin Village",
			short = "Sen'jin Village sits on the southern coast of Durotar, a scatter of small huts and one larger longhouse gathered above a dock that runs into the sea.",
			full = "Sen'jin Village sits on the southern coast of Durotar, a scatter of small huts and one larger longhouse gathered above a dock that runs into the sea. It is a quiet place beside a crossroads, one path bending north toward Razor Hill, the other winding southeast down to the village itself.\n\nThe Darkspear trolls who hold it are mostly herbalists and alchemists, gathering what grows along the coast and turning it into potions over the huts' low fires.\n\nIn the days of the Darkspear Rebellion, Sen'jin became once more the tribe's rallying point, before the fight moved on and Razor Hill, retaken, became the rebellion's new heart in its place.",
			source = "https://warcraft.wiki.gg/wiki/Sen'jin_Village",
		},
		["shrine of the dormant flame"] = {
			name = "Shrine of the Dormant Flame",
			short = "The Shrine of the Dormant Flame crowns the tallest peak of the region, reached only by a hidden path that spirals up from beside the Southfury River, northwest of the Valley of Trials.",
			full = "The Shrine of the Dormant Flame crowns the tallest peak of the region, reached only by a hidden path that spirals up from beside the Southfury River, northwest of the Valley of Trials. From its top the land opens out below, though the drop at the edge is not one to test.\n\nThe shrine is holy to every shaman of the Horde, for it was here that the young among them learned to master fire. A shaman seeking to prove such control would defeat a fire elemental and carry back its ember to light the brazier at the summit, the flame a sign that the trial was won.\n\nTelf Joolam kept that shrine and once guided aspiring shaman through the trial. Now the brazier stands cold, and Telf walks the mountaintop alone.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Dormant_Flame",
		},
		["skull rock"] = {
			name = "Skull Rock",
			short = "Skull Rock, a hollow in northeastern Durotar shaped like its name, shelters a holdout of the Burning Blade cult. The orc warlock Gazz'uz leads the cultists within.",
			full = "Skull Rock, a hollow in northeastern Durotar shaped like its name, shelters a holdout of the Burning Blade cult. The orc warlock Gazz'uz leads the cultists within. Kor'kron Deathbringers once stood watch at the entrance, guarding against what waited inside.",
			source = "https://warcraft.wiki.gg/wiki/Skull_Rock",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape.",
			full = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape. It marks the boundary between Ashenvale and Azshara to the north, and further south divides the Northern Barrens from Durotar, before finally pouring itself into the Great Sea in one last waterfall near the goblin port of Ratchet.\n\nThree bridges cross it: one linking Azshara to Ashenvale, one carrying travelers into Orgrimmar itself, and one joining Durotar to the Northern Barrens. Just north of the western bridge into the orc capital, there is a single point where four lands touch at once, the water running between them all.\n\nAt the river's mouth, a goblin named Horton Hornblower keeps a riverboat tied at his dock, ferrying those who need passage upstream toward the Barrens.\n\nThe river still runs strong enough to water the fields along its banks, but its water can no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["spirit rock"] = {
			name = "Spirit Rock",
			short = "Above the Valley of Trials, reached by the Hidden Path, stands Spirit Rock, sacred to the shaman of the Horde. Aspiring shaman once drank sapta beside the stone, sitting with the earth until it answered them.",
			full = "Above the Valley of Trials, reached by the Hidden Path, stands Spirit Rock, sacred to the shaman of the Horde. Aspiring shaman once drank sapta beside the stone, sitting with the earth until it answered them.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rock",
		},
		["thunder ridge"] = {
			name = "Thunder Ridge",
			short = "Thunder Ridge lies in northwestern Durotar, its gorge now standing in still water.",
			full = "Thunder Ridge lies in northwestern Durotar, its gorge now standing in still water. Once a forest of ancient trees grew here, and the thunder lizards that made their home among them lived in harmony with the wood, watched over by the spirit Owa'nohe.\n\nThat harmony broke after Durotar's founding. Rexxar, traveling to the ridge for shimmerweed on Drek'Thar's errand, noticed the lizards turning strange and violent. He and the old farseer found the cause: a human lumber camp, stripping the forest bare and driving the beasts to madness. To stop worse from coming, they put the lizards down themselves, and Rexxar carried their eggs back to Orgrimmar for Drek'Thar to study.\n\nThe felling did not stop there. Years later the ridge's forest was cut away entirely, scattering hundreds of thunder lizards loose. Jaina Proudmoore, sent by Thrall to learn why, found the trees had been felled by demonic magic, the work of the Burning Blade seeking to unmake the region's peace.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Ridge",
		},
		["tiragarde keep"] = {
			name = "Tiragarde Keep",
			short = "Tiragarde Keep rose from the crimson rock of the Scuttle Coast at the order of Grand Admiral Daelin Proudmoore, who could not accept the peace his daughter Jaina had struck with the Horde.",
			full = "Tiragarde Keep rose from the crimson rock of the Scuttle Coast at the order of Grand Admiral Daelin Proudmoore, who could not accept the peace his daughter Jaina had struck with the Horde. He brought his fleet from Kul Tiras and threw it against Durotar's shores, raising the keep in haste as a foothold for his private war. It did him no good. The orcs broke his assault, and Tiragarde Keep fell to ruin.\n\nDaelin himself died soon after, killed when the Horde struck Theramore. But before sailing from Kul Tiras, the Admiral had written orders for such a day. When no word came from his fleet, those orders found Lieutenant Benedict, who marched a reserve force to the ruins and took them back, determined to carry on a dead man's crusade. His men held the keep, a white and gleaming wound in the red stone, and young Horde warriors sent to test it always failed to root the humans out.\n\nNow Benedict's soldiers lie dead across the ground, all but one man still watching from a beached ship's crow's nest. Northwatch Hold has sent fresh soldiers to hold the walls in their place.",
			source = "https://warcraft.wiki.gg/wiki/Tiragarde_Keep",
		},
		["torkren farm"] = {
			name = "Tor'kren Farm",
			short = "Tor'kren Farm sits north of the Southfury Watershed, a modest holding that has never turned the profit its neighbors have.",
			full = "Tor'kren Farm sits north of the Southfury Watershed, a modest holding that has never turned the profit its neighbors have. Misha Tor'kren once ran it with her son Kron, until he went hunting crocolisks along the Southfury River and did not return, killed by the very beasts he sought.\n\nMisha stayed on alone. She still grieves him, and wishes for a necklace strung from crocolisk teeth, something to hold in his memory.",
			source = "https://warcraft.wiki.gg/wiki/Tor'kren_Farm",
		},
		["valley of trials"] = {
			name = "Valley of Trials",
			short = "Every young orc who takes up a blade or a totem first proves it here, in this walled valley of southern Durotar, where the sun bakes the sand hard and shows no mercy to those who fail.",
			full = "Every young orc who takes up a blade or a totem first proves it here, in this walled valley of southern Durotar, where the sun bakes the sand hard and shows no mercy to those who fail. Those who die in the attempt are left where they fall.\n\nAt the valley's heart stands the Den, a cave hollowed from the cliff and fitted with what comforts the desert allows. Here the recruiters and trainers make their home, and here the young return to report what they have overcome before they are judged ready for the world beyond the walls.\n\nBut the valley is no longer as safe as its purpose demands. In the caves to the north, once empty and natural, demons of the Burning Blade have taken root. They are weak things individually, but they have begun creeping south into the valley proper. Their presence lends weight to old rumors that the Shadow Council has found a foothold somewhere in the region.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
	},
	-- Mulgore: 18 subzones
	[1412] = {
		["baeldun digsite"] = {
			name = "Bael'dun Digsite",
			short = "Dwarves from Bael Modan cut a quarry into the western edge of Mulgore, against the warnings of Baine Bloodhoof, who saw it as an affront to the Earth Mother.",
			full = "Dwarves from Bael Modan cut a quarry into the western edge of Mulgore, against the warnings of Baine Bloodhoof, who saw it as an affront to the Earth Mother. When talk failed, the Bloodhoof tribe seized the dwarves' pickaxes and broke them, hoping to stop the digging without bloodshed.\n\nThe dwarves refused to listen and kept digging. Their reckless excavation roused the spirits of the land, and the diggers were killed for their persistence. The quarry still scars the mountainside.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Digsite",
		},
		["bloodhoof village"] = {
			name = "Bloodhoof Village",
			short = "Bloodhoof Village sits at the waters of Stonebull Lake in the central plains of Mulgore, named for the tribe that calls it home.",
			full = "Bloodhoof Village sits at the waters of Stonebull Lake in the central plains of Mulgore, named for the tribe that calls it home. Here the wild kodo of the plains are broken and trained, and their broad backs given over to the tauren as mounts, the beasts led in from the grasslands to be tamed at the village's edge.\n\nBaine Bloodhoof watched over the village before he went north to Thunder Bluff to take up his father's place as High Chieftain of the tauren tribes. While he tended to the daily needs of Bloodhoof's people, the spirits were tended by Zarlman Two-Moons, who took up the burden of guiding young tauren in the ways of their ancestors.\n\nThe village has not gone untested. When it came under attack, it was a tauren champion who turned the assault back, holding the settlement against those who would have seen it burn.",
			source = "https://warcraft.wiki.gg/wiki/Bloodhoof_Village",
		},
		["brambleblade ravine"] = {
			name = "Brambleblade Ravine",
			short = "Brambleblade Ravine cuts into the northeastern edge of Red Cloud Mesa, home to the Bristleback quilboars. At the back of the ravine stands the hut of their chief, Sharptusk Thornmantle.",
			full = "Brambleblade Ravine cuts into the northeastern edge of Red Cloud Mesa, home to the Bristleback quilboars. At the back of the ravine stands the hut of their chief, Sharptusk Thornmantle. Early tauren struck into the ravine to disrupt the tribe's raids, even attacking Thornmantle himself, while many Bristlebacks pushed outward to seize new ground from the tauren at Thornsnarl.",
			source = "https://warcraft.wiki.gg/wiki/Brambleblade_Ravine",
		},
		["camp narache"] = {
			name = "Camp Narache",
			short = "Camp Narache sits at the northern edge of the Red Cloud Mesa, tents of the Hawkwind Tribe gathered around a center where its teachers stand in a circle, paying respect to the fallen Greatmother Hawkwind.",
			full = "Camp Narache sits at the northern edge of the Red Cloud Mesa, tents of the Hawkwind Tribe gathered around a center where its teachers stand in a circle, paying respect to the fallen Greatmother Hawkwind. The main tent shelters wounded braves; nearby stand a spirit lounge, a bakery, an armory, and a trader's tent.\n\nWhen Muln and his shaman could do nothing but retreat, it was Shotoa who took care of it. The wounded still resting in the main tent are proof the cost was recent, not a story worn smooth by years.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Narache",
		},
		["golden plains"] = {
			name = "Golden Plains",
			short = "The Golden Plains open in a great basin below Thunder Bluff, treasured ground in the tauren homeland. Herds of kodo move across the grass, and tauren hunters favor this basin above nearly any other.",
			full = "The Golden Plains open in a great basin below Thunder Bluff, treasured ground in the tauren homeland. Herds of kodo move across the grass, and tauren hunters favor this basin above nearly any other.\n\nSomewhere in that shifting green sea, it is said, the famous Arra'chea still dwells.",
			source = "https://warcraft.wiki.gg/wiki/Golden_Plains",
		},
		["kodo rock"] = {
			name = "Kodo Rock",
			short = "Kodo Rock stands a short way out from Camp Narache, on the line toward Brambleblade Ravine.",
			full = "Kodo Rock stands a short way out from Camp Narache, on the line toward Brambleblade Ravine. It is easy to miss unless one is already close, hidden until the last few steps, marked only by the bare patch of dirt around its base.\n\nYoung tauren shaman have come here in their first days of learning, drawn by the rock itself rather than by anything built around it.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Rock",
		},
		["palemane rock"] = {
			name = "Palemane Rock",
			short = "Palemane Rock is a cave cut deep into the mountainside of western Mulgore, home to the gnolls of the Palemane tribe.",
			full = "Palemane Rock is a cave cut deep into the mountainside of western Mulgore, home to the gnolls of the Palemane tribe. They keep to both the camp outside and the tunnels within, and they are aggressive, falling upon anyone who strays too near their ground.",
			source = "https://warcraft.wiki.gg/wiki/Palemane_Rock",
		},
		["ravaged caravan"] = {
			name = "Ravaged Caravan",
			short = "The Ravaged Caravan lies broken on the northeastern shore of Stonebull Lake, a mound of splintered wagons still breathing black smoke over Mulgore.",
			full = "The Ravaged Caravan lies broken on the northeastern shore of Stonebull Lake, a mound of splintered wagons still breathing black smoke over Mulgore.\n\nIt was bound for Supervisor Fizsprocket's mining operation when the tauren, weary of watching the Venture Company move through their land, struck it down. What remains is wreckage, and the goblins who survived still hold the smoldering mound, guarding their ruined cargo rather than let it go.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Red Cloud Mesa",
			short = "Red Cloud Mesa was once a place of quiet beauty, its grasses rolling out beneath open sky. It does not look that way now.",
			full = "Red Cloud Mesa was once a place of quiet beauty, its grasses rolling out beneath open sky. It does not look that way now.\n\nThe Bristleback quilboar came up out of Brambleblade Ravine in the northeast and would not stop coming. Wherever they took ground, thorned vines followed, twisting over the earth as if the land itself were being strangled. The tauren huts that once stood scattered across the mesa are burned husks now, and the well that gave the area its water lies broken and dry. What was pasture became a warzone, tauren braves holding what ground they could against the advancing quilboar line.\n\nThe worst of it sits at the southwest corner, where the old pass leading out of the mesa was buried by a landslide. The quilboar's leader, Thornmantle, claimed the ruin for himself and built his hideout atop the wreckage, turning the one road out of Red Cloud Mesa into a stronghold for the creatures who cut it off.\n\nCamp Narache, in the mesa's northwest corner, is the last ground here that still holds safely against the quilboar tide.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Red Rocks",
			short = "Red Rocks rises in the sandstone country beyond Thunder Bluff, its color the deep rust of old blood and older earth.",
			full = "Red Rocks rises in the sandstone country beyond Thunder Bluff, its color the deep rust of old blood and older earth. It is not a place of dying but of crossing over, where the tauren send their honored dead to the Earth Mother and the Sky Father on cleansing flame. Not every tauren earns rest here. Only those who helped raise Thunder Bluff from the plains, or gave their lives defending their tribes and chieftains, are carried to these rocks. It is also where the young come to listen: braves seeking passage into adulthood climb here to hear the wisdom of their ancestors carried on the wind, so that the same ground holds both a people's first steps and its last.\n\nCairne Bloodhoof, high chieftain of the tauren, was cremated at Red Rocks, his ashes given to the flame that has taken so many of his people's honored dead before him.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Rolling Plains",
			short = "The Rolling Plains stretch southward from Bloodhoof Village toward the Barrens, open grass country roamed by wolves, kodo, tallstriders, and cougars.",
			full = "The Rolling Plains stretch southward from Bloodhoof Village toward the Barrens, open grass country roamed by wolves, kodo, tallstriders, and cougars.\n\nIt is the one place in Mulgore where centaur outriders still manage to slip past the tauren's borders. In the eastern reaches, a nest of Windfury harpies has taken hold as well.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["stonebull lake"] = {
			name = "Stonebull Lake",
			short = "Stonebull Lake curls in a long horseshoe around Bloodhoof Village, holding it close on three sides. The water runs cool and full of fish, and lines are cast into it through long, quiet hours.",
			full = "Stonebull Lake curls in a long horseshoe around Bloodhoof Village, holding it close on three sides. The water runs cool and full of fish, and lines are cast into it through long, quiet hours. Where the lake pinches narrowest, a bridge crosses over, carrying the road that links Bloodhoof Village to Thunder Bluff.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunder bluff"] = {
			name = "Thunder Bluff",
			short = "Thunder Bluff rises on four windswept mesas above the grasslands of Mulgore, reached only by rope-and-wood elevators of tauren make, or by long bridges strung between the rises.",
			full = "Thunder Bluff rises on four windswept mesas above the grasslands of Mulgore, reached only by rope-and-wood elevators of tauren make, or by long bridges strung between the rises. Tents, longhouses, and painted totems crown each summit. For generations the tauren wandered as a nomadic people, harried without rest by the centaur who ranged across Kalimdor. It was Cairne Bloodhoof, chieftain of the Bloodhoof tribe, who ended that exile. When Warchief Thrall and his New Horde came to Mulgore during the Third War, their strength joined Cairne's own and together they broke the centaur and won the grasslands for the tauren at last. Upon the mesas Cairne raised a refuge open to every scattered tribe, and in time those tribes bent to his rule as one people, disagreeing sometimes on the path ahead but never on his wisdom to lead them.\n\nThe bluffs still bear the weight of that founding in their rises and bridges, in the tents of tribes gathered under one chieftain's roof.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
		},
		["thunderhorn water well"] = {
			name = "Thunderhorn Water Well",
			short = "The well stands in the grassland along the north road between Thunder Bluff and Bloodhoof Village. The Venture Company once seized it to choke off the tauren's water, but the tauren drove them out and reclaimed it.",
			full = "The well stands in the grassland along the north road between Thunder Bluff and Bloodhoof Village. The Venture Company once seized it to choke off the tauren's water, but the tauren drove them out and reclaimed it.\n\nLater a disaster struck the well. The shaman Muln Earthfury and the Earthen Ring pleaded with the elements to set it right, but got no answer. It was a stranger named Shotoa who ended it, not by asking the elements but by forcing them to obey.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Venture Co. Mine",
			short = "The Venture Company had been refused mining rights in Mulgore outright, and came anyway, cutting into the eastern cliffs until the mine grew three ways in: the main gate where Supervisor Fizsprocket kept his post, a cliffside cut, and a small lumber camp set up alongside it.",
			full = "The Venture Company had been refused mining rights in Mulgore outright, and came anyway, cutting into the eastern cliffs until the mine grew three ways in: the main gate where Supervisor Fizsprocket kept his post, a cliffside cut, and a small lumber camp set up alongside it.\n\nThe tauren answered the only way left to them. When a supply caravan came up under guard along the northern shore of Stonebull Lake, the Outrunners fell on it and burned it where it stood, certain the fire would leave the goblins nothing worth taking. They left the wreckage behind, satisfied. Later they returned to find Venture Co. salvagers picking through the ashes, hauling away what the flames had failed to ruin.\n\nIt was that discovery, more than the mine itself, that turned the cliffs into a battleground the tauren would not let stand.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Wildmane Water Well",
			short = "The Wildmane Water Well, north of Thunder Bluff, is the northernmost of the tauren's sacred wells. The Venture Company once seized it to control the water, but the tauren drove them out and reclaimed it.",
			full = "The Wildmane Water Well, north of Thunder Bluff, is the northernmost of the tauren's sacred wells. The Venture Company once seized it to control the water, but the tauren drove them out and reclaimed it. Now the exiled Grimtotem tribe taints its waters, spite against those who cast them out.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Windfury Ridge",
			short = "Windfury Ridge takes its name from the harpies nesting in its hills, fierce creatures that swoop upon any who wander too near. Wild cougars and wolves also stalk its slopes.",
			full = "Windfury Ridge takes its name from the harpies nesting in its hills, fierce creatures that swoop upon any who wander too near. Wild cougars and wolves also stalk its slopes.\n\nThe harpies are prized for their brilliant feathers, which the tauren of Thunder Bluff hunt them for, to adorn their weddings and feasts.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Winterhoof Water Well",
			short = "The Winterhoof Water Well lies at the edge of the Rolling Plains in southern Mulgore.",
			full = "The Winterhoof Water Well lies at the edge of the Rolling Plains in southern Mulgore. Years after the Third War, the Venture Company seized it and poisoned the water to choke off the supply, until tauren fighters drove them out. Mull Thunderhorn then raised a totem over the well, and its power cleansed the waters once more.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- The Barrens: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Agama'gor lies north of the road running west from Camp Taurajo, a settlement of Bristleback quilboar.",
			full = "Agama'gor lies north of the road running west from Camp Taurajo, a settlement of Bristleback quilboar. The tribe drops blood shards in its endless raiding, prized tokens the exile Mangletooth, cast out from his own kind, will bless in exchange for those willing to gather them.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "Before the dwarves came, the land around Bael Modan belonged to the Stonespire tauren, who held it as holy ground.",
			full = "Before the dwarves came, the land around Bael Modan belonged to the Stonespire tauren, who held it as holy ground. When the dwarves arrived to dig beneath the surface, seeking whatever the old titan complex buried there still held, they carved into the earth with explosives. The blasts tore apart the Stonespire village and drove most of the tribe from their ancestral home or killed them where they stood. What remains of that village now lies torn apart by the digging machines that took its place.\n\nGann Stonespire tried to end it with words first, walking the roads near Bael Modan seeking a diplomatic settlement, and failed. Vengeance followed instead. He rallied an angry mob of Horde civilians against the dwarven digsite and was wounded in the fighting by Marley Twinbraid, General Twinbraid's son. Dying, Gann helped turn a dwarven artillery shell back against the fortress itself, and the explosion brought it down, taking Marley's flying machine with it.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Bael'dun Keep",
			short = "Bael'dun Keep stands over its digsite in the southern Barrens, held by the dwarves of General Twinbraid.",
			full = "Bael'dun Keep stands over its digsite in the southern Barrens, held by the dwarves of General Twinbraid.\n\nGann Stonespire turned against it out of grief -- his tribe lost, and the dead of Camp Taurajo still weighing on him. With help from a goblin named Weezil Slipshadow, he moved against Twinbraid's dwarves.\n\nThe end came with a single dwarven artillery shell, rigged and fired into the heart of the keep. The blast tore Bael'dun apart and killed the dwarves inside, though a few survivors were pulled alive from the rubble afterward.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Blackthorn Ridge",
			short = "North of Razorfen Kraul, thorns close over a valley held by Razormane quilboar. On the ridge that gives the place its name lives the orc shaman Brine.",
			full = "North of Razorfen Kraul, thorns close over a valley held by Razormane quilboar. On the ridge that gives the place its name lives the orc shaman Brine. Below her camp lies a pool whose water runs clear and pure, untouched by the thorns around it.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Boulder Lode Mine",
			short = "The tunnels of Boulder Lode Mine still show orcish stonework and tattered Horde banners, though no orc holds the place now. The Venture Company took it over, and Boss Copperplug runs the digging under its banner.",
			full = "The tunnels of Boulder Lode Mine still show orcish stonework and tattered Horde banners, though no orc holds the place now. The Venture Company took it over, and Boss Copperplug runs the digging under its banner.\n\nWord once reached Wharfmaster Dizzywig that one of Copperplug's miners had turned up a giant emerald somewhere in the shafts below. Whether it was ever pulled free of the rock, no one here says.\n\nCopperplug also once kept a samophlange manual among his belongings, its pages scattered to others working the mine alongside him, each holding a piece of the whole.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Bramblescar",
			short = "The Razormane quilboar hold Bramblescar, warring with the Bristleback tribe across the road at Agama'gor. Neither needs more reason than the other's presence.",
			full = "The Razormane quilboar hold Bramblescar, warring with the Bristleback tribe across the road at Agama'gor. Neither needs more reason than the other's presence. The Razormane are no kinder to strangers who wander too near their lair.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Camp Taurajo",
			short = "Camp Taurajo stood in the Southern Barrens, near the pass into Mulgore, a small tauren outpost where travelers rested before the road home.",
			full = "Camp Taurajo stood in the Southern Barrens, near the pass into Mulgore, a small tauren outpost where travelers rested before the road home.\n\nThe Alliance came down from Northwatch Hold on false word that the tauren meant to strike first, and on that lie they burned the camp to the ground. It was no battle, only a massacre, an outpost of herders and travelers put to the torch.\n\nWhat remains is ash, and a name the tauren do not say lightly.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "Crossroads",
			short = "The Crossroads takes its name plainly from what it is: the meeting point of the north-south road out of the Gold Road and the long east-west road that runs from Ratchet all the way to the Stonetalon Mountains.",
			full = "The Crossroads takes its name plainly from what it is: the meeting point of the north-south road out of the Gold Road and the long east-west road that runs from Ratchet all the way to the Stonetalon Mountains. It sits at the center of the Northern Barrens, and its position at that crossing has made it the busiest Horde settlement in the region, larger and louder than its few lodgings would suggest. Traders set up along the road and shout over one another to be heard, hawking wares to everyone passing through.\n\nJust outside the town lies a burial ground where the Horde comes to pay respects to its dead, and it has become the place where fallen Horde members are laid to rest and rise again, much as Sentinel Hill serves the Alliance.\n\nThe town has not always kept its peace undisturbed. Raptors once struck the guard tower and made off with a shipment of silver meant as payroll for the Crossroads' own guards, forcing Horde soldiers to hunt the beasts down and recover the stolen coin.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Dreadmist Den",
			short = "Dreadmist Peak wears a shroud of dark red mist that never lifts, and within it the Burning Blade cult keeps its den, cloaked in eternal twilight.",
			full = "Dreadmist Peak wears a shroud of dark red mist that never lifts, and within it the Burning Blade cult keeps its den, cloaked in eternal twilight. Here the cultists guard the Demon Seed, an artifact they hold beyond price.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Dreadmist Peak",
			short = "Dreadmist Peak wears a fog of red mist, residuum of an ancient demonic curse. At its summit, Burning Blade cultists have made their home in the Dreadmist Den, guarding the Demon Seed within.",
			full = "Dreadmist Peak wears a fog of red mist, residuum of an ancient demonic curse. At its summit, Burning Blade cultists have made their home in the Dreadmist Den, guarding the Demon Seed within. The taint lingers on, marking the peak as touched by something never meant to fade.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Dry Hills",
			short = "The Dry Hills climb from the Barrens toward the Stonetalon Mountains, greener than their name suggests. Witchwing harpies have claimed the slopes, raiding the caravans that try to cross the northern Gold Road below.",
			full = "The Dry Hills climb from the Barrens toward the Stonetalon Mountains, greener than their name suggests. Witchwing harpies have claimed the slopes, raiding the caravans that try to cross the northern Gold Road below.\n\nWhen the Primalists turned their attack on the region, elementals swept through the hills, and their power did not simply pass through. It settled into the Witchwing harpies themselves, so that those who nest here now carry something of the elementals within them.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Far Watch Post",
			short = "At the bridge between Durotar and the Northern Barrens, a watch tower rises beside an orc burrow and a line of catapults, its garrison bound to a wolf pen to the south where peons tend the mounts.",
			full = "At the bridge between Durotar and the Northern Barrens, a watch tower rises beside an orc burrow and a line of catapults, its garrison bound to a wolf pen to the south where peons tend the mounts. It is an unlovely post, but a necessary one, guarding the caravans that feed Durotar and the border against Alliance and quilboar alike.\n\nThat watch was broken once, when the Burning Legion took the post. Nathrezim moved among the garrison, binding captured orcs to their will, killing some where they stood while others were pulled free by defenders who fought back in to reclaim their own.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Field of Giants",
			short = "The Field of Giants stretches across the southern Barrens, a wide grass country between Camp Taurajo and the marshes to the south.",
			full = "The Field of Giants stretches across the southern Barrens, a wide grass country between Camp Taurajo and the marshes to the south. Thunder lizards and kodo move across it in great herds, grazing where the Gold Road runs thin and unwatched. The old towers along that southern stretch stand empty now, their garrisons long gone, leaving the road to whatever crosses it.\n\nThe Horde has not entirely given up the land. The shaman Brine keeps to a ridge on the southern edge of the Field, alone among the herds. Not far off, Gann Stonespire nurses an old grievance -- his tribe was driven from its village when dwarves came digging for titan ruins in the ground beside it, ground that is now called Bael Modan.\n\nMore troubling to those who watch the plains is what has begun rising from beneath them: silithid hives, the northernmost known in all Kalimdor.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Forgotten Pools",
			short = "The Forgotten Pools lie north off the western road out of the Crossroads, the northernmost of the oases that break the dry expanse of the Northern Barrens.",
			full = "The Forgotten Pools lie north off the western road out of the Crossroads, the northernmost of the oases that break the dry expanse of the Northern Barrens. Turtles move slow through the water, and Laden Mushrooms grow along the shore, found nowhere else in the Barrens.\n\nKolkar centaurs range the oasis alongside its wildlife, holding it as their own, while Ta'jari and Telar Highstrider have kept watch here, weighing how great a threat the centaur presence has become.\n\nWhen the Burning Legion swept through the land, the pools did not escape. The demons took the oasis entirely, and everything that had lived there before them, centaur and creature alike, was put to death.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Fray Island",
			short = "Fray Island sits small and dry off the eastern shore of the Northern Barrens, its ground honeycombed by a sewer that runs its length, home now to nothing gentler than the fish lurking in its flooded dark.",
			full = "Fray Island sits small and dry off the eastern shore of the Northern Barrens, its ground honeycombed by a sewer that runs its length, home now to nothing gentler than the fish lurking in its flooded dark.\n\nIt was not always a haunt for outlaws. Once it served as a training ground for warriors of every race and creed, led by Klannoc Macleod, shaping fighters regardless of what banner they would later carry.\n\nThat purpose is gone now. The island belongs to Cap'n Garvey, who leads his pirates from its shores, while Alicia Cuthbert holds command of his old flagship, the Maiden's Dagger. What was built to train warriors for any cause now shelters those who fight for none but their captain's profit.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Gold Road",
			short = "The Gold Road stretches between Mor'shan Rampart and the Great Divide, its southern reach known simply as the Southern Gold Road once the bridge is crossed.",
			full = "The Gold Road stretches between Mor'shan Rampart and the Great Divide, its southern reach known simply as the Southern Gold Road once the bridge is crossed.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Grol'dom Farm",
			short = "Grol'dom Farm is one of the pig farms raised in the orcish lands since Orgrimmar's founding, its pens worked to keep the city fed. It has never known quiet: Razormane Pillagers press against its fences constantly.",
			full = "Grol'dom Farm is one of the pig farms raised in the orcish lands since Orgrimmar's founding, its pens worked to keep the city fed. It has never known quiet: Razormane Pillagers press against its fences constantly.\n\nHere stands the Humble Monument, raised to Olgra, wife of Mankrik. It is a small stone among the pig runs, but it is why travelers remember Mankrik's name before they ever speak to him.\n\nWhen the Burning Legion's invasion swept the land, the farm was left in turmoil, its swine hunted down by imps.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Lushwater Oasis",
			short = "Lushwater Oasis breaks the dust of the Northern Barrens with a stand of green and open water, one of three such oases in the region.",
			full = "Lushwater Oasis breaks the dust of the Northern Barrens with a stand of green and open water, one of three such oases in the region. It sits on the edge of the Great Divide, and beasts come to its pools to drink, drawing Kolkar centaur who stalk the treeline waiting for them.\n\nBeneath the oasis lies the entrance to the Wailing Caverns, a place spoken of as accursed, and fishers still work these waters for deviate fish in its shadow.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "Merchant Coast",
			short = "The Merchant Coast takes its name from the trade that runs through Ratchet, whose goblins deal in coin without much caring whose hands it passes through.",
			full = "The Merchant Coast takes its name from the trade that runs through Ratchet, whose goblins deal in coin without much caring whose hands it passes through.\n\nFor years the southern coast belonged to the Southsea Freebooters. One of them, Baron Longshore, stole a haul of cargo from Gazlowe and buried it rather than return it. Northwatch Hold later captured Longshore, and with him went the secret of where the cargo lay.\n\nGazlowe found little comfort in this. Northwatch's presence has only interrupted his trade with the Horde, leaving his fortune buried somewhere along the coast.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Mor'shan Base Camp",
			short = "Mor'shan Base Camp stands south of the Ashenvale border, near the Mor'shan Rampart.",
			full = "Mor'shan Base Camp stands south of the Ashenvale border, near the Mor'shan Rampart. It is the base of the Warsong Outriders, and from here the Horde's path into Warsong Gulch begins, tying the outpost to the long struggle with the Alliance over that ground.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Mor'shan Rampart",
			short = "The Mor'shan Rampart stands where the Gold Road meets the northern edge of the Barrens, raised against the Alliance push out of Ashenvale.",
			full = "The Mor'shan Rampart stands where the Gold Road meets the northern edge of the Barrens, raised against the Alliance push out of Ashenvale. It serves now as a launching point for raids on the night elven town of Astranaar to the north.\n\nAshenvale skirmishers charge the rampart, bowmen loose arrows from behind them, and the Mor'shan defenders answer in kind, neither side driving the other off for good.\n\nDuring the War of the Thorns, two Horde rogues killed the elves holding the rampart outright. It has changed hands between the Alliance and the defenders ever since.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Raptor Grounds",
			short = "The valley south in the Barrens, west of Northwatch Hold, belongs to the Sunscale raptors, and they are not like other raptors.",
			full = "The valley south in the Barrens, west of Northwatch Hold, belongs to the Sunscale raptors, and they are not like other raptors. Crude huts rise among the rocks, and cruder tools lie scattered about, proof of an intelligence no one expects behind a raptor's eyes. Drawn to anything that glints, the Sunscale steal freely from nearby Horde settlements.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Ratchet",
			short = "Ratchet sits on the eastern shore of the Barrens, a harbor built by nobody's design and everybody's leftovers.",
			full = "Ratchet sits on the eastern shore of the Barrens, a harbor built by nobody's design and everybody's leftovers. Gazlowe raised it after Orgrimmar was finished, flush with the coin Thrall had paid him and his crew for their work on the Warchief's city. The town began with smugglers and grew from there, filling up with whoever the rest of the world had thrown out. It kept no flag but its own, trading through Booty Bay and Baron Revilgaz across the sea, and let orc and human money spend the same in its streets.\n\nThat neutrality nearly broke it. The Burning Blade worked quietly at the seams between Orgrimmar and Theramore, staging shipping incidents near the port until traders and sailors of both nations were brawling in its streets. When the bruiser Muzzlecrank arrested the captains Klatt and Joq, Northwatch Hold read it as the opening move of an orcish war and called for reinforcements. Ratchet became a staging ground for a Horde army marching against Northwatch. Only when the cult's hand in the whole affair came to light did Thrall call the fighting off.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Shrine of the Fallen Warrior",
			short = "On a small hill west of the Crossroads, a trail winds up from the base of a mound, climbing the ridge until it reaches the shrine at the top.",
			full = "On a small hill west of the Crossroads, a trail winds up from the base of a mound, climbing the ridge until it reaches the shrine at the top. The Shrine of the Fallen Warrior stands alone there, quiet above the plains of the Northern Barrens.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "Sludge Fen",
			short = "Sludge Fen was once a pool of crystal-blue water. The Venture Company found it, raised an oil rig over it, and left it a mire of black waste and industrial runoff, worked now under the eye of Supervisor Lugwizzle.",
			full = "Sludge Fen was once a pool of crystal-blue water. The Venture Company found it, raised an oil rig over it, and left it a mire of black waste and industrial runoff, worked now under the eye of Supervisor Lugwizzle.\n\nIt was here that Wizzlecrank came, sent by Sputtervalve of the Tinkers' Union. Sputtervalve had been ordered by Director Riddlevox to match the Venture Company's shredders, and rather than build one that could compete, he chose to steal one outright. Wizzlecrank leapt into a stolen shredder without first securing the key to drive it, and sat stranded in the mire until the key was lifted from the supervisor himself and the machine hauled off toward Ratchet, Venture Co. workers giving chase the whole way.\n\nA sludge beast was found here too, tracked all the way from Nozzlepot's Outpost to the wreck of the fen it now called home.\n\nThe oil rig still stands over the ruined water, and the goblins still work it, waste and all.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Southern Gold Road",
			short = "The Southern Gold Road takes its name from the caravans that travel it, running from the Great Lift at the southern edge of the Barrens to the bridge joining the region's northern and southern halves.",
			full = "The Southern Gold Road takes its name from the caravans that travel it, running from the Great Lift at the southern edge of the Barrens to the bridge joining the region's northern and southern halves. Beyond the bridge, the same highway continues simply as the Gold Road.\n\nTraders and travelers wear its dust from far afield: out of Gadgetzan in Tanaris, from Auberdine in Darkshore, and down from Nighthaven in the north, all following the same stretch of open Barrens earth.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape.",
			full = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape. It marks the boundary between Ashenvale and Azshara to the north, and further south divides the Northern Barrens from Durotar, before finally pouring itself into the Great Sea in one last waterfall near the goblin port of Ratchet.\n\nThree bridges cross it: one linking Azshara to Ashenvale, one carrying travelers into Orgrimmar itself, and one joining Durotar to the Northern Barrens. Just north of the western bridge into the orc capital, there is a single point where four lands touch at once, the water running between them all.\n\nAt the river's mouth, a goblin named Horton Hornblower keeps a riverboat tied at his dock, ferrying those who need passage upstream toward the Barrens.\n\nThe river still runs strong enough to water the fields along its banks, but its water can no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "Stagnant Oasis",
			short = "The waters here have gone still, choked with growth, but they still draw life to their edges.",
			full = "The waters here have gone still, choked with growth, but they still draw life to their edges. Kolkar centaur camp along the fringes of the Stagnant Oasis, and the Lost Barrens kodo that linger here are gaunt and solitary, weaker than their kin further south. Oasis snapjaws move through the shallows, and deviate fish can be drawn from the murky water.\n\nWhen the Primalists loosed their elementals upon the land, the spirits swept into the oasis and lingered there, seeping into the Kolkar camped nearby and leaving the centaur touched by that raw power.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Thorn Hill",
			short = "Thorn Hill sits on the north face of the mountain between the Crossroads and Durotar, a warren of the Razormane quilboar under the rule of Tortusk.",
			full = "Thorn Hill sits on the north face of the mountain between the Crossroads and Durotar, a warren of the Razormane quilboar under the rule of Tortusk. From its heights the Razormane have struck at Horde caravans passing through the region, raids frequent and bold enough to draw the attention of the Horde's own security forces, who now watch the hill as a standing threat.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "Tidus Stair",
			short = "The Tidus Stair rises above the Merchant Coast in a series of stone terraces, like a giant's staircase cut into the shore southeast of Ratchet.",
			full = "The Tidus Stair rises above the Merchant Coast in a series of stone terraces, like a giant's staircase cut into the shore southeast of Ratchet. Two tauren, Islen Waterseer and Mahren Skyseer, keep to the terraces, fishing lines cast into the surf below, speaking quietly with the spirits of the water as they wait.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Wailing Caverns",
			short = "Beneath the dry grass of the Barrens run rivers that never see the sun, breaking the surface as small oases before the dust reclaims the land.",
			full = "Beneath the dry grass of the Barrens run rivers that never see the sun, breaking the surface as small oases before the dust reclaims the land. These waters drew the night elf druid Naralex deep underground, into a cave system he named for the mournful wail of steam forced through its cracks. He believed that if he joined the waters to the Emerald Dream itself, he could pour that green dream across the savannah and restore it to what it had been.\n\nHe led his disciples down and sat to meditate, opening himself as a channel between the Dream and the waking world. But the Emerald Nightmare found the opening first, and Naralex could not wake. Through his sleeping body the Nightmare's corruption poured instead, twisting the waters, warping the creatures of the caverns into deviate and misshapen things, and driving his disciples to madness. Most became the Druids of the Fang, lost to the very nightmare they had come to hold back.\n\nThe Horde descended into the caverns to undo what had happened, cutting through the corruption to reach the sleeping druid and free those disciples who could still be saved.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Alterac Mountains: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Dalaran rose after the Troll Wars, founded by magi of the Arathorian Empire as a city-state answerable to no crown but its own.",
			full = "Dalaran rose after the Troll Wars, founded by magi of the Arathorian Empire as a city-state answerable to no crown but its own. Its rulers were the Kirin Tor, the elite of the world's wizards, governed by the Council of Six, and at the city's heart stood the Violet Citadel, a sanctum where the study of magic was pursued more deeply than anywhere save the elven lands of Quel'Thalas. By the Third War even the high elven magi of Quel'Thalas deferred to its sovereignty.\n\nThat standing did not save it. The Scourge fell upon the city in a siege that scattered its people, and Archimonde himself came to level the Violet Citadel and the streets around it, breaking the Kirin Tor's leadership and driving the survivors into exile.\n\nThey came back. Out of the ruin the Kirin Tor rebuilt Dalaran and raised a great magical dome to shield its restored heart, then lifted the entire city into the air so that no army of the dead could ever again march against its walls on open ground.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Dandred's Fold",
			short = "A farm and manor stands on the western edge of the Uplands, its harbor giving onto Lordamere Lake and the Misty Shore.",
			full = "A farm and manor stands on the western edge of the Uplands, its harbor giving onto Lordamere Lake and the Misty Shore.\n\nHere lived Aliden, and here he kept a necklace that had once belonged to Taretha Foxton. His life ended at this fold, and it was his mistress Elysa, wearing the necklace herself, who gave it up, fearing that she would be harmed as he had been.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Lordamere Internment Camp",
			short = "Lordamere Internment Camp sits on a hill above the Dalaran Crater, the only camp of its kind raised in the Alterac Mountains, held by soldiers of Dalaran.",
			full = "Lordamere Internment Camp sits on a hill above the Dalaran Crater, the only camp of its kind raised in the Alterac Mountains, held by soldiers of Dalaran.\n\nPrince Arthas Menethil and Lady Jaina Proudmoore once came here in secret, on their way to Dalaran, slipping past guard patrols and watchtowers under cover of night to look upon the orcs held within. What they found were not warriors but the lethargic remnants of a broken people, among them females and infants. Jaina, seeing them, felt her certainty falter into doubt and remorse. Arthas felt none of it, insisting the camps were necessary. Neither of them was seen, and they left the way they came, the argument between them unresolved.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "Ruins of Alterac",
			short = "Broken walls climb the slopes of the Alterac Mountains where a city once stood, its palace half-standing, its church and town hall fallen in on themselves, its gate built in the fashion of Stormwind's own.",
			full = "Broken walls climb the slopes of the Alterac Mountains where a city once stood, its palace half-standing, its church and town hall fallen in on themselves, its gate built in the fashion of Stormwind's own.\n\nIts ruin came from its own king. During the Second War, King Aiden Perenolde turned traitor, casting his lot with the Orcish Horde against his fellow humans. Alteraci soldiers were found fighting alongside the orcs, and a prison camp near the city held captive citizens of Dalaran. When the truth came out, the other human kingdoms marched on Alterac in retaliation. The people fled or were driven from their homes, and King Terenas Menethil II of Lordaeron declared the city under martial law, casting Perenolde down and throwing him into chains.\n\nThe city never rose again. Crushridge ogres, led by Mug'thol, settled into the empty streets and palace, while the scattered remnants of the old Alteraci people held the outlying villages beyond. Wrecked meat wagons still lie near the northern rampart and the gate, and the graveyards within and beyond the walls, the snow-buried farm, and shattered ballistae among the rubble remain as they were left.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Uplands",
			short = "The Uplands once fed the kingdom of Alterac, its hills tilled and grazed to fill royal granaries.",
			full = "The Uplands once fed the kingdom of Alterac, its hills tilled and grazed to fill royal granaries. When the heart of that nation was destroyed, the Uplands fell to the Syndicate, who hold no ground in the Alterac Mountains more firmly than here. Their camps cover the hills, ruled in the Baron Vardus's name. In the westernmost reach stands Dandred's Fold, a remnant of the old order amid fields that feed no one now.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Arathi Highlands: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Boulderfist Hall",
			short = "Boulderfist Hall is a fortified ogre mound in southern Arathi Highlands, near Thandol Span and Witherbark Village. Deep within its largest cave broods Kor'gresh Coldrage, chief of the Boulderfist clan.",
			full = "Boulderfist Hall is a fortified ogre mound in southern Arathi Highlands, near Thandol Span and Witherbark Village. Deep within its largest cave broods Kor'gresh Coldrage, chief of the Boulderfist clan.\n\nBy the time of the Battle for Stromgarde, the Boulderfist had pushed outward, spreading their camp across the surrounding hills and fortifying it further.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Boulder'gor",
			short = "North of Stromgarde Keep rises the hill called Boulder'gor. Boulderfist ogres hold their mound here at the Boulderfist Outpost, and Witherbark forest trolls keep to the same high ground.",
			full = "North of Stromgarde Keep rises the hill called Boulder'gor. Boulderfist ogres hold their mound here at the Boulderfist Outpost, and Witherbark forest trolls keep to the same high ground. On its eastern side stands the Circle of Elements, and just south of it lie a pair of farms.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Circle of East Binding",
			short = "The Stone of East Binding stands in the eastern Arathi Highlands, near Hammerfall, one of the Circles of Binding raised across the region.",
			full = "The Stone of East Binding stands in the eastern Arathi Highlands, near Hammerfall, one of the Circles of Binding raised across the region. Water elementals still keep watch over the stone, holding to whatever charge was laid upon them long ago.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Circle of Inner Binding",
			short = "The Circle of Inner Binding stands in the southern Arathi Highlands near Stromgarde Keep, watched over by earth elementals. Here rests the Stone of Inner Binding, strongest of the region's binding stones.",
			full = "The Circle of Inner Binding stands in the southern Arathi Highlands near Stromgarde Keep, watched over by earth elementals. Here rests the Stone of Inner Binding, strongest of the region's binding stones.\n\nThrough its shard, Myzrael found a way to reach out to mortal travelers.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Circle of Outer Binding",
			short = "The Stone of Outer Binding stands at the center of its ring near Refuge Pointe, one of the Circles of Binding set across the Arathi Highlands.",
			full = "The Stone of Outer Binding stands at the center of its ring near Refuge Pointe, one of the Circles of Binding set across the Arathi Highlands. Air elementals keep watch over the stone, holding to whatever binding was laid upon this place.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Circle of West Binding",
			short = "The Stone of West Binding once stood near Thoradin's Wall in the Arathi Highlands, guarded by fire elementals, one of the old Circles of Binding set into that land.",
			full = "The Stone of West Binding once stood near Thoradin's Wall in the Arathi Highlands, guarded by fire elementals, one of the old Circles of Binding set into that land.\n\nThen the Horde raised Ar'gorok upon the site. Where the stone and its guardians stood, the Horde now cuts timber at Hatchet Ridge, and the circle is gone.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Dabyrie's Farmstead",
			short = "In the northern reaches of Arathi Highlands stands the farmstead of the Dabyrie family, Kenata and her children Fardel and Marcel, loyal citizens of Stromgarde.",
			full = "In the northern reaches of Arathi Highlands stands the farmstead of the Dabyrie family, Kenata and her children Fardel and Marcel, loyal citizens of Stromgarde. Where so many of their neighbors perished or fled in the Third War, the Dabyries endured and prospered, and their farm still stands green and worked while others lie in ruin.\n\nThat survival earned them an enemy. Genavie Callow had lost everything to the plague that swept the land, her family dead, her estate burned to nothing, and what few precious things remained to her taken, she claimed, by the Dabyries themselves. Raised into undeath with nothing left but her bitterness, Genavie sent killers against the family not once but twice. Both times they failed, and the Dabyries kept their land.\n\nThe farm's fortunes have long been tied to Stromgarde Keep itself. When the keep fell to the Horde, the League of Arathor did not scatter, but held the farmstead under Knight-Captain Aldrin, keeping the Alliance cause alive in the north. When the keep flew Alliance colors instead, the Syndicate crept down from the Alterac Mountains to seize the farm in its turn, only to be thrown back, the land returning once more to the Dabyries.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Drowned Reef",
			short = "Beneath the bay off Arathi's southern shore lies a sunken elven city, ruled now by the Daggerspine naga under Prince Nazjak, who commands the very tides of the bay.",
			full = "Beneath the bay off Arathi's southern shore lies a sunken elven city, ruled now by the Daggerspine naga under Prince Nazjak, who commands the very tides of the bay.\n\nThat mastery has doomed more ships than can be counted, among them the Maiden's Folly and the Spirit of Silverpine. Crews seeking shelter in Faldir's Cove find the water turning against them, until their ship joins the wrecks already scattered across the reef.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Drywhisker Gorge",
			short = "Drywhisker Gorge cuts through the mountains in the eastern Arathi Highlands, northeast of Hammerfall, ending in a cave the Drywhisker kobolds have made their own.",
			full = "Drywhisker Gorge cuts through the mountains in the eastern Arathi Highlands, northeast of Hammerfall, ending in a cave the Drywhisker kobolds have made their own. Allies to the giants of the highlands, these kobolds guard a scattering of motes and, buried deeper still, a stone shard holding a fragment of the essence of Princess Myzrael.\n\nAmong the Drywhisker, one name stood above the rest: Overseer Krix, who kept a donkey penned near his hollow, fattened for slaughter and meant to be his dinner. He never got the chance. Krix fell, and the donkey he had marked for the pot was spared, led out of the gorge to find a home far from the kobolds' fires.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Faldir's Cove",
			short = "Faldir's Cove takes its name from Faldir, who is said to have launched his voyage from this harbor with the followers who would go on to found the kingdom of Stormwind.",
			full = "Faldir's Cove takes its name from Faldir, who is said to have launched his voyage from this harbor with the followers who would go on to found the kingdom of Stormwind. The name has clung to it ever since as a marker of that first departure.\n\nIn more recent memory, the Blackwater Raiders came here hunting an elven treasure, sailing three ships under Captains Steelgut and O'Breen. A tide raised by naga guarding sunken ruins nearby dragged two of the vessels under; only the Harbinger reached the cove safely, its crew trapped in the bay until the naga were driven off and the lost ships' navigation logs recovered from the wreckage.\n\nWhen war broke out over Stromgarde, the Alliance and the keep's returning citizens seized the cove, and held it through the fighting even after Stromgarde itself fell, keeping it still when the war had ended.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Go'Shek Farm",
			short = "Go'Shek Farm once belonged to Primwell Skye, a veteran of the Second War, before Forsaken and orcs from Hammerfall took the farmstead for their own purposes.",
			full = "Go'Shek Farm once belonged to Primwell Skye, a veteran of the Second War, before Forsaken and orcs from Hammerfall took the farmstead for their own purposes. The orcs have drawn supplies from it for Hammerfall ever since, while the Forsaken have used its fields and outbuildings for their alchemy, the work of one Apothecary Jorell, whose notes on a new plague were uncovered here.\n\nThe farm's bloodiest hour came when Regent Marran Trollbane led the 7th Legion and the Stromic army against it, only to be met by Overlord Geya'rah's Mag'har and Kor'kron. Thrall pressed Geya'rah to stand down, and Jaina Proudmoore worked to blunt Marran's command of her own soldiers. It was Geya'rah, seeing no honor in the fight, who sounded the horn to end it -- and both armies obeyed. When Marran refused to yield, Lord Danath Trollbane himself arrested her and offered reparations, which Geya'rah declined, asking only that the hatred between their peoples be allowed to end.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Hammerfall",
			short = "The stone walls that ring Hammerfall once held orcs in chains.",
			full = "The stone walls that ring Hammerfall once held orcs in chains. After the Second War, it stood as one of the largest of the internment camps raised by the Alliance of Lordaeron, a place built to keep a broken people caged.\n\nIt did not stay a cage. Thrall and Orgrim Doomhammer led the Horde against it to free those held within, and in the chaos of that assault, as Thrall worked to cover the retreat of the freed orcs, a knight's lance found Doomhammer from behind. It struck with such force that it pierced the plate of his armor front and back, and the old Warchief fell there, in the camp he had come to liberate.\n\nAfter the Third War, the Horde returned to the ruins and rebuilt them as a forward base, naming the place Hammerfall in memory of the Warchief who died taking it.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Northfold Manor",
			short = "Northfold Manor stood empty after Stromgarde fell, until the Syndicate took it for their own and made it an outpost in Arathi Highlands.",
			full = "Northfold Manor stood empty after Stromgarde fell, until the Syndicate took it for their own and made it an outpost in Arathi Highlands.\n\nIt was here that the troll shaman Tor'gan came, drawn by a wrongness in the air he could not name. As he neared the manor the feeling sharpened into something physical, his blood heating, rage building in him without cause. On the ground he found the source, at least in part: an amulet of bloodstone, the kind used to draw forth demons, though this one had been drained of whatever power it once held. The traces of demonic summoning around the manor were unmistakable. Tor'gan could not say why the Syndicate, a gang of thieves and opportunists, would meddle in such magic, and he needed whole amulets, not spent ones, to learn the truth of it.\n\nThe manor's fate became a small piece of the larger struggle for the land around it, claimed in the name of the dead of Stromgarde by some, and fought over by those still trying to reclaim their fallen kingdom.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Refuge Pointe",
			short = "When Stromgarde's capital fell in the Third War, most of its people fled south, but the proud remnant of the army refused to leave the Highlands.",
			full = "When Stromgarde's capital fell in the Third War, most of its people fled south, but the proud remnant of the army refused to leave the Highlands. They made their stand at Refuge Pointe, and from its tents the war to reclaim Arathi was directed ever since.\n\nThat cause was paid for dearly. With most of the Stromgarde army gone to Khaz Algar, Refuge Pointe was left thin of defenders, and Joseph led the Scarlet Crusade's Red Dawn against it. Civilians and guards were cut down, others dragged off as captives, and only the passerby Karga Bloodfury managed to pull a few free. Faerin Lothar and a company of adventurers arrived seeking King Danath Trollbane, found the zealots still at their work, and cut them down, driving Joseph to flee.\n\nRefuge Pointe still stands, its southernmost tent kept as an inn, held by soldiers who have never stopped waiting to march north again.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Stromgarde Keep",
			short = "Stromgarde Keep, also known simply as Stromgarde, is the capital city of the kingdom of Stromgarde, located in the southwest of the Arathi Highlands.",
			full = "Stromgarde Keep, also known simply as Stromgarde, is the capital city of the kingdom of Stromgarde, located in the southwest of the Arathi Highlands. In ages past, the settlement was a cradle for human civilization, when it served as the capital of the Arathorian Empire under the name of Strom. By the time of the arrival of the Orcish Horde, it stood as a major power center as part of the Alliance of Lordaeron during and after some time following the Second War.\n\nStromgarde was eventually sacked and left in ruins at some point after the events of the Third War and remained in this condition for many years to follow. It was divided into three sections -- one around the inner keep itself and under the rule of the Syndicate, the former mage district largely under the control of the Boulderfist clan ogres with aid from the Witherbark trolls, while the last section remained under the control of the Stromgarde military and once served as the headquarters of Prince Galen Trollbane, until his death.\n\nSupported by the Alliance and led by Danath Trollbane, the League of Arathor fully re-established itself in Stromgarde and began restoring the settlement to its former glory. However, it soon became the focal point of the conflict between the Alliance and the Horde for control of the Arathi Highlands. Ultimately, the Alliance managed to defeat the Horde, returning most of Arathi into the hands of Stromgarde after many years of strife.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "Two vast arches of dwarven stone span the valley here, joining the Wetlands to the Arathi Highlands.",
			full = "Two vast arches of dwarven stone span the valley here, joining the Wetlands to the Arathi Highlands. The Anvilmar line guarded them for three generations, and they were raised after the War of the Three Hammers so that Ironforge might keep faith and trade with its Wildhammer kin at Aerie Peak. Both kingdoms grew fat on the traffic that crossed them.\n\nThe Span was nearly lost when Kam Deepfury and Balgaras the Foul turned the Dark Iron clan against it. One of the two great arches was destroyed, and dwarves died holding what remained. The bridge only stood because Hjalmar Anvilmar did not: captured by the Dark Irons, he gave his life in a rescue led by Thargas Anvilmar, Varian Wrynn, Broll Bearmantle, and Valeera Sanguinar, and his death bought the time needed to save the last span from ruin. King Magni's reinforcements arrived, Balgaras fell, and the Dark Irons were driven from the bridge they had so nearly toppled.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "King Thoradin raised his wall soon after Strom became a capital, a barrier meant to hold the Amani trolls off the newborn empire of Arathor.",
			full = "King Thoradin raised his wall soon after Strom became a capital, a barrier meant to hold the Amani trolls off the newborn empire of Arathor. For generations it stood, a promise that humanity would not be pushed back into the sea.\n\nThe promise broke once. Faerin Lothar was told, as a child, of a curse that fell upon Arathor, twisting men and beasts into something monstrous, and of how an army of those ruined things finally broke through the wall that had never fallen before. Centuries on, the stone still bears that wound, standing gouged and crumbled where the curse tore its way through.\n\nFaerin returned to it grown, walking beside Danath Trollbane on his way to settle a quarrel between Hammerfall and Stromgarde. She had only heard the wall in stories, and stood awestruck before it. Danath called it just a wall, warning her that too much reverence for such legends bred the same pride that had once turned Stromgarde against its neighbors.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Tower of Arathor",
			short = "The Tower of Arathor stands in the mage district of Stromgarde Keep, named for the old empire whose sons once studied the arcane within its walls.",
			full = "The Tower of Arathor stands in the mage district of Stromgarde Keep, named for the old empire whose sons once studied the arcane within its walls. Among them was Trelane, who as a young wizard built into the tower a defense of water and stone, sealed behind an enchanted gem, so that no enemy could walk its halls unchallenged.\n\nThe defense did not save him. When the Syndicate and the Boulderfist ogres broke Stromgarde, Trelane fought to hold the tower and failed, fleeing the city he had studied in. The ogres took the district for their own, and an ogre mage named Ruul Onestone made his den within.\n\nYears later, still grieving what he had left behind, Trelane asked his former apprentice Malin to recover what remained inside: his phylactery, his orb, an ember agate he had prized. A stolen gem, remade, was pressed to the old pedestals near the entrance, and the guardians Trelane had set decades before woke again to drive back the ogres while his treasures were carried out.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Witherbark Village",
			short = "Witherbark Village sits around a small lake in the southeast of the Arathi Highlands, its huts ringing the water and a wide cavern opening behind them where the tribe's leaders hold court.",
			full = "Witherbark Village sits around a small lake in the southeast of the Arathi Highlands, its huts ringing the water and a wide cavern opening behind them where the tribe's leaders hold court.\n\nThe Witherbark trolls struck a loose alliance with the Boulderfist ogres nearby against the humans of Stromgarde and the orcs of Hammerfall. Together troll and ogre warbands seized a section of ruined Stromgarde and held it against those who once called it home.\n\nBoth the Alliance and the Horde came to see the Witherbark trolls as a problem to be ended. Among those marked for death was Nimar the Slayer, feared above the rest, who in his last fight took a great many attackers down with him before he fell.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Badlands: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Agmond's End",
			short = "Agmond's End takes its name from a dwarven prospector who dug here and never left. Troggs infesting the site rose against him, and he did not survive them.",
			full = "Agmond's End takes its name from a dwarven prospector who dug here and never left. Troggs infesting the site rose against him, and he did not survive them.\n\nTheldurin later withdrew to a camp in the Scar of the Worldbreaker. In his place came Dr. Hieronymus Blam, a gnome who ringed the old dig with turrets of his own making.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Angor Fortress",
			short = "Angor Fortress stands as the seat of Dark Iron operations in the Badlands, its dwarves organizing their delving into Uldaman from within its walls.",
			full = "Angor Fortress stands as the seat of Dark Iron operations in the Badlands, its dwarves organizing their delving into Uldaman from within its walls. Within the keep also resides Ambassador Infernus, an agent of Ragnaros, bound to the Dark Irons' purpose.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Apocryphan's Rest",
			short = "A dragon's skeleton lies broken in the dust south of Kargath, vast enough to bear its own name: Apocryphan's Rest. Only the great ribs and jaw remain, picked bare by the buzzards that nest and hunt among the bones still.",
			full = "A dragon's skeleton lies broken in the dust south of Kargath, vast enough to bear its own name: Apocryphan's Rest. Only the great ribs and jaw remain, picked bare by the buzzards that nest and hunt among the bones still.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Camp Boff",
			short = "Camp Boff, southeastern of the Dustbelcher ogres' four camps, is held by only three of their kind. Their leader, Boss Tho'grun, answers to none of the camps alone, pacing the Badlands between all four instead.",
			full = "Camp Boff, southeastern of the Dustbelcher ogres' four camps, is held by only three of their kind. Their leader, Boss Tho'grun, answers to none of the camps alone, pacing the Badlands between all four instead.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Camp Cagg",
			short = "Camp Cagg is one of the holds of the Dustbelcher ogres, alongside Camp Boff, Kosh, and Wurg. Their leader, Boss Tho'grun, claimed none of them as his own, choosing instead to patrol the Badlands between all four.",
			full = "Camp Cagg is one of the holds of the Dustbelcher ogres, alongside Camp Boff, Kosh, and Wurg. Their leader, Boss Tho'grun, claimed none of them as his own, choosing instead to patrol the Badlands between all four.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Camp Kosh",
			short = "Camp Kosh sits at the northern edge of the Dustbelcher ogres' holdings, preying on caravans that must cross the Badlands toward Kargath or down into the Searing Gorge.",
			full = "Camp Kosh sits at the northern edge of the Dustbelcher ogres' holdings, preying on caravans that must cross the Badlands toward Kargath or down into the Searing Gorge.\n\nWhen Sigrun Ironhew and his men pulled out from the Uldaman excavation, they could not carry everything with them, and left wagons and crates strewn along their retreat. The ogres of Camp Kosh fell on what was abandoned, weapons and food alike, hauling it back to their camp. Sigrun did not let the loss stand, and sought to have the supplies won back.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Camp Wurg",
			short = "Camp Wurg stands as one of the homes of the Dustbelcher ogres, kin to the camps of Cagg, Boff, and Kosh.",
			full = "Camp Wurg stands as one of the homes of the Dustbelcher ogres, kin to the camps of Cagg, Boff, and Kosh. Their leader, Boss Tho'grun, kept to no single camp, but roamed the Badlands between all four, watching over the ogres wherever they made their ground.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Dustbelch Grotto",
			short = "In the southwestern reaches of the Badlands rises a great mound of earth, hollowed and heaped by generations of labor.",
			full = "In the southwestern reaches of the Badlands rises a great mound of earth, hollowed and heaped by generations of labor. Dustbelch Grotto is home to the Dustbelcher ogres, who claim it as their own against the barren stone around them.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Dustbowl",
			short = "The Dustbowl is a stretch of cracked, arid ground in the northwest of the Badlands, between Kargath and the Valley of Fangs. Little grows here but scattered cacti and a few hardy trees.",
			full = "The Dustbowl is a stretch of cracked, arid ground in the northwest of the Badlands, between Kargath and the Valley of Fangs. Little grows here but scattered cacti and a few hardy trees. Coyotes, rock elementals, and buzzards share the waste, and Camp Wurg stands among them.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Dustwind Gulch",
			short = "The heat in Dustwind Gulch settles into the rock and never quite leaves. Little grows here among the dry stone, and the wind carries only dust across the ravine's western reaches, out toward Lethlor.",
			full = "The heat in Dustwind Gulch settles into the rock and never quite leaves. Little grows here among the dry stone, and the wind carries only dust across the ravine's western reaches, out toward Lethlor.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Hammertoe's Digsite",
			short = "Hammertoe's Digsite lies in the northern Badlands, its excavation abandoned by Hammertoe and now held by a gang of Dark Irons, likely part of the same force that has pushed into Uldaman.",
			full = "Hammertoe's Digsite lies in the northern Badlands, its excavation abandoned by Hammertoe and now held by a gang of Dark Irons, likely part of the same force that has pushed into Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath stands in the Badlands, the only outpost the Horde ever raised in Khaz Modan, named for Kargath Bladefist, chieftain of the Shattered Hand.",
			full = "Kargath stands in the Badlands, the only outpost the Horde ever raised in Khaz Modan, named for Kargath Bladefist, chieftain of the Shattered Hand.\n\nOn Thrall's own order, the Kargath Expeditionary Force rode out from here again and again into the dry country. Their searching turned up Uldaman, a dwarven dig the dwarves themselves guarded jealously, and Horde soldiers were sent down into it to learn what secrets were worth such care. But the Expeditionary Force's true task was cutting a road through the Searing Gorge to Blackrock Mountain, where Rend Blackhand ruled the Dark Horde and needed answering. That road ran straight through Dark Iron dwarf territory, and the Horde found itself at war with the Dark Irons again simply for trying to pass.\n\nMost of those who once held Kargath have since resettled nearby, in a rebuilt and fortified town near Apocryphan's Rest, carrying its purpose forward under a new roof.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Lethlor Ravine",
			short = "The ravine's crags shelter whelps and drakes of the black dragonflight, drawn to the crystalline obelisks that rise from the broken ground here, relics that mark this place as something more than empty wasteland cutting through the Badlands.",
			full = "The ravine's crags shelter whelps and drakes of the black dragonflight, drawn to the crystalline obelisks that rise from the broken ground here, relics that mark this place as something more than empty wasteland cutting through the Badlands.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Maker's Terrace",
			short = "The Maker's Terrace is a broad excavation cut into the earth outside Uldaman's entrance. Dark Iron dwarves now patrol its trenches, holding the ground before the sealed hall beyond.",
			full = "The Maker's Terrace is a broad excavation cut into the earth outside Uldaman's entrance. Dark Iron dwarves now patrol its trenches, holding the ground before the sealed hall beyond.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Mirage Flats",
			short = "The Mirage Flats lie between Dragon's Mouth and New Kargath, east of Dustbelch Grotto. Little of it remains whole, and what is left has become no-man's land, held by neither side.",
			full = "The Mirage Flats lie between Dragon's Mouth and New Kargath, east of Dustbelch Grotto. Little of it remains whole, and what is left has become no-man's land, held by neither side.\n\nGiant buzzards, ridge stalker patriarchs, and rabid crag coyotes are all that claim it now.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Uldaman is a huge and ancient, massive vault created by the titan keepers, buried deep within mountains of Khaz Modan. It is located in the Badlands, west of what was once the entrance to Loch Modan.",
			full = "Uldaman is a huge and ancient, massive vault created by the titan keepers, buried deep within mountains of Khaz Modan. It is located in the Badlands, west of what was once the entrance to Loch Modan. Prior to the Third War, it was partially excavated by the dwarves from Ironforge, but has since fallen into the hands of the troggs and Dark Irons, who find the place ideal to dig for earthly riches. It was previously a titan-forged facility.\n\nUldaman contains many artifacts for those willing to seek them out, primarily archaeologists and adventurers, who are slowly digging up this ruin of a titan-forged city. There are members of the Explorers' League, but also of the Reliquary, equally eager to get their hands on ancient treasures.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Valley of Fangs",
			short = "The Valley of Fangs cuts narrow between two great walls of stone in the Badlands, and its name is no idle one. Wolves and cougars den in the rocks above, and anyone who walks the valley does so watched.",
			full = "The Valley of Fangs cuts narrow between two great walls of stone in the Badlands, and its name is no idle one. Wolves and cougars den in the rocks above, and anyone who walks the valley does so watched.\n\nHere, Martek the Exiled keeps company with Rigglefuzz and Jazzrik.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Blasted Lands: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "Dark Portal",
			short = "The Dark Portal was raised by treachery. The human mage Medivh, his mind no longer wholly his own, worked with the warlock Gul'dan to tear open a passage between Draenor and Azeroth.",
			full = "The Dark Portal was raised by treachery. The human mage Medivh, his mind no longer wholly his own, worked with the warlock Gul'dan to tear open a passage between Draenor and Azeroth. On Draenor, Gul'dan had orcish stonemasons build the frame at a place where the world's power ran strong -- and when the work was done, the warlocks murdered the very masons who had built it, their deaths priming the final seal. Then, as the ritual began, Gul'dan drained the life from nearly every draenei prisoner still held by the Horde, all at once, to force the tear wide enough to reach Azeroth. Medivh answered from the other side, ripping open the Black Morass. Through that opening the orcs marched into the Kingdom of Stormwind, and the First War began.\n\nFor years after, armies of orcs and ogres came through it without end. But when the Horde broke at Blackrock Spire and the Alliance took the ruined gateway, the archmage Khadgar worked a spell meant to end it forever. The blast destroyed the stone frame the orcs had built, but the tear in reality itself could not be unmade. Khadgar urged Lordaeron to build Nethergarde Keep to keep watch over the ruins, in case it ever opened again.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Dreadmaul Post",
			short = "Dreadmaul Post is a mound of the Dreadmaul ogre clan, who crossed into Azeroth from Draenor and chose to stay close to the Dark Portal ever since.",
			full = "Dreadmaul Post is a mound of the Dreadmaul ogre clan, who crossed into Azeroth from Draenor and chose to stay close to the Dark Portal ever since. Their hold on the ground here has never slackened. A lost draenei can sometimes still be found wandering nearby.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Garrison Armory",
			short = "The Garrison Armory is a mining outpost near Nethergarde Keep in the Blasted Lands.",
			full = "The Garrison Armory is a mining outpost near Nethergarde Keep in the Blasted Lands. Alliance miners here draw ore and minerals from the scarred ground, shipping them to Stormwind in exchange for the supplies Nethergarde depends upon to survive.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Nethergarde Keep",
			short = "Nethergarde Keep stands on a high bluff above the only road into the Blasted Lands, built to watch the Dark Portal after the Second War at the insistence of Archmage Khadgar, who feared Draenor would send its armies through again.",
			full = "Nethergarde Keep stands on a high bluff above the only road into the Blasted Lands, built to watch the Dark Portal after the Second War at the insistence of Archmage Khadgar, who feared Draenor would send its armies through again. The kingdoms of the Alliance of Lordaeron paid for it, some more willingly than others, and the Stonemasons Guild raised its walls under Edwin VanCleef.\n\nKhadgar remained master of the keep until Ner'zhul's clans reopened the Portal from Draenor's side and besieged Nethergarde once more. Khadgar rallied Turalyon, Danath Trollbane, Alleria Windrunner, and Kurdran Wildhammer, and led the Alliance through the Portal to end the war at its source. When Ner'zhul's tearing of Draenor threatened to spill ruin back into Azeroth, the five sealed the Portal from the other side and did not return. For twenty years afterward, the Dark Portal stood silent, and Nethergarde's mages turned to studying what its energies had done to the land around them.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Rise of the Defiler",
			short = "The mountains take their name from the demon who claims them. Razelikh the Defiler makes his home in this broken, craggy rise at the heart of the Blasted Lands, and nothing softens the ground around him.",
			full = "The mountains take their name from the demon who claims them. Razelikh the Defiler makes his home in this broken, craggy rise at the heart of the Blasted Lands, and nothing softens the ground around him.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Serpent's Coil",
			short = "Serpent's Coil twists through the eastern Blasted Lands, its passages carved past burnt-out orcish structures left standing since the Second War.",
			full = "Serpent's Coil twists through the eastern Blasted Lands, its passages carved past burnt-out orcish structures left standing since the Second War.\n\nArchmage Allistarj once commanded his Shadowsworn from within this labyrinth. He is dead now, killed in the cave he ruled, and the amulet he wore was left behind in a chest near the entrance. His Shadowsworn did not scatter when he fell. They found another master and kept to their tunnels, as if nothing had changed.\n\nDeeper in, a gnome named Kasim Sharim has made his camp. He is Alliance, by his own oath, yet he has raised a Horde banner over his fire and settled in alone among the cave's old dangers.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "Tainted Scar",
			short = "The Tainted Scar lies in the western Blasted Lands, ground once green as part of the Black Morass, now burned to lifeless red soil by the corrupting breath of the Dark Portal.",
			full = "The Tainted Scar lies in the western Blasted Lands, ground once green as part of the Black Morass, now burned to lifeless red soil by the corrupting breath of the Dark Portal. Nothing grows there. Nothing but demons live there.\n\nAfter the Legion's defeat at Mount Hyjal, the ered'ruin Lord Kazzak withdrew what remained of his forces into the Scar and made it his stronghold, setting his lieutenant Razelikh the Defiler to hold it. He later passed command to Kruul, who ruled through terror until the demons were driven back through the Dark Portal, and Kruul abandoned the Scar to join the last stand beyond it.\n\nAn old human warlock, Daio the Decrepit, came into the wasteland afterward and made his home at its altar, performing rituals among the lingering demons and teaching the infernal arts to those who sought him out. He remains there still.\n\nMost of the Scar has since been swallowed by encroaching forest, but around Daio's altar a small scar of barren ground endures, red and dead, a wound the green has never quite closed over.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Tirisfal Glades: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Agamand Family Crypt",
			short = "North of Agamand Mills stands the Agamand Family Crypt, dark and dusty with generations of the dead.",
			full = "North of Agamand Mills stands the Agamand Family Crypt, dark and dusty with generations of the dead. Captain Dargol, a minion of the Scourge, has taken it for his own and roused the ancestors from their graves, so that the family's own dead now rise against any who enter unbidden.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Agamand Mills",
			short = "The windmills of Agamand still turn above the highlands of northern Tirisfal, though no living hand tends them.",
			full = "The windmills of Agamand still turn above the highlands of northern Tirisfal, though no living hand tends them. The land came into the family's keeping long ago, bought with the wealth of noble immigrants from Strom, and for generations it stood as a working estate.\n\nWhen the Scourge first came through Tirisfal, Gregor Agamand refused to flee. He fortified the Mills and convinced his workers to stand with him, and for a time the walls held. What broke them was not the undead but the youngest Agamand son, Devlin, who turned against his own house. He murdered two watchmen in the night and led a band of Scourge through the breach to the sleeping defenders, killing a third of them before he was stopped. Weakened past recovery, the Agamands could not hold their borders, and before long the whole family fell to the Plague of Undeath and rose as mindless Scourge, haunting the mills they once owned.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Balnir Farmstead",
			short = "The Balnir Farmstead lies in ruin, its fences broken, its stables empty, only a few wandering Scourge left where horses once grazed.",
			full = "The Balnir Farmstead lies in ruin, its fences broken, its stables empty, only a few wandering Scourge left where horses once grazed. Jorum and Vara Balnir raised the great white horses of Lordaeron here, the same stock that carried kings, and it was in this yard that a colt named Invincible was born while a young Prince Arthas looked on, having slipped away from Capital City to play with the Balnir boy Jarim. Arthas took the colt as his own, and when Invincible later died in a riding accident, he was buried on the farm at the prince's request.\n\nYears later, on the day Capital City fell, the Scourge came to the farmstead and slaughtered the Balnir family. Arthas came too, no longer a prince but a death knight fresh from killing his own father, and with Frostmourne he tore Invincible from the earth and raised him into undeath. The grave was left open, and it remains open still, empty even of bones, while snapdragons that Vara once tended keep growing wild in the ruined garden.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Brightwater Lake",
			short = "Long before Tirisfal took its name, Eidre and her family held the land around the keep by this lake. Then the dreadlord Kathra'natir came and infected the ground.",
			full = "Long before Tirisfal took its name, Eidre and her family held the land around the keep by this lake. Then the dreadlord Kathra'natir came and infected the ground.\n\nIt was on a small island within these waters that Alodi, the first Guardian of Tirisfal, fought the demon.\n\nGunther's Retreat now stands on that same island, the water giving no sign of what it once held.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill was once a quiet town of Lordaeron, held by the Barov family, with the Agamands keeping a manor of their own within its walls.",
			full = "Brill was once a quiet town of Lordaeron, held by the Barov family, with the Agamands keeping a manor of their own within its walls. That quiet ended before the Third War, when the necromancer Kel'Thuzad, still living, chose Brill to test his plague of undeath. It worked too well. The dead rose in such numbers that Kel'Thuzad used the proof of it to talk the Lich King into moving before his invasion was ready. The town's defenders could not hold it, and fled to join Prince Arthas as he hunted the source of the sickness. Outside the walls, a mass graveyard was dug to hold what Tirisfal lost.\n\nNow the Forsaken hold Brill, rebuilding what the plague and later fighting left as little more than broken walls. A blacksmith who once worked here is remembered only because he turned, mindless, back into the Scourge. In Gallows' End Tavern, captured Scarlet Zealots have been used to test Forsaken poisons, payment in kind for the Crusade's raids.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Brill Town Hall",
			short = "Magistrate Sevren governs from the podium of Brill Town Hall, tallest structure in the town.",
			full = "Magistrate Sevren governs from the podium of Brill Town Hall, tallest structure in the town. Only here and at the Defiler's Den does the Forsaken dominion keep such an office of rule, a shape of the old world put to the service of the new.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark stands where Tirisfal Glades gives way to the Western Plaguelands, the last line the Forsaken hold against the Scourge pressing from the east.",
			full = "The Bulwark stands where Tirisfal Glades gives way to the Western Plaguelands, the last line the Forsaken hold against the Scourge pressing from the east. Here the Argent Dawn and the Forsaken set aside their long distrust of one another and stand together, watching the same horizon for the same enemy.\n\nNot long ago this ground was choked in plaguemist, its sky stained the same sickly yellow-gray as the blighted land beyond it. Reclamation efforts pushing into the Plaguelands have since thinned that mist, and the Bulwark now looks much like the rest of Tirisfal around it.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Cold Hearth Manor",
			short = "Cold Hearth Manor once earned its name honestly, known through Tirisfal for its warmth and the richness of its crops. The Plague of Undeath ended that.",
			full = "Cold Hearth Manor once earned its name honestly, known through Tirisfal for its warmth and the richness of its crops. The Plague of Undeath ended that. Everyone who lived or worked its fields died in the sickness, and the ground grew barren, overrun with mindless Scourge zombies where harvests once stood.\n\nThe Forsaken took the farmhouse for their own, holding it against the dead still wandering the fields, and offering trade to travelers on the road nearby.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Crusader Outpost",
			short = "The tower stands on the hills of eastern Tirisfal Glades, watching the road below. The Scarlet Crusade holds it, using the height to guard the road and to catch by surprise any who move against the Scarlet Monastery.",
			full = "The tower stands on the hills of eastern Tirisfal Glades, watching the road below. The Scarlet Crusade holds it, using the height to guard the road and to catch by surprise any who move against the Scarlet Monastery. Captain Vachon commands here.\n\nThe stones still bear marks of an attack by Lilian Voss, evidence of a fight fiercer than the outpost's usual watch.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Deathknell",
			short = "The valley of Deathknell lies within Tirisfal Glades, its narrow approaches held by lines of Deathguard Elites, watchful against the Scourge that spawned the Forsaken and the Scarlet Crusade that hunts them still.",
			full = "The valley of Deathknell lies within Tirisfal Glades, its narrow approaches held by lines of Deathguard Elites, watchful against the Scourge that spawned the Forsaken and the Scarlet Crusade that hunts them still. It is here that the newly-risen dead first open their eyes to their second existence, in a place that offers little beyond bare survival.\n\nGold is the village's constant want. The mine that might supply it lies northwest, but spiders have long since claimed its tunnels, and the folk of Deathknell labor again and again to drive them out, without lasting success.\n\nThe name itself sets Deathknell apart. Every other settlement raised by the Banshee Queen's rebel dead kept the name it bore in life. Deathknell alone was given a new name, and no one now living can say why, or what it was called before.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Faol's Rest",
			short = "Faol's Rest lies southwest of the Scarlet Monastery, a quiet grave in Tirisfal Glades. Here was laid Archbishop Alonsus Faol, much revered, who died before the Scourge came to Lordaeron.",
			full = "Faol's Rest lies southwest of the Scarlet Monastery, a quiet grave in Tirisfal Glades. Here was laid Archbishop Alonsus Faol, much revered, who died before the Scourge came to Lordaeron.\n\nDeath did not hold him. When the plague swept the kingdom, Faol rose undead, and in time became Forsaken, taking his place among the leading voices of the Conclave.\n\nWhere crowds once came to mourn him, the grave now lies untended and mostly forgotten. Yet it has not gone entirely unused: members of the Conclave gathered here again, meeting at the resting place of one of their own.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Gallows' End Tavern",
			short = "The tavern in Brill takes its name from what waits below.",
			full = "The tavern in Brill takes its name from what waits below. In its cellars are held prisoners of the Forsaken: a Scarlet Zealot and a Dwarven Mountaineer, chained far from whatever brought them into Tirisfal Glades, kept there as a promise of the end the tavern's name foretells.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Garren's Haunt",
			short = "Garren's Haunt was once a bountiful farmstead in the northern Tirisfal Glades, its fields wide and its barn full.",
			full = "Garren's Haunt was once a bountiful farmstead in the northern Tirisfal Glades, its fields wide and its barn full. That ended with the Scourging of Lordaeron, when the Scourge fell upon it and put Garren and his family to the sword. The Plague of Undeath followed, and the land itself turned gray and lifeless, the crops dead in the furrows.\n\nWhat was left standing did not stay empty. The Rot Hide gnolls took the farmhouse and fields for their own, led by Maggot Eye, who fell upon anyone who wandered too near. A darkhound named Plague now lairs in the barn where livestock once sheltered.\n\nNo one can say what became of Maggot Eye and his gnolls in the end. The farmhouse, the silos, and the barn still stand over the wide field, gray and empty, with no one left to claim them.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Gunther's Retreat",
			short = "Gunther's Retreat is a small island in Brightwater Lake, claimed by the Forsaken lich Gunther Arcanus and his zombie minions.",
			full = "Gunther's Retreat is a small island in Brightwater Lake, claimed by the Forsaken lich Gunther Arcanus and his zombie minions. On a nameless islet to the southwest lies Lillith's Dinner Table, a strange, isolated feature apart from the lich's court.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Night Web's Hollow",
			short = "The hollow lies northwest of Deathknell, a narrow vale opening into an old gold mine, both claimed entire by spiders. Young spiders wander the vale above; adult broods hold the tunnels below.",
			full = "The hollow lies northwest of Deathknell, a narrow vale opening into an old gold mine, both claimed entire by spiders. Young spiders wander the vale above; adult broods hold the tunnels below.\n\nAt the very bottom of the mine, past the dark and the dust, the Night Web Matriarch waits, mistress of everything that skitters above her.\n\nThe newly raised of the Forsaken come here to test themselves against the spiders, some pushing deep into the mine to learn what secrets its dark still keeps.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Nightmare Vale",
			short = "Nightmare Vale was once green, teeming with forest life. That life is gone. The trees have withered, and the animals that once lived here have been eaten by darkhounds and huge vampire bats that now haunt the valley.",
			full = "Nightmare Vale was once green, teeming with forest life. That life is gone. The trees have withered, and the animals that once lived here have been eaten by darkhounds and huge vampire bats that now haunt the valley.\n\nAmong the bats flies a rare one, pale against the dead wood: Ressan the Needler.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "North Coast",
			short = "The beach along the northern edge of Tirisfal Glades has gone dark and cold since the Plague of Undeath marred the region. Dead sea creatures rot at the waterline.",
			full = "The beach along the northern edge of Tirisfal Glades has gone dark and cold since the Plague of Undeath marred the region. Dead sea creatures rot at the waterline. Murlocs have overrun the shore, ravenous things that pick through the wrack alongside other marine scavengers.\n\nThe scar that cuts inland from where the Alliance came ashore, running through to the ruins of Brill, is remembered as the Lion's Wake, a line of destruction still visible in the land.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "The palace of Lordaeron still stands above the ruin, its gardens broken, its courtyard empty of the crowds that once filled it.",
			full = "The palace of Lordaeron still stands above the ruin, its gardens broken, its courtyard empty of the crowds that once filled it. Here Arthas Menethil returned from Northrend and slew his own father, King Terenas, before opening the gates to the Scourge and letting them put the city's people to the sword. Those who linger in the courtyard say they can still hear it: hushed voices before the killing, bells in the entryway, a cheer for the returning prince, murmurs from the throne room, and beneath it all Arthas's words after the deed was done, promising a new order risen from the ashes of the old. Those who can see beyond the veil say the citizens themselves still walk there, unaware they are dead.\n\nSylvanas Windrunner later turned on her own allies, the very forces she had fought beside to break the dreadlords holding the city, and claimed the ruin for herself. Beneath its stones now lies the Undercity, the buried capital of the Forsaken.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Scarlet Monastery",
			short = "The halls of the Scarlet Monastery were built for quieter purposes. Once the seat of Archbishop Alonsus Faol, it held the libraries and seminaries where paladins of the Silver Hand trained in their youth.",
			full = "The halls of the Scarlet Monastery were built for quieter purposes. Once the seat of Archbishop Alonsus Faol, it held the libraries and seminaries where paladins of the Silver Hand trained in their youth. Alexandros Mograine himself once prayed and studied within these walls.\n\nAfter Lordaeron fell, Mograine led the last Knights of the Silver Hand back here as a forward base against the Forsaken. It was in these halls that the order split, and the fanatics who remained renamed the place the Scarlet Monastery, turning it into a fortress of zealotry where any non-human, and eventually anyone unmarked by their tabard, was condemned as plagued.\n\nThe monastery's chapel bears the memory of its darkest betrayal. Renault Mograine, who had murdered his own father Alexandros for the Crusade's cause, was struck down here by that same father's spirit, called forth through the voice of the Ashbringer and given form by Darion Mograine.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Scarlet Watch Post",
			short = "North of the Scarlet Monastery, in the Tirisfal Glades, stands the Scarlet Watch Post.",
			full = "North of the Scarlet Monastery, in the Tirisfal Glades, stands the Scarlet Watch Post. The monastery's northern side has no natural defense, so the Scarlet Crusade keeps this tower manned to see danger coming before it reaches the gates.\n\nCaptain Melrache commands it, one of four such Crusader's Outposts set across the Glades to watch over the monastery's weaker approaches.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Shadow Grave",
			short = "The Shadow Grave sits atop the slope above Deathknell, among the tombs of the Deathknell Graves in the Tirisfal mountains.",
			full = "The Shadow Grave sits atop the slope above Deathknell, among the tombs of the Deathknell Graves in the Tirisfal mountains. A path winds down from its entrance to the village below, where the newly risen first open their eyes to the world above.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Solliden Farmstead",
			short = "The pumpkin rows of Solliden still ripen every autumn, one of the few patches of northern Lordaeron where the old farming families never fell to the Plague of Undeath.",
			full = "The pumpkin rows of Solliden still ripen every autumn, one of the few patches of northern Lordaeron where the old farming families never fell to the Plague of Undeath. Their fields lie untouched by the rot that claimed the rest of Tirisfal, and the Scarlet Crusade watches over them from the nearby Palisade, keeping the Forsaken and the Scourge at bay.\n\nThe farmers pay for that safety with isolation. They trust no banner, Horde or Alliance, and turn away both alike. Yet their peace is watched with suspicion. The Forsaken worry that these unbroken families, sitting so near the borders of Gilneas and Stormwind, might one day be turned into recruits against them, and some argue the farmstead should be silenced before that chance arises.\n\nSolliden endures for now, a green field in a grey land, tended by the last of Tirisfal's untouched.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Stillwater Pond",
			short = "Before the plague, Stillwater Pond was where children of the glades learned to swim, too young yet for the deeper, colder waters of Brightwater Lake.",
			full = "Before the plague, Stillwater Pond was where children of the glades learned to swim, too young yet for the deeper, colder waters of Brightwater Lake. Families picnicked along its banks. It was a small, gentle place.\n\nThe plague changed it utterly. The pond now lies gray and still, its fish reduced to skeletons drifting beneath the surface, seen only by wandering undead and wild beasts. The darkhound Bayne prowls its edges, feeding on whatever comes too close.\n\nNew things have taken root in the poisoned water. Marrowpetals grow along the bottom, and Stillwater Lilies ring the shore. Giant flesh-eating tadpoles now infest the pond, bred from chemicals carelessly dumped by the Royal Apothecary Society.\n\nWhen the Forsaken began rebuilding Brill, Scarlet Crusade warriors took to patrolling the pond's shores.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrace of Repose",
			short = "The hedges here are trimmed square, the fountain runs clear, and the grass holds a green found nowhere else in Tirisfal Glades, where the Plague of Undeath has turned water to stagnant rot.",
			full = "The hedges here are trimmed square, the fountain runs clear, and the grass holds a green found nowhere else in Tirisfal Glades, where the Plague of Undeath has turned water to stagnant rot. This terrace alone escaped it, and the Scarlet Crusade tends it still, just north of the gates of Scarlet Monastery.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["undercity"] = {
			name = "Undercity",
			short = "Beneath the ruined palace of Lordaeron lie crypts and sewers older than the Scourge itself, where the poorest of the old kingdom once huddled among the dead.",
			full = "Beneath the ruined palace of Lordaeron lie crypts and sewers older than the Scourge itself, where the poorest of the old kingdom once huddled among the dead. It was here that Arthas Menethil meant to build the Scourge's seat of power, only to abandon the half-finished catacombs when the Lich King called him north.\n\nSylvanas Windrunner and her free-willed dead finished what Arthas began, twisting the tunnels into an unassailable stronghold, and named themselves the Forsaken. In the throne room they raised, a stone tomb honors King Terenas, crafted by the humans who once served him, though his ashes were spent long ago to raise Kel'Thuzad from death. A trail of blood still marks the floor by the throne, left by a crown that rolled from a dying king's head.\n\nRivers of poisoned sludge now run through every quarter, choking the air for the living. Yet for Sylvanas and her kind, it remains the only refuge left to them.",
			source = "https://warcraft.wiki.gg/wiki/Undercity",
		},
		["venomweb vale"] = {
			name = "Venomweb Vale",
			short = "Venomweb Vale lies south of the Scarlet Monastery, and once it was the kind of place hunters came for deer and rabbit, its grass green and its trees full of birdsong.",
			full = "Venomweb Vale lies south of the Scarlet Monastery, and once it was the kind of place hunters came for deer and rabbit, its grass green and its trees full of birdsong. None of that remains. The vale is thick with poisonous spiders now, ruled by the brood-mother Sri'skulk.\n\nThe spiders are not natural. This valley was once the traditional meeting place of the Council of Tirisfal, sacred ground where the first Guardian was empowered. To defend that secret place, one of the Council's own bred the spiders that now choke it, trading the vale's peace for its protection.\n\nA single rock of fool's gold still sits where Aegwynn once met with the Council. It was ordinary stone once, until Magna Scavell's apprentice Falric transformed it by accident, centuries ago, and it has stayed that way since.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "Whispering Gardens",
			short = "On this hill south of the Scarlet Monastery gate, a host of Scourge once met the men who would become the Scarlet Crusade, and both sides left their dead among the stones.",
			full = "On this hill south of the Scarlet Monastery gate, a host of Scourge once met the men who would become the Scarlet Crusade, and both sides left their dead among the stones.\n\nTheir voices linger still, rising as faint whispers across the hillside in the twilight.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Whispering Shore",
			short = "The Whispering Shore lies on the western coast of Tirisfal Glades, north of Solliden Farmstead. Fishermen once favored these waters for their bounty.",
			full = "The Whispering Shore lies on the western coast of Tirisfal Glades, north of Solliden Farmstead. Fishermen once favored these waters for their bounty. Now the water runs cold and dark, and murlocs have claimed the shore, savaging any who wander near. Their leader is the vicious Muad, and nothing of the old plenty remains.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Silverpine Forest: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Ambermill",
			short = "After the Scourge and the Burning Legion tore through the north, the wizards of Dalaran discovered that Ambermill sat above a dormant ley line, and set about waking it for their own purposes.",
			full = "After the Scourge and the Burning Legion tore through the north, the wizards of Dalaran discovered that Ambermill sat above a dormant ley line, and set about waking it for their own purposes. The town became a source of human resistance the Forsaken could not ignore. To keep it safe, Archmage Ataeric bound Ambermill into a pocket dimension of its own, reachable only through a portal and passable only by one carrying an Archmage's signet ring, while elemental servitors guarded the grounds outside against Sylvanas Windrunner's dead.\n\nThat single requirement proved the town's undoing. Sent by Sylvanas herself, an intruder passed the portal, cut down magi in the streets, and killed Ataeric where he kept the dimension alive. With him dead, Ambermill fell back into Azeroth, its warding gone, and the Forsaken took it before it could be defended. Ataeric and his wizards did not stay buried; they rose again in Forsaken service.\n\nServitors walk Ambermill's mills and stables once more, though the shield that once held the town apart from the world is gone for good.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Beren's Peril",
			short = "In the hills southwest of Ambermill, where the main road meets the side path winding down from the mill town, lies Beren's Peril.",
			full = "In the hills southwest of Ambermill, where the main road meets the side path winding down from the mill town, lies Beren's Peril.\n\nYears after the Third War, Forsaken scouts brought word to Shadow Priest Allister that undead were gathering there, readying a strike against the Sepulcher. The report was thin, but Allister could not afford to ignore it. What waited at Beren's Peril were the servants of the necromancer Thule Ravenclaw, hidden among the hills and preparing their attack in secret.\n\nLater, during the invasion of Gilneas, the place took on a stranger purpose. A transdimensional portal to Ambermill stood there, guarded by the Ambermill Portal Guardians, sealed against any but the bearer of a Dalaran Archmage's Signet Ring. On Sylvanas Windrunner's orders, that ring was taken from Relios the Relic Keeper, and through the portal it opened, Ambermill's magi fell one by one, Archmage Ataeric among them, until the town was torn back into Azeroth and the Forsaken poured in behind it.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Dawning Isles",
			short = "The Dawning Isles once rose clean and low from Lordamere Lake, until the Plague of Undeath reached them. The trees sickened, and murlocs and bog beasts overran the isles.",
			full = "The Dawning Isles once rose clean and low from Lordamere Lake, until the Plague of Undeath reached them. The trees sickened, and murlocs and bog beasts overran the isles. The bog beasts have since vanished, but the Vile Fin murlocs bred without check and now hold the isles as their own.\n\nThe Scarlet Crusade later claimed the isles as a foothold, launching an attack from here against the Ruins of Lordaeron. The Forsaken struck back across the water in answer.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Dead Field",
			short = "The farm called Dead Field lies abandoned in northern Silverpine Forest, its fields long given over to rot. No one now remembers who once worked this ground.",
			full = "The farm called Dead Field lies abandoned in northern Silverpine Forest, its fields long given over to rot. No one now remembers who once worked this ground.\n\nThe Rot Hide gnolls hold it now, bound in service to the Scourge, and their numbers have only grown.\n\nThe Forsaken have struck at the Dead Field again and again in small numbers, and each time the attack has failed. The reason has a name: Nightlash, a banshee who does not linger idle among the gnolls she commands. Only when the Rot Hides are attacked does she appear, and it is her coming that has turned back every assault.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Decrepit Ferry",
			short = "The dock at Fenris Isle once kept a simple rhythm: farmsteads sent part of their harvest across to the island's lord, and the ferryman carried it over for a small fee.",
			full = "The dock at Fenris Isle once kept a simple rhythm: farmsteads sent part of their harvest across to the island's lord, and the ferryman carried it over for a small fee.\n\nThe Scourge ended that. The ferryman was killed, his boat broken apart, and the crossing he tended became a wound instead of a road. Ghouls and skeletal warriors moved into the ruined docks, and Rot Hide gnolls settled among them.\n\nNo ferry runs there now, only the dead.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Deep Elem Mine",
			short = "The Deep Elem Mine once had a foreman named Grimson the Pale. When Arugal's magic spread through Silverpine Forest, Grimson turned worgen, and led the beasts to make the mine their own den.",
			full = "The Deep Elem Mine once had a foreman named Grimson the Pale. When Arugal's magic spread through Silverpine Forest, Grimson turned worgen, and led the beasts to make the mine their own den. It was Dalar Dawnweaver who moved against him, sending warriors to strike off Grimson's head so the mine could be claimed for the Forsaken, in the name of Varimathras.\n\nThe mine changed hands again through treachery. Sylvanas Windrunner believed she had cornered the leaders of the Gilneas Liberation Front within it, and sent Master Forteski, called the Horseman, out to the mine with a contingent of her finest Veteran Forsaken Troopers to finish them. But Ivar Bloodfang had set a trap: the mine stood empty, packed to explode. When the Forsaken entered, the charges went off and tore the troopers to pieces. Only a single messenger survived to carry word back of what had happened.\n\nThe mine's entrance still lies choked with rubble from that blast.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Fenris Isle",
			short = "Fenris Isle rises out of the center of Lordamere Lake, its keep standing where Lordaeron once quartered a military garrison.",
			full = "Fenris Isle rises out of the center of Lordamere Lake, its keep standing where Lordaeron once quartered a military garrison. When the Scourge swept over the land, Fenris Keep was abandoned, its people scattered or slain, and for a time the Rot Hide gnolls held it under their master Thule Ravenclaw.\n\nIt was here that the survivors of the Forsaken attacks in the Hillsbrad Foothills made their choice. The undead Agatha had come among them, killing to raise the dead into her ranks, when Darius Crowley and Ivar Bloodfang offered the Refugee Leadership a different end: die and rise as undead, or drink the blood offered them and become worgen, beyond undeath's reach, and go on fighting. Most chose vengeance. Several hundred Hillsbrad refugees took the blood and became worgen, and Ivar's pack carried the same offer to nearly every human left alive in Lordaeron, throwing themselves afterward into the fight against the Forsaken across Silverpine Forest.\n\nYears later the Scarlet Crusade seized the isle as a staging ground against the Forsaken, who broke them and drove them out, reclaiming Fenris Isle for their own.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Fenris Keep",
			short = "The gloomy Fenris Keep lays at the center of Lordamere Lake in Silverpine Forest upon the Fenris Isle. The keep had strategic significance, and was home to a sizable portion of Lordaeron's military.",
			full = "The gloomy Fenris Keep lays at the center of Lordamere Lake in Silverpine Forest upon the Fenris Isle. The keep had strategic significance, and was home to a sizable portion of Lordaeron's military.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "Greymane Wall",
			short = "King Genn Greymane built this wall out of resentment, unwilling to keep paying for the Alliance's orc prisoners while Gilnean soldiers died for causes not his own.",
			full = "King Genn Greymane built this wall out of resentment, unwilling to keep paying for the Alliance's orc prisoners while Gilnean soldiers died for causes not his own. He resolved to seal his kingdom away, and it was Lord Vincent Godfrey who chose where the stone should rise: through Lord Darius Crowley's own lands, using the mountains as a footing, cutting Pyrewood Village and Ambermill away from the rest of Gilneas. Greymane agreed, certain Crowley would understand.\n\nThe wall did what it was built to do. When the Plague of Undeath swept over Lordaeron, Gilneas stood behind its gate untouched while refugees gathered outside and, over the years the gate stayed shut, died there. When the Scourge reached the wall itself, Greymane opened the gate and sent his soldiers to meet them; they were beaten and raised as undead. Desperate, he had Archmage Arugal summon worgen to finish the fight. The beasts drove off the Scourge, then turned on the soldiers who had summoned them. Greymane sealed the gate for good, but some of the retreating men carried the curse home with them, and it spread quietly through the kingdom for years.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Ivar Patch",
			short = "Ivar's Patch was once a working farm, its rows heavy with pumpkins, worked by hired hands under a man named Ivar.",
			full = "Ivar's Patch was once a working farm, its rows heavy with pumpkins, worked by hired hands under a man named Ivar. It was a prosperous place, by all accounts a pleasant one, until the Scourge came down over Lordaeron and the plague took everyone on it. Ivar, his family, and his farmhands rose again as ghouls, and the man himself became something called Ivar the Foul, a rotting thing that still haunts the patch and tears into anyone who comes too near.\n\nThree deathstalkers of the Forsaken, Rane Yorick, Quinn Yorick, and Erland McKree, were sent north through Silverpine to judge how dangerous the land had become. Ivar's ghouls fell on them at the farm, and Ivar himself wounded Quinn. Rane and Quinn barricaded themselves inside Ivar's old house while Erland pressed on alone.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Lordamere Lake spreads beneath the shadow of what was once the greatest of human capitals, and it takes its name from the city that stood on its northern shore, itself named for old Lordain.",
			full = "Lordamere Lake spreads beneath the shadow of what was once the greatest of human capitals, and it takes its name from the city that stood on its northern shore, itself named for old Lordain. In the years when the Alliance of Lordaeron was young and its kingdoms prosperous, Lordaeron, Dalaran, and Alterac all rose within sight of these waters.\n\nAfter the Third War, when Dalaran lay in ruins, Lady Vashj led her naga to these shores and made them a refuge, retreating here after the fighting at the fallen city.\n\nThe lake has since become a border of a different kind, separating the Forsaken holdings of Tirisfal Glades and Silverpine Forest from the disputed heights of the Alterac Mountains. At its heart sits Fenris Isle, whose keep fell to the Forsaken under Deathstalker Hayward, and the Horde used fighting there as cover to slip Undercity refugees across the water to safety.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Malden's Orchard",
			short = "The orchard still bears its owner's name, though Malden himself is long gone, driven from his home when the Scourge came down upon Lordaeron.",
			full = "The orchard still bears its owner's name, though Malden himself is long gone, driven from his home when the Scourge came down upon Lordaeron. His trees remain, dark and evergreen, heavy with fruit no one has picked in years, and his cottage still stands empty beside them.\n\nBlack worgs have since taken the orchard for their own. When the Deathstalker Erland McKree was sent to scout it, he found the pack too numerous to pass and was driven to shelter inside Malden's abandoned cottage, pinned there for days. Only with the help of other Forsaken agents did he finally break free, fleeing southwest to rejoin his partners at the Ivar Patch.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "North Tide's Hollow",
			short = "North Tide's Hollow lay just north of the Sepulcher, a stretch of forest given over to the Moonrage worgen, servants of the Archmage Arugal.",
			full = "North Tide's Hollow lay just north of the Sepulcher, a stretch of forest given over to the Moonrage worgen, servants of the Archmage Arugal. It was one of their many haunts.\n\nWhat they built there showed nothing of craft or comfort. Their camps were crude, thrown together from the meanest necessities of survival, enough to keep a tough worgen fed and out of the weather. No home, only a haunt.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "North Tide's Run",
			short = "The northwestern shore of Silverpine Forest is a bare beach fronting the Great Sea, marked by a sunken Horde ship half-swallowed in the shallows.",
			full = "The northwestern shore of Silverpine Forest is a bare beach fronting the Great Sea, marked by a sunken Horde ship half-swallowed in the shallows.\n\nNear the wreck, a man named Wallace the Blind keeps a small campfire burning by the water's edge.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Olsen's Farthing",
			short = "Olsen's Farthing once stood on the main road that carried trade through Silverpine Forest, its fields busy with the ordinary work of a farmstead.",
			full = "Olsen's Farthing once stood on the main road that carried trade through Silverpine Forest, its fields busy with the ordinary work of a farmstead.\n\nThat ended a few years after the Third War, when the farm was left in ruins. Undead answering to Thule Ravenclaw took the ground for their own, falling on anyone who wandered too near, and Olsen's Farthing never returned to the plow.\n\nLater still, the Scarlet Crusade, holding Fenris Isle, turned the ruined farm into another front in their war against the Forsaken. They let the plague run loose in the wolves, bears, and deer that ranged the fields until the animals sickened and turned savage, and they nailed their condemnations of the Forsaken to the trees standing among the wreckage, so that the farm itself became a message to anyone still living who might pass through.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Pyrewood Village",
			short = "On the height above Pyrewood stood a keep held by Baron Silverlaine and the paladins of the Silver Hand. Archmage Arugal's worgen slaughtered them all and took the keep, renaming it Shadowfang.",
			full = "On the height above Pyrewood stood a keep held by Baron Silverlaine and the paladins of the Silver Hand. Archmage Arugal's worgen slaughtered them all and took the keep, renaming it Shadowfang. From there Arugal cursed the villagers below: by night they became ravening worgen, and by day they woke as themselves again, remembering nothing of it. Even so, the village kept trading with travelers as if nothing above it had changed.\n\nIt did not last. The Forsaken came to root the worgen from Silverpine, turned Pyrewood's own council against it, and hunted Arugal down, beheading him and burying him in an unmarked grave just south of the village he had ruined.\n\nYears later, in the war for Gilneas, the village changed hands again between the Forsaken and the Gilneas Liberation Front, until Lord Godfrey, unable to hold it, ordered it burned rather than lost. Only ruins were left, patrolled afterward by Forsaken troopers among the ash.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Sepulcher",
			short = "The Sepulcher, also known as the Silverpine Sepulcher, is a Forsaken base located in the western side of Silverpine Forest. The area itself lies above the Lordaeronian coastline, nestled within the surrounding hills.",
			full = "The Sepulcher, also known as the Silverpine Sepulcher, is a Forsaken base located in the western side of Silverpine Forest. The area itself lies above the Lordaeronian coastline, nestled within the surrounding hills. It was nothing more than a large graveyard and string of expeditionary caravans and individuals.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Shadowfang Keep",
			short = "Shadowfang Keep is a haunted keep not far from the borders of Gilneas in southern Silverpine Forest, on a high bluff overlooking Pyrewood Village.",
			full = "Shadowfang Keep is a haunted keep not far from the borders of Gilneas in southern Silverpine Forest, on a high bluff overlooking Pyrewood Village. It was named for the forces of its former master, the demented Archmage Arugal, who wrested the keep from Baron Silverlaine with his worgen \"children\" and held it until he was defeated by a group of Horde heroes. The keep was then occupied by the Scourge remnants and followers of the renegade Gilnean nobleman Vincent Godfrey, traitor to both his homeland and to the Forsaken who returned him from death.\n\nBy the end of the war, the Bloodfang pack had taken control of the keep, moving most of its artifacts to Fenris Keep to be guarded closely.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Shining Strand",
			short = "The Shining Strand runs along the edge of Lordamere Lake, from the ruined capital of Lordaeron in the north down to the rough hills separating Silverpine from the Alterac Mountains.",
			full = "The Shining Strand runs along the edge of Lordamere Lake, from the ruined capital of Lordaeron in the north down to the rough hills separating Silverpine from the Alterac Mountains.\n\nThe Vile Fin murlocs once held the strand, their settlements thick enough to make the shore perilous for travelers. Apothecary Berard wrote of them before his death, noting that a Hardened Tumor could be drawn from the Vile Fins, and guessing it might serve in brewing a new plague.\n\nThe murlocs are gone now, driven off to the Dawning Isles, and the Forsaken hold their camps along the shore in their place. They do not hold it easily. Worgen press against them there still.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Skittering Dark",
			short = "The mine called the Skittering Dark has been given over to the Skitterweb spiders that web its shafts and the ground outside.",
			full = "The mine called the Skittering Dark has been given over to the Skitterweb spiders that web its shafts and the ground outside. Deep within dwells the Skitterweb Matriarch, a spider grown monstrous with age, ruling the swarm from the dark. Outside the mine, the rare spider Krethis the Shadowspinner sometimes stirs.\n\nCocoons litter the area, holding what the spiders have taken: worgen, worgs, bears, even orcs who crashed along the shore to the west.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "South Tide's Run",
			short = "The coast here takes its name in pairing with the shore north of it, where the Great Sea beats against Silverpine Forest's edge. It is a place known more for what borders it than for anything that happened upon it.",
			full = "The coast here takes its name in pairing with the shore north of it, where the Great Sea beats against Silverpine Forest's edge. It is a place known more for what borders it than for anything that happened upon it.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Valgan's Field",
			short = "The farm still bears the name of the man who worked it, though nothing else of him remains. Valgan was killed or driven off when the Scourge came down over northern Silverpine, and he did not keep what he'd built.",
			full = "The farm still bears the name of the man who worked it, though nothing else of him remains. Valgan was killed or driven off when the Scourge came down over northern Silverpine, and he did not keep what he'd built.\n\nFor a time the feral Moonrage worgen held the field, but they too have vanished, leaving only Nightlash to prowl the empty furrows now and then. Once, it must have been worth owning: the ground looks north toward Lordamere Lake, and the view alone would have made the place lovely.\n\nMore recently, Lieutenant Hawlsey used the field as a training ground for recruits, until the Forsaken marked him for death and sent killers after him.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Western Plaguelands: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark stands where Tirisfal Glades gives way to the Western Plaguelands, the last line the Forsaken hold against the Scourge pressing from the east.",
			full = "The Bulwark stands where Tirisfal Glades gives way to the Western Plaguelands, the last line the Forsaken hold against the Scourge pressing from the east. Here the Argent Dawn and the Forsaken set aside their long distrust of one another and stand together, watching the same horizon for the same enemy.\n\nNot long ago this ground was choked in plaguemist, its sky stained the same sickly yellow-gray as the blighted land beyond it. Reclamation efforts pushing into the Plaguelands have since thinned that mist, and the Bulwark now looks much like the rest of Tirisfal around it.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Caer Darrow",
			short = "The keep on Caer Darrow was raised by human hands long ago, and within it stood an ancient high elven runestone, sacred and old.",
			full = "The keep on Caer Darrow was raised by human hands long ago, and within it stood an ancient high elven runestone, sacred and old. When the Horde came in the Second War, they sacked the fortress and tore the stone from its place, breaking it apart to forge the Altars of Storms, through which Gul'dan bound magic into his ogre allies.\n\nThe keep was rebuilt and became the seat of House Barov. But the Barovs grew greedy and afraid of their own mortality, and struck a bargain with Kel'Thuzad to preserve their power beyond their years. Within six months the manor had become Scholomance, a school of necromancy hidden beneath the old halls. The family's own servants were used to test the plague of undeath, and that plague was loosed and killed everyone on the island. None survived as living things; their spirits remain, bound to relive their final moments, and the lake around them has stood lifeless and still ever since.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Chillwind Camp",
			short = "Chillwind Camp sits where the road out of the Alterac Mountains drops into the Western Plaguelands, the last safe ground before the poisoned country begins.",
			full = "Chillwind Camp sits where the road out of the Alterac Mountains drops into the Western Plaguelands, the last safe ground before the poisoned country begins. The Argent Dawn keeps it under Lord Maxwell Tyrosus, and it was here that Darion Mograine came looking for volunteers after he joined their cause. His father Alexandros Mograine's soul was trapped in Naxxramas, and Darion asked the camp to give him men willing to go in after it. Enough answered, and they rode out from Chillwind on gryphons.\n\nLater the camp became a staging ground for Lord Grayson Shadowbreaker's Knights of the Silver Hand, sent to fight under Commander Ashlam Valorfist against the Scourge holding Andorhal. The knights he sent were young and promising. All of them died here, cut down by the undead they had come to burn out.\n\nAfter the Alliance was broken at the Battle for Andorhal, Valorfist said plainly what everyone at Chillwind already feared: that the Forsaken would come for the camp next.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Dalson's Tears",
			short = "Dalson's Orchard was once a working farm. Now it stands in the Western Plaguelands under the Scourge, its name changed with its fate: Dalson's Tears.",
			full = "Dalson's Orchard was once a working farm. Now it stands in the Western Plaguelands under the Scourge, its name changed with its fate: Dalson's Tears.\n\nAt the heart of the field the Scourge have set a great cauldron that never stops working, pouring disease-thick vapor into the air, guarded by Cauldron Lord Malvinious and the shambling dead in his service.\n\nThe family who worked this land never left it. Mrs. Dalson wanders the property still, a skeleton picking through the rows she once walked living. Her husband did not join the wandering dead but became a ghoul, shut away in the outhouse where he was locked in, rotting there still, the key to the family's old cabinet carried on his rotting body.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Darrowmere Lake",
			short = "The waters of Darrowmere still hold the shape of the kingdom that once stood above them. At its heart sits Caer Darrow, an island town abandoned to silence, where the House of Barov once kept its halls.",
			full = "The waters of Darrowmere still hold the shape of the kingdom that once stood above them. At its heart sits Caer Darrow, an island town abandoned to silence, where the House of Barov once kept its halls. Beneath that town, hidden from the lake's surface, lies Scholomance, where the Cult of the Damned raised its undead servants and continues its work out of sight.\n\nThe lake was not always so empty. During the Second War, its waters carried the ships of the Alliance, drawn largely from the Proudmoore fleet. Before Quel'Thalas burned, the Grand Admiral ordered several vessels to ferry Turalyon and Alleria Windrunner's army near Stratholme. Turalyon considered sailing straight into Quel'Thalas itself, but Alleria warned him the elves would never allow human ships up their river.\n\nNow the lake lies still, its surface giving no sign of the fleets once gathered on it, or of what stirs beneath the drowned town at its center.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Felstone Field",
			short = "The soil at Felstone was once good soil, turned for grain rather than graves. That ended when the Scourge came down and took the farm whole, raising a black cauldron where the crop rows had been.",
			full = "The soil at Felstone was once good soil, turned for grain rather than graves. That ended when the Scourge came down and took the farm whole, raising a black cauldron where the crop rows had been. It has boiled ever since, breathing sickness low over the grass, watched over by Bilemaw and the skeletal dead that guard him.\n\nIn the northeastern corner, one house still stands. Janice Felstone remains inside it, holding to a home everything around her has already forgotten was ever more than a killing field.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Gahrron's Withering",
			short = "Gahrron's Withering lies at the eastern edge of the Western Plaguelands, though its name once was Gahrron's Quickening, when it belonged to a farmer named Del Gahrron.",
			full = "Gahrron's Withering lies at the eastern edge of the Western Plaguelands, though its name once was Gahrron's Quickening, when it belonged to a farmer named Del Gahrron. The Scourge took the land and raised a great cauldron in the middle of the field, spewing disease-filled vapors into the air without pause, tended by Cauldron Lord Soulwrath and the officers who stand watch around it, while Haunting Visions and packs of Wailing Deaths and Hungering Wraiths move through the withered rows.\n\nThe farm remembers another death besides its own. Joseph Redpath came here corrupted, turned to the Scourge's purpose, and it was Alliance forces who cut him down on this ground. His shield was left where he fell, and it remains there still, the only marker that a man named Redpath ever stood on this farm at all.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Hearthglen",
			short = "Hearthglen sits north of Andorhal, its walls holding a peaceful order rare in the Western Plaguelands, its keep and mine and mage tower ringed by stone that has never once fallen.",
			full = "Hearthglen sits north of Andorhal, its walls holding a peaceful order rare in the Western Plaguelands, its keep and mine and mage tower ringed by stone that has never once fallen. Its history is written in the Fordrings.\n\nTirion Fordring once ruled the town from Mardenholde Keep, until he was cast out for treason after showing mercy to an orc, Eitrigg. His son Taelan later took his place as Lord of Mardenholde, and it was Taelan who opened the gates to the shattered Order of the Silver Hand after the fall of Capital City. That refuge did not last: the order was remade into the Scarlet Crusade by a man whose body was worn by a demon, and the town was seized for it.\n\nYears later Tirion tried to win his son back, sending a hidden gift into Hearthglen. Taelan agreed to abandon the zealots and meet his father outside the walls, but the betrayal was sensed, and an inquisitor was sent to silence it. Tirion arrived to find his son dying, killed the man who had done it, and swore there, over Taelan's body, to raise the Silver Hand again as a force of good. He returned to lead Hearthglen once more, and it now trains the Argent Crusade in his name.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Mardenholde Keep",
			short = "Mardenholde Keep was long the seat from which Tirion Fordring ruled Hearthglen, Arden captain of its guard.",
			full = "Mardenholde Keep was long the seat from which Tirion Fordring ruled Hearthglen, Arden captain of its guard. In the council room a great oak table stood at its center, covered by a map of the principality rendered down to the smallest detail, and there Tirion met with his advisors to weigh the safety of the land he had been given to keep. The keep's walls had never fallen, not even in the darkest years of the orcish invasion, and its people took pride in that. Tirion's downfall came when he was charged with treason for sparing the orc Eitrigg, and he was cast out and exiled.\n\nAfter the Scourging of Lordaeron, Tirion's son Taelan gave the keep to the surviving Knights of the Silver Hand, who in time renamed themselves the Scarlet Crusade. Taelan rose among them as Highlord, and Mardenholde became the heart of Scarlet rule in the region, its walls now holding the son against his father's name.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Northridge Lumber Camp",
			short = "The Northridge Lumber Camp stands where the trees of the northern Western Plaguelands have been stripped back, close to Hearthglen, the timber turned to lumber for the Scarlet Crusade's stockpiles.",
			full = "The Northridge Lumber Camp stands where the trees of the northern Western Plaguelands have been stripped back, close to Hearthglen, the timber turned to lumber for the Scarlet Crusade's stockpiles. The Crusade prized this wood enough to work the mill hard, and both the Alliance and the Horde saw the worth in denying it to them, loosing termites into the stacked timber to rot the supply from within.\n\nThe mill was not always the Crusade's. Nathaniel Dumah's family ran it before the Third War took the land from people like them. Dumah returned and reclaimed it for the Argent Crusade, though the camp now stands under siege by Northridge Spiders.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["plaguemist ravine"] = {
			name = "Plaguemist Ravine",
			short = "A mist hangs low and sickly in this ravine, where the rest of the Hinterlands stays green and clean.",
			full = "A mist hangs low and sickly in this ravine, where the rest of the Hinterlands stays green and clean. It seeps down from the north, from the Western Plaguelands, following the path that climbs toward Caer Darrow, as if the plague itself had crept south along this one narrow seam in the hills. The contrast between that poisoned air and the untouched woods around it is what gave the ravine its name.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["ruins of andorhal"] = {
			name = "Ruins of Andorhal",
			short = "Andorhal lies broken at the heart of the Western Plaguelands, its streets given over to the dead.",
			full = "Andorhal lies broken at the heart of the Western Plaguelands, its streets given over to the dead. Ghouls shamble among the ruined houses, skeletons stand where guards once did, banshees wail over the wreckage, and abominations lumber through what were once city squares. Over it all presides Araj the Summoner, a lich who has made the ruins his own, holding them with Scourge agents drawn from the corpses of whoever once lived here.\n\nThe city that stood here is gone in all but name. What remains is a shell walked by the Scourge, a place where the plague that ravaged this land found its purest expression: not a battlefield left to rot, but a settlement remade entirely into an extension of the undead that took it. No banner flies here that belongs to the living. The dead do not conquer and move on; they stay, and Andorhal is theirs.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "The Scholomance, also known as the School of Necromancy, is a vile academy for prospective necromancers of the Scourge, is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of Caer Darrow.",
			full = "The Scholomance, also known as the School of Necromancy, is a vile academy for prospective necromancers of the Scourge, is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of Caer Darrow. The layout of the dungeon changed to be less confusing, similar to how the Sunken Temple was done. Five bosses await adventurers there.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Sorrow Hill",
			short = "In gentler days, Sorrow Hill received the dead of Andorhal and the villages around it, rich and poor alike, in crypts and simple plots on the slope south of the town.",
			full = "In gentler days, Sorrow Hill received the dead of Andorhal and the villages around it, rich and poor alike, in crypts and simple plots on the slope south of the town. When the plague came and the Scourge began their raids, the hill filled faster than it could hold, its graves shallow and hurried, scarcely marked, the toll of the town's defense laid down in rows. Before long the living gave up burying their dead altogether, digging instead a mass grave south of the cemetery where they burned their own, dreading what the plague would make of them if left whole in the ground.\n\nThe last blow fell when Arthas cut down Lord Uther the Lightbringer. What remained of Andorhal's people, before they abandoned the town for good, carried Uther's broken body to the crown of the hill and raised a great tomb over it. Some say the hill itself takes its name from that grave.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril divides the Western and Eastern Plaguelands, rising near the Terrorweb Tunnel in the north and flowing down into Darrowmere Lake, where it becomes the Darrowmere River.",
			full = "The Thondroril divides the Western and Eastern Plaguelands, rising near the Terrorweb Tunnel in the north and flowing down into Darrowmere Lake, where it becomes the Darrowmere River.\n\nIts banks are no cleaner than the blighted land around them. Maggots, vampire bats, plaguebears, and spiders infest both shores, and snapjaws have since joined them. The river marks a boundary, not a refuge.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Uther's Tomb",
			short = "Uther's Tomb stands at Sorrow Hill, south of the ruins of Andorhal, the only bastion of the Light left standing in a dying land.",
			full = "Uther's Tomb stands at Sorrow Hill, south of the ruins of Andorhal, the only bastion of the Light left standing in a dying land. The Path of Uther climbs to it from the lower slopes, and the ground is held sacred by every follower of the Light who still walks the Plaguelands. High Priest Thel'danis keeps vigil over it.\n\nUther the Lightbringer died at Andorhal, cut down along with Sage Truthbearer and Ballador the Bright when the prince he had once served came for the remains of Kel'Thuzad. Arthas Menethil, no longer a man his old knights would have known, tore through their forces and took the urn holding King Terenas's remains from the corpse of the master he murdered. What was left of Uther's soldiers carried his body from that field and raised a tomb for him, a headstone showing him with a tome of Light in one hand and his warhammer in the other.\n\nThat vigil was tested when Mehlar Dawnblade, once Uther's own student, came meaning to defile the grave of the man who had trained the prince that destroyed everything. The ghost of Uther himself rose to bar him, and the tomb held.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "Weeping Cave",
			short = "The Weeping Cave sits west of the Thondroril, its low tunnels thick with bog beasts and oozes that have crept in among the dripping stone.",
			full = "The Weeping Cave sits west of the Thondroril, its low tunnels thick with bog beasts and oozes that have crept in among the dripping stone. Deeper in, an elemental called the Husk stirs but rarely, a rare and reclusive thing that hides for long stretches among the rot before showing itself again.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "Writhing Haunt",
			short = "The Writhing Haunt was once farmland, part of the fields that fed the living east of Andorhal. Nothing grows there now that would sustain a living thing.",
			full = "The Writhing Haunt was once farmland, part of the fields that fed the living east of Andorhal. Nothing grows there now that would sustain a living thing.\n\nAt the center of the field stands a great cauldron, set there by the Scourge, spewing disease-filled vapors endlessly into the air. It is not left unguarded. Cauldron Lord Razarch stands watch over it, with rotting ghouls, freezing ghouls, and fetid zombies moving through the field around him.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Eastern Plaguelands: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Blackwood Lake",
			short = "Blackwood Lake lies foul and stagnant in the Eastern Plaguelands, its waters given over to corrupted elementals. Beneath the surface, the annals say, rests the head of Horgus the Ravager.",
			full = "Blackwood Lake lies foul and stagnant in the Eastern Plaguelands, its waters given over to corrupted elementals. Beneath the surface, the annals say, rests the head of Horgus the Ravager.\n\nA town called Blackwood once stood here, home to Grand Marshal Othmar Garithos. Nothing remains of it now but the lake's name.\n\nThe Argent Dawn keeps a small camp on the shore, where a lone medic tends the infantry.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Browman Mill",
			short = "Browman Mill bears its owner's name, though nothing of him remains but what the Scourge left standing.",
			full = "Browman Mill bears its owner's name, though nothing of him remains but what the Scourge left standing. Stephen Browman worked this lumber mill until he was killed and raised as a ghoul, set to guard the place he once owned. He stands there still, faithful to the masters who killed him.\n\nThe mill now crawls with skeletons, banshees, and Abominations, mustering in the shadow of nearby Light's Hope Chapel.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Corin's Crossing",
			short = "Corin's Crossing sits at a crossroads once linking Andorhal, Darrowshire, Stratholme, and Tyr's Hand. Its town hall and blacksmith stand empty of the living now, the streets between them filled with Scourge.",
			full = "Corin's Crossing sits at a crossroads once linking Andorhal, Darrowshire, Stratholme, and Tyr's Hand. Its town hall and blacksmith stand empty of the living now, the streets between them filled with Scourge.\n\nSomething else lingers here besides the shambling dead. Unseen Servants move through the ruins unseen by mortal eyes, seeing through even the arts of those trained to vanish from sight. No stealth carries a traveler past them safely.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Crown Guard Tower",
			short = "Crown Guard Tower once stood watch over Lordaeron, until the Scourge swept through the Eastern Plaguelands and left it broken stone and silence, one more ruin among many.",
			full = "Crown Guard Tower once stood watch over Lordaeron, until the Scourge swept through the Eastern Plaguelands and left it broken stone and silence, one more ruin among many.\n\nFor a time the ruin itself became a prize. Neither Alliance nor Horde could let it lie, and both sides bled for the chance to hold its fallen walls, each hoping to turn the wreck into a foothold in the plague-lands.\n\nIt stands rebuilt now, raised again by the Argent Crusade along with the other watchtowers of the region, and serves them as an outpost. Like Light's Hope Chapel nearby, there are signs of life around it again after so much ruin.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Darrowshire",
			short = "Darrowshire once stood as a village in the south, until the Third War brought the Scourge to its gates.",
			full = "Darrowshire once stood as a village in the south, until the Third War brought the Scourge to its gates. The ghoul lord Horgus the Ravager and the death knight Marduk Blackpool led the assault, and though the defenders fought hard and won ground at first, they were overwhelmed and slaughtered to the last.\n\nThose who died did not simply die. Their bodies rose again as ghouls bound to the Scourge, spirits trapped inside the rotting flesh that once was theirs.\n\nDarrowshire stands silent and broken now, empty but for ghosts. Rarely, the ruins stir, and the battle plays itself out again, phantom against phantom, the dead relighting a fight already lost.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Eastwall Gate",
			short = "The Eastwall Gate stands as the side entrance to Stratholme, opening directly onto Elder's Square, where Alonsus Chapel keeps its watch and Aurius still resides.",
			full = "The Eastwall Gate stands as the side entrance to Stratholme, opening directly onto Elder's Square, where Alonsus Chapel keeps its watch and Aurius still resides.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Eastwall Tower",
			short = "Eastwall Tower once stood watch over the Eastern Plaguelands, until the Scourge invasion of Lordaeron threw it down and left it in ruins.",
			full = "Eastwall Tower once stood watch over the Eastern Plaguelands, until the Scourge invasion of Lordaeron threw it down and left it in ruins.\n\nWhat came after was not reconquest but contest. Alliance and Horde fought over the fallen tower again and again, each seeking to hold its stones as a foothold to fortify themselves in the ruined kingdom.\n\nThe tower stands rebuilt now, raised up by the Argent Crusade along with its sister towers across the Plaguelands. Where there was rubble there are now signs of life, much as at nearby Light's Hope Chapel, and the old quarrel over its stones has gone quiet.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Fungal Vale",
			short = "The ground of the Fungal Vale has turned a sickly purple, wrapped in a murky haze where the Plague of Undeath runs deepest through the Eastern Plaguelands.",
			full = "The ground of the Fungal Vale has turned a sickly purple, wrapped in a murky haze where the Plague of Undeath runs deepest through the Eastern Plaguelands. The Scourge holds this ground alongside the Cult of the Damned, working freely in the mist. It lies north of the Marris Stead and the Crown Guard Tower.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "Infectis Scar",
			short = "The Infectis Scar was not cut by water, like the Pestilent Scar nearby. It was torn open by a broken sword.",
			full = "The Infectis Scar was not cut by water, like the Pestilent Scar nearby. It was torn open by a broken sword.\n\nNear Corin's Crossing, the death knight Marduk Blackpool's runesword shattered against a dwarf captain's shield. He kept the hilt and let the blade fall. Where the evil steel struck the blighted earth, the ground gave way, opening into the chasm that now holds this dark lake.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Lake Mereldar",
			short = "Lake Mereldar lies south of Corin's Crossing, its waters fouled by the blight and stirred by corrupted water elementals.",
			full = "Lake Mereldar lies south of Corin's Crossing, its waters fouled by the blight and stirred by corrupted water elementals. Along its shore stand the ruins of an old house, and a shack and ferry that once belonged to a farm long since abandoned.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Light's Hope Chapel",
			short = "Light's Hope Chapel is the Argent Crusade base of operations in the Eastern Plaguelands, and a place of comfort for those who make the journey here.",
			full = "Light's Hope Chapel is the Argent Crusade base of operations in the Eastern Plaguelands, and a place of comfort for those who make the journey here. Located on the slopes of a mountainous area east of the region, it was originally a mere chapel of the Church of the Holy Light, until it expanded into a full-fledged fortified outpost after the end of the Scourgewar. Underneath is the Sanctum of Light, catacombs which house the remains of the heroes of Lordaeron. Many were exhumed from around Lordaeron and moved to here so they could not be resurrected in the service of the Lich King.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "Marris Stead",
			short = "This homestead on its ridge was once the home of Nathanos Marris, whose skill at arms was renowned, and whom Sylvanas Windrunner would visit.",
			full = "This homestead on its ridge was once the home of Nathanos Marris, whose skill at arms was renowned, and whom Sylvanas Windrunner would visit.\n\nWhen Stratholme fell and the Scourge poured across Lordaeron, Nathanos died defending his own house, cut down by the abomination Ramstein the Gorger. He rose again as a mindless thrall bound to the Lich King, and it was near this very stead that Sylvanas's dark rangers finally tracked him down.\n\nOnce she had broken the Lich King's hold over him and made him one of the Forsaken, Sylvanas sent Nathanos back to the home he had died in. He returned with his blighthounds and set about recruiting soldiers to hold the Plaguelands against the Scourge and the Scarlet Crusade. He also gathered relics from the battle of Darrowshire and kept them within the house, for reasons he told no one.\n\nHis presence did not stay hidden. Agents sent to investigate strange reports of Forsaken activity around the stead vanished, and the truth that came out was worse than feared: Nathanos himself had become the Blightcaller, remade as the Banshee Queen's champion.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "At the heart of Zul'Mashar rises Mazra'Alor, a great ziggurat of stone.",
			full = "At the heart of Zul'Mashar rises Mazra'Alor, a great ziggurat of stone. Forest trolls of the Mossflayer tribe hold it still, their shadow hunters keeping to its heights and terraces, watching over the ruined jungle city that has grown up around them.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Northdale",
			short = "Northdale is a ruin now. Here Taelan Fordring turned his back on the Order of the Silver Hand and gave himself to the Scarlet Crusade instead.",
			full = "Northdale is a ruin now. Here Taelan Fordring turned his back on the Order of the Silver Hand and gave himself to the Scarlet Crusade instead.\n\nNothing living has reclaimed the town. Banshees drift among the broken walls, and unseen watchers linger in the shadows. The nearby lake holds only corrupted water elementals.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Northpass Tower",
			short = "Northpass Tower stands at the farthest edge of the Eastern Plaguelands, where the road runs north toward the Ghostlands of Quel'Thalas.",
			full = "Northpass Tower stands at the farthest edge of the Eastern Plaguelands, where the road runs north toward the Ghostlands of Quel'Thalas. It was one of the watchtowers thrown down when the Scourge swept through Lordaeron, left as broken stone.\n\nAfterward it became ground worth fighting over rather than living in, as Alliance and Horde both sought to fortify themselves in the blighted kingdom by holding its ruins.\n\nThe Argent Crusade has since rebuilt it, along with the other fallen towers of the plaguelands, turning it into an outpost. Where there was once only ruin and contested ground, there are signs of life again, much as at Light's Hope Chapel nearby.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "Noxious Glade",
			short = "The Noxious Glade lies up a hill north of Light's Hope Chapel, in a hollow the Scourge has claimed for its own.",
			full = "The Noxious Glade lies up a hill north of Light's Hope Chapel, in a hollow the Scourge has claimed for its own. Even against the ruin of the Eastern Plaguelands, this ground stands apart: the air hangs thick and sickly green, and the earth has gone the color of a bruise, dark purple where the blight has soaked deepest.\n\nA plague cauldron sits within the glade, feeding the corruption outward, alongside a slaughterhouse and raised ziggurats. A tunnel called the Noxious Pass connects the glade to Death's Breach.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Pestilent Scar",
			short = "The Pestilent Scar is a deep gorge in the blighted earth, its shape more natural than the nearby Infectis Scar, as though a lake once dried here before something filled it again to the rim.",
			full = "The Pestilent Scar is a deep gorge in the blighted earth, its shape more natural than the nearby Infectis Scar, as though a lake once dried here before something filled it again to the rim.\n\nNow the water stands dark and thick, home to oozes. The Argent Crusade has raised bridges across the gorge, the only way over the water.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Plaguewood",
			short = "The Plaguewood stretches south from Stratholme toward Terrordale, and once it was a gentle woodland, the kind of green country a traveler might have found in Elwynn Forest.",
			full = "The Plaguewood stretches south from Stratholme toward Terrordale, and once it was a gentle woodland, the kind of green country a traveler might have found in Elwynn Forest. A small village stood near the arch at the forest's entrance. That peace ended when the grain poisoned at Andorhal found its way here. A Lordaeronian soldier named Sergeant Morigan, stationed in the village, was the first to sense that something in his home had gone wrong. By the time the Scourging of Lordaeron was done, the forest was already ruined.\n\nThe land itself changed. The soil turned soft and spongy underfoot, and the trees gave way to fungus grown monstrous, toadstools dwarfing what remained of the old canopy, some venting a dark brown gas not unlike the vapor that hisses from the Scourge's plague cauldrons. The forest earned a new name from it: the Plaguewood.\n\nNow ziggurats and slaughterhouses fill the woodland, thick with the Scourge, while Scarlet Crusade patrols work the road to and from Stratholme, cutting down undead and any living travelers unlucky enough to cross their path.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Quel'Lithien Lodge",
			short = "Quel'Lithien Lodge stood near the entrance to Quel'Thalas, one of two great gatherings of the high elves in Lordaeron, a Farstrider camp where rangers came and went freely and were greeted warmly as kin.",
			full = "Quel'Lithien Lodge stood near the entrance to Quel'Thalas, one of two great gatherings of the high elves in Lordaeron, a Farstrider camp where rangers came and went freely and were greeted warmly as kin. By the Second War its hunters answered to Renthar Hawkspear.\n\nThe Scourge invasion of Quel'Thalas broke that warmth. The teachings practiced at the lodge had become a source of division dangerous enough that Lor'themar, now regent of a wounded nation, exiled the group south rather than let the quarrel tear the kingdom apart. Among those cast out was the priestess Aurora Skycaller. From then on the lodge was no longer a waypoint but a home, and a bitter one.\n\nCut off from their homeland, the exiles heard nothing of what followed until Lor'themar made one last journey south to tell them himself, and to offer aid now that the land stood safer. Renthar's answer was fury: he refused outright and swore to kill any messenger sent bearing it. Lor'themar could not blame him for that anger, only grieve for it, and left in sorrow.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Scarlet Base Camp",
			short = "The Scarlet Base Camp stands barricaded on the eastern shore of Lake Mereldar, within sight of the religious bastion of Tyr's Hand.",
			full = "The Scarlet Base Camp stands barricaded on the eastern shore of Lake Mereldar, within sight of the religious bastion of Tyr's Hand. Its defenses were reinforced, for the camp guards something more than the lakeshore itself: within it lies the entrance to the Scarlet Enclave.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "Scarlet Basilica",
			short = "The Scarlet Basilica stands at the heart of Tyr's Hand, the high seat of religious power for the Scarlet Crusade, bound to the nearby Tyr's Hand Abbey and to the Scarlet Monastery in Tirisfal Glades.",
			full = "The Scarlet Basilica stands at the heart of Tyr's Hand, the high seat of religious power for the Scarlet Crusade, bound to the nearby Tyr's Hand Abbey and to the Scarlet Monastery in Tirisfal Glades. Crusader Lord Valdelmar holds his place within its walls.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "Stratholme (or Stratholme City) was the northernmost and second-most populous city of the kingdom of Lordaeron. It was here that the Order of the Silver Hand was founded prior to the Second War.",
			full = "Stratholme (or Stratholme City) was the northernmost and second-most populous city of the kingdom of Lordaeron. It was here that the Order of the Silver Hand was founded prior to the Second War. Years later, the port city was plagued by the Cult of the Damned, using infected grain from Andorhal, and its population was ultimately purged by the mad Prince Arthas Menethil. In the aftermath, Stratholme became the Scourge's capital in Lordaeron after the undead moved in, and is still burning to this day.\n\nThe city included many well-known buildings, from the glorious Bastion of the Silver Hand to Ezra Grimm's famous tobacco shop.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Terrordale",
			short = "Terrordale stands empty at the edge of the Plaguewood, given over to the Scourge and to plagued animals.",
			full = "Terrordale stands empty at the edge of the Plaguewood, given over to the Scourge and to plagued animals. Only two living souls keep to its streets: Augustus the Touched, who still trades among the ruin, and Egan, who hunts the dead that do not stay buried.\n\nFor Terrordale was haunted, and not gently. Spirits walked there, and in places the town itself seemed to give way beneath them, the physical world buckling under the weight of the spirit realm pressing through.\n\nLord Grayson Shadowbreaker turned this suffering ground to a purpose. He sent paladins to exorcise Terrordale's spirits, not merely to cleanse the town but to prove something of those who undertook it, judgment and sacrifice, before they could be given their chargers.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Terrorweb Tunnel",
			short = "The tunnel bores through the mountain northwest of Terrordale, opening south onto the Thondroril River. Nerubian crypt fiends have claimed it entirely, thick along its length in the dark.",
			full = "The tunnel bores through the mountain northwest of Terrordale, opening south onto the Thondroril River. Nerubian crypt fiends have claimed it entirely, thick along its length in the dark. Among them stalks something worse: a Nerubian Overseer, elite and powerful, that turns a dangerous crossing into something far worse.\n\nAt the river entrance stands Tirion Fordring, keeping watch over the mouth of the tunnel where the nerubian dark spills into daylight.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril divides the Western and Eastern Plaguelands, rising near the Terrorweb Tunnel in the north and flowing down into Darrowmere Lake, where it becomes the Darrowmere River.",
			full = "The Thondroril divides the Western and Eastern Plaguelands, rising near the Terrorweb Tunnel in the north and flowing down into Darrowmere Lake, where it becomes the Darrowmere River.\n\nIts banks are no cleaner than the blighted land around them. Maggots, vampire bats, plaguebears, and spiders infest both shores, and snapjaws have since joined them. The river marks a boundary, not a refuge.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Tyr's Hand",
			short = "Tyr's Hand stands in the mountains of the southeastern Plaguelands, its ground spared the worst of the blight even as its trees decay.",
			full = "Tyr's Hand stands in the mountains of the southeastern Plaguelands, its ground spared the worst of the blight even as its trees decay. It takes its name from the keeper Tyr, who lost his hand to the proto-dragon Galakrond and had one of silver forged for him by the watcher Jotun. Tyr died far from here, but his name remained on this city, one of the oldest and most revered holy sites of the Church of the Light, a city of churches built around the Scarlet Basilica and a fortified abbey.\n\nWhen the Third War turned the Eastweald into the Plaguelands, Tyr's Hand did not fall. Lord Valdelmar held it through daily assaults by the undead, allying first with the Knights of the Silver Hand and then with the Scarlet Crusade, sending supplies and reinforcements out to other Scarlet holdouts even as the rest of the region burned around it.\n\nIn the end no blade of the Scourge took the city. Every Crusader within its walls was turned to undeath from within, Valdelmar among them, and the Brotherhood of the Light marched against their own former allies, cut down the undead leadership, and took Tyr's Hand for their own.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "Undercroft",
			short = "The Undercroft is a crypt in the southwestern Eastern Plaguelands, home to a band of undead trolls led by the undead dire troll Zaeldarr the Outcast, who raids the Argent Dawn's grave pit at Light's Hope Chapel for bodies.",
			full = "The Undercroft is a crypt in the southwestern Eastern Plaguelands, home to a band of undead trolls led by the undead dire troll Zaeldarr the Outcast, who raids the Argent Dawn's grave pit at Light's Hope Chapel for bodies. Among the tombs stands a false grave marked for Tirion Fordring.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Zul'Mashar was once the seat of the Mossflayer tribe, forest trolls who held this corner of the Eastern Plaguelands.",
			full = "Zul'Mashar was once the seat of the Mossflayer tribe, forest trolls who held this corner of the Eastern Plaguelands. Years of war with the humans of Lordaeron left their lands in ruin, and what they clawed back was finished off by the plague of undeath. The ziggurat of Mazra'Alor still rises above the wreckage, but the city is only a shadow of what it was.\n\nWorse, the Mossflayers who remain are being quietly turned toward undeath, so their own capital now edges toward becoming another foothold for the Scourge. Warlord Thresh'jin and Zul'Brin Warpbranch hold what is left of the tribe against that slow corruption.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Hillsbrad Foothills: 29 subzones
	[1424] = {
		["alterac mountains"] = {
			name = "Alterac Mountains",
			short = "Rain never quite stops falling on these peaks. Once the Alteraci tribe held these slopes, until their leader Ignaeus lost a duel to King Thoradin and bent the knee to Arathor.",
			full = "Rain never quite stops falling on these peaks. Once the Alteraci tribe held these slopes, until their leader Ignaeus lost a duel to King Thoradin and bent the knee to Arathor. From that surrender grew a city-state that came to rule much of the northlands from among the summits, its name given to the whole range.\n\nThat kingdom betrayed the Alliance of Lordaeron during the Second War, and Lordaeron's armies marched into the mountains to strike Alterac at its heart. The city fell, and its ruins were later claimed by the Crushridge ogres under their warlord Mug'thol. The royal line did not vanish quietly: the exiled prince Aliden Perenolde returned in the guise of the Syndicate, a company of fallen nobles and rogues who still hold Strahnbrad and other corners of the range, warring endlessly with the ogres.\n\nDalaran, too, once stood here, a city-state of its own among these heights, before it was sealed within an impregnable shell and lifted whole into the sky, leaving only a crater behind.\n\nWhat Alliance presence remains clings to the entrances of Alterac Valley, where Stormpike dwarves and Frostwolf orcs still contest the frontier.",
			source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
		},
		["azurelode mine"] = {
			name = "Azurelode Mine",
			short = "Before the Greymane Wall sealed Gilneas away, Azurelode Mine and the hill above it belonged to that kingdom.",
			full = "Before the Greymane Wall sealed Gilneas away, Azurelode Mine and the hill above it belonged to that kingdom. It lies in the southwestern Hillsbrad Foothills, south of Hillsbrad Fields and west of what was once Southshore.\n\nLater it became an Alliance mine, worked by miners under Foreman Bonds out of Hillsbrad Fields, guarded and kept running to supply iron to Alliance armories.\n\nThat order has broken. Spiders' paralytic poison has taken the sentries, the foreman, and the miners who could not flee in time, and they lie helpless where they fell, kept rather than killed, held for use at the Sludge Fields to the north.\n\nThe mine's own creatures, the domesticated Mine Creepers, have gone unfed for days, and hunger has turned them against the paralyzed humans in their reach; they no longer answer to command.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Chillwind Point",
			short = "Chillwind winds pour down from the Western Plaguelands through the ravine below, cold enough to cut, sweeping a rise that once belonged to Lordaeron.",
			full = "Chillwind winds pour down from the Western Plaguelands through the ravine below, cold enough to cut, sweeping a rise that once belonged to Lordaeron. At its heart stands a troll ruin far older than the kingdom that later claimed this pass. Bath'rah the Windwatcher, a jungle troll, keeps to it still, friendly to those who pass.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Corrahn's Dagger",
			short = "Corrahn's Dagger, second finger of Hillsbrad, once belonged to the Syndicate before it fell from their grasp.",
			full = "Corrahn's Dagger, second finger of Hillsbrad, once belonged to the Syndicate before it fell from their grasp. Now the Stormpike clan holds it as a forward camp, gathering for their assault on the Forsaken, with Captain Iceheart commanding the dwarves stationed there.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Crushridge Hold",
			short = "The Crushridge ogres have dug their mound into the earth near the Ruins of Alterac, and around it their encampments spread across the mountainside.",
			full = "The Crushridge ogres have dug their mound into the earth near the Ruins of Alterac, and around it their encampments spread across the mountainside. The cave holds a large number of them still.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["dandreds fold"] = {
			name = "Dandred's Fold",
			short = "A farm and manor stands on the western edge of the Uplands, its harbor giving onto Lordamere Lake and the Misty Shore.",
			full = "A farm and manor stands on the western edge of the Uplands, its harbor giving onto Lordamere Lake and the Misty Shore.\n\nHere lived Aliden, and here he kept a necklace that had once belonged to Taretha Foxton. His life ended at this fold, and it was his mistress Elysa, wearing the necklace herself, who gave it up, fearing that she would be harmed as he had been.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["darrow hill"] = {
			name = "Darrow Hill",
			short = "Darrow Hill lies beneath the Headland in the northern Hillsbrad Foothills.",
			full = "Darrow Hill lies beneath the Headland in the northern Hillsbrad Foothills. Mountain lions and stags range across its open fields, and within the Foothill Caverns dwell yetis, guarding seams of Alterac granite in the rock.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok stood in the southeastern hills of Hillsbrad, a dwarven keep under Captain Ironhill.",
			full = "Dun Garok stood in the southeastern hills of Hillsbrad, a dwarven keep under Captain Ironhill. His garrison guarded the humans of Hillsbrad and watched over the Azurelode Mine, and for that the Forsaken hated them, unable to abide dwarves holding ground so close to their reach.\n\nThe Forsaken came against Dun Garok outnumbering the dwarves ten to one. Ironhill's garrison did not yield the walls. They fought until every dwarf among them was dead, and the keep fell only because there was no one left standing to hold it.\n\nDeath did not settle the matter. The fallen dwarves rose again as spirits, and they kept their fortress still, haunting the hills and refusing to let it go even without flesh to defend it. The Forsaken, unable to root out the dead, abandoned the attempt and left the spirits to their ruin. Captain Ironhill's ghost remains among them, lingering not for vengeance but out of grief for the people who stayed behind with him.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Durnholde Keep",
			short = "Durnholde Keep is a ruined stronghold located east of the town of Tarren Mill in the Hillsbrad Foothills. It used to be an internment camp and prison for the orcs.",
			full = "Durnholde Keep is a ruined stronghold located east of the town of Tarren Mill in the Hillsbrad Foothills. It used to be an internment camp and prison for the orcs.\n\nAlong with its inner barracks, Durnholde also had a mage tower and an arena.\n\nThe small village that encircled Durnholde was inhabited by those who made their living off tending to the needs of the fortress's inhabitants.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Eastern Strand",
			short = "The Eastern Strand runs along the southeastern shore of Hillsbrad Foothills, its sands and shallows claimed by the Daggerspine naga, coiled in the surf and along the beach.",
			full = "The Eastern Strand runs along the southeastern shore of Hillsbrad Foothills, its sands and shallows claimed by the Daggerspine naga, coiled in the surf and along the beach. Among their dead, plans for an attack have been found, carried on their persons, hinting at some design the sea-born naga mean to see through.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Gallows' Corner",
			short = "The crossroads at Gallows' Corner sits near the Ruins of Alterac, marked by a scout tower long since fallen to ruin.",
			full = "The crossroads at Gallows' Corner sits near the Ruins of Alterac, marked by a scout tower long since fallen to ruin. Crushridge ogres now hold the ground, pacing the roads where they meet, and nothing passes here without their notice.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Gavin's Naze",
			short = "The last of Hillsbrad's four fingers is the most guarded. The Stormpike clan holds it, raising siege engines here to loose upon the Forsaken when the time comes.",
			full = "The last of Hillsbrad's four fingers is the most guarded. The Stormpike clan holds it, raising siege engines here to loose upon the Forsaken when the time comes.\n\nBefore the dwarves took the hill, mountain lions roamed it, among them the uniquely colored Araga.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Growless Cave",
			short = "Growless Cave lies in the Alterac Mountains, home to mountain yeti, with Skhowl often prowling near its entrance.",
			full = "Growless Cave lies in the Alterac Mountains, home to mountain yeti, with Skhowl often prowling near its entrance.\n\nDeep inside once stood the Flame of Uzel, a pyre built by the human Helcular for his ritual to become a lich. Burning meat upon it would draw the great yeti Frostmaw to the cave. The flame is gone now, but the yeti remain.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "Headland",
			short = "The Headland is the third of the four fingers reaching out from Hillsbrad. The Stormpike clan raised a training camp here, where soldiers drill under Instructor Rufus, Drill Sergeant Magnus, and Captain Crudbeard.",
			full = "The Headland is the third of the four fingers reaching out from Hillsbrad. The Stormpike clan raised a training camp here, where soldiers drill under Instructor Rufus, Drill Sergeant Magnus, and Captain Crudbeard.\n\nOn the cliffside above, Araga and her cubs rest, undisturbed by the clash of drilling soldiers below.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Hillsbrad Fields",
			short = "The Hillsbrad Fields refers to the area which included the town of Hillsbrad and a large and fertile cultivated area that provided food for the people of Southshore and the whole of Hillsbrad Foothills.",
			full = "The Hillsbrad Fields refers to the area which included the town of Hillsbrad and a large and fertile cultivated area that provided food for the people of Southshore and the whole of Hillsbrad Foothills.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Lordamere Lake spreads beneath the shadow of what was once the greatest of human capitals, and it takes its name from the city that stood on its northern shore, itself named for old Lordain.",
			full = "Lordamere Lake spreads beneath the shadow of what was once the greatest of human capitals, and it takes its name from the city that stood on its northern shore, itself named for old Lordain. In the years when the Alliance of Lordaeron was young and its kingdoms prosperous, Lordaeron, Dalaran, and Alterac all rose within sight of these waters.\n\nAfter the Third War, when Dalaran lay in ruins, Lady Vashj led her naga to these shores and made them a refuge, retreating here after the fighting at the fallen city.\n\nThe lake has since become a border of a different kind, separating the Forsaken holdings of Tirisfal Glades and Silverpine Forest from the disputed heights of the Alterac Mountains. At its heart sits Fenris Isle, whose keep fell to the Forsaken under Deathstalker Hayward, and the Horde used fighting there as cover to slip Undercity refugees across the water to safety.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["misty shore"] = {
			name = "Misty Shore",
			short = "Mist hangs low along the waterline between Dandred's Fold and Dalaran Crater, where turtles move slowly through the shallows.",
			full = "Mist hangs low along the waterline between Dandred's Fold and Dalaran Crater, where turtles move slowly through the shallows. For a time the shore was watched by two of the Scarlet Crusade, zealous enough to fall upon anyone who came too near.\n\nAcross the water, the Dawning Isles can be seen, and beyond them the grim shape of Fenris Keep.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Nethander Stead",
			short = "The fields east of Southshore once belonged to the Nethander family, but now Mudsnout gnolls hold the farm, and nowhere else do their kind live.",
			full = "The fields east of Southshore once belonged to the Nethander family, but now Mudsnout gnolls hold the farm, and nowhere else do their kind live.\n\nGreat white mushrooms, called Mudsnout Blossoms, push up through the neglected soil. Apothecary Lydon once prized them for his deadly Elixir of Agony. Now Kingslayer Orkus wants them, hoping they might save his dying mount.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Purgation Isle",
			short = "The isle rises out of the water south of Hillsbrad in a single climbing spiral, its slopes given over to a cemetery and the broken shell of a scout tower.",
			full = "The isle rises out of the water south of Hillsbrad in a single climbing spiral, its slopes given over to a cemetery and the broken shell of a scout tower. Before the First War it belonged to Kul Tiras, held as part of that kingdom's reach along these shores.\n\nThe isle later became the site of a council meant to stay secret: Ivar Bloodfang, Balinda Stonehearth, and Vanndar Stormpike gathered there to weigh how Hillsbrad might be wrested back from the Horde. The meeting did not stay hidden. Kingslayer Orkus struck at the isle astride the frost wyrm Kasha, and in the fighting the battle plans were seized from the gathered commanders. The theft succeeded, but it cost Orkus his life -- he took wounds he did not recover from, dying with the plans already carried away.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Ravenholdt Manor",
			short = "Ravenholdt Manor sits apart, hidden on a plateau where the Alterac Mountains meet the Hillsbrad Foothills, reached only by a narrow path that twists back on itself and passes through a cave before opening onto the manor grounds.",
			full = "Ravenholdt Manor sits apart, hidden on a plateau where the Alterac Mountains meet the Hillsbrad Foothills, reached only by a narrow path that twists back on itself and passes through a cave before opening onto the manor grounds. It is not a place that welcomes strangers.\n\nThe manor belongs to Lord Jorach Ravenholdt, and its roof still wears the orange of Alterac, a mark of the kingdom that once held this ground before the First War tore it apart. Within its walls, Simone Cantrell tends the garden and Master Kang oversees the training arena, but the house is otherwise closed to outsiders.\n\nWhen the Syndicate spread through the Highlands in the years after Alterac's fall, Jorach Ravenholdt did what his own people could not: he opened his manor to SI:7, letting Stormwind's agents use his home as their base to root out the Syndicate's hold on the region. It was an old lord's house lent to a foreign purpose, and it worked.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["ruins of alterac"] = {
			name = "Ruins of Alterac",
			short = "Broken walls climb the slopes of the Alterac Mountains where a city once stood, its palace half-standing, its church and town hall fallen in on themselves, its gate built in the fashion of Stormwind's own.",
			full = "Broken walls climb the slopes of the Alterac Mountains where a city once stood, its palace half-standing, its church and town hall fallen in on themselves, its gate built in the fashion of Stormwind's own.\n\nIts ruin came from its own king. During the Second War, King Aiden Perenolde turned traitor, casting his lot with the Orcish Horde against his fellow humans. Alteraci soldiers were found fighting alongside the orcs, and a prison camp near the city held captive citizens of Dalaran. When the truth came out, the other human kingdoms marched on Alterac in retaliation. The people fled or were driven from their homes, and King Terenas Menethil II of Lordaeron declared the city under martial law, casting Perenolde down and throwing him into chains.\n\nThe city never rose again. Crushridge ogres, led by Mug'thol, settled into the empty streets and palace, while the scattered remnants of the old Alteraci people held the outlying villages beyond. Wrecked meat wagons still lie near the northern rampart and the gate, and the graveyards within and beyond the walls, the snow-buried farm, and shattered ballistae among the rubble remain as they were left.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["slaughter hollow"] = {
			name = "Slaughter Hollow",
			short = "Deep in the Alterac Mountains, Slaughter Hollow rises as a mound of packed earth and refuse, the seat of the Crushridge ogres.",
			full = "Deep in the Alterac Mountains, Slaughter Hollow rises as a mound of packed earth and refuse, the seat of the Crushridge ogres. Nothing here is built to human scale; the ground itself has been beaten into ramps and dens by generations of heavy tread.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Sofera's Naze",
			short = "The Syndicate once held this rise, one of the four fingers of Hillsbrad, until SI:7 came to root them out, called in by the Stormpike clan.",
			full = "The Syndicate once held this rise, one of the four fingers of Hillsbrad, until SI:7 came to root them out, called in by the Stormpike clan. Where the Syndicate's watch used to stand, a small scouting camp now keeps the hill instead.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Southpoint Tower",
			short = "Southpoint Tower stands broken at the western edge of Hillsbrad Foothills, south of the road into Silverpine Forest.",
			full = "Southpoint Tower stands broken at the western edge of Hillsbrad Foothills, south of the road into Silverpine Forest. The Forsaken have set a Deathstalker named Lesh among its stones, watching the road for Alliance movement. It is lonely work, her post far from any other Forsaken presence, and she has fallen more than once to those she was sent to watch, with no one near enough to help her.\n\nThe tower was not always a ruin. It stood whole as a human structure until the Forsaken at last won the long battle for Hillsbrad. In victory they tore it down completely and raised Southpoint Gate on the ground where it had stood, leaving no trace of what came before.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad sits empty now on the northeastern foothills of the Alterac Mountains, its town hall and blacksmith abandoned to the wind near the border of the Western Plaguelands.",
			full = "Strahnbrad sits empty now on the northeastern foothills of the Alterac Mountains, its town hall and blacksmith abandoned to the wind near the border of the Western Plaguelands.\n\nIn the last uneasy years before the Third War, Blackrock orcs came down on the village to take slaves for burning in the Legion's name. Strahnbrad had almost nothing to defend it, only a handful of footmen, but they got word out before the attack started. The Knights of the Silver Hand answered. Uther the Lightbringer rode for the orc camp itself, hoping to stop the raid before it began, and sent Prince Arthas Menethil ahead to hold the town if he failed.\n\nHe failed. By the time Arthas reached Strahnbrad the attack was already underway, and Dean, Joe, Mike, Scott, and many others were already dead. What defenders remained joined him, and together they broke the orcs, killing the Slave Master who had led the raid. The Alliance held the field, but the village never recovered from what it lost that day.\n\nThe Syndicate holds Strahnbrad now, using the ruined town to claw the Alterac Mountains back for themselves.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Tarren Mill",
			short = "Tarren Mill did not stay in human hands. The Forsaken took it and rebuilt it gaunt and grey, in the style carried south from Northrend.",
			full = "Tarren Mill did not stay in human hands. The Forsaken took it and rebuilt it gaunt and grey, in the style carried south from Northrend. Only an old barn on the outskirts still remembers what the town once was. From here the Forsaken made war on Southshore to the south, a bitter, unending skirmish between the two towns, until Southshore fell to ruin and Tarren Mill stood alone as the Horde's bastion over Hillsbrad.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "King Thoradin raised his wall soon after Strom became a capital, a barrier meant to hold the Amani trolls off the newborn empire of Arathor.",
			full = "King Thoradin raised his wall soon after Strom became a capital, a barrier meant to hold the Amani trolls off the newborn empire of Arathor. For generations it stood, a promise that humanity would not be pushed back into the sea.\n\nThe promise broke once. Faerin Lothar was told, as a child, of a curse that fell upon Arathor, twisting men and beasts into something monstrous, and of how an army of those ruined things finally broke through the wall that had never fallen before. Centuries on, the stone still bears that wound, standing gouged and crumbled where the curse tore its way through.\n\nFaerin returned to it grown, walking beside Danath Trollbane on his way to settle a quarrel between Hammerfall and Stromgarde. She had only heard the wall in stories, and stood awestruck before it. Danath called it just a wall, warning her that too much reverence for such legends bred the same pride that had once turned Stromgarde against its neighbors.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["uplands"] = {
			name = "Uplands",
			short = "The Uplands once fed the kingdom of Alterac, its hills tilled and grazed to fill royal granaries.",
			full = "The Uplands once fed the kingdom of Alterac, its hills tilled and grazed to fill royal granaries. When the heart of that nation was destroyed, the Uplands fell to the Syndicate, who hold no ground in the Alterac Mountains more firmly than here. Their camps cover the hills, ruled in the Baron Vardus's name. In the westernmost reach stands Dandred's Fold, a remnant of the old order amid fields that feed no one now.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
		["western strand"] = {
			name = "Western Strand",
			short = "The Western Strand lies along the southwest coast of Hillsbrad Foothills. Torn Fin murlocs have built small camps along its shore, and Andy Murgole patrols the stretch of sand between them.",
			full = "The Western Strand lies along the southwest coast of Hillsbrad Foothills. Torn Fin murlocs have built small camps along its shore, and Andy Murgole patrols the stretch of sand between them.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- The Hinterlands: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Aerie Peak",
			short = "The Wildhammer dwarves did not choose the Hinterlands first.",
			full = "The Wildhammer dwarves did not choose the Hinterlands first. Their home was Grim Batol, deep in the mountain, until the War of the Three Hammers ended and the dwarves returned to find their fortress poisoned by the death of Modgud. Grim Batol could not be lived in again. So the Wildhammers built anew here, atop the mountainside rather than within it, unwilling after the horrors of tunnel-fighting against the Dark Iron dwarves to bury themselves in stone again. The Aerie stands open to the sky because of that war.\n\nIt was from here that Kurdran Wildhammer led his gryphon riders against orc forces sent to strike the Hinterlands as a feint while the true Horde army moved on Quel'Thalas. Anduin Lothar's forces came to his aid and helped drive the orcs and forest trolls from Wildhammer land, and for that Kurdran pledged his clan to the Alliance.\n\nFalstad Wildhammer, left as High Thane when Kurdran did not return, rules the Aerie still. The forest trolls of the Hinterlands, who call the Wildhammers squatters on ancestral ground, still raid the gryphon aeries, while the high elves of Quel'Danil remain the dwarves' allies against that same enemy.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Agol'watha lies in ruin in the north-central Hinterlands, a temple raised by the Amani Empire and later claimed by the Vilebranch trolls, who set broodguards to watch over the eggs of Shadra's brood among its stones.",
			full = "Agol'watha lies in ruin in the north-central Hinterlands, a temple raised by the Amani Empire and later claimed by the Vilebranch trolls, who set broodguards to watch over the eggs of Shadra's brood among its stones. The eye of Shadra was once kept here, guarded until it was carried away. Now animated sludges have overrun the crumbling temple.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "Altar of Zul",
			short = "At the top of the Altar of Zul stands Qiaga the Keeper, watching over the stones the Vilebranch trolls raised in the Hinterlands.",
			full = "At the top of the Altar of Zul stands Qiaga the Keeper, watching over the stones the Vilebranch trolls raised in the Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Bogen's Ledge",
			short = "Bogen's Ledge is a cave in the southwestern Hinterlands. Two trolls, Mai'jin and Tcha'kaz, once held it, until Ambassador Rualeth at Aerie Peak sought their deaths as a gesture of goodwill.",
			full = "Bogen's Ledge is a cave in the southwestern Hinterlands. Two trolls, Mai'jin and Tcha'kaz, once held it, until Ambassador Rualeth at Aerie Peak sought their deaths as a gesture of goodwill. With the trolls gone, the cave stands empty now, serving no purpose.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "Creeping Ruin",
			short = "The Creeping Ruin was once a forest troll ruin, its stones taken over by hostile slimes that crept through the broken halls.",
			full = "The Creeping Ruin was once a forest troll ruin, its stones taken over by hostile slimes that crept through the broken halls. Those slimes are gone now, and the ruin belongs to the spider children of Shadra, who have claimed the old troll stones as their own.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Featherbeard's Hovel",
			short = "Featherbeard's Hovel stands beside Aerie Peak in the Hinterlands, a small house that once belonged to Featherbeard. It is quiet now, holding nothing more than the memory of the one who lived there.",
			full = "Featherbeard's Hovel stands beside Aerie Peak in the Hinterlands, a small house that once belonged to Featherbeard. It is quiet now, holding nothing more than the memory of the one who lived there.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "The Witherbark trolls hold Hiri'watha south of Quel'Danil Lodge, deep in the Hinterlands woods.",
			full = "The Witherbark trolls hold Hiri'watha south of Quel'Danil Lodge, deep in the Hinterlands woods.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Jintha'Alor (also spelled Jintha'alor) is a forest troll city of the located in the Hinterlands. Jintha'Alor was built by the trolls of the Amani Empire, and named after Jintha, a leader of the Amani in ancient times.",
			full = "Jintha'Alor (also spelled Jintha'alor) is a forest troll city of the located in the Hinterlands. Jintha'Alor was built by the trolls of the Amani Empire, and named after Jintha, a leader of the Amani in ancient times. It is the second largest city of the forest trolls, second only to Zul'Aman. It was ruled by the Vilebranch tribe for many years and used as a fortress to sacrifice others.\n\nThe Totem of Akil'darah can be found here. Both the Wildhammer clan and Revantusk tribe laid siege to the city, seeking to end the Vilebranch's incursions upon their land and claim vengeance for their fallen kindred. In the aftermath of this attack, the Revantusk took a step further and claimed the city for their tribe and the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Overlook Cliffs",
			short = "The Overlook Cliffs mark the place where the Hinterlands stop being mountains and become sky.",
			full = "The Overlook Cliffs mark the place where the Hinterlands stop being mountains and become sky. Here the great river that winds through the region reaches its end, pouring off the edge in a massive waterfall to the shoreline below.\n\nThe cliffs are steeper and higher than they look, and many travelers, misjudging the drop, have fallen to their deaths on the rocks below.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Plaguemist Ravine",
			short = "A mist hangs low and sickly in this ravine, where the rest of the Hinterlands stays green and clean.",
			full = "A mist hangs low and sickly in this ravine, where the rest of the Hinterlands stays green and clean. It seeps down from the north, from the Western Plaguelands, following the path that climbs toward Caer Darrow, as if the plague itself had crept south along this one narrow seam in the hills. The contrast between that poisoned air and the untouched woods around it is what gave the ravine its name.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Quel'Danil Lodge",
			short = "Quel'Danil Lodge is one of the last true gatherings of the high elves, the larger of only two such settlements remaining in Lordaeron.",
			full = "Quel'Danil Lodge is one of the last true gatherings of the high elves, the larger of only two such settlements remaining in Lordaeron. After the Third War it became a place of correspondence, its ambassadors reaching out to the other peoples of the Alliance. That outreach won the Highvale elves an alliance with the Wildhammer dwarves, and it earned them the hatred of the Revantusk trolls, who sought to see the elves slaughtered and their records burned. The documents survived, records of deaths, births, seasons, and every treaty the elves had made.\n\nStranger than any raid was the sickness that came after: young rangers found dead with no wound on them, their faces locked in terror, and healers who touched the bodies nearly dying themselves. The elves first blamed the Witherbark or the Revantusk, then admitted no blade had done this. Their own magic could not touch it, so Magister Falath traveled to Ironforge to beg the paladins of the Silver Hand for help. What was found and driven out was a Vengeful Spirit, and only then did the deaths stop.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Revantusk Village",
			short = "Revantusk Village stands on the coast of the Hinterlands, the last home of a forest troll tribe that chose loyalty over survival.",
			full = "Revantusk Village stands on the coast of the Hinterlands, the last home of a forest troll tribe that chose loyalty over survival.\n\nWhen the Old Horde fell in the Second War, the forest trolls who had served it scattered, most abandoning their orc allies without a second thought. The Revantusks could not free the captive orcs, too few in number, and found the orcs themselves indifferent to freedom. Still their loyalty lingered, and for it other forest trolls turned on them. Worn down and hunted, they fled to the Hinterlands coast and built their village there, hoping to be forgotten.\n\nThey were not forgotten by their own hearts. When word reached them that Thrall had raised a new Horde and led his people back to the shamanistic ways, the Revantusks sent their fastest runners to find him. Thrall met them with respect, and the two peoples bound themselves in a pact of friendship. For this, every other forest troll tribe brands the Revantusk cowards and traitors to their kind, and a long enmity stands between the village and the Wildhammer dwarves who share the Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "Seradane is an area in the northeastern part of the Hinterlands which houses one of the four entrances to the Emerald Dream, a large circular portal.",
			full = "Seradane is an area in the northeastern part of the Hinterlands which houses one of the four entrances to the Emerald Dream, a large circular portal.\n\nThe Great Tree was planted by the followers of Fandral Staghelm from one of Nordrassil's branches in order to stem the tide of saronite seeping up from the land.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "In the Hinterlands stands Shadra'Alor, raised by the forest trolls of the Amani Empire. Here the loa Shadra could be called down to answer the trolls' summons, a place set apart for that purpose alone.",
			full = "In the Hinterlands stands Shadra'Alor, raised by the forest trolls of the Amani Empire. Here the loa Shadra could be called down to answer the trolls' summons, a place set apart for that purpose alone.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Shaol'watha was once a temple of the Vilebranch forest trolls, standing broken now in the northeastern Hinterlands.",
			full = "Shaol'watha was once a temple of the Vilebranch forest trolls, standing broken now in the northeastern Hinterlands. The Revantusk tribe drove the Vilebranch out and turned the ruins into a staging ground to strike Stormfeather Outpost and claim it for the Horde. The Wildhammer dwarves answered by taking the old troll camp nearby. The war between them cost both sides their commanders: the Revantusk general Gan'dranda and the Wildhammer general Thornar Thunderclash each fell to the enemy they had marched against.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Shindigger's Camp",
			short = "Rhapsody Shindigger, a dwarf well into her cups, keeps camp here alongside the high elf Gilveradin Sunchaser.",
			full = "Rhapsody Shindigger, a dwarf well into her cups, keeps camp here alongside the high elf Gilveradin Sunchaser. Between them the two make an odd pairing, drink and elven composure sharing the same small fire in the Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Skulk Rock",
			short = "Skulk Rock stands as a ruin of the forest trolls, its stones given over to slimes, with a cave beneath where ghost mushrooms grow, found in few other places.",
			full = "Skulk Rock stands as a ruin of the forest trolls, its stones given over to slimes, with a cave beneath where ghost mushrooms grow, found in few other places.\n\nDuring the Second War the Old Horde held Skulk Rock as a base, abandoned when the Alliance of Lordaeron drove them out.\n\nA shadow of Skulk Rock also exists within the Emerald Dream, corrupted by the Nightmare, where wildkin serve the Doomkin and guard the Elunar Relic.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Valorwind Lake",
			short = "Valorwind Lake lies northeast of Shadra'Alor in the Hinterlands. Along its banks grows the Violet Tragan, a strange mushroom found nowhere else in the world, drawing those who prize rare things to its quiet shore.",
			full = "Valorwind Lake lies northeast of Shadra'Alor in the Hinterlands. Along its banks grows the Violet Tragan, a strange mushroom found nowhere else in the world, drawing those who prize rare things to its quiet shore.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Wildhammer Keep",
			short = "Aerie Peak rises around Wildhammer Keep, home of the dwarves who bear its name. Within its walls travelers find rest and shelter, and by the door stands an anvil, though no forge burns beside it.",
			full = "Aerie Peak rises around Wildhammer Keep, home of the dwarves who bear its name. Within its walls travelers find rest and shelter, and by the door stands an anvil, though no forge burns beside it.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "Zun'watha stands empty now, stone left to the trees. The Witherbark trolls who once filled it are gone, and no one has taken their place.",
			full = "Zun'watha stands empty now, stone left to the trees. The Witherbark trolls who once filled it are gone, and no one has taken their place. Only Zul'arek Hatefowler still returns, walking alone among the ruins of what his tribe abandoned.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Amberstill Ranch",
			short = "Amberstill Ranch sits north of Gol'Bolar Quarry, on the road toward Loch Modan. Yarlyn Amberstill keeps the place, breeding snowshoe rabbits and training the mountain rams stabled here.",
			full = "Amberstill Ranch sits north of Gol'Bolar Quarry, on the road toward Loch Modan. Yarlyn Amberstill keeps the place, breeding snowshoe rabbits and training the mountain rams stabled here.\n\nThe rams are given only to dwarves, or to outsiders who have earned Ironforge's fullest trust, a mark of how closely the ranch is bound to the mountain kingdom.\n\nA wendigo named Vagash preys on the herds, and Yarlyn has called for its death, a reminder that for all its homely look, the ranch stands close to wild country.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Anvilmar",
			short = "Anvilmar stands in the north of Coldridge Valley, built around a great central forge. It was the first settlement of any size its people raised here, the gathering place before all else that followed.",
			full = "Anvilmar stands in the north of Coldridge Valley, built around a great central forge. It was the first settlement of any size its people raised here, the gathering place before all else that followed. The forge still stands, cold iron waiting under the same roof.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Brewnall Village",
			short = "In Chill Breeze Valley, near Gnomeregan, stands the small dwarven village of Brewnall, home to the Barleybrews.",
			full = "In Chill Breeze Valley, near Gnomeregan, stands the small dwarven village of Brewnall, home to the Barleybrews. The clan has given itself to the brewer's craft, endlessly refining the old dwarven tradition of ale-making, sending its young out to guard the village from wild beasts and to hunt down secret ingredients for the perfect brew.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Chill Breeze Valley",
			short = "The snow of Chill Breeze Valley tells its own story.",
			full = "The snow of Chill Breeze Valley tells its own story. Where the valley runs east to west, between Gnomeregan and Kharanos, the path is worn smooth by dwarves and gnomes passing back and forth, and nothing there troubles the eye.\n\nIt is the north-south branch that people avoid. The snow along it is stained dark in patches, and the carcasses of animals lie torn open where they fell. Those who go looking for whatever did this do not always come back, and the ones who return speak of a cave where something far stronger than a wolf or bear still waits.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Coldridge Pass",
			short = "The pass is the only road out of Coldridge Valley, the narrow throat every young dwarf must cross to reach Kharanos. Troggs have taken it now, and travelers cross it running or fighting, with nothing in between.",
			full = "The pass is the only road out of Coldridge Valley, the narrow throat every young dwarf must cross to reach Kharanos. Troggs have taken it now, and travelers cross it running or fighting, with nothing in between.\n\nFendrig Redbeard learned that the hard way. He led twelve miners into the pass to survey the infestation, and there the stone gave way beneath him, burying him under rubble. The others turned back to dig him free, and the pass answered by collapsing entirely. Twelve miners died under that rock. Only Fendrig was pulled out alive.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Coldridge Valley",
			short = "Coldridge Valley lies shut away in the southwestern corner of Dun Morogh, its only way out the tunnel of Coldridge Pass to the northeast, infested with trogg raiders.",
			full = "Coldridge Valley lies shut away in the southwestern corner of Dun Morogh, its only way out the tunnel of Coldridge Pass to the northeast, infested with trogg raiders. Beyond it the road runs east, then north through Kharanos, climbing at last into the mountains to the gates of Ironforge.\n\nEven before the troggs choked the pass, the valley was a place of small, constant labor: trolls and troggs harried its edges, and its folk spent their days tending the wildlife around them.\n\nThat is still its character: a narrow, guarded hollow whose one way out is barred by raiders, so that anyone leaving it must pass through danger before ever reaching Ironforge's gates.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Frostmane Hold",
			short = "Frostmane Hold stands on the western edge of Dun Morogh's cold mountains, its buildings and cave system once held by the Frostmane ice trolls, guarded close by headhunters and hideskinners.",
			full = "Frostmane Hold stands on the western edge of Dun Morogh's cold mountains, its buildings and cave system once held by the Frostmane ice trolls, guarded close by headhunters and hideskinners. That grip broke, and the trolls fell back to Frostmane Retreat, leaving the hold empty.\n\nTroggs came after, spilling up through a tunnel and taking gnomes captive. Kharmarn Palegrip answered them, ordering explosives set to bring the tunnel down and seal the troggs out for good.\n\nThe hold still bears both tenants' marks: troll-built walls around a cave mouth choked with fallen stone.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge rise from the stone of Dun Morogh long before a traveler reaches them, visible across the valley.",
			full = "The Gates of Ironforge rise from the stone of Dun Morogh long before a traveler reaches them, visible across the valley. The great ramp climbs to them from the south, lesser paths wind up from the Commons, but every road ends the same way: at doors built to be seen from miles off.\n\nPass through and the first thing to greet a visitor is not a dwarf but a statue, High King Modimus Anvilmar carved huge, standing eternal watch just inside the threshold.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Gnomeregan is the subterranean capital city of the eponymous kingdom of Gnomeregan and the wrought-iron evidence of gnomish brilliance, ambition, and ingenuity.",
			full = "Gnomeregan is the subterranean capital city of the eponymous kingdom of Gnomeregan and the wrought-iron evidence of gnomish brilliance, ambition, and ingenuity.\n\nDuring the Third War, a trogg invasion led to its tragic downfall, pulled from their sleep by the upheaval of titan sites. In a desperate attempt to kill the invaders, the gnomish ruler, High Tinker Gelbin Mekkatorque, on the advice of his advisor Sicco Thermaplugg, ordered his people to open the pressure valves of their giant, grinding machines and released toxic radiation throughout the city. Though the radiation killed some of the troggs, it empowered others, while nearly eighty percent of gnomekind died within days. The survivors fled to the protection of Ironforge, while others were transformed into horrific, mindless, evil-doing leper gnomes, who still live there. Driven completely mad by the radiation, Thermaplugg declared himself \"King of Gnomeregan\" and took control of the city, leading an army of troggs and leper gnomes.\n\nAfter the Northrend campaign, Mekkatorque launched Operation: Gnomeregan with the support of the Alliance, allowing the gnomes to reclaim both the surface and the upper floors of Gnomeregan. Since then, the S.A.F.E. forces have been responsible for cleaning up the radiation, as well as saving the survivors inside the capital, using New Tinkertown as their base of operations at the surface.\n\nThe city is currently a mid-level dungeon.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Gol'Bolar Quarry",
			short = "The dwarves cut deep into the rock at Gol'Bolar Quarry, seeking what the stone of Dun Morogh always gives them, and for a time they had it.",
			full = "The dwarves cut deep into the rock at Gol'Bolar Quarry, seeking what the stone of Dun Morogh always gives them, and for a time they had it. Then the troggs came up from below and overran the excavation, driving the miners back from the pits they had opened and claiming the mine as their own.\n\nThe camp that stands there now is what is left of that dig, held by miners who have not given up the ground, still contesting the tunnels one collapse at a time.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "Grizzled Den",
			short = "The Grizzled Den is a wide cave system cut into the stone southwest of Kharanos, and something with cold breath has claimed it.",
			full = "The Grizzled Den is a wide cave system cut into the stone southwest of Kharanos, and something with cold breath has claimed it. Wendigos pack the tunnels, hunting in numbers, flooding from the dark together when disturbed rather than facing an intruder alone. Their breath carries frost, and more than one who came looking for a single mane found himself surrounded before he understood the danger.\n\nThe manes are the draw, prized for seat covers, and that has been enough to send waves of the hopeful into the den despite the risk. Deeper in, one wendigo is said to be larger and harder than the rest, and copper runs through the rock in veins for those who look past the fur.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Helm's Bed Lake",
			short = "Helm's Bed Lake lies frozen through most of the year, its surface locked in ice thick enough to walk across in safety.",
			full = "Helm's Bed Lake lies frozen through most of the year, its surface locked in ice thick enough to walk across in safety. Yet a hole is kept open at all times, cut and cleared so that fresh water beneath the ice remains within reach.\n\nSafe as the ice itself may be, the shores are not. Wild creatures and stray troggs roam the ground around the lake, and to the south stands an abandoned building now held by Dark Iron dwarves, who strike at anyone who strays too near its walls.\n\nSomewhere along the lake's edge lies the body of Narm Faulk, left where he fell.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Iceflow Lake",
			short = "Iceflow Lake freezes hard through most of the year under the cold of western Dun Morogh, but the dwarves of Brewnall Village keep one hole cut in the ice, tended so it never fully closes, for fresh water and for fishing.",
			full = "Iceflow Lake freezes hard through most of the year under the cold of western Dun Morogh, but the dwarves of Brewnall Village keep one hole cut in the ice, tended so it never fully closes, for fresh water and for fishing.\n\nAt the lake's center rise a few large islands, best left alone. A ravenous wolf pack has claimed them, led by the worg Timber, and it is his pack that keeps the islands a place the dwarves warn against rather than cross to.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Ironband's Compound",
			short = "South of Helm's Bed Lake in eastern Dun Morogh stands a compound that took Sturgy Ironband's name, though it is his no longer.",
			full = "South of Helm's Bed Lake in eastern Dun Morogh stands a compound that took Sturgy Ironband's name, though it is his no longer. Dark Iron dwarves hold it now, and they strike at anyone who strays too near, leaving little doubt of whose ground this has become.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["ironforge"] = {
			name = "Ironforge",
			short = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance.",
			full = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance. Carved into the depths of Ironforge Mountain in northern Dun Morogh, it is the ancestral home of the dwarves and one of the oldest cities on Azeroth. The Council of Three Hammers rules over the city to ensure the fair and equal treatment of all dwarves within its walls from the High Seat. The city is also the capital of the Kingdom of Khaz Modan, which is ruled by the Bronzebeard clan.\n\nAn expansive underground city of craftsmen, explorers, miners, and warriors, famous for its industry and as an Alliance center of commerce, Ironforge is equal parts fortress and capital and a testament to the dwarves' strength and resilience. The city consists of a series of concentric rings, with the smaller levels deeper underground, all radiating out from the namesake Great Forge at its center. Ironforge is perhaps the most intricate of the Alliance cities, boasting many small passageways, shops built into the rock walls, and cavernous rooms. The feel of the city is a bustling, rowdy, and somewhat industrial one, where there are always a thousand things happening at any time of the day or night. However, it is predominantly safe-feeling and cozy; fires roar in the hearths of the inns and shops, and much dwarven laughing and frivolity is to be heard. Also, unlike Stormwind and Darnassus, the city is actually a massive cavern carved into the earth by the dwarves; the ceiling and floor are both hard stone.\n\nMainly because of the Deeprun Tram, linking Ironforge and Stormwind City, and the district of Tinker Town, Ironforge is one of the most racially diverse cities in the Alliance world. With the Council of Three Hammers uniting all three dwarven clans, Ironforge has recently welcomed Dark Iron dwarves and Wildhammer dwarves into Ironforge as well.\n\nThe collective frivolity, the bustling and gruff manner of the dwarves, and the proximity to many quest and raid areas have historically made Ironforge, along with Stormwind City, a popular place to idle.",
			source = "https://warcraft.wiki.gg/wiki/Ironforge",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos sits among the wind-scoured peaks of Dun Morogh, a small town built for a hard country.",
			full = "Kharanos sits among the wind-scoured peaks of Dun Morogh, a small town built for a hard country. Its forge stays lit through the frost, its gnomish workshop clatters through the day, and the Thunderbrew Distillery pours some of the finest ale to be found anywhere, a small comfort against the wilds pressing in on every side. To the west a cavern shelters wendigo; to the northwest, atop Shimmer Ridge, the Frostmane trolls have made their hold. Kharanos stands as the forward post against both, and it is here that new recruits from Anvilmar report before going out into the mountains in earnest.\n\nThe town's name is bound up with a single night when a giant of a Frostmane troll came down on Kharanos and nearly finished it, dwarf by dwarf, before anyone could stand against it. It was Lazlo Grindwidget who finally brought the troll down, and for it he is remembered as a hero of the town.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Misty Pine Refuge",
			short = "Father Gavin keeps the Argent Dawn's watch at Misty Pine Refuge alone now. Refugees linger here, cared for by Buin \"Phloppy\" Freehand, who gives freely and asks nothing in return.",
			full = "Father Gavin keeps the Argent Dawn's watch at Misty Pine Refuge alone now. Refugees linger here, cared for by Buin \"Phloppy\" Freehand, who gives freely and asks nothing in return.\n\nWhen demons swept into the area during the invasions, Mountaineer Helmholt and his mountaineers held the refuge against them, alongside the guards.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "North Gate Outpost",
			short = "North Gate Outpost sits astride North Gate Pass, the narrow way that joins Dun Morogh to Loch Modan, and it is the dwarves' northeasternmost hold in the mountains.",
			full = "North Gate Outpost sits astride North Gate Pass, the narrow way that joins Dun Morogh to Loch Modan, and it is the dwarves' northeasternmost hold in the mountains.\n\nThe mountaineers posted here spend their days pressing back the wildlife that presses in from the crags on every side. Some who went hunting the fiercer beasts of the pass have not returned, and no one at the outpost can yet say what became of them.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "North Gate Pass cuts through the mountains between Dun Morogh above and Loch Modan below, the shortest way down toward the Wetlands, and so it sees steady traffic.",
			full = "North Gate Pass cuts through the mountains between Dun Morogh above and Loch Modan below, the shortest way down toward the Wetlands, and so it sees steady traffic. At the pass stands North Gate Outpost, a guard station set to watch the road between the two lands.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Shimmer Ridge",
			short = "Shimmer Ridge rises in northern Dun Morogh, within sight of the Gates of Ironforge, held by Frostmane trolls in two camps joined by a bridge.",
			full = "Shimmer Ridge rises in northern Dun Morogh, within sight of the Gates of Ironforge, held by Frostmane trolls in two camps joined by a bridge. Among the huts they tend shimmerweed and keep tamed boars.\n\nAt Varian's request, Moira led her personal guard against the Frostmane once a magical storm gripping the ridge was broken and the trolls guarding it were driven back, seizing the ridge for the queen.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "South Gate Outpost",
			short = "South Gate Outpost sits astride the South Gate Pass, the mountain road joining Dun Morogh to Loch Modan.",
			full = "South Gate Outpost sits astride the South Gate Pass, the mountain road joining Dun Morogh to Loch Modan. Mountaineers hold the outpost and have cleared the pass of the wildlife that presses in elsewhere, so those stationed here do not fight the battles their kin endure at North Gate Outpost. Travelers moving to and from Thelsamar pass this way, through a stretch of road already made safe.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "South Gate Pass cuts a way through the mountains, linking the high snows of Dun Morogh to the valleys of Loch Modan. It is the shortest road down to Thelsamar.",
			full = "South Gate Pass cuts a way through the mountains, linking the high snows of Dun Morogh to the valleys of Loch Modan. It is the shortest road down to Thelsamar. The dwarves keep it watched, holding South Gate Outpost here to guard the way between mountain and valley.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Steelgrill's Depot",
			short = "Steelgrill's Depot sits east of Kharanos, a small camp of miners and engineers going about their trade in the shadow of the mountains.",
			full = "Steelgrill's Depot sits east of Kharanos, a small camp of miners and engineers going about their trade in the shadow of the mountains. Dwarves and gnomes work here side by side, tending to the machinery and stores that keep the outpost running.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Thunderbrew Distillery",
			short = "The Thunderbrew Distillery stands in Kharanos, its ale known far beyond the mountains. Innkeeper Belm keeps the place, and warriors, priests, paladins, mages, and rogues have all trained beneath its roof.",
			full = "The Thunderbrew Distillery stands in Kharanos, its ale known far beyond the mountains. Innkeeper Belm keeps the place, and warriors, priests, paladins, mages, and rogues have all trained beneath its roof.\n\nIt took its name from Grimbooze Thunderbrew, who owned it when the wandering brewmaster Chen Stormstout once came through its doors.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "Tundrid Hills",
			short = "The Tundrid Hills lie in south-central Dun Morogh, west of Gol'Bolar Quarry, a stretch of broken ground where wolves and other wild things prowl and few walk unarmed.",
			full = "The Tundrid Hills lie in south-central Dun Morogh, west of Gol'Bolar Quarry, a stretch of broken ground where wolves and other wild things prowl and few walk unarmed. Some cut through the hills to pass between Coldridge Valley and eastern Dun Morogh, though it is a far harsher road than the one through Kharanos.\n\nThe Frostmane trolls have raised a large camp in the valley here, holding this ground and hostile to any who wander too near.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- Searing Gorge: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Blackchar Cave",
			short = "During the Lunar Festival, Ironband the Elder is found sealed away within Blackchar Cave, near Blackrock Mountain.",
			full = "During the Lunar Festival, Ironband the Elder is found sealed away within Blackchar Cave, near Blackrock Mountain.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions.",
			full = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions. One of the most dangerous places in Azeroth, inside this unnaturally created volcano is some of the greatest work ever wrought by the dwarves. Created when Emperor Dagran Thaurissan accidentally summoned Ragnaros from the Firelands, the mountain was hotly contested between the Firelord's Dark Iron servants and the black dragon Nefarian's Blackrock orcs, until the Horde and Alliance adventurers invaded the volcano to decimate their armies, ending their decades-long conflict.\n\nDuring the Ironmarch, the Black Iron attempted to destroy Stormwind City by inducing an eruption, but were stopped in time by the heroes.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "Cauldron",
			short = "At the center of the Searing Gorge lies the Cauldron, a vast pit ringed by the digging machines that tore it open. It was fortified by the Dark Iron dwarves after Ragnaros was summoned.",
			full = "At the center of the Searing Gorge lies the Cauldron, a vast pit ringed by the digging machines that tore it open. It was fortified by the Dark Iron dwarves after Ragnaros was summoned.\n\nFire and magma elementals move through the crevices below. Among them labor the slave workers, captives worked without end in the heat and ash. The toil and the heat and their masters have broken something in them. They no longer know a rescuer from a captor, and will turn on anyone who interrupts their labor, even those who come meaning to free them.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Dustfire Valley",
			short = "Dustfire Valley runs through the Searing Gorge, its winds thick with ash, leading north to the gates of Stonewrought Pass and on to the Valley of Kings in Loch Modan.",
			full = "Dustfire Valley runs through the Searing Gorge, its winds thick with ash, leading north to the gates of Stonewrought Pass and on to the Valley of Kings in Loch Modan. Those gates once demanded a key, but now stand open to all who walk the valley.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Firewatch Ridge",
			short = "Firewatch Ridge overlooks the Cauldron, the great excavation scarring Searing Gorge. Dark Iron dwarves hold the ridge, their camp guarded by mechanical golems and giant flame spiders nesting among the rocks.",
			full = "Firewatch Ridge overlooks the Cauldron, the great excavation scarring Searing Gorge. Dark Iron dwarves hold the ridge, their camp guarded by mechanical golems and giant flame spiders nesting among the rocks.\n\nIn the ridge's northwestern reaches lies a cave claimed by the Twilight's Hammer, its depths held by warriors of their own.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Grimesilt Dig Site",
			short = "The Grimesilt Dig Site once belonged to the Ironforge dwarves before the Dark Iron dwarves seized it and made it their own.",
			full = "The Grimesilt Dig Site once belonged to the Ironforge dwarves before the Dark Iron dwarves seized it and made it their own. Dorius Stonetender, one of the original diggers, still lies injured at the bottom of the pit, left among the ruins of the work he started.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "Sea of Cinders",
			short = "The Sea of Cinders lies flat and black in the southern Searing Gorge, beneath the shadow of Blackrock Mountain. Nothing grows here.",
			full = "The Sea of Cinders lies flat and black in the southern Searing Gorge, beneath the shadow of Blackrock Mountain. Nothing grows here. Fire and wind have scoured the ground to ash, and the ash never settles -- cinders still rise from the smoldering earth, stinging eyes and throat, making the crossing a misery.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "Slag Pit",
			short = "The Slag Pit sinks into the floor of the Cauldron, deep in the excavation that scars Searing Gorge. Dark Iron dwarves hold it, cruel masters over slave laborers driven by slavers and taskmasters.",
			full = "The Slag Pit sinks into the floor of the Cauldron, deep in the excavation that scars Searing Gorge. Dark Iron dwarves hold it, cruel masters over slave laborers driven by slavers and taskmasters. The workers will not rise unprovoked, but strike a taskmaster within their sight and they turn fierce in their masters' defense.\n\nThe Dark Irons mine on regardless, and meet any interference with open hostility.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Stonewrought Pass",
			short = "The tunnel called Stonewrought Pass cuts through the northern end of Dustfire Valley, running from Searing Gorge up into Loch Modan, opening at last upon the Valley of Kings.",
			full = "The tunnel called Stonewrought Pass cuts through the northern end of Dustfire Valley, running from Searing Gorge up into Loch Modan, opening at last upon the Valley of Kings.\n\nIts stonework bears the hand of Franclorn Forgewright, whose craft also raised the great Stonewrought Dam and other works of dwarven architecture across the Eastern Kingdoms.\n\nThe Loch Modan gate was once held shut by Mountaineer Pebblebitty, but the pass now stands open on both ends.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Tanner Camp",
			short = "Sarah Tanner keeps her tent in the Searing Gorge, the master of elemental leatherworking for the Alliance.",
			full = "Sarah Tanner keeps her tent in the Searing Gorge, the master of elemental leatherworking for the Alliance. Behind her camp a long passage winds back into the rock, leading at last to the thunder lizard Margol the Rager, who lairs where the tunnel ends.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Thorium Point",
			short = "Thorium Point sits in the northern reaches of Searing Gorge, held by neither Horde nor Alliance but by the Thorium Brotherhood, a guild of dwarves apart from the old quarrels of their kin.",
			full = "Thorium Point sits in the northern reaches of Searing Gorge, held by neither Horde nor Alliance but by the Thorium Brotherhood, a guild of dwarves apart from the old quarrels of their kin. Most who walk its grounds are Dark Iron dwarves, answering only to the Brotherhood's own purposes.\n\nA forge and anvil stand at the heart of the town, kept burning against the ash and heat around it.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Burning Steppes: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions.",
			full = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions. One of the most dangerous places in Azeroth, inside this unnaturally created volcano is some of the greatest work ever wrought by the dwarves. Created when Emperor Dagran Thaurissan accidentally summoned Ragnaros from the Firelands, the mountain was hotly contested between the Firelord's Dark Iron servants and the black dragon Nefarian's Blackrock orcs, until the Horde and Alliance adventurers invaded the volcano to decimate their armies, ending their decades-long conflict.\n\nDuring the Ironmarch, the Black Iron attempted to destroy Stormwind City by inducing an eruption, but were stopped in time by the heroes.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Blackrock Pass",
			short = "Blackrock Pass is the gate between two worlds. Before the Redridge Pass was cut open, it was the only way on foot into the Burning Steppes, save for the black tunnels through Blackrock Mountain itself.",
			full = "Blackrock Pass is the gate between two worlds. Before the Redridge Pass was cut open, it was the only way on foot into the Burning Steppes, save for the black tunnels through Blackrock Mountain itself.\n\nThe change underfoot is immediate. Behind lies Redridge Mountains, quiet and ordered. Ahead, past the gate marking the border, the ground gives way to the scorched and twisted ruin of the Burning Steppes.\n\nThose who do not yet know what waits beyond are warned to turn back here. What lives past the pass answers to none of the mercy shown behind it.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Blackrock Stronghold",
			short = "The stronghold rises at the northern edge of the Burning Steppes, just outside Blackrock Spire, a mass of dark stone held by the Blackrock clan.",
			full = "The stronghold rises at the northern edge of the Burning Steppes, just outside Blackrock Spire, a mass of dark stone held by the Blackrock clan. Beyond its walls, in the Fields of Honor, orcs and their allies muster and drill, kept in line by the Blackrock Sergeants who patrol among them. General Thorg'izog commands from within, meting out discipline to the troops and setting the order of the field.\n\nThe sergeants who once ruled the Fields of Honor met their end in a single mysterious spate of violence, cudgeled to death by an unseen hand that moved through their ranks and left the stronghold's discipline in ruin.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Scorched hills rise in the southwest of the Burning Steppes, their slopes blackened and bare. This is Draco'dar, ground claimed by the black dragonflight, and its minions still crawl over every ridge and hollow.",
			full = "Scorched hills rise in the southwest of the Burning Steppes, their slopes blackened and bare. This is Draco'dar, ground claimed by the black dragonflight, and its minions still crawl over every ridge and hollow. No one crosses it alone and comes through unmarked.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Dreadmaul Rock",
			short = "Dreadmaul Rock is a hollowed mass of stone, its paths winding past ogre dens burrowed into the rock itself.",
			full = "Dreadmaul Rock is a hollowed mass of stone, its paths winding past ogre dens burrowed into the rock itself. The Firegut clan holds it as their seat, staging raids southward into the Redridge Mountains from its heights and tangled caves.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Flame Crest",
			short = "Flame Crest is a small rock outcropping in the Burning Steppes, reachable only by a crude bridge. In a shallow cave at its back lives the hermit Kibler and his ever-talking parrot Opus.",
			full = "Flame Crest is a small rock outcropping in the Burning Steppes, reachable only by a crude bridge. In a shallow cave at its back lives the hermit Kibler and his ever-talking parrot Opus. It was here that Eitrigg and Ariok made their base while planning an attack against the Blackrock clan.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Morgan's Vigil",
			short = "Morgan's Vigil stands broken in the Burning Steppes, its houses burned to the ground and its single mage tower crumbled to ruin. Tents have gone up among the wreckage, shelter for those who remain.",
			full = "Morgan's Vigil stands broken in the Burning Steppes, its houses burned to the ground and its single mage tower crumbled to ruin. Tents have gone up among the wreckage, shelter for those who remain.\n\nIt was once an outpost, but Morgan, for whom it is named, would not stay behind walls. She and many of the settlement's people left the Vigil to its ruin and went down into Blackrock Mountain, to strike at what festers there.\n\nWhat is left is a name without its namesake, and tents pitched among burned timber.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "Pillar of Ash",
			short = "The Pillar of Ash rises at the eastern end of Black Tooth Hovel, a scorched tower standing over ground that still bears the mark of fire.",
			full = "The Pillar of Ash rises at the eastern end of Black Tooth Hovel, a scorched tower standing over ground that still bears the mark of fire.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["ruins of thaurissan"] = {
			name = "Ruins of Thaurissan",
			short = "Once these ashen flats in the Burning Steppes were green, and the city here bore the name of its founder: Thaurissan City, capital of the Dark Iron clan, exiled from Ironforge and led south by Sorcerer-Thane Thaurissan during the War of the Three Hammers.",
			full = "Once these ashen flats in the Burning Steppes were green, and the city here bore the name of its founder: Thaurissan City, capital of the Dark Iron clan, exiled from Ironforge and led south by Sorcerer-Thane Thaurissan during the War of the Three Hammers.\n\nThe Dark Irons were losing that war. Their army had just been broken against the other two clans' strongholds when Thaurissan, desperate to turn the tide, gathered seven of his most trusted dwarves and called down into the powers sleeping beneath the earth for a servant to win the war back. What answered was no servant, but Ragnaros, Elemental Lord of Fire, and his coming split the mountains with a volcano that burned the valley to ash. The city was annihilated with him in it, and the surviving Dark Irons were enslaved to the Firelord. What freedom Thaurissan had won at Ironforge, he lost here, forever.\n\nRelics still lie among the ruined stones, and to touch one is to be flooded with the memory it holds: a lone dwarf kneeling among seven corpses before a pillar of flame, the last vision of the city as it burned.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Slither Rock",
			short = "Past the Terror Wing Path in the far northeast of the Burning Steppes, a small cave opens into the rock.",
			full = "Past the Terror Wing Path in the far northeast of the Burning Steppes, a small cave opens into the rock. It once housed the black dragonspawn Cyrus Therepentous, who met visitors with scorn and rude remark, yet would still lend his strength against a common foe.\n\nNow Acride dwells there instead.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Terror Wing Path",
			short = "The valley called Terror Wing Path lies in the eastern Burning Steppes, and it earns its name honestly: whelps and dragonkin of the black dragonflight nest and hunt throughout it.",
			full = "The valley called Terror Wing Path lies in the eastern Burning Steppes, and it earns its name honestly: whelps and dragonkin of the black dragonflight nest and hunt throughout it.\n\nThrough its southeastern edge runs Redridge Pass, a goblin-built road climbing into the hills toward the Redridge Mountains and the Swamp of Sorrows. There, Sharon Boomgetter offers passage to the resort town of Bogpaddle.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Elwynn Forest: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Brackwell Pumpkin Patch",
			short = "Brackwell Pumpkin Patch lies quiet in southeast Elwynn Forest now, its rows of pumpkins tended by no one who belongs there.",
			full = "Brackwell Pumpkin Patch lies quiet in southeast Elwynn Forest now, its rows of pumpkins tended by no one who belongs there. The Brackwell family once worked this land, and what became of them nobody can say, only that by the Year 25 ADP the Defias Brotherhood had taken the farmstead for its own, using it as a place to move gold stolen from Elwynn's mines.\n\nSomething darker passed through the patch as well. The bandit Erlan Drudgemoor talked Surena Caledon into running away with him, and she went, carrying with her a bloodstone choker that was never hers to take. That choker belonged to her master, the warlock Gakin the Darkbinder, who wanted his property back and his apprentice's treachery answered for in blood.\n\nThe Brackwells left behind one thing worth remembering fondly: a sow named Princess, grown enormous on stolen vegetables from neighboring Stonefield Farm, where she used to slip away to gorge herself on Ma Stonefield's watermelons.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Crystal Lake",
			short = "East of Goldshire, Crystal Lake's waters churn with murlocs.",
			full = "East of Goldshire, Crystal Lake's waters churn with murlocs. On the islet at its center stands a grave, worn plain but for one line cut into it: \"Deeply missed, never forgotten\" -- no name, no date, nothing to say who lies there. A human homestead keeps watch from the southern shore, its people living out their days within sight of the murlocs and the nameless grave alike.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Eastvale Logging Camp",
			short = "The mills at Eastvale never stop for long.",
			full = "The mills at Eastvale never stop for long. Timber moves out on strict deadlines, ordered by buyers who care nothing for the wilderness pressing in on every side, and the lumberjacks who cut it work with that pressure always at their backs.\n\nLord Joran Tremaind, of the House of Nobles, built his family's fortune here, and he has said plainly that Eastvale would have come to nothing without the people of Westfall standing behind it. Marshal Haggard, who once commanded the Stormwind Guard, chose to spend his retirement in a manor here rather than anywhere grander.\n\nThe forest does not make it easy. By the twenty-fifth year after the Portal's opening, wolves and bears had turned from nuisance to crisis, driving off workers and threatening to bury the camp in missed deadlines. The Stormwind Guard, unable to spare enough of its own, turned to outside hands to thin the packs, and one beast among the wolves proved bad enough that its head was carried in to Marshal Patterson as proof the worst of it was over.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Echo Ridge Mine",
			short = "Kobolds swarmed into Echo Ridge Mine in northwestern Northshire Valley, thieving so troublesome that Marshal McBride called on able hands to thin their numbers again and again.",
			full = "Kobolds swarmed into Echo Ridge Mine in northwestern Northshire Valley, thieving so troublesome that Marshal McBride called on able hands to thin their numbers again and again. Why the mine finally fell silent, no one can say. Perhaps the earth gave way in a tremor, or perhaps it was sealed to keep the kobolds out for good. The entrance stands closed now.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Fargodeep Mine",
			short = "The Fargodeep Mine once yielded gold for Stormwind. It stands abandoned now, overrun by a clan of kobolds that has taken its shafts for its own.",
			full = "The Fargodeep Mine once yielded gold for Stormwind. It stands abandoned now, overrun by a clan of kobolds that has taken its shafts for its own.\n\nWord of the kobolds reached Marshal Dughan, and patrols through the area were strengthened once the reports were confirmed. Among the kobolds is one known by name, Goldtooth, who carries off whatever glitters, including a necklace that once belonged to Auntie Bernice Stonefield, lost somewhere in the dark below.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Forest's Edge",
			short = "Forest's Edge lies where Elwynn's trees thin toward Westfall, bounded by the Nazferiti and a small southern river, with Westbrook Garrison watching over its northern reaches.",
			full = "Forest's Edge lies where Elwynn's trees thin toward Westfall, bounded by the Nazferiti and a small southern river, with Westbrook Garrison watching over its northern reaches.\n\nThe forest belongs to the gnolls, who have made their home here alongside wandering boars. Among them one stands apart: Hogger, an elite of his kind, who has claimed a hill in the southern woods as his own, apart from his pack, ruling it alone.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Goldshire",
			short = "Goldshire rose small and quiet, one of the first towns to spring up in Elwynn Forest after Stormwind's founding, when its people began spilling into the surrounding country.",
			full = "Goldshire rose small and quiet, one of the first towns to spring up in Elwynn Forest after Stormwind's founding, when its people began spilling into the surrounding country.\n\nIts worst hour came during the First War, when Warchief Blackhand turned the Horde against it and Moonbrook together, the last two towns left standing between King Llane and his people, cut down deliberately to sever Stormwind from everything beyond its walls before the keep itself was put to the sack. Goldshire fell. It did not rise again until after the Second War, when Turalyon himself oversaw the return of the kingdom's scattered people and saw the town rebuilt from what the orcs had left of it.\n\nThe Lion's Pride Inn has kept its doors open all the while, one of the most respectable ale houses in Azeroth, and Marshal Dughan keeps the peace under its roof.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Heroes' Vigil",
			short = "A ring of stones circles the Stone of Remembrance on the small island in Stone Cairn Lake, raised for the dead of the First War, when orcs swept down on Goldshire and the lands around it.",
			full = "A ring of stones circles the Stone of Remembrance on the small island in Stone Cairn Lake, raised for the dead of the First War, when orcs swept down on Goldshire and the lands around it. Rogue wizards hold the island now, dealing roughly with any who wander in. Among the stones lies the body of Henze Faulk, left where he fell.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Jasperlode Mine",
			short = "Jasperlode once fed Stormwind's forges, hauled up alongside the ore of Fargodeep to arm the kingdom's wars. That work has stopped.",
			full = "Jasperlode once fed Stormwind's forges, hauled up alongside the ore of Fargodeep to arm the kingdom's wars. That work has stopped. Kobolds swarm the shafts now, thick enough that the mine is theirs in all but name, and Stormwind's army, stretched thin by graver threats, has never spared the men to take it back.\n\nThe kobolds are not the worst of it. Deeper in, where the tunnels narrow and the light gives out, a colony of mine spiders has nested, and to them the kobolds are prey rather than rivals. Their queen, Mother Fang, rules that darkness and suffers no trespassers.\n\nMarshal Dughan led more than ten men into the mine once, Zaldimar Wefhellt among them, to clear the kobolds out for good. The kobolds overran them instead. He still dreams of it.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Jerod's Landing",
			short = "Jerod's Landing sits on the Elwynn bank of the Nazferiti.",
			full = "Jerod's Landing sits on the Elwynn bank of the Nazferiti. The Defias Brotherhood once seized it, and under the Dockmaster's men it became a smuggling dock, ferrying stolen goods from Redridge to Klaven's Tower in Westfall. The Brotherhood has fallen, but a band of thieves runs the landing still.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Maclure Vineyards",
			short = "The Maclure Vineyards in southern Elwynn Forest belong to the Maclure family, who carry a bitter rivalry with the neighboring Stonefields.",
			full = "The Maclure Vineyards in southern Elwynn Forest belong to the Maclure family, who carry a bitter rivalry with the neighboring Stonefields. Yet a child of the Maclures and a child of the Stonefields have fallen in love, in defiance of everything their families taught them, and those who know of it hope the two young hearts might mend what generations of quarreling never could.\n\nWild boars now root freely through the vineyard rows, more numerous than the hands left to chase them off.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Mirror Lake",
			short = "A waterfall feeds Mirror Lake, small and bright beneath it, in a fold of western Elwynn Forest near the orchard.",
			full = "A waterfall feeds Mirror Lake, small and bright beneath it, in a fold of western Elwynn Forest near the orchard. It looks made for swimming or fishing, and it would be, if not for the Defias bandits who have made the area theirs.\n\nThe lake has another mouth besides the waterfall. The sewers beneath the Stormwind Stockade run out into its waters, and it was through them that Varok Saurfang escaped his cell, coming up out of the dark into the lake. Here his trail was picked up again, Dark Ranger Lyana and a Horde champion following the escape route he had carved back to open water.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Mirror Lake Orchard",
			short = "The orchard lies along the southern shore of Mirror Lake, in the west of Elwynn Forest, its cottage standing quiet among the trees.",
			full = "The orchard lies along the southern shore of Mirror Lake, in the west of Elwynn Forest, its cottage standing quiet among the trees.\n\nThe Defias Brotherhood once held it, working the orchard and the cottage beside it as their own, though whose hands first tended these rows is unknown.\n\nLater, Twilight's Hammer cultists seized the ground, under an overseer named Sylandra.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Northshire Abbey",
			short = "Northshire Abbey stands in the foothills of Elwynn Forest, home to the clerics who first carried the Church of the Holy Light south into Stormwind's lands.",
			full = "Northshire Abbey stands in the foothills of Elwynn Forest, home to the clerics who first carried the Church of the Holy Light south into Stormwind's lands. For generations they were the kingdom's comfort in hard times, and it was here, quietly, that the Guardian of Tirisfal, Medivh, was tended through the long years of his coma.\n\nThe abbey did not survive the First War. Its clerics stood with Stormwind's armies against the Horde, but the orcs came for Northshire itself, and not long after the half-orc Garona was brought there as a prisoner, they burned the abbey to the ground. Refugees pulled what sacred tomes they could from the wreckage before fleeing north to Lordaeron. For years afterward the ruined ground served a darker purpose, as the headquarters of Cho'gall's Twilight's Hammer clan in league with Gul'dan. Only when the Alliance reclaimed Elwynn Forest did Archbishop Alonsus Faol return to rebuild it, raising up a new order of clerics, priests, and paladins under the name the Brotherhood of Northshire.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Northshire Valley",
			short = "Northshire Valley lies closed in on every side by mountains that no army could cross, save for the one pass to the south, walled in stone and watched day and night.",
			full = "Northshire Valley lies closed in on every side by mountains that no army could cross, save for the one pass to the south, walled in stone and watched day and night. A river runs the length of the valley before slipping out toward Crystal Lake.\n\nDuring the Second War the valley was anything but peaceful. Cho'gall made Northshire Abbey his own, and the Twilight's Hammer clan set its headquarters here in service to Gul'dan, turning the holy ground into a seat for the Horde's dark allies.\n\nThe abbey stands again as it once did, its halls given over to training those willing to take up arms in the kingdom's defense. Marshal Douglas McBride commands its garrison and answers for the valley's safety, though safety here is a relative thing. Wolves have come down out of Duskwood in numbers the woods have never held, and kobolds have burrowed into Echo Ridge Mine. The valley looks serene from the pass, but McBride and his guards know better.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Northshire Vineyards",
			short = "The vineyards lie east of the abbey. The Defias Brotherhood took them for their own, setting agents among the vines under Garrick Padfoot.",
			full = "The vineyards lie east of the abbey. The Defias Brotherhood took them for their own, setting agents among the vines under Garrick Padfoot. From here his minions raided outward, holding among their plunder property stolen from Milly Osworth, hidden in the rows until it could be reclaimed.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Ridgepoint Tower",
			short = "Ridgepoint Tower stands watch where Elwynn Forest meets darker country.",
			full = "Ridgepoint Tower stands watch where Elwynn Forest meets darker country. Manned by the Stormwind Guard, it holds the line against threats from every side: gnolls and orcs out of the Redridge Mountains, the undead drifting from Duskwood, and the Defias massing in nearby camps.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Stone Cairn Lake",
			short = "Stone Cairn Lake takes its name from Heroes' Vigil, the stone cairn raised on the island that rings the lake's waters, built to remember the dead of the First War against the orcs.",
			full = "Stone Cairn Lake takes its name from Heroes' Vigil, the stone cairn raised on the island that rings the lake's waters, built to remember the dead of the First War against the orcs. The loss was so great that people once made pilgrimage here to grieve.\n\nThat peace no longer holds. Rogue Wizards have settled the island, taking the memorial ground for their own, while a tribe of murlocs has raised crude huts along the lake's southern banks. What was once a place of quiet remembrance now must be approached with caution.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "Stonefield Farm",
			short = "Stonefield Farm lies in southern Elwynn Forest, worked by the Stonefield family, who hold a bitter rivalry with the neighboring Maclures.",
			full = "Stonefield Farm lies in southern Elwynn Forest, worked by the Stonefield family, who hold a bitter rivalry with the neighboring Maclures. Yet a child of each family has fallen in love in defiance of the feud, a quiet Romeo-and-Juliet romance carried on between two houses that otherwise despise one another. Some hope it may yet be the thing that finally unites the farms.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["stormwind city"] = {
			name = "Stormwind City",
			short = "The stones of Stormwind carry more grief than any human city on Azeroth, and more stubborn hope besides.",
			full = "The stones of Stormwind carry more grief than any human city on Azeroth, and more stubborn hope besides.\n\nWhen the Horde marched on the city, siege engines battered its walls through the night and warlocks burned its soldiers where they stood. The city held only because Anduin Lothar circled his knights around by sea and struck the orcs from behind while the gates opened and the defenders poured out to meet them. A year later the orcs returned and broke through. King Llane Wrynn was cut down by the assassin Garona, and Stormwind burned to ash. Its survivors fled north to Lordaeron in a fleet of small boats.\n\nThe city was rebuilt stone by stone by the Stonemasons' Guild, white and whole again, under the boy-king Varian. But the nobles who commissioned the work ran the treasury dry, and when Guildmaster Edwin VanCleef demanded the wages owed his men, the House of Nobles disbanded the guild instead. The riot that followed killed Queen Tiffin. Varian's fury drove the stonemasons from the city they had raised with their own hands; they fled into Westfall and became the Defias Brotherhood.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
		},
		["thunder falls"] = {
			name = "Thunder Falls",
			short = "A steep path climbs from the shore of Mirror Lake, past a small rural cottage where an anvil sits warm beside a cozy fire, and up into the mountains of north-western Elwynn Forest to Thunder Falls.",
			full = "A steep path climbs from the shore of Mirror Lake, past a small rural cottage where an anvil sits warm beside a cozy fire, and up into the mountains of north-western Elwynn Forest to Thunder Falls. The ravine is unlike any other in the forest, fed by water at both ends. One stream tumbles down from a third waterfall, hidden away on the northern cliffs and impossible to reach, while the river below eventually finds its own falls, spilling out near the edge of Westfall.\n\nBandits keep to the cottage and the path around it, and the ravine's broken, hilly terrain makes the descent to the lower falls a careful business rather than a straight climb. The violet perch that run in these waters are drawn up from a place shaped, on both ends, by falling water.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Tower of Azora",
			short = "The Tower of Azora rises narrow above the fields of central Elwynn Forest, its stones humming faintly with old magic.",
			full = "The Tower of Azora rises narrow above the fields of central Elwynn Forest, its stones humming faintly with old magic. Gnomes tend its halls, answering to the Archmage of Azora, Theocritus, who holds the tower's true authority.\n\nThe tower's magic does not stay within its walls. Things that wander too close are changed by it: buckets left nearby begin to move on their own, and butterflies drifting near the stones grow monstrous, forcing the servants of Azora to deal with them as a matter of routine.\n\nFar off in the Redridge Mountains stands the Tower of Ilgalar, home to the sorcerer Morganth, and between the two towers there is no peace, only a constant watching, each spying on the other through magical means.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Westbrook Garrison",
			short = "The barracks at Westbrook Garrison stand at the western edge of Elwynn Forest, watching the road toward Westfall, and its guards have never had an easy post.",
			full = "The barracks at Westbrook Garrison stand at the western edge of Elwynn Forest, watching the road toward Westfall, and its guards have never had an easy post.\n\nWith Lady Katrana Prestor's corruption unsettling the kingdom and the bulk of the Stormwind army called away abroad, the garrison was left thin, while gnolls and thieves out of Westfall pressed in from the woods around it. Deputy Rainer, unable to keep the roads safe with so few men, asked Marshal Dughan at Goldshire for soldiers. Dughan had none to send, and sent Alliance adventurers instead. With their help the garrison broke the Riverpaw pack infesting the woods to the south.\n\nOne gnoll they never broke. Wanted posters still hang at the garrison gate naming Hogger, chieftain of the Riverpaw, who has overpowered every attempt made to capture him.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Deadwind Pass: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Ariden's Camp",
			short = "The camp stands empty north of the road through Deadwind Pass, a scatter of cold fire rings and abandoned tents between Duskwood and the Swamp of Sorrows.",
			full = "The camp stands empty north of the road through Deadwind Pass, a scatter of cold fire rings and abandoned tents between Duskwood and the Swamp of Sorrows.\n\nIt was here that Ariden made his stand before the curse took him. He led the Dark Riders, and from this camp he ran his last trade: relics he claimed had once belonged to Medivh himself, sold to whoever passed through the pass willing to pay for a piece of the Guardian's legend. The artifacts were false. Then the curse found Ariden, and the camp was left as it is now, tents standing, fires dead, the man who ran it gone.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Deadman's Crossing",
			short = "At the crossroads stands a hangman's tree, still bearing two corpses turning in the wind. Beside it a signpost gives its warning: Turn Back.",
			full = "At the crossroads stands a hangman's tree, still bearing two corpses turning in the wind. Beside it a signpost gives its warning: Turn Back. Abandon hope, all ye who enter here.\n\nFrom here the road runs west into Duskwood, east toward the Swamp of Sorrows, south toward Karazhan in Deadwind Pass. The warning does not lie about what waits further off the road and further south -- yet the crossing itself keeps to the road's word, safe ground bounded by signs that mean everything past their edges.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Deadwind Ravine",
			short = "The cleft cuts through the mountains of Deadwind Pass, its walls rising toward Karazhan to the south.",
			full = "The cleft cuts through the mountains of Deadwind Pass, its walls rising toward Karazhan to the south. The western road runs along its upper level, ending at the southern bridge, near enough the tower that its shadow falls over the stones.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Grosh'gok Compound",
			short = "The Deadwind ogres hold the Grosh'gok Compound, southernmost and largest of the mounds burrowed into the Vice's caves.",
			full = "The Deadwind ogres hold the Grosh'gok Compound, southernmost and largest of the mounds burrowed into the Vice's caves.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Karazhan (a.k.a. Medivh's Tower) is an abandoned citadel (or castle) located on a nexus of ley lines in southern Deadwind Pass.",
			full = "Karazhan (a.k.a. Medivh's Tower) is an abandoned citadel (or castle) located on a nexus of ley lines in southern Deadwind Pass. The tower is best known for its last known occupant -- Medivh, the last Guardian of Tirisfal. After Medivh was killed by Khadgar, Anduin Lothar, and Garona, the tower sealed itself off from the rest of the world. But recently, Karazhan has reawakened -- an evil presence has taken the tower as its own, its halls crawling with spirits and demons, and with the Shade of Medivh, his power being so great that his magic still echoes through the halls of Karazhan.\n\nIt is impossible to set eyes upon Karazhan without reflecting on the dark saga of its master. As befitting his title, the Last Guardian of Tirisfal had amassed a vast collection of writings and artifacts that dwarfs even that of the Kirin Tor. The tower is vast, dangerous, with ghosts everywhere, and where some of the world's most powerful and dangerous artifacts are stored, brought for years by the Dark Riders. Following the third invasion of the Burning Legion, Khadgar moved into the tower, seeking knowledge to save Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "Master's Cellar",
			short = "The ruined village above the Master's Cellar once housed the servants of Karazhan, those who kept the tower's fires lit and its halls swept for the master who dwelt above.",
			full = "The ruined village above the Master's Cellar once housed the servants of Karazhan, those who kept the tower's fires lit and its halls swept for the master who dwelt above. What became of them is written in the ground beneath their homes.\n\nTwo ways lead down into the dark. One opens into a vast wine cellar, its racks still standing, its shadows thick with the Unliving Residents and Unliving Caretakers who once tended it in life and now shamble through it in death, alongside Damned Souls, Restless Shades, and Wailing Spectres. The other entrance drops into a twin of that cellar, but here the floor gave way long ago, opening onto a cave system plunging deep underground, haunted by the same restless dead.\n\nGhosts riddle the place from one end to the other. Whatever was done to the servants of Karazhan, or whatever they did, left them unable to leave.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Morgan's Plot",
			short = "Morgan's Plot is a small decrepit church with a graveyard and crypt located in Deadwind Pass.",
			full = "Morgan's Plot is a small decrepit church with a graveyard and crypt located in Deadwind Pass. It can be found just behind Karazhan, and its graveyard serves as the respawn and spirit healer point for adventurers who die within the actual Karazhan instance. Lydia Accoste is found here.\n\nThe chapel itself was once inhabited by two Unliving Residents, and there was a third patrolling just down the hill.\n\nAegwynn and Cook are buried here, and Moroes and Medivh were before they were revived.\n\nThis section concerns content related to Legion.\n\nSince the third invasion of the Burning Legion, the place is now inhabited by Restless Spirits.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Sleeping Gorge",
			short = "In eastern Deadwind Pass, the land dips into a small chasm known as the Sleeping Gorge. One of the paths leading south to Karazhan runs through it for a time, before turning east into the Vice.",
			full = "In eastern Deadwind Pass, the land dips into a small chasm known as the Sleeping Gorge. One of the paths leading south to Karazhan runs through it for a time, before turning east into the Vice.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "Vice",
			short = "The Vice lies along the southern stretch of the road to Karazhan, in the desolate reach of Deadwind Pass.",
			full = "The Vice lies along the southern stretch of the road to Karazhan, in the desolate reach of Deadwind Pass. Here the Deadwind ogres have raised their mounds and camps, scattered across ground that offers nothing to sustain them but restless spirits and the few vultures that circle overhead. Why they chose such a barren stretch to call home, no one can say.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Duskwood: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Addle's Stead",
			short = "The fields of Addle's Stead lie gone to seed, the farmhouse and barn standing empty, left behind when the darkness crept over Duskwood and no one came back to work the soil.",
			full = "The fields of Addle's Stead lie gone to seed, the farmhouse and barn standing empty, left behind when the darkness crept over Duskwood and no one came back to work the soil.\n\nThe Defias Brotherhood took the place for their own. Their agents moved through the field, hid themselves in the barn, and stalked the small farmhouse, keeping among their papers a docket that held clues to the disappearance of Varian Wrynn.\n\nEven in death the Defias did not leave. Forlorn Spirits linger among the rows now, said to be the shades of the Brotherhood's own dead, still bound to the ground they once held.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Beggar's Haunt",
			short = "The tower at Beggar's Haunt has stood empty of soldiers for longer than anyone marks.",
			full = "The tower at Beggar's Haunt has stood empty of soldiers for longer than anyone marks. The Forsaken came after: Deathstalker Zraedus and Apothecary Faustin conducted experiments within its walls, but both are gone now, killed or departed. The tower has fallen to a new occupant, Abercrombie, who dwells there alone.\n\nA twisting path winds down to a small pool fed by a waterfall. Beside the water lies an unmarked grave, flanked by two great statues carved in the likeness of those that stand at the Dark Portal.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Brightwood Grove",
			short = "Brightwood Grove lies west of Darkshire, its few buildings now fallen to ruin. Nightbane worgen have claimed the dark fields for their own, raising crude camps and falling upon anything that strays too near.",
			full = "Brightwood Grove lies west of Darkshire, its few buildings now fallen to ruin. Nightbane worgen have claimed the dark fields for their own, raising crude camps and falling upon anything that strays too near.\n\nOnce the grove kept quieter company. Med'an and Meryl Winterstorm made their home here, known to almost no one beyond Garona Halforcen and Koron. That obscurity did not save them. Twilight's Hammer cultists fell upon the house, and in the attack Garona was taken.\n\nThe cult did not leave the grove for good. Under Twilight Lord Urgrok, its followers returned and seized one of the worgen camps for their own, working their rites among the ruins where the Winterstorms had once lived.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "Darkened Bank",
			short = "The Darkened Bank runs the length of Duskwood's northern shore, from the forest's far western edge to the bridge that carries the road into the Redridge Mountains.",
			full = "The Darkened Bank runs the length of Duskwood's northern shore, from the forest's far western edge to the bridge that carries the road into the Redridge Mountains.\n\nAt its western end, two refugees, Sven Yorgen and Lars, have made a small camp. They fled here from whatever drove them from their homes, and now they linger on this strip of shore, watching the darker woods to the south with the wariness of men who have already lost more than they wanted to.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Darkshire",
			short = "Darkshire was not always so named. It rose long ago as Grand Hamlet, a small woodland town built up as Stormwind's people spread into the nearby lands.",
			full = "Darkshire was not always so named. It rose long ago as Grand Hamlet, a small woodland town built up as Stormwind's people spread into the nearby lands. But the land itself never recovered from what happened at Karazhan. When the Guardian Medivh was slain in his tower there, the fel energy loosed by his death crept into the surrounding forest, twisting it into the thorned, lightless place it remains. Brightwood became Duskwood, and Grand Hamlet took the truer name of Darkshire.\n\nThe town's militia, the Night Watch, exists because Stormwind abandoned it. When Lady Katrana Prestor's schemes in Stormwind emptied the kingdom's garrisons from the forest, the townsfolk armed themselves rather than wait for soldiers who were never coming. Formed and trained entirely by the people of the forest, they have since held the roads against wolves, walking corpses, and worse, with no army left to call upon but themselves.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Dawning Wood Catacombs",
			short = "Beneath Raven Hill Cemetery, the ground itself is hollow. The Dawning Wood Catacombs twist through the dark in two directions. The eastern passage opens into a den of ghouls, disease-ridden and vicious.",
			full = "Beneath Raven Hill Cemetery, the ground itself is hollow. The Dawning Wood Catacombs twist through the dark in two directions. The eastern passage opens into a den of ghouls, disease-ridden and vicious. The western leads to a hall of skeletons, still guarding the tombs of the dead they once were.\n\nDeep within stands a shadow altar, once used by the Conclave to summon the ghost of Natalie Seline. What they raised did not stay bound to their will. Mathias Shaw and Flynn Fairwind cut her down and seized the sacred torch from the altar, then fled through the tunnels with the roused dead of the catacombs hunting behind them.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Forlorn Rowe",
			short = "A darkness clings to this hill on the northern edge of Raven Hill Cemetery, thicker than the gloom over the rest of Duskwood.",
			full = "A darkness clings to this hill on the northern edge of Raven Hill Cemetery, thicker than the gloom over the rest of Duskwood. Here Morbent Fel made his home, a necromancer whose arcane mastery over death bound the forest's undead to his will. Breaking his hold took a weapon forged for the purpose, and blood spilled fighting through the dead he commanded.\n\nWhen Morbent Fel fell at last, Commander Ladimore planted the Torch of Holy Flame before the necromancer's own door. Its light dispelled the dark enchantments that had animated the dead, and it burns there still, holding the undead of Raven Hill quiet in the shadow of Morbent Fel's house.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "Hushed Bank",
			short = "The Hushed Bank runs the length of Duskwood's western river, from where Westfall, Elwynn Forest, and Duskwood meet, down toward Stranglethorn Vale.",
			full = "The Hushed Bank runs the length of Duskwood's western river, from where Westfall, Elwynn Forest, and Duskwood meet, down toward Stranglethorn Vale. A covered bridge crosses the water here, the old way between Duskwood and Westfall.\n\nLars and Sven Yorgen once kept a camp on the northern corner of the bank, among spiders and wolves. Grave Robbers hold that camp now, and bears and owls move through the fog where the wolves once hunted.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Manor Mistmantle",
			short = "Manor Mistmantle stands in northeastern Duskwood, its grounds gone to rot, its halls given over to the ghoulish things that once served Stalvan Mistmantle, a schoolteacher and private tutor who died and rose again as an agent of the undead.",
			full = "Manor Mistmantle stands in northeastern Duskwood, its grounds gone to rot, its halls given over to the ghoulish things that once served Stalvan Mistmantle, a schoolteacher and private tutor who died and rose again as an agent of the undead.\n\nOnly one thing there still lives. Amid the ruin grows a single flower, the Tear of Tilloa, untouched by whatever curse has taken the rest of the grounds.\n\nAfter Stalvan's death, the manor did not fall quiet. Duskwood's branch of the Wolf Cult took the grounds for its own, killing off the ghouls that had haunted the place under Stalvan.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Raven Hill",
			short = "The buildings of Raven Hill stand empty along the western edge of Duskwood, their windows dark, their doors long since given up to rot.",
			full = "The buildings of Raven Hill stand empty along the western edge of Duskwood, their windows dark, their doors long since given up to rot. Few living souls ever kept residence here. Jitters remained, as did Bliztik, a goblin who kept himself out of sight on the top floor of one of the crumbling houses rather than risk the streets below. The rest of the town belonged to the dead -- the Unseen moved through it long after its people had gone, and no one troubled to reclaim the place from them.\n\nWhat haunted Raven Hill was not only the departed. Cecilia Clessington was kept here once, shut away in a manor her father purchased for that very purpose, watched over by attendants sworn to her silence. When she was questioned about the Drakefire Amulet, those attendants turned violent rather than let her answer, and were cut down for it. Outside, Vanessa VanCleef was waiting, and pressed Cecilia further once the manor's guardians had fallen.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Raven Hill Cemetery",
			short = "Raven Hill Cemetery sprawls north of the town it takes its name from, its rows of graves long since overrun by the undead, by spiders grown massive in the corruption, and by grave robbers who turn on anyone who disturbs them.",
			full = "Raven Hill Cemetery sprawls north of the town it takes its name from, its rows of graves long since overrun by the undead, by spiders grown massive in the corruption, and by grave robbers who turn on anyone who disturbs them. It was not always so vast; the graveyard swelled to swallow the surrounding ground only after the corruption of Duskwood took hold, and it stands abandoned now, tended by no one living.\n\nIn the cemetery's northwest corner rises Forlorn Rowe, once the home of the necromancer Morbent Fel. When Morgan Ladimore returned from the Third War, he came here and found the grave of his wife and children. He wept over it, and then he turned on the cemetery's attendants and killed three of them. After Morbent Fel's defeat, Commander Ladimore set the Torch of Holy Flame before the necromancer's old home, and its light still burns there, breaking dark enchantments and keeping the dead of the cemetery quiet.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Roland's Doom",
			short = "Roland's Doom takes its name for reasons the dirt does not tell, but the mound of earth near its entrance does, if disturbed. Here died Velinde Starsong, a night elven priestess who once carried the Scythe of Elune.",
			full = "Roland's Doom takes its name for reasons the dirt does not tell, but the mound of earth near its entrance does, if disturbed. Here died Velinde Starsong, a night elven priestess who once carried the Scythe of Elune. Her spirit still answers when the mound is touched.\n\nThe mine now belongs to the Nightbane pack, held by Gutspill and Nefaru, who lead the worgen ranging out from the nearby Rotting Orchard.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "Rotting Orchard",
			short = "The trees of the Rotting Orchard have gone black and brittle, their fruit rotting where it fell between the farmstead and the cemetery.",
			full = "The trees of the Rotting Orchard have gone black and brittle, their fruit rotting where it fell between the farmstead and the cemetery. The dilapidated buildings standing open to the weather are now home to the Nightbane pack of worgen. Shadow Weavers work their magic in hidden camps, Stalkers keep to the shadows, and Marus, the packleader, patrols the ground between the orchard and his den.\n\nA mirror of this orchard exists within the Emerald Dream, corrupted by the Nightmare. There, worgen twisted further still guard the Shadowscythe under the command of Amokarok.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Tranquil Gardens Cemetery",
			short = "Southeast of Darkshire, the Tranquil Gardens Cemetery keeps a name it no longer earns, for the dead here do not lie still, though they rise weak and thin, the least of Duskwood's horrors.",
			full = "Southeast of Darkshire, the Tranquil Gardens Cemetery keeps a name it no longer earns, for the dead here do not lie still, though they rise weak and thin, the least of Duskwood's horrors.\n\nA ruined church stands among the graves, roof broken to the sky, and inside it wanders a ghoul gone entirely mad.\n\nJust north of the plots stands Blind Mary's house, alone within sight of ground that never rests.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Twilight Grove",
			short = "The Twilight Grove sits in the middle of Duskwood and contains an unnamed great tree. It is home to one of the four portals to the Emerald Dream and was once guarded by the lieutenants of Ysera's green dragonflight.",
			full = "The Twilight Grove sits in the middle of Duskwood and contains an unnamed great tree. It is home to one of the four portals to the Emerald Dream and was once guarded by the lieutenants of Ysera's green dragonflight. The great tree was planted by Fandral Staghelm and his followers from one of Nordrassil's branches, in order to stem the tide of saronite seeping up from the land.\n\nThe Twilight Grove also contains a moonwell and a night elf gazebo. The other three dream portals can be found in Feralas, the Hinterlands, and Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Vul'Gol Ogre Mound",
			short = "Vul'Gol is a small basin sunk into the south of Duskwood, and it does not belong to the living anymore. The Splinter Fist ogres hold it entire, ruled by their chief Zzarc'Vul, whose name the mound now carries.",
			full = "Vul'Gol is a small basin sunk into the south of Duskwood, and it does not belong to the living anymore. The Splinter Fist ogres hold it entire, ruled by their chief Zzarc'Vul, whose name the mound now carries. Walk its edges and the old shape of the place still shows through the ogres' squalor: broken farmhouses and fallen fences, the marks of people who once worked this ground before the ogres came down and took it.\n\nThe Night Watch knows what is here and has chosen, deliberately, to leave it be. Its numbers are too few and too precious to spend grinding down an ogre camp when worse things stir elsewhere in Duskwood, so the mound has simply been left to fester.\n\nOthers have reasons of their own to want inside. The necromancer Abercrombie lost a crate of tools and herbs to an ogre raid, precious enough to him that he could not write it off, and it sits somewhere in the mound still, ogre plunder now.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "Yorgen Farmstead",
			short = "Sven Yorgen once tended this farmstead. Driven from it, he camps now at the Darkened Bank, watching over land he no longer holds.",
			full = "Sven Yorgen once tended this farmstead. Driven from it, he camps now at the Darkened Bank, watching over land he no longer holds.\n\nThe Defias Brotherhood has taken it for its own. Stealthed assassins move unseen through the fields.\n\nA second Yorgen Farmstead exists within the Emerald Dream, where Nightmare-corrupted dragonkin serve Ylanthrius, guarding dragon eggs.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "Algaz Station",
			short = "Algaz Station sits east of the North Gate Pass, south of Dun Algaz, and takes its name from that old stronghold.",
			full = "Algaz Station sits east of the North Gate Pass, south of Dun Algaz, and takes its name from that old stronghold. Dwarven mountaineers hold the outpost, watching the pass under Mountaineer Stormpike, with the armorer Gothor Brumn keeping their gear in order.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "The tunnel through the mountains between Loch Modan and the Wetlands is old enough that the Wildhammer dwarves used it to flee Ironforge, driven out in the War of the Three Hammers, before the orcs ever came to Khaz Modan.",
			full = "The tunnel through the mountains between Loch Modan and the Wetlands is old enough that the Wildhammer dwarves used it to flee Ironforge, driven out in the War of the Three Hammers, before the orcs ever came to Khaz Modan.\n\nWhen the Horde was broken at Dun Modr, its survivors fled south and dug in at Dun Algaz, a secondary outpost in the pass. Anduin Lothar meant to finish them there and drive the orcs back for good, and ordered the outpost torn down. The assault failed. The orcs held the pass, and Dun Algaz became the last ground the Horde kept in the region.\n\nMore recently the Dragonmaw clan overran the post outright, forcing the dwarven mountaineers who once watched the hills back to the upper tunnel. With the pass contested, the road between the dwarven homelands and Menethil Harbor grew dangerous, and the orcs threatened to cut Loch Modan off from the harbor entirely.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Farstrider Lodge",
			short = "The Farstrider Lodge stands in southeastern Loch Modan, its timber and stonework unmistakably high elven in make, though only one high elf remains within its halls.",
			full = "The Farstrider Lodge stands in southeastern Loch Modan, its timber and stonework unmistakably high elven in make, though only one high elf remains within its halls. Humans and dwarves have since made it their own, and it now serves as a hunters' lodge, its keepers skilled in tracking beast and bow alike.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Grizzlepaw Ridge",
			short = "Grizzlepaw Ridge rises south of Thelsamar, thick with bears.",
			full = "Grizzlepaw Ridge rises south of Thelsamar, thick with bears. Among them one is known by name: Ol' Sooty, a ferocious old bear who wanders down from his lair to the valley floor, and anyone careless enough to cross him finds him quick to pounce.\n\nGorick Guzzledraught keeps himself here too, among the ridge's bear-trails.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Ironband's Excavation Site",
			short = "Ironband's Excavation Site cuts deep into southeastern Loch Modan, where Prospector Ironband set his miners digging.",
			full = "Ironband's Excavation Site cuts deep into southeastern Loch Modan, where Prospector Ironband set his miners digging.\n\nThe earth did not stay quiet. Troggs broke up from below, larger and more violent than their kin at other dwarven digs, and drove the miners from their own trenches. The site remains unfinished, its trenches held now by the troggs that took them.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "The Loch",
			short = "The Loch was once the largest body of water in Khaz Modan, and third largest in the known world, after Lordamere and Darrowmere. Its waters gave Loch Modan its name and shape.",
			full = "The Loch was once the largest body of water in Khaz Modan, and third largest in the known world, after Lordamere and Darrowmere. Its waters gave Loch Modan its name and shape.\n\nNow the Twilight's Hammer holds two islands rising from the lakebed, encamped where only water once lay.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Mo'grosh Stronghold",
			short = "The caves of Mo'grosh Stronghold, in northeastern Loch Modan, hold the Mo'grosh ogres, darkmaulers and earthbenders who serve the Twilight's Hammer.",
			full = "The caves of Mo'grosh Stronghold, in northeastern Loch Modan, hold the Mo'grosh ogres, darkmaulers and earthbenders who serve the Twilight's Hammer. They drive elementium spikes into the drained lakebed, defiling the ground as their kin at the lakeside camp do. Over them stands Gor'kresh, disciple of Cho'gall himself.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "North Gate Pass cuts through the mountains between Dun Morogh above and Loch Modan below, the shortest way down toward the Wetlands, and so it sees steady traffic.",
			full = "North Gate Pass cuts through the mountains between Dun Morogh above and Loch Modan below, the shortest way down toward the Wetlands, and so it sees steady traffic. At the pass stands North Gate Outpost, a guard station set to watch the road between the two lands.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Silver Stream Mine",
			short = "The Silver Stream Mine once ran rich with silver, and the dwarves of Ironforge drew on it for generations before its veins finally gave out.",
			full = "The Silver Stream Mine once ran rich with silver, and the dwarves of Ironforge drew on it for generations before its veins finally gave out. Rather than abandon the tunnels, the Miners' League turned the emptied mine into a storage depot.\n\nThe mine still holds one thing no other place yields: Charged Rift Gems, prized for crafting mage robes.\n\nNow the tunnels belong to no dwarf. A swarm of Tunnel Rat kobolds has overrun the mine, claiming its depths and stores for their own.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate outpost"] = {
			name = "South Gate Outpost",
			short = "South Gate Outpost sits astride the South Gate Pass, the mountain road joining Dun Morogh to Loch Modan.",
			full = "South Gate Outpost sits astride the South Gate Pass, the mountain road joining Dun Morogh to Loch Modan. Mountaineers hold the outpost and have cleared the pass of the wildlife that presses in elsewhere, so those stationed here do not fight the battles their kin endure at North Gate Outpost. Travelers moving to and from Thelsamar pass this way, through a stretch of road already made safe.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "South Gate Pass cuts a way through the mountains, linking the high snows of Dun Morogh to the valleys of Loch Modan. It is the shortest road down to Thelsamar.",
			full = "South Gate Pass cuts a way through the mountains, linking the high snows of Dun Morogh to the valleys of Loch Modan. It is the shortest road down to Thelsamar. The dwarves keep it watched, holding South Gate Outpost here to guard the way between mountain and valley.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Stonesplinter Valley",
			short = "Stonesplinter Valley cuts through the mountains of southwestern Loch Modan, once a clean and untroubled stretch of ground. That is no longer so.",
			full = "Stonesplinter Valley cuts through the mountains of southwestern Loch Modan, once a clean and untroubled stretch of ground. That is no longer so. The Stonesplinter troggs have overrun it, spreading through its length and driving out whatever peace it held.\n\nDeep within, the troggs answer to Grawmug, their leader, entrenched at the valley's heart.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Stonewrought Dam",
			short = "Stonewrought Dam rises where Loch Modan meets its northern border, a wall of hewn stone holding back water that would otherwise have long ago reclaimed the lowlands beyond.",
			full = "Stonewrought Dam rises where Loch Modan meets its northern border, a wall of hewn stone holding back water that would otherwise have long ago reclaimed the lowlands beyond.\n\nFew who cross it know that the hand behind its making was a Dark Iron hand. The dwarf Franclorn Forgewright, architect of that clan, oversaw its raising and gave the world the stonewrought method by which it stands. His craft doubled the breadth of the Loch behind the dam's face, and in holding that water back shaped the flooded plains of the Wetlands below, ground that had once lain mostly beneath the surface.\n\nThe Twilight's Hammer broke what the Dark Iron craft had built, shattering the dam with their Twilight Landshaper. The workers who once labored along its length are gone now, unaccounted for, likely dead. The place stands mostly abandoned, its damage still raw.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Stoutlager Inn",
			short = "The Stoutlager Inn stands in Thelsamar, its hearth kept warm and its ale kept flowing. It is one of the most popular gathering places in Loch Modan, where travelers rest and drink and trade what news they carry.",
			full = "The Stoutlager Inn stands in Thelsamar, its hearth kept warm and its ale kept flowing. It is one of the most popular gathering places in Loch Modan, where travelers rest and drink and trade what news they carry.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Thelsamar sits on the western shore of Loch Modan, north of Grizzlepaw Ridge and northeast of Stonesplinter Valley, a dwarven town with gryphons wheeling from its roost.",
			full = "Thelsamar sits on the western shore of Loch Modan, north of Grizzlepaw Ridge and northeast of Stonesplinter Valley, a dwarven town with gryphons wheeling from its roost. A road runs just west of it, climbing through the passes toward Dun Morogh and the Wetlands.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Valley of Kings",
			short = "The Valley of Kings lies in the southwestern reach of Loch Modan, a strip of green pressed between the dwarven highlands and the scorched country beyond.",
			full = "The Valley of Kings lies in the southwestern reach of Loch Modan, a strip of green pressed between the dwarven highlands and the scorched country beyond. It serves as a passage both toward Dun Morogh and toward the region known as the Searing Gorge, whose gate stands locked and guarded, watched over by Mountaineer Pebblebitty, who yields passage only to those she judges strong enough.\n\nWhat draws the eye here are the two great statues that rise over the valley, carved in the likenesses of the dwarven kings Madoran Bronzebeard and Khardros Wildhammer. When the two kings died, their sons joined together to raise these monuments in their fathers' honor, setting them to stand watch over the pass into the southlands, land that had turned volcanic under the scorching presence of Ragnaros.\n\nThe statues serve a double purpose: a warning to any enemy who would come north through the Gorge, and a reminder of the price the Dark Irons paid for their crimes.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Redridge Mountains: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Alther's Mill",
			short = "The mill northeast of Lakeshire was once a quiet backwater, troubled only by spiders, buzzards, and the odd stray orc, a place travelers passed on their way to Stonewatch Keep.",
			full = "The mill northeast of Lakeshire was once a quiet backwater, troubled only by spiders, buzzards, and the odd stray orc, a place travelers passed on their way to Stonewatch Keep.\n\nThen the Blackrock clan took it and built a great worg kennel here. Under the orcs Homurk and Murdunk, the mill became a prison as much as a camp, and it was here that the human Messner was held captive among the howling worgs.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Galardell Valley",
			short = "Galardell Valley cuts through the northeastern Redridge Mountains, thick with gnolls under Lieutenant Fangore, who calls the pack down on any who face him alone.",
			full = "Galardell Valley cuts through the northeastern Redridge Mountains, thick with gnolls under Lieutenant Fangore, who calls the pack down on any who face him alone.\n\nAbove them stands the Tower of Ilgalar, where the evil Morganth dwells, drawing far more dread than the gnolls below.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Lake Everstill",
			short = "The waters of Lake Everstill lie calm at the heart of Redridge, ringed by the quiet rooftops of Lakeshire, and drained eastward by a river that runs on toward the dark walls of Stonewatch Keep.",
			full = "The waters of Lake Everstill lie calm at the heart of Redridge, ringed by the quiet rooftops of Lakeshire, and drained eastward by a river that runs on toward the dark walls of Stonewatch Keep. Once the lake was known simply for its fishing. That has changed. Murloc tribes have overrun the shallows and deeps alike, and something larger moves beneath the surface now, an elite thresher said to patrol the depths.\n\nThe lake still bears the scar of a mage's mistake. In the twenty-fourth year after the opening of the Dark Portal, a portal was opened at the lake's bottom, meant to lead up to Ironforge. No one thought to filter what would pass through it. Water poured through the opening without check, and the result was two disasters at once: Lakeshire's lake ran dry while Ironforge, far above, was flooded by the very waters that should have stayed here. The lake has since refilled, but the memory of the drought and the flood it caused far away remains tied to these waters.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Lakeridge Highway",
			short = "The Lakeridge Highway runs along the southern edge of Lake Everstill, once well-traveled before the First War. Since orcs took Stonewatch Keep, the road has fallen into disuse.",
			full = "The Lakeridge Highway runs along the southern edge of Lake Everstill, once well-traveled before the First War. Since orcs took Stonewatch Keep, the road has fallen into disuse. Gnolls now patrol most of its length, and further along, camouflaged Blackrock hunters lie in wait. Travel here is not safe.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Lakeshire",
			short = "Lake Everstill lies still and cold beneath the Redridge peaks, and the town on its shore has bled for that ground more than once.",
			full = "Lake Everstill lies still and cold beneath the Redridge peaks, and the town on its shore has bled for that ground more than once. When Warchief Blackhand first led orcs into these mountains, Sir Anduin Lothar and the Knights of Stormwind ambushed them on the slopes and nearly broke them, until two Shadow Council warlocks turned the battle and forced Lothar back. Blackhand returned weeks later with a greater host and took Lakeshire outright. Only after the Second War did the Alliance of Lordaeron reclaim it, Supreme Commander Turalyon overseeing the return of its scattered people.\n\nPeace never held long. Stonewatch Keep's guard platoon fell to Blackrock orcs driven by the warlock Morganth, who then turned on his own allies and raised an army of Shadowhide gnolls from the Tower of Ilgalar. Magistrate Solomon begged Stormwind for soldiers and was given none. In the end it was John J. Keeshan's Bravo Company that broke the siege, storming Stonewatch. Against the dragon Darkblaze over the lake, the company was destroyed to a man; Keeshan leapt onto the dying wyrm's back and vanished with it into the water. The townsfolk later recovered what belongings of his the lake gave back.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Redridge Canyons",
			short = "The gnolls of Redridge answer to Yowler, who dens among the canyon walls in the northwestern reaches of the mountains, holding the pack together as their leader.",
			full = "The gnolls of Redridge answer to Yowler, who dens among the canyon walls in the northwestern reaches of the mountains, holding the pack together as their leader.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Render's Camp",
			short = "Render's Camp sits among the northwestern peaks of Redridge, an outpost of the Blackrock orcs watching the way into the Burning Steppes beyond.",
			full = "Render's Camp sits among the northwestern peaks of Redridge, an outpost of the Blackrock orcs watching the way into the Burning Steppes beyond.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Render's Rock",
			short = "Render's Rock is a cave in the northwestern Redridge Mountains, its mouth opening toward the Burning Steppes, held by Blackrock orcs.",
			full = "Render's Rock is a cave in the northwestern Redridge Mountains, its mouth opening toward the Burning Steppes, held by Blackrock orcs.\n\nHere Corporal Keeshan lay wounded, unable to reach Lakeshire on his own.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Render's Valley",
			short = "The Blackrock orcs have dug in at Render's Valley, deep in the southeastern Redridge Mountains.",
			full = "The Blackrock orcs have dug in at Render's Valley, deep in the southeastern Redridge Mountains. Their outpost has hardened into a camp ringed with towers, its ranks thick with elite warriors, its skies watched over by dragon riders standing guard above the stone.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Rethban Caverns",
			short = "The caverns cut deep into the northwestern Redridge Mountains, dark tunnels held by gnolls under their cunning chieftain, Ardo Dirtpaw.",
			full = "The caverns cut deep into the northwestern Redridge Mountains, dark tunnels held by gnolls under their cunning chieftain, Ardo Dirtpaw. Within them lies Rethban ore, guarded jealously by his pack. The caverns are said to take their name from a man called Bart Rethban, though little else of him remains.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Stonewatch",
			short = "Stonewatch once belonged to the humans of Lakeshire, a fortress of keep, tower, and falls set to watch over Redridge against the raids that came out of the Burning Steppes.",
			full = "Stonewatch once belonged to the humans of Lakeshire, a fortress of keep, tower, and falls set to watch over Redridge against the raids that came out of the Burning Steppes. It did not fall to the orcs alone.\n\nThe warlock Morganth struck a bargain with Gath'Ilzogg and his Blackrock orcs, and together they threw themselves against Stonewatch Keep with a savagery that broke it. The keep fell. But no sooner had the orcs claimed their victory than Morganth turned on them, raising the Tower of Ilgalar for himself and binding a warband of Shadowhide gnolls under Lieutenant Fangore to his will. Orc and man alike have died to those gnolls since, prey to a warlock who used the siege only to build his own dominion within it.\n\nCut loose by their betrayer, the Blackrock orcs held the keep regardless, with Gath'Ilzogg ruling it and Tharil'zun as his lieutenant, until both were hunted down and killed within its walls. Stonewatch has stood empty since.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Stonewatch Falls",
			short = "Water spills from Lake Everstill, dropping down the hillside below Stonewatch into a deep pool against the eastern Redridge Mountains.",
			full = "Water spills from Lake Everstill, dropping down the hillside below Stonewatch into a deep pool against the eastern Redridge Mountains. A small tribe of murlocs has settled the shore, fishing the lake and raising crude shelters of stone and reed.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Stonewatch Keep",
			short = "Stonewatch Keep once belonged to the humans of Lakeshire, until the warlock Morganth struck a bargain with Gath'Ilzogg and his Blackrock orcs.",
			full = "Stonewatch Keep once belonged to the humans of Lakeshire, until the warlock Morganth struck a bargain with Gath'Ilzogg and his Blackrock orcs. Together they fell upon Redridge with a savagery that broke the keep's defenders, and Stonewatch was taken.\n\nVictory did not bind the alliance. Morganth turned on the orcs who had won it for him, raising the Tower of Ilgalar and filling it with Shadowhide gnolls under Lieutenant Fangore, bent to his own purposes. Since then both orc and man have died to the brutes he set loose.\n\nThe orcs held what remained of the keep regardless, Gath'Ilzogg ruling it with his lieutenant Tharil'zun at his side. It was in the fighting for Stonewatch that they took Corporal Keeshan of the Stormwind Army captive and dragged him off to their camps to the north. Magistrate Solomon set a price on Gath'Ilzogg's head for it, and Marshal Marris of Lakeshire swore the same for Tharil'zun.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Stonewatch Tower",
			short = "Stonewatch Tower stood beside Stonewatch Keep, once held by the humans of Lakeshire before the Blackrock clan seized both.",
			full = "Stonewatch Tower stood beside Stonewatch Keep, once held by the humans of Lakeshire before the Blackrock clan seized both. The tower remained firmly in the grip of Gath'Ilzogg's underlings, a stubborn outpost even as the land around it changed hands. Only when Darkblaze fell did the orcs abandon it, leaving the tower deserted.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Three Corners",
			short = "Three Corners lies where three roads meet just inside the Redridge Mountains, splitting toward Goldshire, Lakeshire, and Darkshire.",
			full = "Three Corners lies where three roads meet just inside the Redridge Mountains, splitting toward Goldshire, Lakeshire, and Darkshire. Barricades cross the roads here, manned by Redridge Garrison watchmen, and the signs nailed to them leave no room for argument: no transients, no exceptions. From the watchtower above the crossing, Watch Captain Parker keeps to the study of the gnolls pressing in from the hills, a newly given post and an old problem.\n\nThe quiet of the place broke entirely when the Scourge came down on it. Guard Captain Fairbanks's defenses were thrown against bloodthirsty ghouls while a frostwyrm wheeled overhead, and Guard Captain Josephine sent word back to Stormwind that the dead were still gathering, and that without more swords sent west, the city itself might soon be under siege.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Tower of Ilgalar",
			short = "Morganth once ruled the Tower of Ilgalar, deep in the eastern Redridge Mountains.",
			full = "Morganth once ruled the Tower of Ilgalar, deep in the eastern Redridge Mountains. Exiled from the Mage Quarter of Stormwind City for his study of the dark arts, he made this tower his refuge and bent the Shadowhide gnoll clan to his will.\n\nMorganth is gone now. In his place stands Grand Magus Doane -- in truth the black dragon Darkblaze, wearing a man's shape.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Stranglethorn Vale: 38 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Balia'mah Ruins",
			short = "Ancient troll ruins stand east of the river below Grom'gol, their builders long forgotten. The Skullsplitter trolls hold them now.",
			full = "Ancient troll ruins stand east of the river below Grom'gol, their builders long forgotten. The Skullsplitter trolls hold them now.\n\nDuring the war against the Zandalari, jungle serpents invaded Balia'mah, forcing their way into the ruins the Skullsplitters had claimed as their own.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Bal'lal Ruins",
			short = "Broken columns and half-sunk stonework mark where Bal'lal once stood on the coast of the Vile Reef, north of Grom'gol.",
			full = "Broken columns and half-sunk stonework mark where Bal'lal once stood on the coast of the Vile Reef, north of Grom'gol. Little remains but rubble now, claimed by Bloodscalp trolls who linger among the ruins of what earlier hands raised long ago.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Bloodsail Compound",
			short = "The Bloodsail Buccaneers keep a loose camp along the western coast of Stranglethorn Vale, their tents and fires scattered without much order above the surf.",
			full = "The Bloodsail Buccaneers keep a loose camp along the western coast of Stranglethorn Vale, their tents and fires scattered without much order above the surf.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Booty Bay",
			short = "The city sits in the cliffs around a sheltered blue lagoon at the southern tip of Stranglethorn Vale, entered by foot through the bleached white jaws of a giant shark.",
			full = "The city sits in the cliffs around a sheltered blue lagoon at the southern tip of Stranglethorn Vale, entered by foot through the bleached white jaws of a giant shark. Life is cheap here, and no one is worth trusting; it is a rogue's paradise, thick with information bought and sold.\n\nThe cove was not always Booty Bay. It was once Blackwater Cove, a small port held by humans, until jungle trolls overran it and drove them out. The goblins of the Steamwheedle Cartel came after, pushing the trolls from the shore in turn and raising their own harbor on the ruins, a trading post that stood already before the First War was fought.\n\nAfter the Second War, two orcs passed through. Bloodeye Redfist, a hotheaded troublemaker, had gotten himself into goblin custody and was near to being sold off, when Rehgar Earthfury bought his freedom from them.\n\nThe port is run now by the Blackwater Raiders under Baron Revilgaz, who shares the top floor of the inn with the Raiders' own Fleet Master Seahorn. The Baron keeps every hired blade he can find, for the Bloodsail Buccaneers have never let the town rest.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Cape of Stranglethorn",
			short = "The southern reach of Stranglethorn is a land of ruined troll temples and long sandy shores, held together by one town: Booty Bay, seated on the coast, run by goblin pirates who answer to no crown.",
			full = "The southern reach of Stranglethorn is a land of ruined troll temples and long sandy shores, held together by one town: Booty Bay, seated on the coast, run by goblin pirates who answer to no crown. Its harbor serves every flag and none, trading in whatever coin is offered, and a boat runs north from its docks to Ratchet.\n\nThat neutrality has a cost. The goblins of Booty Bay keep their peace by making it profitable to keep the peace, but the Bloodsail Buccaneers do not deal in that currency. Once these were pirates of the same waters, but the Bloodsail crews turned to raiding the shipping lanes Booty Bay depends on, and the goblins answered by naming them enemies outright. What began as rivalry between captains has hardened into open hostility along a coast too rich in trade to be left alone by either side.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Crystal Shore",
			short = "The Crystal Shore runs where the South Seas break against the Cape of Stranglethorn, from the Wild Shore up to the cliffs where the Cape meets Northern Stranglethorn.",
			full = "The Crystal Shore runs where the South Seas break against the Cape of Stranglethorn, from the Wild Shore up to the cliffs where the Cape meets Northern Stranglethorn. A steep ridge walls it off from the interior, crossed by two narrow paths, one winding up into Mistvale Valley.\n\nThree oil platforms belonging to the Venture Company tower over the southern waters, pipelines climbing the ridge to a storage tank above the beach. At the northern end stand the Ruins of Aboraz, old stone left to the tide.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Crystalvein Mine",
			short = "Crystalvein Mine holds a vein of Singing Crystals, stones found nowhere else in Stranglethorn.",
			full = "Crystalvein Mine holds a vein of Singing Crystals, stones found nowhere else in Stranglethorn. The basilisks nesting within eat them, and the crystals have hardened the reptiles' hides into something tougher than scale and bone. The Venture Co. moved in hoping to strip the mine bare, but the infestation has turned back every attempt.\n\nOutside stand figures of trolls and men, crystallized where they stood.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Grom'gol Base Camp",
			short = "Grom'gol Base Camp sits on the southwestern coast of Northern Stranglethorn, its palisades built strong against the jungle pressing in on all sides.",
			full = "Grom'gol Base Camp sits on the southwestern coast of Northern Stranglethorn, its palisades built strong against the jungle pressing in on all sides. Commander Aggro'gosh holds it, keeping open the supply chain that runs to Stonard in the Swamp of Sorrows.\n\nIts hardest trial came when the Gurubashi trolls turned on it during the war against the Zandalari. Bloodlord Mandokir led the assault himself. The camp held, and he was thrown back.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Gurubashi Arena",
			short = "The stone circle north of Booty Bay is older than the town, a relic of the Gurubashi Empire that once ruled the south of the Eastern Kingdoms.",
			full = "The stone circle north of Booty Bay is older than the town, a relic of the Gurubashi Empire that once ruled the south of the Eastern Kingdoms. The fights held here long ago were not sport but battles to the death, and the sand was once muddy with troll blood.\n\nWhat happens in the arena now is gentler, overseen by Short John Mithril, who keeps order over brawls fought for coin and boasting rather than lives.\n\nBeneath the common matches lies an older purpose. Once in a generation, the finest troll fighters from across Azeroth gathered here to test themselves against one another for the favor of the loa. To win was among the greatest honors a troll could claim. The rite was presided over by Rastakhan, the Zandalari king. With his death, no one can say whether the trolls will come again to fight for glory in this old arena.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Jaguero Isle",
			short = "Off the coast of the Wild Shore, panthers and gorillas hold Jaguero Isle. Among them rules King Mukla, an ape grown to enormous size, who keeps a tauren captive there, Princess Poobah.",
			full = "Off the coast of the Wild Shore, panthers and gorillas hold Jaguero Isle. Among them rules King Mukla, an ape grown to enormous size, who keeps a tauren captive there, Princess Poobah.\n\nHalf-buried bottles lie scattered along the Wild Shore's coastline, washed up from the sea, one holding a carefully folded note.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Janeiro's Point",
			short = "A small island stands off Booty Bay, crowned by a great statue of a goblin whose name no one now remembers, arms flung wide in welcome to every ship that comes within sight of the harbor.",
			full = "A small island stands off Booty Bay, crowned by a great statue of a goblin whose name no one now remembers, arms flung wide in welcome to every ship that comes within sight of the harbor. It was raised as a beacon, a promise of safe anchorage.\n\nTime has not been kind to it. The statue's left arm has broken away, leaving a ragged hollow in its side. Within that wound sits a small alcove crowded with treasure and sealed chests, untouched and untouchable, as if the goblin still guards what was placed there long ago.\n\nThe island no longer belongs to whatever hands built the statue. The sea giant Mok'rash the Cleaver has made it his home.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Kal'ai Ruins",
			short = "The Kal'ai Ruins lie half-drowned in Northern Stranglethorn, ancient troll stonework worn to broken walls and pillars beneath the tide.",
			full = "The Kal'ai Ruins lie half-drowned in Northern Stranglethorn, ancient troll stonework worn to broken walls and pillars beneath the tide. Their builders are long gone. The Murkgill tribe of murlocs now claims the flooded ruins as its own.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Kurzen's Compound",
			short = "Colonel Kurzen once commanded every soldier who now calls himself a rebel. Something turned his mind, and the men who would not follow him into that madness broke away, taking up arms against their former colonel.",
			full = "Colonel Kurzen once commanded every soldier who now calls himself a rebel. Something turned his mind, and the men who would not follow him into that madness broke away, taking up arms against their former colonel. Kurzen did not live to see how the split ended; he died before it was settled, and the loyalists who remained now answer instead to Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel, who carry on the fight against the deserters they call jungle fighters.\n\nNear the stables, cages hold captured panthers and Stranglethorn tigers, broken and trained by Kurzen's men until they answer to soldiers instead of instinct, becoming war panthers and war tigers fit to fight alongside the expedition that tamed them.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lake Nazferiti",
			short = "Lake Nazferiti's waters churn with frenzies and crocolisks, and the Venture Company has raised a sprawling base along its shore.",
			full = "Lake Nazferiti's waters churn with frenzies and crocolisks, and the Venture Company has raised a sprawling base along its shore. The river feeding it may be the longest in the southern Eastern Kingdoms, its confirmed source a waterfall in the Redridge Mountains, with headwaters perhaps reaching as far as haunted Deadwind Pass.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Mistvale Valley",
			short = "Fog settles thick over Mistvale Valley in the southern reaches of the Cape of Stranglethorn, and through it move the great Mistvale gorillas that give the vale its name, their shapes half-hidden in the grey until one is nearly upon them.",
			full = "Fog settles thick over Mistvale Valley in the southern reaches of the Cape of Stranglethorn, and through it move the great Mistvale gorillas that give the vale its name, their shapes half-hidden in the grey until one is nearly upon them.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Mizjah Ruins",
			short = "The Mizjah Ruins lie southeast of Grom'gol Base Camp, held by Mosh'Ogg Brutes and their Witch Doctors.",
			full = "The Mizjah Ruins lie southeast of Grom'gol Base Camp, held by Mosh'Ogg Brutes and their Witch Doctors. From these broken stones the ogres fall upon the supply caravans bound for Stonard, picking the road bare before wagons ever reach their destination.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Mosh'Ogg Ogre Mound",
			short = "The Mosh'Ogg mound sits south of Zul'Gurub, home to the ogre tribe of the same name. Deep within it, their leader, the ogre mage Mai'Zoth, guards a relic of great power called the Mind's Eye.",
			full = "The Mosh'Ogg mound sits south of Zul'Gurub, home to the ogre tribe of the same name. Deep within it, their leader, the ogre mage Mai'Zoth, guards a relic of great power called the Mind's Eye.\n\nBefore the ogres came, the mound was a shrine to the loa Lukou, tended by the Darkspear trolls. When the Darkspear left Stranglethorn, the worship of Lukou went with them.\n\nYears later the ogres turned the old shrine to a darker use, capturing Lukou and holding the loa captive within the mound. It was Rokhan of the Darkspear who came searching for the lost loa, entering the mound to free what the Mosh'Ogg had taken.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Nek'mani Wellspring",
			short = "High in the cliffs above the Southern Savage Coast, on the west side of the Cape of Stranglethorn, the Nek'mani Wellspring holds the only clean freshwater south of Duskwood.",
			full = "High in the cliffs above the Southern Savage Coast, on the west side of the Cape of Stranglethorn, the Nek'mani Wellspring holds the only clean freshwater south of Duskwood. Scholars have never agreed whose it is; every race claims the waters were made sacred for them alone. The argument was never settled by words. Now an expedition of naga has taken the spring and guards it ferociously.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Nesingwary's Expedition",
			short = "Below the river north of Lake Nazferiti sits the camp the dwarven hunter Hemet Nesingwary carved out of the jungle.",
			full = "Below the river north of Lake Nazferiti sits the camp the dwarven hunter Hemet Nesingwary carved out of the jungle. He led an expedition deep into Stranglethorn for the sake of the wild game that filled its valleys and hunting grounds. What began as little more than a hunter's camp has grown since into a proper station, reached now by a road cut through the undergrowth, and fortified against the jungle around it.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Rebel Camp",
			short = "The Rebel Camp stands in the northern reach of Stranglethorn Vale, west of the road down from Duskwood, within sight of Kurzen's Compound.",
			full = "The Rebel Camp stands in the northern reach of Stranglethorn Vale, west of the road down from Duskwood, within sight of Kurzen's Compound. Those who hold it were once Colonel Kurzen's own men.\n\nIn Year 25 ADP, Kurzen and the Stormwind expedition he led fell to Mai'Zoth's curse, their minds turned to madness. A handful broke free of it. Lieutenant Doren gathered them into rebellion, and they fled west from the compound to raise a camp of their own, set on undoing what the colonel had become. Krazek of Booty Bay kept them supplied, sending land mines so the rebels could hold their ground against Kurzen's cursed soldiers.\n\nDoren learned that three of the expedition's prisoners had somehow escaped the curse that claimed the rest: Berrin Burnquill, Emerine Junis, and Osborn Obnoticus. Freed from captivity, the three made their way to the Rebel Camp and joined it.\n\nLater, Bloodlord Mandokir led the Gurubashi trolls against the camp itself, and it was only turned back with help from outside.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruins of Aboraz",
			short = "Overgrown stone terraces along the coast still bear the carvings of the trolls who raised them. Now the ruins belong to Zanzil the Outcast, a witch doctor cast out from his own kind, who has made them his stronghold.",
			full = "Overgrown stone terraces along the coast still bear the carvings of the trolls who raised them. Now the ruins belong to Zanzil the Outcast, a witch doctor cast out from his own kind, who has made them his stronghold. His ghouls, naga, and troll minions wander freely among the old stones.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruins of Jubuwal",
			short = "The Ruins of Jubuwal, ancient troll stonework beside the Gurubashi road, now belong to Zanzil the Outcast, whose ghouls, naga, and trolls fill the ruins.",
			full = "The Ruins of Jubuwal, ancient troll stonework beside the Gurubashi road, now belong to Zanzil the Outcast, whose ghouls, naga, and trolls fill the ruins. Among them hide Jon-Jon the Crow and Maury \"Club Foot\" Wilkins, debtors who fled the ruthless Sea Wolf MacKinley rather than pay what they owe.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruins of Zul'Kunda",
			short = "The Ruins of Zul'Kunda lie deep in the jungle, claimed by the Bloodscalp trolls. Here their leaders hold court: Nezzliok the Dire and Gan'zulah, whose names alone keep any challenge to the ruins at bay.",
			full = "The Ruins of Zul'Kunda lie deep in the jungle, claimed by the Bloodscalp trolls. Here their leaders hold court: Nezzliok the Dire and Gan'zulah, whose names alone keep any challenge to the ruins at bay.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruins of Zul'Mamwe",
			short = "Ruined and hemmed in by mountains on every side but the north, Zul'Mamwe belongs to the Skullsplitters, the second great troll tribe of Stranglethorn Vale, ruled by their chieftain Ana'thek the Cruel.",
			full = "Ruined and hemmed in by mountains on every side but the north, Zul'Mamwe belongs to the Skullsplitters, the second great troll tribe of Stranglethorn Vale, ruled by their chieftain Ana'thek the Cruel. During the war against the Zandalari, jungle serpents pressed into the ruins, forcing their way in alongside the trolls.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "Savage Coast",
			short = "The Savage Coast runs along Stranglethorn Vale's northern shore, from the Westfall border down past the Vile Reef to Grom'Gol Base Camp.",
			full = "The Savage Coast runs along Stranglethorn Vale's northern shore, from the Westfall border down past the Vile Reef to Grom'Gol Base Camp. Crocolisks lurk in its shallows and basilisks bask among the rocks. Troll settlements dot the coastline, holdouts of a jungle left largely untamed.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Between the two great continents, where the waters of the Great Sea run deep and warm, lies the tangle of islands and reefs known as the South Seas.",
			full = "Between the two great continents, where the waters of the Great Sea run deep and warm, lies the tangle of islands and reefs known as the South Seas. Zandalar rises here, ancient seat of the trolls. Tel'Abim breaks the water further off. Kezan sits apart, its own scarred and smoking rock.\n\nThe coasts nearest the mainland are known better than the deep water beyond them. Stranglethorn Vale marks where the Eastern Kingdoms give way to this sea. To the west, Tanaris, the Thousand Needles, and Uldum stand where Kalimdor's shore meets the same waters.\n\nBeyond those known shores the South Seas keep their own geography of scattered, half-charted places: shallows and coves, sunken ruins, isles named for sailors and wrecks that found them and never came back to say more. Somewhere within this water, it is said, lies the Maelstrom itself, the great churning wound at the world's heart, though few who study the South Seas can say so with certainty.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Southern Savage Coast",
			short = "The Southern Savage Coast runs where the South Seas break against the western shore of the Cape of Stranglethorn, stretching from Hardwrench Hideaway in the north down past Janeiro's Point to the Wild Shore.",
			full = "The Southern Savage Coast runs where the South Seas break against the western shore of the Cape of Stranglethorn, stretching from Hardwrench Hideaway in the north down past Janeiro's Point to the Wild Shore. The Vile Reef marks where it parts from its northern namesake, the Savage Coast, the waters shifting there from the Great Sea into the South Seas. Along its bays and inlets it also touches the Gurubashi Arena and the Nek'mani Wellspring, before giving way near Booty Bay to the coast beyond.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Spirit Den",
			short = "The Spirit Den lies hidden in a cave at the northern end of Mistvale Valley, within the Cape of Stranglethorn. Witch Doctor Unbagwa keeps himself within, apart from the eyes of the valley outside.",
			full = "The Spirit Den lies hidden in a cave at the northern end of Mistvale Valley, within the Cape of Stranglethorn. Witch Doctor Unbagwa keeps himself within, apart from the eyes of the valley outside.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "Stockpile",
			short = "In the cave known as the Stockpile, at the back of Kurzen's Compound, four chiefs of the compound keep their equipment for war: Anders, Gaulus, Miranda, and Esquivel.",
			full = "In the cave known as the Stockpile, at the back of Kurzen's Compound, four chiefs of the compound keep their equipment for war: Anders, Gaulus, Miranda, and Esquivel. Here the tools of their fighting are gathered and held ready, deep in the compound's rear ground.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Tkashi Ruins",
			short = "The Tkashi Ruins are old troll stonework in Stranglethorn Vale, southwest of Nesingwary's camp, held now by the Bloodscalp trolls.",
			full = "The Tkashi Ruins are old troll stonework in Stranglethorn Vale, southwest of Nesingwary's camp, held now by the Bloodscalp trolls.\n\nTheir shamanism runs deep in these stones, and the artifacts scattered through the ruins are bound up in that practice, remnants of whatever power the Tkashi once called upon and the Bloodscalp now claim as their own.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Venture Co. Base Camp",
			short = "The Venture Company runs its base camp here, the center of its search for Tumbled Crystals, with the Operations Center standing close beside it.",
			full = "The Venture Company runs its base camp here, the center of its search for Tumbled Crystals, with the Operations Center standing close beside it.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Venture Co. Operations Center",
			short = "A Venture Company oil platform rises from a lake in Northern Stranglethorn.",
			full = "A Venture Company oil platform rises from a lake in Northern Stranglethorn. Goblin mechanics keep its machinery running while geologists comb the jungle around it, part of the company's push to claim the land's resources for itself.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "Vile Reef",
			short = "Beneath the bright coral of the Vile Reef, off the western coast of Stranglethorn, lie sunken troll ruins where murlocs have made their home.",
			full = "Beneath the bright coral of the Vile Reef, off the western coast of Stranglethorn, lie sunken troll ruins where murlocs have made their home. There stands the Altar of the Tides, half-lost to the reef grown up around it.\n\nGiant clams scatter the coral beds, rumored to hide blue pearls within their shells. Along the coast, broken shipwrecks lie half-buried in sand, wrecked by waters no ship sails safely.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Wild Shore",
			short = "Where the Eastern Kingdoms run out of land, the coast breaks into rock and shallow water, and here the Bloodsail Buccaneers keep their fleet at anchor.",
			full = "Where the Eastern Kingdoms run out of land, the coast breaks into rock and shallow water, and here the Bloodsail Buccaneers keep their fleet at anchor. The strait between the mainland and Jaguero Isle gives them cover and a narrow crossing, and their ships ride the water as if they own this stretch of shore, which they do.\n\nGorlash the giant wanders the same coastline, answering to no one, least of all the Bloodsail.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Yojamba Isle",
			short = "A cluster of tiny islands sits off the northwestern edge of northern Stranglethorn, near the Westfall border.",
			full = "A cluster of tiny islands sits off the northwestern edge of northern Stranglethorn, near the Westfall border. Here the Zandalar Tribe once called on the Alliance and the Horde to stand with them against Hakkar the Soulflayer, whose corruption festered in Zul'Gurub.\n\nWhen Hakkar fell, most of the Zandalari took ship for home. A few returned later, not for war but for words: a gathering meant to unite the scattered troll tribes for the sake of their race.\n\nWhat remains now is stranger. The Crystal Spine Matriarch has made the isle hers, and where Bloodscalp trolls once stood, berserkers, witch doctors, shaman, she has turned them to stone, scattered across the shore, frozen mid-motion.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ziata'jai Ruins",
			short = "The Ziata'jai Ruins stand north of Fort Livingston, old troll stonework long since claimed by the Skullsplitter tribe.",
			full = "The Ziata'jai Ruins stand north of Fort Livingston, old troll stonework long since claimed by the Skullsplitter tribe. Jungle serpents have since pushed into the ruins, coiling through the broken stone the Skullsplitters call home.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub rises in northeastern Stranglethorn Vale, its terraces and idols half-swallowed by jungle.",
			full = "Zul'Gurub rises in northeastern Stranglethorn Vale, its terraces and idols half-swallowed by jungle. Once it was the seat of an empire that ruled every jungle troll tribe in the land; now it is only the Gurubashi capital, and something far worse besides.\n\nThe empire broke itself here. Fifteen hundred years before the Dark Portal opened, priests called the Atal'ai summoned the avatar of Hakkar the Soulflayer, a blood-god of terrible hunger. They were driven into exile, and the empire they left behind collapsed into ruin.\n\nThe priests learned that Hakkar could only take physical form within Zul'Gurub itself. It was here that Jin'do the Hexxer enslaved a company of Gurubashi high priests to drag the Soulflayer into the world. Five champions, each bound to a Primal God, were sent to stop him, and every one of them fell instead, their stolen power feeding Hakkar's strength. The Darkspear tribe stormed the city and cut down Jin'do, but not before Hakkar had already crossed into Azeroth.\n\nMuch of the city has since caved in on itself, and the taint of the Soulflayer has never left these stones.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Zuuldaia Ruins",
			short = "The stones at Zuuldaia have outlasted whoever first raised them.",
			full = "The stones at Zuuldaia have outlasted whoever first raised them. Now they belong to the Bloodscalp trolls, who hold the ruins along the northern reach of Stranglethorn's western coast, having made this ancient place their own.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Swamp of Sorrows: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Fallow Sanctuary",
			short = "In the Swamp of Sorrows stands the Fallow Sanctuary, village of a tribe called simply the Lost Ones. Homesickness has driven every one of them mad, until nothing gentle was left.",
			full = "In the Swamp of Sorrows stands the Fallow Sanctuary, village of a tribe called simply the Lost Ones. Homesickness has driven every one of them mad, until nothing gentle was left. All have gone completely feral.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "Harborage",
			short = "In the north of the Swamp of Sorrows stands the Harborage, a refuge of Broken who crossed over from Draenor and, unlike so many of their kind, kept their minds whole.",
			full = "In the north of the Swamp of Sorrows stands the Harborage, a refuge of Broken who crossed over from Draenor and, unlike so many of their kind, kept their minds whole. It was led by the elder Magtoor.\n\nThe Broken here were harassed by the Lost Ones of the Fallow Sanctuary, mutated draenei who had once called them kin. The Lost Ones stole draenethyst shards from the Harborage, and to the Broken these shards are not treasure but sanity itself, the thing that keeps them from sliding into the ruin that claimed their tormentors.\n\nAnchorite Avuun came to dwell among them in this time, seeking some cure for the Broken's affliction. The Harborage was rebuilt after the old draenei manner and given over to the Alliance.\n\nMagtoor has grown old in the years since, and now the Harborage waits with Avuun at his side, readying itself for the day their elder passes.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Itharius's Cave",
			short = "In the far southwestern reaches of the Swamp of Sorrows, a cave shelters the high elf Itharius.",
			full = "In the far southwestern reaches of the Swamp of Sorrows, a cave shelters the high elf Itharius. Outside, green whelps stumble and scrap among themselves, unruly and young, and it is Itharius who watches over them as they grow.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Misty Reed Post",
			short = "Misty Reed Post stands between the Stagalbog and the Misty Reed Strand, a small outpost of Stonard. Tok'Kar keeps watch here with Katar, a few Stonard hunters, and a shaman.",
			full = "Misty Reed Post stands between the Stagalbog and the Misty Reed Strand, a small outpost of Stonard. Tok'Kar keeps watch here with Katar, a few Stonard hunters, and a shaman. No burrow or tower has been built yet, though Tok'Kar dreams of raising one someday.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Misty Reed Strand",
			short = "The Misty Reed Strand runs long and grey where the Swamp of Sorrows meets the water, littered with driftwood and debris, home to crocolisks, crabs, murlocs, and gilblins.",
			full = "The Misty Reed Strand runs long and grey where the Swamp of Sorrows meets the water, littered with driftwood and debris, home to crocolisks, crabs, murlocs, and gilblins.\n\nThe Steamwheedle Cartel raised the resort town of Bogpaddle on its northern edge, with a full harbor, and pushed smaller camps south along the coast. The swamp did not yield easily. Something has turned the local wildlife vicious beyond its nature, and the southern camps have been torn apart for it. Baba Bogbrew has been brought in to find the cause, and until she does, the wreckage of goblin ambition still lies where it fell.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Misty Valley",
			short = "Fog lies thick over Misty Valley, in the northwestern Swamp of Sorrows, north of the way into Deadwind Pass. Native grells move through the mist, and at the back of the valley a cave shelters a great panther, Duskfang.",
			full = "Fog lies thick over Misty Valley, in the northwestern Swamp of Sorrows, north of the way into Deadwind Pass. Native grells move through the mist, and at the back of the valley a cave shelters a great panther, Duskfang.\n\nThat cave once belonged to another tenant, the Mire Lord, an elemental thing. Where it went, no one can say.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Pool of Tears",
			short = "Beneath the still waters of the Pool of Tears rests the Temple of Atal'Hakkar, sunk there by Ysera herself to seal away its corruption.",
			full = "Beneath the still waters of the Pool of Tears rests the Temple of Atal'Hakkar, sunk there by Ysera herself to seal away its corruption. Green dragons once watched over the drowned temple.\n\nThe pool has never been at peace since. Blood-thirsty frenzies move through its depths, and along the shore and underwater lie the broken remains of Atal'ai ruins, among which relics of the drowned cult can still be found.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "Shifting Mire",
			short = "The silt of the Shifting Mire does not lie still. It gathers itself, drifts, and creeps across the ground as though something beneath it breathed.",
			full = "The silt of the Shifting Mire does not lie still. It gathers itself, drifts, and creeps across the ground as though something beneath it breathed. Anchorite Avuun, who has studied it, holds that the force behind this is no curse but a positive energy stirring the earth.\n\nCrocolisks, sorrow spinners, swamp jaguars, and the Lost Ones move through ground that never quite settles beneath them.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Sorrowmurk",
			short = "The Sorrowmurk lies east of the Pool of Tears, near the Sunken Temple.",
			full = "The Sorrowmurk lies east of the Pool of Tears, near the Sunken Temple. Green dragonspawn once crawled thick through its mud, and a great green drake wheeled above it, making the swamp a place only the most reckless traveler would enter.\n\nThat tide has since drawn back. In its place, a neutral band of goblins led by Crazy Larry has raised a camp on the shore, now besieged in turn by gilblins crawling up out of the water.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Splinterspear Junction",
			short = "Splinterspear Junction sits where the road into the Swamp of Sorrows forks, one branch running north toward the Fallow Sanctuary, the other south to Stonard.",
			full = "Splinterspear Junction sits where the road into the Swamp of Sorrows forks, one branch running north toward the Fallow Sanctuary, the other south to Stonard. An old orcish watch tower still stands over the crossing, and Horde patrols keep the roads under watch.\n\nBefore it was a junction, this ground was the orcish outpost of Kyross, the closest Horde stronghold to the human township of Grand Hamlet. In the First War, Stormwind sent war parties into the swamp to see it burned. In one such battle Lieutenant Blake Godwyn fell, an officer out of Lordaeron. He was buried where he died, alongside the ancestral sword he had carried into the swamp, and his grave remains there still, at the fork of the road, under the shadow of the tower.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "The Stagalbog is dense marshland south of the Pool of Tears, where the Swamp of Sorrows meets the southern mountains.",
			full = "The Stagalbog is dense marshland south of the Pool of Tears, where the Swamp of Sorrows meets the southern mountains. Its only settlement is the camp of Baba Bogbrew, whose people emerged from the nearby Temple of Atal'Hakkar. West of the camp, a cave opens at the foot of the mountains.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Stagalbog Cave",
			short = "The cave beneath the Stagalbog once belonged to the Marsh tribe of murlocs, ruled by the Swamp Talker.",
			full = "The cave beneath the Stagalbog once belonged to the Marsh tribe of murlocs, ruled by the Swamp Talker. Something in that rule spread beyond them: animals across the swamp turned strange, growing aggressive beyond their nature, drawn one by one toward the cave.\n\nOutside its mouth, just to the east, a small camp of Steamwheedle Cartel goblins has settled under Baba Bogbrew.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Stonard",
			short = "Stonard rises out of the Swamp of Sorrows on old ground, raised by the Old Horde in the Black Morass in the days after the Dark Portal first opened, one of the earliest orc settlements ever built in this world, sister to the fortress once called Rockard.",
			full = "Stonard rises out of the Swamp of Sorrows on old ground, raised by the Old Horde in the Black Morass in the days after the Dark Portal first opened, one of the earliest orc settlements ever built in this world, sister to the fortress once called Rockard. When the Second War broke and the old order collapsed, Stonard fell quiet, likely destroyed or abandoned. Rockard never returned to orcish hands; the Dreadmaul ogres took it instead and renamed it Dreadmaul Hold, and it stands against the Horde still.\n\nStonard was rebuilt. With the new Horde came a will to hold this swamp again, and the town rose around one of the few great halls still standing among orcish communities, guarded by two burrows. For a long while it stood alone here, the only Horde outpost in reach.\n\nIts nearness to the Alliance lands of Redridge, Elwynn, and Duskwood has not gone unnoticed. The Alliance raised Marshtide Watch on the edge of the Pool of Tears to answer it, and the marsh called the Bloodmire has become the ground where the two sides meet again, Stonard's walls the prize each time.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Temple of Atal'Hakkar",
			short = "The Temple of Atal'Hakkar (also known as the Sunken Temple) is a shrine to the nefarious Blood God Hakkar the Soulflayer that was erected by the Atal'ai trolls led by their master Jammal'an the Prophet.",
			full = "The Temple of Atal'Hakkar (also known as the Sunken Temple) is a shrine to the nefarious Blood God Hakkar the Soulflayer that was erected by the Atal'ai trolls led by their master Jammal'an the Prophet. Believing that this was the intended site for Hakkar's reentry into Azeroth, the great Dragon Aspect Ysera and her green dragonflight sunk the temple into the depths of the Swamp of Sorrows. However, this actually helped the Atal'ai by ensuring their efforts to summon Hakkar went on undisturbed.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Westfall: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Alexston Farmstead",
			short = "The fields at Alexston Farmstead once fed families, before the Defias Brotherhood claimed them as they claimed so many farms across Westfall.",
			full = "The fields at Alexston Farmstead once fed families, before the Defias Brotherhood claimed them as they claimed so many farms across Westfall. The Brotherhood has since fallen, but no one has returned to work the soil. Only the mechanical Harvest Watchers remain, striding through empty rows as if still guarding a harvest no one will bring in.\n\nBaros Alexston, who rose to serve Stormwind City as an architect, was born to nothing here, and worked this same land as a boy.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Dagger Hills",
			short = "The ridge rises behind Moonbrook, giving the southern reach of Westfall its second name.",
			full = "The ridge rises behind Moonbrook, giving the southern reach of Westfall its second name. Little moves here now but Grimbooze Thunderbrew, alone in the hills, and the ghoul Leprithus, which still rises from the ground now and again.\n\nWhen the Burning Legion swept through, the Dagger Hills fell under its dominion. Dreadlords enslaved the people who lived here, and defenders later killed them.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "Dead Acre",
			short = "The Dead Acre was once a working farm in southeast Westfall, near the bridge into Duskwood. That ended when the Defias Brotherhood put the place to the torch, farmhouse and fields together.",
			full = "The Dead Acre was once a working farm in southeast Westfall, near the bridge into Duskwood. That ended when the Defias Brotherhood put the place to the torch, farmhouse and fields together.\n\nWhat is left is ash. The ground still smolders, and mechanical Harvest Watchers stalk the ruined furrows where crops once grew, the only things left tending a field that will never be harvested again.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Deadmines",
			short = "Beneath Moonbrook the tunnels run deep, and once they ran with gold. Before the orcs ever crossed into human lands, the Deadmines fed Stormwind's treasury -- by some accounts a third of it came from this rock.",
			full = "Beneath Moonbrook the tunnels run deep, and once they ran with gold. Before the orcs ever crossed into human lands, the Deadmines fed Stormwind's treasury -- by some accounts a third of it came from this rock. The First War emptied the mines of miners, and afterward they were left for dead, thought haunted, and untouched for a long while.\n\nInto that silence came Edwin VanCleef, who gathered the Defias Brotherhood, former laborers turned brigands, and set them to building a juggernaught in the depths with goblin help.\n\nVanCleef's reckoning came when Gryan Stoutmantle sent soldiers through Ironclad Cove to the juggernaught itself. They killed VanCleef there and carried his head off as proof. What none of them saw was his daughter, watching from the shadows as her father was beheaded. Vanessa VanCleef did not forget it. Five years later she had made herself leader of the Defias in his place, and set the mines back to their old purpose, raising new hands to finish the juggernaught her father had begun.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Demont's Place",
			short = "The farmhouse west of Moonbrook stands empty, its fields as ruined as those of the Dead Acre nearby. It once belonged to someone named Demont, though nothing here says more than that.",
			full = "The farmhouse west of Moonbrook stands empty, its fields as ruined as those of the Dead Acre nearby. It once belonged to someone named Demont, though nothing here says more than that. Defias agents held it for a time, using the abandoned farmstead for their own ends, until the Brotherhood fell and left it deserted again.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Dust Plains",
			short = "The Dust Plains lie across southern Westfall, open ground held by gnolls camped throughout the dust.",
			full = "The Dust Plains lie across southern Westfall, open ground held by gnolls camped throughout the dust.\n\nOn the eastern edge stands Mortwake's Tower, once a mage's hold. Mercenaries occupy it now, working for Helix Gearbreaker.\n\nWhen the Burning Legion came, the plains fell under its control. Its people were enslaved by nathrezim, then killed by the very defenders sent to free them.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Furlbrow's Pumpkin Farm",
			short = "Furlbrow's Pumpkin Farm once belonged to the family whose name it bears, until the Defias Brotherhood swept through Westfall and turned its fields over to their mechanical harvest golems.",
			full = "Furlbrow's Pumpkin Farm once belonged to the family whose name it bears, until the Defias Brotherhood swept through Westfall and turned its fields over to their mechanical harvest golems. Farmer Furlbrow and his wife Verna abandoned the land rather than face the Brotherhood, fleeing north to the road near the Jansen Stead, where they have remained ever since, landless.\n\nWhat they left behind did not stay empty. Homeless Stormwind citizens and transients, drifting through Westfall with nowhere else to go, settled among the pumpkin rows and the idle golems, making a home of what the Defias had seized and abandoned.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Gold Coast Quarry",
			short = "The Gold Coast Quarry once yielded gold and ore for the crown of Stormwind. When Westfall fell to ruin, the Defias Brotherhood claimed it, working the tunnels for themselves and patrolling its paths for a long while.",
			full = "The Gold Coast Quarry once yielded gold and ore for the crown of Stormwind. When Westfall fell to ruin, the Defias Brotherhood claimed it, working the tunnels for themselves and patrolling its paths for a long while. Their hold broke only when the People's Militia defeated them here. The quarry stands abandoned now.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Jangolode Mine",
			short = "The Jangolode Mine once fed Stormwind City with minerals dug from its tunnels. The Defias Brotherhood seized it for a time, and when they were driven out, kobolds claimed the mine for themselves.",
			full = "The Jangolode Mine once fed Stormwind City with minerals dug from its tunnels. The Defias Brotherhood seized it for a time, and when they were driven out, kobolds claimed the mine for themselves.\n\nLater the Burning Legion took the area. Its kobold residents were enslaved by nathrezim, then killed by the defenders who came to break the Legion's hold.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "Jansen Stead",
			short = "Jansen Stead lies at the northern edge of Westfall, where the road runs down to the bridge into Elwynn Forest.",
			full = "Jansen Stead lies at the northern edge of Westfall, where the road runs down to the bridge into Elwynn Forest. Like the other farms of the plains, it once had a family working its fields, but the Defias Brotherhood drove them off along with everyone else who tried to make a living from this land.\n\nWhat remains has become a gathering place for the dispossessed of Westfall, homeless folk from Stormwind, drifters, transients with nowhere else to go. They keep to the ruined stead and say little to strangers, which is what makes the place uneasy. Nearby, Theodore and Verna Furlbrow were murdered, and the killing is still being looked into. Those camped at Jansen Stead know something of it, but none will speak.\n\nThe stead takes its name from Private Jansen of the Westfall Brigade, though little else is remembered of him now.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Longshore",
			short = "The coast of Westfall stretches on for miles, one of the widest beaches in all of Azeroth. It is a hard shore to walk.",
			full = "The coast of Westfall stretches on for miles, one of the widest beaches in all of Azeroth. It is a hard shore to walk. Murlocs move along it in unchecked swarms, and among them prowls Old Murk-Eye, a creature known by name to those who have faced him and lived. Out past the breakers, the wrecks of ships rest half-buried in the shallows, elven destroyers among them.\n\nOn the far southwestern reach of that coast stands Daphne Stilwell's farm. The Defias Brotherhood came against her there, again and again, until Duthorian Rall sent aspiring Knights of the Silver Hand to stand watch over her land and drive the attackers back.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "Molsen Farm",
			short = "The fields of Molsen Farm lie quiet now. The Defias Brotherhood once held it, as they held so many farms of Westfall, driving off whoever worked the land.",
			full = "The fields of Molsen Farm lie quiet now. The Defias Brotherhood once held it, as they held so many farms of Westfall, driving off whoever worked the land. Only a name endures -- Private Molsen of the Westfall Brigade, whose kin, it is said, once called this ground home.\n\nThe Brotherhood is broken now, but the farm was never given back. Mechanical Harvest Watchers patrol its empty rows, deadly to anything that crosses them.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Moonbrook",
			short = "Beneath the fields of Moonbrook once ran a third of Stormwind's treasury, gold pulled from the tunnels later called the Deadmines.",
			full = "Beneath the fields of Moonbrook once ran a third of Stormwind's treasury, gold pulled from the tunnels later called the Deadmines. The town was the kingdom's breadbasket, until the disbanding of the Stonemasons Guild set off riots that killed Queen Tiffin Wrynn. King Varian's vengeance for her death fell hardest on the guild, and the Stonemasons fled into the farmlands of Westfall to escape him. Stoked from the shadows, their anger became the Defias Brotherhood. Under Edwin VanCleef they turned to banditry, drove the farmers from Moonbrook, and took the abandoned mine tunnels beneath the town as their headquarters, working there in secret to build a weapon meant to destroy Stormwind from the sea.\n\nFor years no army came to answer them. It was Gryan Stoutmantle's People's Militia, and the heroes he gathered to his cause, who finally broke the Brotherhood's hold, following VanCleef into the Deadmines and killing him there. Only then was Moonbrook free again.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Saldean's Farm",
			short = "Saldean's Farm stands alone among the farmsteads of Westfall, for it is the one the Defias Brotherhood never fully took.",
			full = "Saldean's Farm stands alone among the farmsteads of Westfall, for it is the one the Defias Brotherhood never fully took. Harvest golems still stalk the fields, but Farmer Saldean and his wife Salma have refused to abandon their home, and for years their farmhouse has served as a halfway house for the desperate, feeding the homeless who drifted into the region with their famous stew.\n\nOne day a little girl stumbled into the farmhouse and collapsed, remembering nothing of who she was. The Saldeans took her in and named her Hope, for the hard times that had fallen on them all. That child was Vanessa VanCleef. When she returned to them years later, they grieved for what she had done under that name, but to them she remained, and would always remain, only Hope.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Sentinel Hill",
			short = "Sentinel Hill stands on its rise above Westfall, a tower ringed by cottages, forge, and lumber mill.",
			full = "Sentinel Hill stands on its rise above Westfall, a tower ringed by cottages, forge, and lumber mill. King Varian Wrynn poured supplies, troops, and siege engines into it, hoping to raise it from the wreckage of a kingdom's breadbasket and shelter Stormwind's homeless. That hope is unfinished. The stronghold's gates are still closed to the ragged crowds camped in its shadow, waiting for walls that are not yet theirs to enter.\n\nFrom this hill the garrison has pushed outward, clawing back Moonbrook, the Furlbrow's Pumpkin Farm, and the Jansen Stead. But the reclaiming has come at a cost: the Defias Brotherhood, born of Westfall's own dispossessed, has turned on the very hill meant to save them.\n\nSentinel Hill remains a promise still being paid for, watched over by soldiers holding a line between a starving countryside and the crowd outside the gate.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Stendel's Pond",
			short = "Stendel's Pond lies southwest of Sentinel Hill, a small stretch of water ringed by gnolls now.",
			full = "Stendel's Pond lies southwest of Sentinel Hill, a small stretch of water ringed by gnolls now. Two graves sit at its edge, and scattered bones lie half-buried in the mud nearby, enough to make anyone think twice before drinking from it.\n\nSomething else is said to linger beneath the surface, an old, strange fish that almost no one has ever pulled from the water, alongside the schools of sagefish that are common enough to catch.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Westfall Lighthouse",
			short = "The Westfall Lighthouse stands just off the coast at the far southern edge of Westfall, its beam still circling out over the water at night.",
			full = "The Westfall Lighthouse stands just off the coast at the far southern edge of Westfall, its beam still circling out over the water at night. It was once tended by a family, until the murloc known as Old Murk-Eye came out of the surf and frightened them from their post. They came back and relit the flame, braver than the sea deserved. Old Murk-Eye returned too, this time with murlocs at his back, and the family that had fled once had nowhere left to flee to. They died there, in view of the keeper who could do nothing to save them.\n\nThat keeper is Captain Grayson, and he never left. He stands outside the lighthouse still, a ghost bound to a duty no living hand took up, watching the coast for the murlocs that killed the family he could not protect.\n\nThe doorway of the lighthouse carries its own quiet record. Mathias Shaw cuts a notch into the wood for every agent of his he loses. The door is covered in cuts.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Wetlands: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Angerfang Encampment",
			short = "Angerfang Encampment is the largest Dragonmaw orc camp in central Wetlands, home to the Angerfang. Catapults gathered here for one purpose: to be turned on Menethil Harbor.",
			full = "Angerfang Encampment is the largest Dragonmaw orc camp in central Wetlands, home to the Angerfang. Catapults gathered here for one purpose: to be turned on Menethil Harbor.\n\nThe camp answered to Nek'rosh Skullcrusher, son of Nekros Skullcrusher, who carried the plan against the harbor forward. The Alliance judged him worth killing for it, and sent agents to end him. With his death the push toward Menethil broke apart, and Captain Stoutfist called for the war banners of the beaten Angerfang as proof the camp's teeth had been pulled.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baradin Bay",
			short = "The waters of Baradin Bay wash the coast where Dun Morogh gives way to Gilneas, past Menethil Harbor, Stromgarde Keep, the emptied township of Southshore, and Stormglen Village.",
			full = "The waters of Baradin Bay wash the coast where Dun Morogh gives way to Gilneas, past Menethil Harbor, Stromgarde Keep, the emptied township of Southshore, and Stormglen Village. It is a working sea, patrolled since the Second War by the Kul Tiran armada, whose duty it was to keep the shipping lanes between the Eastern Kingdoms free.\n\nThat duty was paid for in wrecks. The Third Fleet of Kul Tiras was destroyed in the Second War, and its bones remain scattered along the coast of the Wetlands, hulls broken open on the rocks, others gone down entirely into the deep water of the bay. A lost fleet rests within sight of the harbor it once sailed from.\n\nBeneath the surface the bay belongs to older things than ships. Murlocs and crocolisks keep to the shallows near the shore, while out past the reefs the deeper water holds crabs and sharks.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Black Channel Marsh",
			short = "Black Channel Marsh lies in the southwestern Wetlands, along the road to Menethil Harbor.",
			full = "Black Channel Marsh lies in the southwestern Wetlands, along the road to Menethil Harbor. Its waters hide numerous raptor lairs, and the hungriest of the beasts sometimes wander close to the road, so travelers passing this way keep a careful watch on the reeds.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Bluegill Marsh",
			short = "Bluegill Marsh, in the western Wetlands, holds several murloc camps that never stand alone. The Bluegill come in twos and threes through the reeds, hard to face one at a time.",
			full = "Bluegill Marsh, in the western Wetlands, holds several murloc camps that never stand alone. The Bluegill come in twos and threes through the reeds, hard to face one at a time.\n\nGobbler rules over them, a murloc fiercer than the rest, and under him the Bluegill have grown bold enough to raid beyond the marsh for stolen goods.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Deepwater Tavern",
			short = "The Deepwater Tavern stands at the heart of Menethil Harbor, loud most nights with talk and drink, and no stranger to fists -- Tapoke \"Slim\" Jahn has started more than a few brawls within its walls.",
			full = "The Deepwater Tavern stands at the heart of Menethil Harbor, loud most nights with talk and drink, and no stranger to fists -- Tapoke \"Slim\" Jahn has started more than a few brawls within its walls.\n\nWhen disaster struck the town and the water rose, the tavern did not close its doors. Sandbags piled against the flood now serve locals as a bench, and outside, the stable master and his riding rams stand unbothered in the flooded ground. Inside, the tavern became a refuge for those left with nowhere else to go, sheltering families who lost their homes to the water.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Direforge Hill",
			short = "Direforge Hill once served the Dark Iron dwarves as a campsite under the warlock Balgaras the Foul. What remains of it now burns.",
			full = "Direforge Hill once served the Dark Iron dwarves as a campsite under the warlock Balgaras the Foul. What remains of it now burns. Fire elementals and smouldering oozes roam the hill, setting the old works and the countryside alight, much to the distress of Rethiel the Greenwarden.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Dragonmaw Gates",
			short = "Four grandiose gates block the winding path from the Wetlands up to Grim Batol, guarding the way to the old dwarven citadel.",
			full = "Four grandiose gates block the winding path from the Wetlands up to Grim Batol, guarding the way to the old dwarven citadel.\n\nThe red dragonflight once held them, watched over by the drake Axtroz, and those who struck at the gates paid for every step gained.\n\nAt Wyrms' Bend, one gate became the key to Grim Batol, held shut by cultists of the Twilight's Hammer, until the Horde's Gob Squad and the Alliance's Highbank forces forced it open together to reach the citadel beyond.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "The tunnel through the mountains between Loch Modan and the Wetlands is old enough that the Wildhammer dwarves used it to flee Ironforge, driven out in the War of the Three Hammers, before the orcs ever came to Khaz Modan.",
			full = "The tunnel through the mountains between Loch Modan and the Wetlands is old enough that the Wildhammer dwarves used it to flee Ironforge, driven out in the War of the Three Hammers, before the orcs ever came to Khaz Modan.\n\nWhen the Horde was broken at Dun Modr, its survivors fled south and dug in at Dun Algaz, a secondary outpost in the pass. Anduin Lothar meant to finish them there and drive the orcs back for good, and ordered the outpost torn down. The assault failed. The orcs held the pass, and Dun Algaz became the last ground the Horde kept in the region.\n\nMore recently the Dragonmaw clan overran the post outright, forcing the dwarven mountaineers who once watched the hills back to the upper tunnel. With the pass contested, the road between the dwarven homelands and Menethil Harbor grew dangerous, and the orcs threatened to cut Loch Modan off from the harbor entirely.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Dun Modr stands south of Thandol Span, a dwarven city that has changed hands more times than its walls can easily show.",
			full = "Dun Modr stands south of Thandol Span, a dwarven city that has changed hands more times than its walls can easily show.\n\nDuring the Second War, the Orcish Horde seized it and built an outpost among its ruins, raiding the farmlands of the Wetlands and beating back every Alliance attempt to dislodge them. Stromgarde warriors, striking from the island citadel of Tol Barad, finally broke the outpost and drove the orcs south to Dun Algaz. The Horde struck back and retook Dun Modr, even pressing their attack against Tol Barad itself, but the war turned against them elsewhere. When their forces broke at Capital City, Anduin Lothar drove them back through Thandol Span into Khaz Modan, and Dun Modr passed into Alliance hands.\n\nYears later, with Ironforge's soldiers spent fighting the Alliance's wars abroad, the Dark Iron dwarves seized their chance and took the city for their own. It took Thargas Anvilmar, leading Ironforge's warriors, to drive them out and restore Dun Modr to the kingdom.\n\nThe city now holds a blacksmith's shop and an inn-brewery, a modest place for one so often fought over.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "Green Belt",
			short = "The Green Belt is a marsh thick with crocolisks, bog beasts, and oozes, its ground never solid.",
			full = "The Green Belt is a marsh thick with crocolisks, bog beasts, and oozes, its ground never solid. Rethiel the Greenwarden watches over it, and lately his patience has worn thin, as flooding and stranger disturbances creep through the wetland he tends.\n\nTo the southeast lies a wrecked Dragonmaw clan caravan, half-sunk in the bog and crawling with red whelps, a wound left from the clan's ruin at Grim Batol. The Dragonmaw have not learned from it. Bands of their orcs still work the marsh, hunting black dragon whelps to steal and break to their will. The black dragon Pyrricion has not forgiven them for it, and neither have his slavers, who are often seen there with blades drawn against the Dragonmaw over the stolen brood.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Grim Batol is a mountain fortress located in the western Twilight Highlands (formerly in the eastern Wetlands). It has great walls and spires that reach toward a steel-gray sky, but the stronghold's bulk is underground.",
			full = "Grim Batol is a mountain fortress located in the western Twilight Highlands (formerly in the eastern Wetlands). It has great walls and spires that reach toward a steel-gray sky, but the stronghold's bulk is underground. It was founded by the Wildhammer dwarves until it was cursed during the War of the Three Hammers. It was later seized by orcs to serve as a prison for the Dragon Aspect Alexstrasza until she was freed during the Battle of Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Ironbeard's Tomb",
			short = "West of the road to Dun Modr, in the north-central Wetlands, stands a crypt raised for a dwarf called Ironbeard, whose statue still keeps watch over the graveyard beside it.",
			full = "West of the road to Dun Modr, in the north-central Wetlands, stands a crypt raised for a dwarf called Ironbeard, whose statue still keeps watch over the graveyard beside it. The tomb has been overrun by oozes, black and crimson and worse, which have fouled the crypt itself. No one brings their dead here anymore. The dead already resting inside are left to the oozes, and the statue stands watch over a graveyard that has stopped growing.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "Lost Fleet",
			short = "Beneath the waters of Baradin Bay, off the northern shore of Bluegill Marsh, lie the broken hulls of the Wave Mistress and the Intrepid, all that remains of Kul Tiras's Third Fleet.",
			full = "Beneath the waters of Baradin Bay, off the northern shore of Bluegill Marsh, lie the broken hulls of the Wave Mistress and the Intrepid, all that remains of Kul Tiras's Third Fleet.\n\nThey went down during the Second War, at the Battle of Crestfall, when red dragons enslaved by the Dragonmaw clan fell from the sky upon the Alliance ships and wrapped them in fire. Derek Proudmoore, elder son of Lord Admiral Daelin Proudmoore, commanded the fleet that day. He climbed to the crow's nest to shout warning to his father below, and a dragon killed him there before his own ship was dragged under.\n\nYears later the drowned crews rose again, cursed with a twisted form of undeath. The cause lay hidden in the Intrepid's hold: a blackened artifact called the Cursed Eye of Paleth, locked away by the ship's greedy captain, Halyndor, who kept it from his men even as it doomed them. Only First Mate Snellig, whose ghost still walks the nearby shore, kept his mind whole.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Menethil Bay",
			short = "Menethil Bay lies cradled between the harbor and the northern cliffs of Dun Morogh, part of Baradin Bay off the western Wetlands.",
			full = "Menethil Bay lies cradled between the harbor and the northern cliffs of Dun Morogh, part of Baradin Bay off the western Wetlands. When the harbor nearby was flooded, the sea filled the ground around it, and the bay has since grown thick with sharks and crabs.\n\nNear its entrance rests the wreckage of the Flying Osprey.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Menethil Harbor",
			short = "Menethil Harbor is a dwarven port town located on a small island on the western shore of the Wetlands.",
			full = "Menethil Harbor is a dwarven port town located on a small island on the western shore of the Wetlands. A rough place that plays host to sailors, travelers, smugglers, and pirates, it's also a good place to purchase goods and even have a pint and relax. An Alliance stronghold, the most prominent shape here is the thick, stone wall which protects most of the town from inland incursions. Rising above all else, the four towers of Menethil Keep watch over the settlement like stern guardians. Except for the bridge, the only other ways of entering the town are by sea or by a secret underground path leading from the town to the mainland.\n\nIt has also The Lady Mehley boat that sails to the Ruins of Theramore in Dustwallow Marsh, on the continent of Kalimdor, and the Northspear icebreaker that goes to Valgarde in the Howling Fjord, on the continent of Northrend.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Menethil Keep",
			short = "Four towers rise above Menethil Harbor, watching the settlement like stern guardians, and the keep beneath them has not always kept its people safe.",
			full = "Four towers rise above Menethil Harbor, watching the settlement like stern guardians, and the keep beneath them has not always kept its people safe.\n\nFloods struck the harbor and damaged the keep itself, tearing down its stables so that horses had to be kept temporarily on the keep's western side. In that same time of ruin, Dark Iron dwarves under Horghast Flarecrazed struck at Menethil. Captain Stoutfist and his men rushed out to defend the townsfolk, but the assault drove them back within the keep's walls. Stoutfist took a wound in the fighting, and rather than see the keep itself brought down around him, he called on others to hunt down Horghast and end the attack instead.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Mosshide Fen",
			short = "Mosshide Fen lies sodden in the eastern Wetlands, its camps claimed by the Mosshide gnolls.",
			full = "Mosshide Fen lies sodden in the eastern Wetlands, its camps claimed by the Mosshide gnolls. Over this tribe rules Gnawbone, a vicious leader whose word sends his gnolls hunting through the marsh grass for anyone who strays too close to their ground, to be caught and eaten.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Raptor Ridge",
			short = "Raptor Ridge rises northwest of the Dragonmaw Gates, its slopes thick with raptors lairing in great numbers. Deep within its cavern broods the Razormaw Matriarch, watchful over her young.",
			full = "Raptor Ridge rises northwest of the Dragonmaw Gates, its slopes thick with raptors lairing in great numbers. Deep within its cavern broods the Razormaw Matriarch, watchful over her young.\n\nThe mage Rhonin once came here with the draenei Iridi and found the ridge emptier than it should have been. He told her the raptors had drifted toward Menethil Harbor, unsettled by something stirring in Grim Batol. Once that trouble was dealt with, Rhonin judged the danger past, certain the raptors would settle back onto the ridge and trouble the harbor no more.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Saltspray Glen",
			short = "Saltspray Glen lies where the Wetlands meet Baradin Bay, bordered by Bluegill Marsh and Ironbeard's Tomb.",
			full = "Saltspray Glen lies where the Wetlands meet Baradin Bay, bordered by Bluegill Marsh and Ironbeard's Tomb. When the wind rises off the water, the bay throws its spray far inland here, salting the ground, which is how the glen earned its name. Like Black Channel Marsh, Whelgar's Excavation Site, and Raptor Ridge nearby, it crawls with nesting raptors.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Sundown Marsh",
			short = "Sundown Marsh is the deepest, wettest reach of the Wetlands, its waters full of crocolisks, gnolls, raptors, bog beasts, and oozes.",
			full = "Sundown Marsh is the deepest, wettest reach of the Wetlands, its waters full of crocolisks, gnolls, raptors, bog beasts, and oozes.\n\nYet in the middle of it stands Swiftgear Station, a small stone house with a windmill turning over the swamp. Here live an odd couple, Fradd Swiftgear and Wenna Silkbeard, trading the strange things the marsh gives up and recipes found nowhere else, a single dry light in a swamp that welcomes almost no one.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "Two vast arches of dwarven stone span the valley here, joining the Wetlands to the Arathi Highlands.",
			full = "Two vast arches of dwarven stone span the valley here, joining the Wetlands to the Arathi Highlands. The Anvilmar line guarded them for three generations, and they were raised after the War of the Three Hammers so that Ironforge might keep faith and trade with its Wildhammer kin at Aerie Peak. Both kingdoms grew fat on the traffic that crossed them.\n\nThe Span was nearly lost when Kam Deepfury and Balgaras the Foul turned the Dark Iron clan against it. One of the two great arches was destroyed, and dwarves died holding what remained. The bridge only stood because Hjalmar Anvilmar did not: captured by the Dark Irons, he gave his life in a rescue led by Thargas Anvilmar, Varian Wrynn, Broll Bearmantle, and Valeera Sanguinar, and his death bought the time needed to save the last span from ruin. King Magni's reinforcements arrived, Balgaras fell, and the Dark Irons were driven from the bridge they had so nearly toppled.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Thelgen Rock",
			short = "Thelgen Rock, in the southern Wetlands, takes its name from caverns that burrow deep into the mountain, thick with the webs of poisonous spiders.",
			full = "Thelgen Rock, in the southern Wetlands, takes its name from caverns that burrow deep into the mountain, thick with the webs of poisonous spiders. Somewhere within lie veins of incendicite ore, guarded by the spiders' numbers, and their silk, though prized, is not easily won. Cartographers still wander the rock's approaches, unable to close the last gaps of their maps where the tunnels vanish into the dark.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Whelgar's Excavation Site",
			short = "Whelgar's Excavation Site lies east of Menethil Harbor, a dwarven dig overrun by mottled raptors.",
			full = "Whelgar's Excavation Site lies east of Menethil Harbor, a dwarven dig overrun by mottled raptors. The diggers were pinned on a ridge above their own pits and did not hold; they abandoned the site and fell back to Whelgar's Retreat, a camp raised off the main road.\n\nThe dig itself has not gone quiet. Paleolithic elementals and living fossils move among the exposed earth, and Sarltooth, once hunted here and killed, is seen again from time to time.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 17 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil rises at the heart of Shadowglen, sheltering the village grown around its roots.",
			full = "Aldrassil rises at the heart of Shadowglen, sheltering the village grown around its roots. At its very top, above the sight of those below, Tenaron Stormgrip keeps his home, watching over the settlement from the tree's crown.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Ban'ethil Barrow Den",
			short = "Ban'ethil Barrow Den was raised by the night elves as a sacred barrow, a resting place where Druids of the Talon could lie in slumber undisturbed.",
			full = "Ban'ethil Barrow Den was raised by the night elves as a sacred barrow, a resting place where Druids of the Talon could lie in slumber undisturbed. That peace is broken now: the corrupted Gnarlpine furbolg tribe has overrun both its Lower and Upper Den, and a lone night elf ventures in at real risk.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Ban'ethil Hollow",
			short = "South of the road from Dolanaar to Darnassus, Ban'ethil Hollow cuts into the land, held by hostile furbolgs who ambush travelers passing above.",
			full = "South of the road from Dolanaar to Darnassus, Ban'ethil Hollow cuts into the land, held by hostile furbolgs who ambush travelers passing above. Caution serves any who cross there. Deeper in, at the hollow's back, lies the Ban'ethil Barrow Den, from which the furbolgs seem to come.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "Cleft",
			short = "The Cleft, northwest of Dolanaar, is a corrupted Gnarlpine furbolg den. Under Ursal the Mauler, the furbolgs ambush travelers on the road to Darnassus and hold a group of slumbering druids captive within.",
			full = "The Cleft, northwest of Dolanaar, is a corrupted Gnarlpine furbolg den. Under Ursal the Mauler, the furbolgs ambush travelers on the road to Darnassus and hold a group of slumbering druids captive within. Moon Priestess Amara and her bodyguards guard the road near the entrance.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["darnassus"] = {
			name = "Darnassus",
			short = "The night elves built Darnassus after the Third War, when their long immortality had failed them. Many could not bear the sudden weight of aging and frailty.",
			full = "The night elves built Darnassus after the Third War, when their long immortality had failed them. Many could not bear the sudden weight of aging and frailty. A number of grieving druids resolved to plant a new World Tree to restore their bond with the eternal world. With Malfurion Stormrage gone missing, Fandral Staghelm took up the mantle of Archdruid and led the effort. The tree they raised, Teldrassil, rose off the coast until its crown broke above the clouds, and among its boughs the night elves founded their city as a testament to their people's survival.\n\nDarnassus stands open to the sky, unlike the close, walled cities of the humans and dwarves. It is built around a broad lake, its shores joined by graceful bridges, its pathways carpeted in fallen leaves. The Temple of the Moon rises above the trees as the seat of High Priestess Tyrande Whisperwind and her Sisters of Elune, beside the colonnaded Hall of Justice where the Sentinels keep their watch. The city remains what it was built to be: a tranquil refuge, and a monument to a people learning to live with mortality.",
			source = "https://warcraft.wiki.gg/wiki/Darnassus",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Dolanaar stands among the great roots of Teldrassil, southwest of Shadowglen, at the heart of the island's affairs. Koroleth and Kelestra made their home here, among the elders and teachers who kept the village turning.",
			full = "Dolanaar stands among the great roots of Teldrassil, southwest of Shadowglen, at the heart of the island's affairs. Koroleth and Kelestra made their home here, among the elders and teachers who kept the village turning.\n\nIt was here that fire came, when Teldrassil burned, and the flames that swept the World Tree spread down into Dolanaar itself.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Fel Rock",
			short = "North of Dolanaar, the cave called Fel Rock was once beautiful. Now it lies corrupted, infested with grells, and home to the satyr Lord Melenas, whose presence has fouled what remains of its beauty.",
			full = "North of Dolanaar, the cave called Fel Rock was once beautiful. Now it lies corrupted, infested with grells, and home to the satyr Lord Melenas, whose presence has fouled what remains of its beauty. The night elf druid Tallonkai Swiftroot has sworn to see Melenas destroyed for it.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Gnarlpine Hold",
			short = "Gnarlpine Hold, tucked in Teldrassil's far southwest corner, was once home to the Gnarlpine furbolgs.",
			full = "Gnarlpine Hold, tucked in Teldrassil's far southwest corner, was once home to the Gnarlpine furbolgs. Corruption has since taken the place, and demons now pour steadily out of it, streaming north to where Tarindrella and the ancients of Teldrassil meet them in battle.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lake Al'Ameth",
			short = "South of Dolanaar spreads a wide, quiet lake, marked only by a small jetty. Little else stands here. Lately the timberlings along its shores have woken to rage, and the water's edge is no longer safe to walk.",
			full = "South of Dolanaar spreads a wide, quiet lake, marked only by a small jetty. Little else stands here. Lately the timberlings along its shores have woken to rage, and the water's edge is no longer safe to walk.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "Oracle Glade",
			short = "The Oracle Glade lies in the northwestern reaches of Teldrassil, home to the Oracle Tree and the first and most powerful of Teldrassil's moonwells.",
			full = "The Oracle Glade lies in the northwestern reaches of Teldrassil, home to the Oracle Tree and the first and most powerful of Teldrassil's moonwells.\n\nThe tree is unmistakable, its wide trunk rising into boughs shaped like a great eagle perched atop a mighty bear. Many who look upon it whisper that no ordinary growth made it so, that nature magic alone could have shaped such a thing. Since Teldrassil rose, the Oracle Tree has watched over its growth alongside the druids, and it speaks to them in its own way: shedding pieces of bark inscribed with what it has seen, sent to Archdruid Fandral Staghelm in Darnassus.\n\nMalfurion Stormrage himself comes to the glade to meditate, drawn to the tree's long watch.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Pools of Arlithrien",
			short = "The Pools of Arlithrien lie south of Darnassus, a scatter of small pools once peaceful. A lone moonwell still rests among them, abandoned by the night elves who once tended it, driven off by Gnarlpine furbolgs.",
			full = "The Pools of Arlithrien lie south of Darnassus, a scatter of small pools once peaceful. A lone moonwell still rests among them, abandoned by the night elves who once tended it, driven off by Gnarlpine furbolgs. The pools now belong to hostile wildlife, the moonwell untended.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Rut'theran Village",
			short = "Rut'theran Village sits at the very roots of Teldrassil, where the great World Tree meets the sea, the lowest and humblest place in a city that otherwise reaches for the sky.",
			full = "Rut'theran Village sits at the very roots of Teldrassil, where the great World Tree meets the sea, the lowest and humblest place in a city that otherwise reaches for the sky. Even so, it is kept fresh and well-tended. Kaldorei here raise hippogryphs from the egg, tending the young until they are fit to carry riders off to Darkshore or, for those who walk the druidic paths, to Moonglade. The village works quietly in service of the capital above it, and still finds room for song and fire, lighting the Midsummer braziers each year.\n\nIt was to these docks that Malfurion Stormrage and Delaryn Summermoon came during the War of the Thorns, arriving to meet the gathered night elven forces before the storm broke. The storm came anyway. Siege weapons found the village first, and its crowded docks burned before anyone could clear them. Those who did not die in the fire drowned in the dark water beyond it. Within the hour, Rut'theran and all of Teldrassil above it were gone.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Shadowglen",
			short = "Aldrassil rises at the center of Shadowglen, and beneath its boughs the glade never quite leaves dusk.",
			full = "Aldrassil rises at the center of Shadowglen, and beneath its boughs the glade never quite leaves dusk. Mountains close the place in on every side but one, where a single gap to the south lets the path run down toward Dolanaar. In the glen's far northwest, Shadowthread Cave opens into the dark.\n\nThis is the ground where the night elves of Teldrassil are shaped before they are sent into the world, taught at the foot of the great tree by those who keep watch over it. The glade feels sheltered rather than wild, a place meant to hold something young a little longer before the mountains let it go.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Shadowthread Cave",
			short = "Shadowglen's northwest corner opens into Shadowthread Cave, long home to Teldrassil's great spiders. Once merely a part of the wood's order, they have grown hostile of late, and the cave with them.",
			full = "Shadowglen's northwest corner opens into Shadowthread Cave, long home to Teldrassil's great spiders. Once merely a part of the wood's order, they have grown hostile of late, and the cave with them. Deepest within lurks Githyiss the Vile, largest of the brood, bane of more than one young Kaldorei who wandered too far in.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Starbreeze Village",
			short = "Starbreeze Village stood once as a home of the night elves, its few small houses set among the trees southeast of Shadowglen.",
			full = "Starbreeze Village stood once as a home of the night elves, its few small houses set among the trees southeast of Shadowglen. That life ended when the Gnarlpine furbolgs, twisted by corruption, overran the village and made it theirs. Uruson now paces its paths in place of the elves who once lived there, and Ferocitas the Dream Eater lurks at its edges, watching over what the furbolgs have claimed.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Wellspring Lake",
			short = "Wellspring Lake is fed by a spring rising from deep within Teldrassil, its overflow running off as the Wellspring River. Night elven fishermen once favored these waters.",
			full = "Wellspring Lake is fed by a spring rising from deep within Teldrassil, its overflow running off as the Wellspring River. Night elven fishermen once favored these waters. That quiet is gone now: the timberlings gathered at the lake's edge have turned corrupted, and nightsabers and spiders infest the surrounding ground.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Wellspring River",
			short = "The Wellspring River rises from a hidden spring deep within Teldrassil, flowing from Wellspring Lake before plunging over the tree's edge in a waterfall to the sea far below.",
			full = "The Wellspring River rises from a hidden spring deep within Teldrassil, flowing from Wellspring Lake before plunging over the tree's edge in a waterfall to the sea far below.\n\nCrazed timberlings now patrol its banks, attacking any who wander near.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Darkshore: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "The ruins of Ameth'Aran can be found to the southeast of the Ruins of Auberdine, and east from the Blazing Strand, in Darkshore.",
			full = "The ruins of Ameth'Aran can be found to the southeast of the Ruins of Auberdine, and east from the Blazing Strand, in Darkshore. Once it was a place where the servants of Queen Azshara freely practiced their powerful magics. Now it is inhabited by the restless spirits of the Highborne that once dwelt within its walls.\n\nIn Ameth'Aran's ruins lie two large ancient tablets, scrawled with the stories of the town and its fall.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine stood where the land itself remembers an older shape. Before the Sundering tore the world apart, this coast lay far inland, in the shadow of the great cities of the Kaldorei Empire.",
			full = "Auberdine stood where the land itself remembers an older shape. Before the Sundering tore the world apart, this coast lay far inland, in the shadow of the great cities of the Kaldorei Empire. When the seas rushed in and carved Darkshore into being, those cities were lost, and every attempt to settle the new coastline afterward came to nothing. Only Auberdine endured, the one stronghold that held against the emptiness of the shore.\n\nIt grew strange for a night elven town, and Darnassus never let it forget it. Lit brighter than kin thought proper, its signposts written in both Darnassian and Common so that dwarves, gnomes, humans and high elves passing through its port could read them, Auberdine earned a reputation as a home for outcasts and misfits. Those who knew it otherwise, like Shandris Feathermoon, remembered it as a place that had once rung with laughter.\n\nThen the whole town fell still. Every soul in Auberdine sank into the unwaking grip of the Emerald Nightmare, and only fire and a shaking of the earth followed, breaking the port from its footing and wrecking most of what stood. Those who survived did not stay.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Bashal'Aran is a night elven ruin found to the southwest of Lor'danel in northern Darkshore, formerly consisting of ancient Highborne ruins.",
			full = "Bashal'Aran is a night elven ruin found to the southwest of Lor'danel in northern Darkshore, formerly consisting of ancient Highborne ruins.\n\nDuring the Battle for Darkshore, the ruins could be captured and turned into a night elven or a Forsaken base of operations, from where to launch an attack against the Alliance or Horde forces controlling the region. The warfront was won by the Alliance, but Bashal'Aran was later left in ruins once again.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Blackwood Den",
			short = "Deep in southern Darkshore, where the trees give way toward Ashenvale, a scatter of corrupted furbolg camps and a small cave once made up the Blackwood Den, also called Blackwood Hold.",
			full = "Deep in southern Darkshore, where the trees give way toward Ashenvale, a scatter of corrupted furbolg camps and a small cave once made up the Blackwood Den, also called Blackwood Hold.\n\nWithin the cave a lone night elf named Volcor was held, awaiting rescue that had to be arranged from Auberdine.\n\nBy the time war came to Darkshore, the furbolgs had renamed their den Kor'gar.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Cliffspring Falls",
			short = "Cliffspring Falls once ran clear, the source of the Cliffspring River and the drinking water of Darkshore. Now the cave at its source is corrupted.",
			full = "Cliffspring Falls once ran clear, the source of the Cliffspring River and the drinking water of Darkshore. Now the cave at its source is corrupted.\n\nNo one agrees why. Some blame a taint seeping down from Felwood; others point to the Twilight's Hammer, whose cultists have been found deep within the cave. Naga crawl through the tunnels behind the falls as well.\n\nWhat was once the region's lifeblood now rises through ground held by cultists and naga, carrying its corruption out into Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Cliffspring River",
			short = "The Cliffspring River spills from Cliffspring Falls in northern Darkshore and runs on to the sea. Its waters no longer run clean.",
			full = "The Cliffspring River spills from Cliffspring Falls in northern Darkshore and runs on to the sea. Its waters no longer run clean. The Stormscale naga have tainted the river, and the creatures of Darkshore that come to drink from it sicken for the trouble.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Grove of the Ancients",
			short = "The Grove of the Ancients is a sacred ruin, all that remains standing of an old night elven temple, built around the surging waters of the Wildbend River in the southeastern reaches of Darkshore, close against the mountains.",
			full = "The Grove of the Ancients is a sacred ruin, all that remains standing of an old night elven temple, built around the surging waters of the Wildbend River in the southeastern reaches of Darkshore, close against the mountains. Its stones are badly damaged, but the place has not been abandoned. Onu, an Ancient of Lore, still keeps residence here, and the Circle of Ancients gathers within its broken walls to counsel on the fate of the forests.\n\nProtecting the grove drew on an enormous store of energy, and in the end it cost the guardians their wakefulness. Most of them have fallen into a deep slumber, leaving the ruin quieter than it once was, its defenders sleeping among the roots and stones rather than standing watch.\n\nOnu does not stand alone. A pair of merchants keep their trade here amid the ruin, and a druid sleeps nearby, undisturbed by the grove's long history of guardianship.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Long Wash",
			short = "The Long Wash takes its name as a small joke, for it is the shortest stretch of coast in Darkshore, running south from the Ruins of Auberdine to a point due west of Ameth'Aran.",
			full = "The Long Wash takes its name as a small joke, for it is the shortest stretch of coast in Darkshore, running south from the Ruins of Auberdine to a point due west of Ameth'Aran. The sky above is perpetually overcast, and the sand is littered with driftwood, wreckage, and the carcasses of dead sea creatures.\n\nDuring the Horde's invasion of Darkshore, the Long Wash became a battlefield, as soldiers came down onto the sand hunting for food and the night elves met them there.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "Master's Glaive",
			short = "In the southwest reaches of Darkshore lies a monstrous skull, and driven into it a blade too vast for any mortal hand: an adamantine glaive, buried to the hilt in bone.",
			full = "In the southwest reaches of Darkshore lies a monstrous skull, and driven into it a blade too vast for any mortal hand: an adamantine glaive, buried to the hilt in bone.\n\nThe tablets unearthed at Remtravel's Excavation tell what happened here. The skull belongs to Soggoth the Slitherer, a herald of the Old Gods, and it was here that the titans sent twenty stone giants against him. Nineteen died. Only Kronn, the largest, remained, and Soggoth's tendrils closed around him. Kronn did not fight free. He let himself be dragged in, closer and closer to the thing's skull, until he was near enough to drive his sword through bone. He died doing it, but Soggoth fell, and the giant's sword stayed where he left it. It has been called the Master's Glaive ever since.\n\nThe ground here was sacred to the night elves once. It is theirs no longer. The Twilight's Hammer holds it now, digging through Soggoth's remains, working toward one end: to put life back into what Kronn's blade ended.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Mist's Edge",
			short = "The coast called Mist's Edge runs the length of Darkshore, from the ruins near Auberdine in the south, past Lor'danel, to the reach beyond the Shatterspear War Camp in the north.",
			full = "The coast called Mist's Edge runs the length of Darkshore, from the ruins near Auberdine in the south, past Lor'danel, to the reach beyond the Shatterspear War Camp in the north. It is gray and gloomy, its beaches littered with the huge carcasses of sea animals and the wrecks of sunken ships. Crabs scuttle along the entire shore, and murlocs lurk in the shallows, an ever-present threat to anyone who lingers there.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Remtravel's Excavation",
			short = "Prospector Remtravel gave his name to this dig site in Darkshore, and left it in disorder.",
			full = "Prospector Remtravel gave his name to this dig site in Darkshore, and left it in disorder. Somewhere among the trenches lies a fossil he unearthed himself, a thing of unmistakable mystic properties, but the prospector's memory failed him and he could no longer say where he had put it down.\n\nThe digging woke worse things than forgetfulness. Gravelflint troggs came up out of the broken ground, and with them huge golems, stirred loose from whatever sleep the earth had kept them in. What was meant to be a place of careful study became a place no one enters without training.\n\nThe site was abandoned once, when the Horde marched in.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Ruins of Mathystra",
			short = "The Ruins of Mathystra are located in northern Darkshore, just past the Tower of Althalaxx.",
			full = "The Ruins of Mathystra are located in northern Darkshore, just past the Tower of Althalaxx. Mathystra used to be a night elven city before the Great Sundering, but it was utterly decimated by the destruction of the Well of Eternity, and has long since been abandoned by the night elves in favor of the smaller coastal villages further south.\n\nThe ruins contain scattered relics of the old Highborne, and young night elves sometimes attempt to search through Mathystra in search of these relics. Ghost Sabers can also be found here.\n\nThe ancient ruins were inhabited for a time by the Stormscale Naga, who aggressively guarded against any intrusions from outside sources. They established the Shatterspear War Camp next to the ruins. Several night elves are now scouting the area to learn about the trolls' intentions and movements.\n\nDuring the War of the Thorns, the area became a battlefield between the Horde and the night elves.\n\nWith the Battle for Darkshore, the Horde's actions drove the night elf spirits to madness. It is now solely occupied by the spirits of the Highborne.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Tower of Althalaxx",
			short = "In the days of the Great Sundering, when Queen Azshara raised the twin towns of Ameth'Aran and Bashal'Aran, she set an elf named Athrikus Narassin to govern them.",
			full = "In the days of the Great Sundering, when Queen Azshara raised the twin towns of Ameth'Aran and Bashal'Aran, she set an elf named Athrikus Narassin to govern them. He was loyal at first, but the work bored him, and he withdrew more and more to a tower some distance away, until Althalaxx became his true home and his charge an afterthought.\n\nTen thousand years later, what had only been suspected of the tower proved true. A cult calling itself the Dark Strand had gathered within its walls, warlocks and a satyr among them, and Athrikus stood at their head. Behind them worked the Shadow Council, who had turned the idle elf's tower into an instrument of their own designs. Athrikus was struck down for it, and the tower itself was later burned to ruin.\n\nEven fire did not end it. War came again to Darkshore, and the ancestral spirits still bound to the ruins were driven to madness, Athrikus himself rising once more as a restless spectre. Soul gems of his making still lie among the stones, each one a small prison holding a Highborne spirit trapped since his death.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Twilight Vale",
			short = "The forests south of Ameth'Aran, running toward the border of Ashenvale, carry an uneasy name.",
			full = "The forests south of Ameth'Aran, running toward the border of Ashenvale, carry an uneasy name. The trees grow thick and shadowed, and the wildlife has turned against reason: corrupted furbolgs, feral nightsabers, rabid bears. Travelers are warned to keep to the roads, for the deep wood does not forgive wandering.\n\nWhat the vale becomes depends on who holds Darkshore. Under the Alliance, the Bilgewater Cartel logs and poaches here. Under the Horde, the Druids of the Branch tend the same ground to raise treants from root and bark.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Wildbend River",
			short = "The Wildbend River carries the corruption of Felwood down into Darkshore, its waters a continuation of the Bloodvenom River as it spills from the mountains above.",
			full = "The Wildbend River carries the corruption of Felwood down into Darkshore, its waters a continuation of the Bloodvenom River as it spills from the mountains above. It runs tainted through the southern reaches of the land, past the Grove of the Ancients, a wound in the water that never healed clean.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Ashenvale: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar sits on an island in a lake at the heart of Ashenvale, the largest settlement in the region, reached only by two bridges that carry the road through the forest.",
			full = "Astranaar sits on an island in a lake at the heart of Ashenvale, the largest settlement in the region, reached only by two bridges that carry the road through the forest. In its lakeside cemetery stands the grave of Valstann Staghelm, laid to rest here by his family after the War of the Shifting Sands.\n\nLater, when the Horde struck at Ashenvale in a sudden campaign, the blood elf Lorash Sunbeam led rogues against the town itself. Sentinel Captain Alennah Starsong fell defending it, along with guards and townsfolk, before the attackers were finally routed and slain. Captain Delaryn Summermoon and the Darnassian City Guard led the counterattack, and afterward the Guard honored the dead and released their wisps over the town.\n\nStill later, after the night elves lost the field at the Falfarren River, Malfurion Stormrage brought his forces back to Astranaar and turned it into a trap, propping up elven corpses through the streets so that Highlord Saurfang's advancing army found what looked like a town already slaughtered. When Saurfang occupied it, Malfurion's forces lured him into an inn and brought the building down on him.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Bathran's Haunt",
			short = "Bathran's Haunt was once a kaldorei place, its pillars raised and its marble cut in an age long past the elves who built it.",
			full = "Bathran's Haunt was once a kaldorei place, its pillars raised and its marble cut in an age long past the elves who built it. They are gone now, and the ruin stood empty for that reason, forgotten among the trees of northwestern Ashenvale.\n\nIt stands empty no longer. Forsaken have taken the broken columns for their own, herbalists and the thugs who guard them, and wherever they walk the ground follows them into death: the grass browns, the flowers wither and drop. Among the fallen stone they have raised a rough laboratory, working over the local herbs for purposes they keep to themselves.\n\nChief among those herbs is Bathran's Hair, a remedial plant found nowhere else, and it is this that draws most who come here, cutting it from the tainted soil under the watch of the dead.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Blackfathom Deeps",
			short = "Blackfathom Deeps (or just Blackfathom) is a former, partially underwater temple to the moon goddess Elune that was once known as Lathar'Lazal.",
			full = "Blackfathom Deeps (or just Blackfathom) is a former, partially underwater temple to the moon goddess Elune that was once known as Lathar'Lazal. It was thought to have been destroyed during the Sundering, and lost beneath the ocean. Millennia later, members of the Twilight's Hammer cult were drawn by whispers and foul dreams to what is now a series of watery caverns located beneath Ashenvale, near the ancient night elven city of Zoram. After sacrificing untold numbers of innocents, the cult was rewarded with a new task: to protect one of the Old Gods' most cherished creatures, a pet that was in need of nurturing before it could unleash his dark powers on the world, the monstrous hydra Aku'mai the Devourer.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Bloodtooth Camp",
			short = "Bloodtooth Camp lies west of the Falfarren River, southwest of the southern moonwell, named for Ran Bloodtooth, the furbolg who leads it.",
			full = "Bloodtooth Camp lies west of the Falfarren River, southwest of the southern moonwell, named for Ran Bloodtooth, the furbolg who leads it. His tribe was once counted among the furbolgs of Ashenvale, but corruption has taken every one of them, and now they fall upon any outsider who comes near, Ran Bloodtooth guarded close by his own kind.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Bough Shadow",
			short = "A great tree stands here, grown from a branch of Nordrassil, planted by followers of Fandral Staghelm to hold back the saronite seeping up through the land.",
			full = "A great tree stands here, grown from a branch of Nordrassil, planted by followers of Fandral Staghelm to hold back the saronite seeping up through the land.\n\nBeneath its boughs lies one of the portals into the Emerald Dream, and the green dragonflight keeps watch over it. The drakes Phantim and Dreamstalker guard the portal alongside their kin, while dragonspawn patrol the surrounding wood in groups of three, an Oracle flanked by Boughguards and Tree Warders, circling endlessly beneath the shadow of the great tree.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Demon Fall Canyon",
			short = "Demon Fall Canyon carries the scar of the day the orcs broke free of the Legion's curse.",
			full = "Demon Fall Canyon carries the scar of the day the orcs broke free of the Legion's curse.\n\nHere Mannoroth the pit lord met Grommash Hellscream and Thrall in single combat. The demon struck Thrall down before he could act, but Grom was faster than Mannoroth could escape, and his axe opened the pit lord's chest. Mannoroth's death came as a burst of fire and light so violent it tore the life from Grom where he stood, even as it ended the demon forever.\n\nThe orcs named the canyon for that sacrifice, and raised a monument to Grom Hellscream on the spot where he fell. Many still journey here to honor the warrior who broke the Burning Legion's hold over his people.\n\nThe ground has never recovered. Lesser demons now infest the canyon, drawn to the place where their master died.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Demon Fall Ridge",
			short = "Above Demon Fall Canyon, the ridge crawls with lesser demons that haunt both its open slopes and an old barrow den set into its side, abandoned by whoever once dug it.",
			full = "Above Demon Fall Canyon, the ridge crawls with lesser demons that haunt both its open slopes and an old barrow den set into its side, abandoned by whoever once dug it.\n\nDeep within that den waits Diathorus the Seeker, a dreadlord who rules the demonic conclave gathered in Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Dor'Danil Barrow Den",
			short = "The Dor'Danil Barrow Den has long been a resting place for night elven druids, sleeping undisturbed through their long slumbers.",
			full = "The Dor'Danil Barrow Den has long been a resting place for night elven druids, sleeping undisturbed through their long slumbers. When the Horde pushed into Ashenvale, the barrow den fell behind enemy lines, though the orcs paid the sleeping elves little mind. The Forsaken who later joined the Horde were not so indifferent.\n\nThey came with a colder purpose, experimenting on the slumbering druids by severing them from their own spirits. The druids did not simply die. They were driven insane, torn loose from their bodies and left to rage.\n\nNow Forsaken assassins move quietly among the barrows while the enraged souls of the ruined druids haunt the mounds around them.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Falfarren River",
			short = "The Falfarren cuts Ashenvale roughly in two, running down out of the slopes of Mount Hyjal, through the falls above Xavian's lake, and on southwest until it disappears beneath the mountains of the northern Barrens.",
			full = "The Falfarren cuts Ashenvale roughly in two, running down out of the slopes of Mount Hyjal, through the falls above Xavian's lake, and on southwest until it disappears beneath the mountains of the northern Barrens. To the west of its waters lies the night elven land watched over from Astranaar; to the east, the ground the orcs hold from Splintertree Post. It is not a deep river, nor especially wide, though rain can bring it up fast, and below its surface near Felfire Hill bog beasts lurk, ready to drag down anything that wades too carelessly through the shallows.\n\nDuring the War of the Thorns, the night elves burned the bridges spanning the river, hoping to hold it as a line the Horde could not cross. It did not hold. The orcs answered by freezing a stretch of the water itself and walking their army over the ice, and the line the night elves meant to defend gave way beneath their boots.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Fallen Sky Lake",
			short = "Fallen Sky Lake lies quiet in Ashenvale, its waters closed around a small island.",
			full = "Fallen Sky Lake lies quiet in Ashenvale, its waters closed around a small island. On that island the shadethicket oracle keeps its place, older and stronger than the shadethicket kin scattered along the shore around the lake.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Felfire Hill",
			short = "Felfire Hill still bears the scars of the Third War, when infernals fell from the sky and struck the earth here, leaving the ground fit for nothing but demons ever since.",
			full = "Felfire Hill still bears the scars of the Third War, when infernals fell from the sky and struck the earth here, leaving the ground fit for nothing but demons ever since.\n\nThe Horde does not hold the hill itself, only the bridges leading to it, fortified and watched to keep what lingers there from reaching nearby settlements.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Fire Scar Shrine",
			short = "The Fire Scar Shrine, in southwestern Ashenvale, has long since fallen to the demonic influence of the Shadow Council, its stones soaked in a corruption that marks it now as a place of great evil.",
			full = "The Fire Scar Shrine, in southwestern Ashenvale, has long since fallen to the demonic influence of the Shadow Council, its stones soaked in a corruption that marks it now as a place of great evil.\n\nHere the orcish warlock Ilkrud Magthrull once made his home, serving Athrikus Narassin, who led the Cult of the Dark Strand. What he left behind still lingers: the shrine remains infested with demons.\n\nAmong them, rarely, walks Akkrilus, a doomguard whose presence is no common sight.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Forest Song",
			short = "Once Forest Song stood almost empty, its ancient stones kept only by the druid Kayneth Stillwind, who from this lonely ruin directed the fight against the Forsaken creeping through the region.",
			full = "Once Forest Song stood almost empty, its ancient stones kept only by the druid Kayneth Stillwind, who from this lonely ruin directed the fight against the Forsaken creeping through the region.\n\nEverything changed when the Exodar crashed and Architect Nemos and Vindicator Vedaar led draenei survivors into Ashenvale. They chose the old ruin to rebuild, and the night elves welcomed them, sending what aid they could so the artificers might raise a settlement worth calling home. Nemos would not let the ancient trees of Ashenvale be felled for the work, and so timber was instead taken from the enemy camps at Warsong Lumber Camp and Satyrnaar; wood twisted by fel magic could not be used until the ancient Gnarl purified it and returned it to the builders in its own time.\n\nThe demons of Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge were not left to gather strength. Vedaar drove the Burning Legion's remnants from those places, cutting short a demonic strike being prepared against Forest Song after the dreadlords who had planned it were slain.\n\nToday Forest Song stands as a night elf and draenei outpost, watching over the northeastern reaches of Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Greenpaw Village",
			short = "Greenpaw Village is home to the Foulweald tribe, ruled by Chief Murgut and guided by the shaman Oakpaw.",
			full = "Greenpaw Village is home to the Foulweald tribe, ruled by Chief Murgut and guided by the shaman Oakpaw. Its furbolg have turned corrupted, bearmen twisted from what their kind once were, drawing both Horde and Alliance against them.\n\nThe Horde struck hardest. Part of the village lies broken now, and the Foulweald furbolg who survived its fall were not driven off, but taken prisoner.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Howling Vale",
			short = "The Shrine of Mel'Thandris stands within the cave, its stone marked with an ancient inscription praising Elune, and beneath it, in Darnassian, the words: the truth is a guiding light.",
			full = "The Shrine of Mel'Thandris stands within the cave, its stone marked with an ancient inscription praising Elune, and beneath it, in Darnassian, the words: the truth is a guiding light.\n\nThe shrine was raised by the mother of Velinde Starsong, in memory of her aunt Mel'Thandris, who had once been entrusted with the Scythe of Elune, the weapon used to seal away the Druids of the Scythe. When Mel'Thandris fell in the final battle of the War of the Satyr, the scythe was laid to rest within the shrine built in her name. Long after, Velinde found a book in Darnassus telling of that war, and it led her here, to the scythe her aunt had carried.\n\nIn time the shrine fell to ruin, and a tribe of worgen called the Terrowulf overran it entirely. Their calls, echoing through the vale at night, gave the place the name it now bears.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Iris Lake",
			short = "Iris Lake, east of Astranaar, once lay clear like the other pools of Ashenvale. Felwood's corruption reached it as it reached so much of that forest, turning its water a sickly yellowish green.",
			full = "Iris Lake, east of Astranaar, once lay clear like the other pools of Ashenvale. Felwood's corruption reached it as it reached so much of that forest, turning its water a sickly yellowish green. Twisted bog beasts now roam its banks, attacking any who come seeking Elune's Tears in the poisoned shallows.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Kargathia Keep",
			short = "Kargathia Keep stands among the felled trees of the Warsong Lumber Camp in eastern Ashenvale, near the Southfury River, its walls ringed with spiked barricades.",
			full = "Kargathia Keep stands among the felled trees of the Warsong Lumber Camp in eastern Ashenvale, near the Southfury River, its walls ringed with spiked barricades. It serves as the seat of command for the officers of the Warsong Clan, chosen for its position: close enough to Orgrimmar that reinforcements could reach it swiftly if the Alliance moved against the lumber camp.\n\nThe keep takes its name from Kargath Bladefist, honored also at Kargath in the Badlands and Bladefist Bay in Durotar. Overseer Gorthak commands here.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Lake Falathim",
			short = "Lake Falathim once drew night elves to swim and fish, for the goddess's moonlight touched its waters always, day or night. It was a gentle place then.",
			full = "Lake Falathim once drew night elves to swim and fish, for the goddess's moonlight touched its waters always, day or night. It was a gentle place then.\n\nThat ended when murlocs overran the lake, and later they left again, but nothing returned to what it was. The lake sits dank and gloomy now, and tentacles from Below swarm its waters, with Harbinger Aphotic standing over them. Keeper Heartwise has come to fight back the corruption that has taken hold here.\n\nYet the moonlight has not left. It still falls unbroken on the lake, and that light is why spirits within the Veil can look through into the living world at Falathim, even as the water beneath it turned dark.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Maestra's Post",
			short = "Maestra's Post was once a small thing: a tower and a broad night elven hall, home to only a handful of souls, among them two humans, Feero Ironhand and Delgren the Purifier, the only ones of their kind anywhere in Ashenvale.",
			full = "Maestra's Post was once a small thing: a tower and a broad night elven hall, home to only a handful of souls, among them two humans, Feero Ironhand and Delgren the Purifier, the only ones of their kind anywhere in Ashenvale.\n\nThat quiet ended when the Horde came. Under Orux Thrice-Damned, warriors overran the post, and in the chaos Feero and Delgren were taken. The Alliance defenders left behind are stretched thin, fighting the Horde on one side and the corrupted furbolgs of the surrounding wood on the other. What was once a modest outpost is now a battleground, its tower and hall standing over ground still contested.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["morshan rampart"] = {
			name = "Mor'shan Rampart",
			short = "The Mor'shan Rampart stands where the Gold Road meets the northern edge of the Barrens, raised against the Alliance push out of Ashenvale.",
			full = "The Mor'shan Rampart stands where the Gold Road meets the northern edge of the Barrens, raised against the Alliance push out of Ashenvale. It serves now as a launching point for raids on the night elven town of Astranaar to the north.\n\nAshenvale skirmishers charge the rampart, bowmen loose arrows from behind them, and the Mor'shan defenders answer in kind, neither side driving the other off for good.\n\nDuring the War of the Thorns, two Horde rogues killed the elves holding the rampart outright. It has changed hands between the Alliance and the defenders ever since.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["mystral lake"] = {
			name = "Mystral Lake",
			short = "The water elementals of Mystral Lake once answered to the night elves, bound to them by old pacts. That bond broke when Sarilus Foulborne turned his corruption upon the lake.",
			full = "The water elementals of Mystral Lake once answered to the night elves, bound to them by old pacts. That bond broke when Sarilus Foulborne turned his corruption upon the lake. What had been loyal spirits became something twisted and hostile, no longer serving those who once called them. They remain that way still, restless beneath the water.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Night Run",
			short = "Night Run is little more than a scatter of broken pillars and fallen stone, the smallest of the three satyr strongholds that fester in Ashenvale, dwarfed by Satyrnaar and Xavian.",
			full = "Night Run is little more than a scatter of broken pillars and fallen stone, the smallest of the three satyr strongholds that fester in Ashenvale, dwarfed by Satyrnaar and Xavian. What shelter it offers, the Felmusk satyr have made do with, crouching among ruins too meager to be called a settlement at all. It is also the least reachable of the three: it sits upon a naze thrust out into the land, hemmed by cliffs no one can climb, so that reaching it means following the Falfarren River nearly to Xavian's waters before turning west, or else creeping along a narrow ledge north of Raynewood Retreat.\n\nIt was here, not long after the Sundering, that the peace shattered. The Sentinels were locked in battle against the satyr when Arvell and Ralaar, the latter in his Pack Form, fell upon them, killing Aldorei, Elanu, Morina, and Tyrnas, and wounding Shandris herself. That single act of slaughter marked the opening of the War of the Satyr.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Nightsong Woods",
			short = "The Falfarren River cuts Nightsong Woods in two. West of it, the Silverwing Sentinels hold the ground for the night elves.",
			full = "The Falfarren River cuts Nightsong Woods in two. West of it, the Silverwing Sentinels hold the ground for the night elves. East of it, the Warsong Clan has dug in, and the fighting between the two sides never really stops here -- this stretch of Ashenvale is where the war between Horde and Alliance is fought most openly, tree by tree and camp by camp.\n\nFarther east, past a second, nameless river, the land grows more crowded and more contested still. No one holds it whole. The draenei and night elves keep Forest Song there; the Horde works the Warsong Lumber Camp nearby; satyrs squat in Satyrnaar and Xavian; and the Burning Legion claims Felfire Hill and Demon Fall Canyon outright. Four powers, none at peace with any other, packed into one corner of the woods.\n\nSouth of all this, the Warsong orcs have stripped the trees for timber, feeding their settlements with wood torn from Ashenvale's own body -- the land itself scarred by who has been fighting whom.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Raynewood Retreat",
			short = "Raynewood Retreat grew up around the great tree for which it is named, in the north-central reaches of Ashenvale.",
			full = "Raynewood Retreat grew up around the great tree for which it is named, in the north-central reaches of Ashenvale. It became an Alliance outpost, its Cenarion Protectors, blink dragons, and Laughing Sisters keeping watch on the path north into the corrupted land of Felwood. Hidden at the very top of the great tree was Ordanus, a keeper of the grove and one of the eldest sons of Cenarius. The Shadow Council wanted him dead, and Braelyn Firehand made his death her own purpose, sending killers against him. Ordanus survived.\n\nWhen the Horde came in force during the Ashenvale war, they struck both the retreat and the newly raised Raynewood Tower beside it. It availed them little. Every dryad they cut down, Ordanus raised again the instant she struck the earth, and the nightsaber Shadumbra tore through their ranks besides. Thagg sent his own assassins after the keeper himself, but like the Shadow Council before him, he failed. Ordanus lived on, and the trees of Raynewood kept him still.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Ruins of Ordil'Aran",
			short = "Little remains of Ordil'Aran now but broken stone. The Cult of the Dark Strand once made their home among the ruins, ready to strike down any who wandered too close.",
			full = "Little remains of Ordil'Aran now but broken stone. The Cult of the Dark Strand once made their home among the ruins, ready to strike down any who wandered too close. Their vigilance did not save them: the Thistlefur furbolgs drove them out and claimed the ruins for their own, and the cultists' dead still lie scattered among the stones.\n\nAmid the wreckage stands the Heartswood tree, rooted in ground that once held a city and now holds only the furbolgs who took it.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Ruins of Stardust",
			short = "The Ruins of Stardust rise from a small island on a lake in southwestern Ashenvale, once counted among the holy places of the land.",
			full = "The Ruins of Stardust rise from a small island on a lake in southwestern Ashenvale, once counted among the holy places of the land. What sanctity remained there has curdled since the demonic rot of Felwood seeped into these waters, tinting the whole island a sickly yellow-green. Bog beasts, corrupted by the tainted lake, now shamble among the broken stones.\n\nYet the stardust shrubs scattered through the ruins remain untouched by the blight, prized for the powerful healing properties held within their leaves.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar stands broken among the trees of northeastern Ashenvale, its old stonework given over to the tents of the Bleakheart satyr.",
			full = "Satyrnaar stands broken among the trees of northeastern Ashenvale, its old stonework given over to the tents of the Bleakheart satyr. Of the three satyr ruins scattered through the forest, this one is the most whole, and the most easily reached, lying just off the road toward Azshara. That nearness has made it the most fought-over of the three as well.\n\nThe Bleakheart are bound to the Cult of the Dark Strand, and within the ruins rests one of the cult's soulgems, entrusted to the satyr's keeping.\n\nA shadow of the same settlement exists within the Emerald Dream. There, satyr of the Dreamfire sect stand guard under Zalius, sworn to protect an ancient prophecy of Azshara, hidden away from the waking world.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Shady Nook",
			short = "Tucked south of Raynewood Retreat and east of Greenpaw Village, the Shady Nook is a small, quiet valley in Ashenvale. A small family of bears lives here, keeping to the hollow and the small cave that opens onto it.",
			full = "Tucked south of Raynewood Retreat and east of Greenpaw Village, the Shady Nook is a small, quiet valley in Ashenvale. A small family of bears lives here, keeping to the hollow and the small cave that opens onto it.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Shrine of Aessina",
			short = "The Shrine of Aessina stands in southwestern Ashenvale, its stones caught between two purposes. The Alliance labored to raise its defenses anew, while the Horde meant only to see it burned to the ground.",
			full = "The Shrine of Aessina stands in southwestern Ashenvale, its stones caught between two purposes. The Alliance labored to raise its defenses anew, while the Horde meant only to see it burned to the ground.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Silverwind Refuge",
			short = "Silverwind once lived up to its name. Sentinels held it, backed by an army of water elementals bound to their service, and the night elves who dwelt there thought it impenetrable.",
			full = "Silverwind once lived up to its name. Sentinels held it, backed by an army of water elementals bound to their service, and the night elves who dwelt there thought it impenetrable.\n\nIt was not enough. When the Horde came against Silverwind, they turned the elementals' own rage back upon their masters, and the outpost that had seemed unbreakable fell in a single reversal. The orcs showed no distinction between soldier and civilian; Sentinels and townsfolk alike were put to the sword. Those who fled were hunted down on the road, and their bodies were left to rot where they fell, not from neglect but as a warning to anyone who might think of retaking the place. Some of those bodies lie there still, scattered around the outpost among those who once called it home.\n\nThe survivors escaped to Stardust Spire nearby and swore they would have Silverwind back.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Silverwing Grove",
			short = "The Silverwing Sentinels hold their ground in the grove, watching the borders of Ashenvale against the Horde encroaching from the west.",
			full = "The Silverwing Sentinels hold their ground in the grove, watching the borders of Ashenvale against the Horde encroaching from the west. It is a quiet, wooded post beneath the trees, but the peace is only ever borrowed.\n\nDuring the War of the Thorns, the Horde struck at the grove itself, carrying the fighting into the trees the Sentinels had sworn to guard.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Silverwing Outpost",
			short = "Silverwing Outpost stands on the wrong side of the Falfarren River, holding ground the orcs of Ashenvale consider their own to reclaim.",
			full = "Silverwing Outpost stands on the wrong side of the Falfarren River, holding ground the orcs of Ashenvale consider their own to reclaim. Attack follows attack, unrelenting, for the woods will not be rid of the Silverwings without a fight.\n\nDuriel Moonfire commands here, and by his tactics the outpost has held as long as it has. But even he could not turn back every assault. One army broke through the fortifications entirely, driving the Silverwing Sentinels from their post and scattering or killing any who could not escape.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape.",
			full = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape. It marks the boundary between Ashenvale and Azshara to the north, and further south divides the Northern Barrens from Durotar, before finally pouring itself into the Great Sea in one last waterfall near the goblin port of Ratchet.\n\nThree bridges cross it: one linking Azshara to Ashenvale, one carrying travelers into Orgrimmar itself, and one joining Durotar to the Northern Barrens. Just north of the western bridge into the orc capital, there is a single point where four lands touch at once, the water running between them all.\n\nAt the river's mouth, a goblin named Horton Hornblower keeps a riverboat tied at his dock, ferrying those who need passage upstream toward the Barrens.\n\nThe river still runs strong enough to water the fields along its banks, but its water can no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Splintertree Post",
			short = "Splintertree Post stands where Grom Hellscream and his Warsong clan first drove stakes into Ashenvale soil during the Third War, when the orcs pushed into the forest for its timber.",
			full = "Splintertree Post stands where Grom Hellscream and his Warsong clan first drove stakes into Ashenvale soil during the Third War, when the orcs pushed into the forest for its timber. It has never been forgiven for it.\n\nThe night elves have not forgotten what the Warsong did to these woods, and Splintertree pays for it still. Raids on Astranaar are frequent, and the peace between Horde and Alliance counts for little out here -- the outpost sits under near-constant threat of retaliation from the Sentinels, its fortifications scarred, its outer camps sometimes found abandoned or burned before anyone can say who struck.\n\nWhat keeps the walls standing is the lumber camp nearby, whose steady wagons of timber and supply hold the post together. Zekhan's own reckoning of the place is grim: the fighting here will not end soon, not while the night elves still reckon a debt owed for Teldrassil, and not while Splintertree remains the nearest orc throat to put a blade to.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "Talondeep Path",
			short = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its walls pocked with small dead ends and hollows, though nothing living dwells there.",
			full = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its walls pocked with small dead ends and hollows, though nothing living dwells there. One mouth opens west of Mystral Lake in Ashenvale; the other lies in northwestern Windshear Crag among the Stonetalons.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Thistlefur Village",
			short = "Thistlefur Village lies north of Astranaar in Ashenvale, home to the Thistlefur tribe, furbolgs turned savage and corrupted. They fall upon anyone who strays too near without waiting to ask why.",
			full = "Thistlefur Village lies north of Astranaar in Ashenvale, home to the Thistlefur tribe, furbolgs turned savage and corrupted. They fall upon anyone who strays too near without waiting to ask why.\n\nThe tribe answers to two ferocious warriors, Dal Bloodclaw and Rorgish Jowl.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Warsong Labor Camp",
			short = "The Warsong Labor Camp lies in southeastern Ashenvale, east of Fallen Sky Lake and southwest of the Dor'Danil Barrow Den. Loggers, harvesters, and orcish guards work here for the Warsong Clan.",
			full = "The Warsong Labor Camp lies in southeastern Ashenvale, east of Fallen Sky Lake and southwest of the Dor'Danil Barrow Den. Loggers, harvesters, and orcish guards work here for the Warsong Clan. Its isolation leaves the guards exposed, and Alliance raiders strike them here with little fear of reprisal.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Warsong Lumber Camp",
			short = "Axes ring through Ashenvale at Warsong Lumber Camp, where the Warsong clan fells timber under the watch of Kargathia Keep and its kennels.",
			full = "Axes ring through Ashenvale at Warsong Lumber Camp, where the Warsong clan fells timber under the watch of Kargathia Keep and its kennels. The wood cut here does not stay idle; it flows steadily to Splintertree Post nearby, keeping its walls standing and its people fed.\n\nThe forest does not give up its trees freely. Illiyana and her sisters have moved through the cutting grounds calling on nature's fury, tearing shredders apart with magic drawn from the living wood itself, making the camp a battleground between Alliance and Horde.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Xavian rises from the ruins of a night elf temple, its broken columns overgrown and given over to satyrs.",
			full = "Xavian rises from the ruins of a night elf temple, its broken columns overgrown and given over to satyrs. It is the deepest of their holdings in Ashenvale, and the most powerful -- Prince Raze and Geltharis both hold court among its stones, working their rituals with stolen Warsong oil.\n\nThe name is older than the ruin's new masters. Xavius was once a night elf, one of those who helped open the way for the Burning Legion through a portal drawn from the Well of Eternity in Zin-Azshari, in the war that broke the ancient world. When Sargeras found his work wanting, he remade Xavius into the first of the satyrs. The temple bears his name still, close as it lies to Azshara's old domain.\n\nXalan the Feared once commanded here, until Shandris Feathermoon and the druid Arvell led Sentinels against him and cut him down. And it was here that a dryad named Anilia was found dying, having gone in search of a stolen branch of Cenarius, one more searcher who did not come back out of Xavian's ruins.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "Zoram Strand",
			short = "Where the sand runs pale and broken along the northwest edge of Ashenvale, the sea holds a grave. Long before the waters rose here, a night elven city called Zoram stood on this ground.",
			full = "Where the sand runs pale and broken along the northwest edge of Ashenvale, the sea holds a grave. Long before the waters rose here, a night elven city called Zoram stood on this ground. When the world was torn apart in the Great Sundering, Zoram did not survive it. The city and its people went down beneath what is now the Veiled Sea, leaving only the strand behind to mark where a home had been.\n\nWhat lives here now came up out of the same drowned dark. Naga have taken the beach as their own, and the evidence is everywhere in the wreckage: ships broken apart on the rocks, sea creatures beached and dying in the shallows. Among them, the Wrathtail have made themselves known through steady violence, and it was naga who fell upon the settlers of Talen, leaving little doubt as to who commands this shore.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Zoram'gar Outpost",
			short = "Zoram'gar Outpost sits on Zoram Strand, its docks the only Horde harbor within reach of Azuremyst Isle.",
			full = "Zoram'gar Outpost sits on Zoram Strand, its docks the only Horde harbor within reach of Azuremyst Isle. The open shore beside it once served as a staging ground, where the Horde massed its forces before pushing north into Darkshore.\n\nThat same water is now sown with danger. Wary of a Horde strike toward Azuremyst, the Alliance seeded the sea with depth charges. The Horde laid its own in turn, guarding against any landing from the water.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Thousand Needles: 20 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Camp E'thok",
			short = "Camp E'thok, in northwestern Thousand Needles, was a Galak centaur camp.",
			full = "Camp E'thok, in northwestern Thousand Needles, was a Galak centaur camp. Its riders once raided a caravan carrying the goblin Wizlo Bearingshiner, but could not take his prized gadget, tied around the neck of his fierce panther. Survivors of the camp's fall made their way to Splithoof Heights.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Darkcloud Pinnacle",
			short = "Darkcloud Pinnacle rises east of the Great Lift, its settlement spread across three small mesas linked by rope bridges over open air.",
			full = "Darkcloud Pinnacle rises east of the Great Lift, its settlement spread across three small mesas linked by rope bridges over open air. Smaller mesas nearby stand empty, unclaimed. Only two paths lead in: a natural slope up a fourth rise ending in a bridge crossing, or a second bridge reaching over from Razorfen Downs. Both are watched closely.\n\nThe Grimtotem tauren hold this place, led here by Arnak Grimtotem and Harb Foulmountain. From atop the mesas they carry on a secret correspondence with some dark power whose name and nature no one has spoken aloud, passed across the bridges and up the slope, into rooms no outsider is meant to see.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Freewind Post",
			short = "Freewind Post stands atop one of the great mesas of Thousand Needles, reached only by wooden lifts and swaying rope bridges built to keep such heights out of the grasp of the centaur warbands below.",
			full = "Freewind Post stands atop one of the great mesas of Thousand Needles, reached only by wooden lifts and swaying rope bridges built to keep such heights out of the grasp of the centaur warbands below. From here the tauren wage their long struggle against the Galak tribe, and send their young to Highperch to study the wyverns and cull eggs from the ancestral nesting grounds, raising the young serpents as mounts.\n\nThe deeper trouble came from Darkcloud Pinnacle to the northwest, where the Grimtotem tribe held their seat under chieftain Arnak Grimtotem. Freewind blamed him for a string of disappearances and killings among their own. When Lakota Windsong refused his advances, Arnak had her taken against her will, and when her brother came to defend her, he was slain for it. The grief of that loss hardened Freewind Post against its neighbors on the pinnacle.\n\nWhen Cairne Bloodhoof died, the Grimtotem struck at Freewind Post directly, but the assault was thrown back.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "Great Lift",
			short = "The Great Lift was raised by tauren hands to carry travelers down between the Barrens and Thousand Needles.",
			full = "The Great Lift was raised by tauren hands to carry travelers down between the Barrens and Thousand Needles. The tauren Grish Longrunner and Brave Moonhorn once tended it, but neither is to be found now, gone home or lost to the quilboar who have spread through the southern Barrens, closing off the path to the lift.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Highperch",
			short = "Highperch rises above the Thousand Needles, home to wyverns and their nests. Pao'ka Swiftmountain, once trapped here himself, returned after his rescue to watch over them.",
			full = "Highperch rises above the Thousand Needles, home to wyverns and their nests. Pao'ka Swiftmountain, once trapped here himself, returned after his rescue to watch over them.\n\nThen the Twilight's Hammer came, capturing what wyverns they could and killing the rest. Heartrazor, the alpha male, was wounded and pinned down at the back of Highperch by four Twilight subduers. The wind riders taken alive were dragged to the shelf above, the Twilight Aerie, where Twilight's Hammer riders now fly them as their own.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Ironstone Camp",
			short = "Ironstone Camp sits at the edge of the Shimmering Flats, a small Horde foothold sent to drive dwarven excavators from the Rustmaul Digsite.",
			full = "Ironstone Camp sits at the edge of the Shimmering Flats, a small Horde foothold sent to drive dwarven excavators from the Rustmaul Digsite. Instead, Silithid broke from a nearby cave and fell upon them, turning conquest into survival.\n\nMoktar Krin, still holding the camp, now sends others out to kill the Silithid infesting the digsite.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Mirage Raceway",
			short = "The Mirage Raceway began as a rivalry made of steel.",
			full = "The Mirage Raceway began as a rivalry made of steel. The goblin Pozzik and the gnome Fizzle Brassbolts, each certain his race was the superior engineer, built rocket cars and enlisted teams to race them, determined to settle the argument on the track rather than in words.\n\nThe contest outgrew them. Supporters of both Horde and Alliance came to cheer their favorites, and the daily races drew gamblers and seedier company besides, all wagering on which side's cars would win the day.\n\nThe raceway did not survive its own success and was submerged. Pozzik and Fizzle built a floating Speedbarge to hover above the drowned track, and the rivalry continues there still.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Razorfen Downs",
			short = "The entrance to Razorfen Downs is said to be Agamaggan's own maw, a gap in the thorns so well hidden that only those who already know its shape can find it.",
			full = "The entrance to Razorfen Downs is said to be Agamaggan's own maw, a gap in the thorns so well hidden that only those who already know its shape can find it. Beyond lies the ancestral burial ground of the quilboar, their traditional capital, grown rather than built from the same great vines as Razorfen Kraul. Charlga Razorflank shaped most of the thorn dome that shelters it, and in time passed the knowledge of tending it to Chugara Razorflank.\n\nAfter the Third War, the lich Amnennar the Coldbringer turned his agents loose upon the quilboar, binding many of the tribe to his will and remaking the labyrinth into a stronghold of the Scourge. The quilboar fought bitterly to win back their holy ground before his plague could spread beyond it.\n\nAmnennar was struck down, yet his phylactery survived him, and Death Speaker Blackthorn labored among the dead to call his master back into the world. It was Reigol Valdread who struck Blackthorn down instead, ending Amnennar's return for good.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Roguefeather Den",
			short = "In the back of the cave, past the screeching of the harpies who guard it, sits their hoard of gathered food, watched over as fiercely as any treasure.",
			full = "In the back of the cave, past the screeching of the harpies who guard it, sits their hoard of gathered food, watched over as fiercely as any treasure.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Rustmaul Dig Site",
			short = "The Explorers' League was digging into buried ruins in the Shimmering Flats when a war party led by Moktar Krin fell upon them and killed them all.",
			full = "The Explorers' League was digging into buried ruins in the Shimmering Flats when a war party led by Moktar Krin fell upon them and killed them all.\n\nBut the fighting shook loose something sleeping beneath the site: a nest of silithid in a cave within the dig. The insects erupted in an unbroken swarm, and the war party, already spent from the slaughter, broke and fled. Some survivors made it only to Ironstone Camp; others reached Orgrimmar.\n\nThe ruins sit unclaimed atop the nest now, known as the Sunken Dig Site.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["screeching canyon"] = {
			name = "Screeching Canyon",
			short = "The Screeching Canyon cuts through the southern reaches of Thousand Needles, its walls echoing with the cries of the harpies that infest it.",
			full = "The Screeching Canyon cuts through the southern reaches of Thousand Needles, its walls echoing with the cries of the harpies that infest it. Deep in its back stands the Roguefeather Den, the harpies' stronghold, from which their screeching name spread to the canyon itself.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "Shimmering Flats",
			short = "The Shimmering Flats stretches wide and white across the southeastern edge of Thousand Needles, a dried lakebed scoured bare of grass or scrub.",
			full = "The Shimmering Flats stretches wide and white across the southeastern edge of Thousand Needles, a dried lakebed scoured bare of grass or scrub. The wreck of a sailing vessel still lies half-buried in the northern sands, a strange relic of the water that once covered this place, now home only to basilisks, scorpids, turtles, and vultures.\n\nThe flatness of the ground drew goblins and gnomes down from their workshops, who saw in the open salt pan the perfect proving ground for their machines. They built the Mirage Raceway here and threw their inventions against one another in endless contests of speed. Most of those inventions failed. The flats are scattered with the wreckage of gizmos that shook themselves apart and craters blown into the salt by contraptions that never should have run in the first place.\n\nWhen the Raceway itself sank beneath the shifting flats, the goblins Fizzle and Pozzik raised their Speedbarge in its place, keeping the old rivalry alive.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Between the two great continents, where the waters of the Great Sea run deep and warm, lies the tangle of islands and reefs known as the South Seas.",
			full = "Between the two great continents, where the waters of the Great Sea run deep and warm, lies the tangle of islands and reefs known as the South Seas. Zandalar rises here, ancient seat of the trolls. Tel'Abim breaks the water further off. Kezan sits apart, its own scarred and smoking rock.\n\nThe coasts nearest the mainland are known better than the deep water beyond them. Stranglethorn Vale marks where the Eastern Kingdoms give way to this sea. To the west, Tanaris, the Thousand Needles, and Uldum stand where Kalimdor's shore meets the same waters.\n\nBeyond those known shores the South Seas keep their own geography of scattered, half-charted places: shallows and coves, sunken ruins, isles named for sailors and wrecks that found them and never came back to say more. Somewhere within this water, it is said, lies the Maelstrom itself, the great churning wound at the world's heart, though few who study the South Seas can say so with certainty.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["splithoof crag"] = {
			name = "Splithoof Crag",
			short = "Splithoof Crag stood against the northern wall of Thousand Needles, a village of the Galak centaur east of Darkcloud Pinnacle.",
			full = "Splithoof Crag stood against the northern wall of Thousand Needles, a village of the Galak centaur east of Darkcloud Pinnacle. At its heart, within a cavern called Splithoof Hold, the Galak guarded the Cloven Hoof, an ancient artifact kept before the Ancient Brazier and its Sacred Flame.\n\nThe village did not endure. The surviving Galak abandoned it, raising a new home, Splithoof Heights, on the cliffs above the Shimmering Deep. What remains now is debris and underwater life along the mountainside.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Splithoof Hold",
			short = "The Galak centaur made their stronghold in the cave of Splithoof Crag, keeping there the Ancient Brazier and its Sacred Flame, a fire said to burn even underwater.",
			full = "The Galak centaur made their stronghold in the cave of Splithoof Crag, keeping there the Ancient Brazier and its Sacred Flame, a fire said to burn even underwater. Eternal though it was called, Aquarian doused it, and the flame went dark.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Tahonda Ruins",
			short = "Beneath the waves of the Shimmering Deep lies a sunken tauren village, remembered now only by its name: Tahonda.",
			full = "Beneath the waves of the Shimmering Deep lies a sunken tauren village, remembered now only by its name: Tahonda.\n\nNothing explains why it fell. One wall of leather still bears two sets of three parallel tears, claws dragged deep enough to outlast the water and the sand. No record says who made them, or whether anyone survived.\n\nThe ruins keep that silence, settled near the mountain path to Tanaris, gone quiet beneath the shimmering water.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "Weathered Nook",
			short = "On the northern wall of Thousand Needles, a small cave hides in the rock, easy to miss unless one already knows it is there. This is the Weathered Nook, home to Dorn Plainstalker and Prate Cloudseer.",
			full = "On the northern wall of Thousand Needles, a small cave hides in the rock, easy to miss unless one already knows it is there. This is the Weathered Nook, home to Dorn Plainstalker and Prate Cloudseer.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Weazel's Crater",
			short = "In the northern Shimmering Flats, the ground drops into a wide, deep crater. No one knows how it formed. Its name hints at some figure called Weazel, whether the one who found it or the one who blasted it into being.",
			full = "In the northern Shimmering Flats, the ground drops into a wide, deep crater. No one knows how it formed. Its name hints at some figure called Weazel, whether the one who found it or the one who blasted it into being.\n\nScattered rubble across the flats, left by reckless racing machines, suggests the crater may be the wreck of some invention gone wrong.\n\nSaltstone basilisks now den in its depths.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Whitereach Post",
			short = "Whitereach Post once stood along the road near Camp E'thok in Thousand Needles, a small Horde outpost. It did not endure. Of those who might have fled to Westreach Summit, only one name is spoken now: Kanati Greycloud.",
			full = "Whitereach Post once stood along the road near Camp E'thok in Thousand Needles, a small Horde outpost. It did not endure. Of those who might have fled to Westreach Summit, only one name is spoken now: Kanati Greycloud.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Windbreak Canyon",
			short = "Wind serpents nest throughout Windbreak Canyon, their coils wound among the rocks between Freewind Post and the Shimmering Flats. A path winding through the canyon leads on to the Weathered Nook beyond.",
			full = "Wind serpents nest throughout Windbreak Canyon, their coils wound among the rocks between Freewind Post and the Shimmering Flats. A path winding through the canyon leads on to the Weathered Nook beyond.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Stonetalon Mountains: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Blackwolf River",
			short = "The Blackwolf River flows through Windshear Crag from Cragpool Lake in the Stonetalon Mountains. Its waters once ran foul, choked by the Venture Company's deforestation of the valley above.",
			full = "The Blackwolf River flows through Windshear Crag from Cragpool Lake in the Stonetalon Mountains. Its waters once ran foul, choked by the Venture Company's deforestation of the valley above. Since then, the river has run clearer.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Boulderslide Cavern",
			short = "Boulderslide Cavern opens where Boulderslide Ravine ends, into warrens dug by the Boulderslide kobolds.",
			full = "Boulderslide Cavern opens where Boulderslide Ravine ends, into warrens dug by the Boulderslide kobolds. They mine without rest for Resonite, a rare purple crystal touched with earthen magic, and guard every vein of it with their lives.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Boulderslide Ravine",
			short = "The ravine sees little of the fighting that has scarred the land around it. Rams graze its slopes, and cliff stormers circle above, but no army has left its mark here.",
			full = "The ravine sees little of the fighting that has scarred the land around it. Rams graze its slopes, and cliff stormers circle above, but no army has left its mark here.\n\nOpposite the cavern at its heart lies a smaller, abandoned cave, lit once with crude torches and stocked with barrels since left untouched. Its walls carry tribal art, faded now, the kind of marks tauren hands might have made.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Camp Aparaje",
			short = "Camp Aparaje stood in eastern Stonetalon Mountains until the Grimtotem came down from Grimtotem Post. Grundig Darkcloud led the attack that broke the village.",
			full = "Camp Aparaje stood in eastern Stonetalon Mountains until the Grimtotem came down from Grimtotem Post. Grundig Darkcloud led the attack that broke the village. Makaba Flathoof had lived there with his daughter Kaya before it fell.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Charred Vale",
			short = "Once the Charred Vale was green, and Bloodfury harpies nested in its heights while treants walked among the trees, keeping the forest safe.",
			full = "Once the Charred Vale was green, and Bloodfury harpies nested in its heights while treants walked among the trees, keeping the forest safe.\n\nThen the Venture Company came with axe and machine, tearing the vale apart. The treants rose against them and drove the goblins out, but the vale's spirits had already been enraged past calming, and elementals broke loose from the earth itself. Worse, the treants who fought to save the forest did not come away clean -- the goblins' weapons left something in them, twisting the very guardians that had won the fight. The vale burned, and the fire never fully went out. Lava threads through it still, and the ground smolders where soil once was.\n\nWhat rules the ashes now is not the old forest but the fire's own brood -- black dragon whelps and drakes answering to Seldarria. Yet at Sun Rock Retreat the druids have not given up. Slowly, stubbornly, green is returning to the black ground, a forest trying to remember what it once was.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Cragpool Lake",
			short = "Cragpool Lake sits beneath the great timber structure the Venture Company raised above Windshear Crag.",
			full = "Cragpool Lake sits beneath the great timber structure the Venture Company raised above Windshear Crag. Most of the company has pulled out since, but those who remain keep to the structure overhead, among them Gerenzo Wrenchwhistle, who once used this height to oversee the operation below.\n\nThe lake itself is closed to all now, home to Cragjaw, a fish grown far past any natural size.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Greatwood Vale",
			short = "Greatwood Vale lies wooded in the foothills of the Stonetalon Mountains, Malaka'jin to its south and the Northwatch Expedition camped to its north.",
			full = "Greatwood Vale lies wooded in the foothills of the Stonetalon Mountains, Malaka'jin to its south and the Northwatch Expedition camped to its north.\n\nGrundig Darkcloud led the Grimtotem tribe against Camp Aparaje and slaughtered most who lived there. Makaba Flathoof survived, and called for the Grimtotem in the vale to be hunted down for it.\n\nBut the Grimtotem did not stand alone. The Alliance struck a bargain with them: weapons, in exchange for free passage through their lands and protection from the Horde. The pact held long enough to matter. Together they turned back a Horde advance into the vale and cut down four of the Horde's most feared generals there.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Grimtotem Post",
			short = "Grimtotem Post is the tribe's foothold in Stonetalon Mountains, its brutes, ruffians, sorcerers, and mercenaries watching the slopes around it.",
			full = "Grimtotem Post is the tribe's foothold in Stonetalon Mountains, its brutes, ruffians, sorcerers, and mercenaries watching the slopes around it. Grundig Darkcloud commands them here, fierce enough to hold the post for the Grimtotem.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Malaka'jin is a village of troll hunters south of the Grimtotem Post, living modestly off the game they bring down in the Stonetalon Mountains and sell to passing travelers.",
			full = "Malaka'jin is a village of troll hunters south of the Grimtotem Post, living modestly off the game they bring down in the Stonetalon Mountains and sell to passing travelers.\n\nFrom here the Horde launches its attacks against the Grimtotem tribe, whose hold on Stonetalon presses close from the north. The High Road from the Southern Barrens meets the village here as well.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Mirkfallon Lake",
			short = "Mirkfallon Lake sits at the heart of Stonetalon Mountains, once a wild place whose waters and shores were home to wyverns, slimes, and thunder lizards.",
			full = "Mirkfallon Lake sits at the heart of Stonetalon Mountains, once a wild place whose waters and shores were home to wyverns, slimes, and thunder lizards.\n\nThat is no longer true of the hill at its center. Goblins have carved it hollow and raised an oil platform there, ringing the lake with pumpjacks that draw up what lies beneath the water.\n\nSome of the old life remains. Above the lake, at Windshear Heights, the last of the area's wyverns still nest. To the southwest, the Alliance keeps a camp at Mirkfallon Post, watching over what the goblins have built.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Sishir Canyon",
			short = "Sishir Canyon carries the road through the Stonetalon Mountains down toward the Ruins of Eldre'thar. Once its walls were choked with webbing, and clusters of spider eggs layered the rock in every hollow.",
			full = "Sishir Canyon carries the road through the Stonetalon Mountains down toward the Ruins of Eldre'thar. Once its walls were choked with webbing, and clusters of spider eggs layered the rock in every hollow. The canyon belonged to the Deepmoss spiders, and deep within, where the light failed, waited Besseleth, greatest of their brood. The canyon still runs toward the ruins, webbed and thick with eggs, a passage best not lingered in.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Stonetalon Peak",
			short = "The mountain has long been sacred, its stone suffused with old magic. Before the elves who tend it now, the peak served as a temple to Queen Azshara.",
			full = "The mountain has long been sacred, its stone suffused with old magic. Before the elves who tend it now, the peak served as a temple to Queen Azshara.\n\nThe druids of Talon Den kept the valley green, and the settlement above it became a hub for night elves and their allies.\n\nThat peace has broken. Tendrils of a sinister magic have torn into the peak and destroyed the settlement. The Sentinels once stationed to guard it now wander corrupted. Brother Ravenoak, who had lain still for so long, has woken changed, the same corruption moving in him. Harbinger Aph'lass, who commanded the invading magic, has since fallen, but his death has not stilled the tendrils. They spread still through ground that once held nothing more dangerous than old songs to a drowned queen.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Sun Rock Retreat",
			short = "Sun Rock Retreat lies hidden among the peaks south of Mirkfallon Lake, once the primary hub of the Stonetalon Mountains.",
			full = "Sun Rock Retreat lies hidden among the peaks south of Mirkfallon Lake, once the primary hub of the Stonetalon Mountains. Here orc and tauren gathered to repair the damage done to the land by the Venture Company and other forces that sought to strip it bare.\n\nLong before that work began, tauren made pilgrimage to this place, for Sun Rock holds a strong bond to the spirit world, thin enough for those seeking it to cross over. It is said that An'she himself once kissed the mountain where the retreat now stands, and that this is the source of its power still.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "Talon Den",
			short = "The barrow den takes its name from the peak that holds it, its passages home to Mirkfallon dryads and Cenarion Caretakers who tend the mountain, alongside the Mirkfallon Keepers who watch over the same slopes.",
			full = "The barrow den takes its name from the peak that holds it, its passages home to Mirkfallon dryads and Cenarion Caretakers who tend the mountain, alongside the Mirkfallon Keepers who watch over the same slopes.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "Talondeep Path",
			short = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its walls pocked with small dead ends and hollows, though nothing living dwells there.",
			full = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its walls pocked with small dead ends and hollows, though nothing living dwells there. One mouth opens west of Mystral Lake in Ashenvale; the other lies in northwestern Windshear Crag among the Stonetalons.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Webwinder Path",
			short = "The road runs from Malaka'jin to Mirkfallon Lake, though much of the ground beside it has sunk low over time.",
			full = "The road runs from Malaka'jin to Mirkfallon Lake, though much of the ground beside it has sunk low over time. West of Malaka'jin the Horde raised a barricade across the path, meant to hold the Alliance from pushing further east.\n\nAramar Thorne and Makasa Flintwill once led their companies down this stretch. Looking up, Makasa and Murky found the forest canopy transformed into a labyrinth of spider silk, tunnels and loops of glittering ivory strands woven into a fortress in the branches, thick with spiders.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Windshear Crag",
			short = "Windshear Crag was once old-growth forest, thick and green in its valley among the Stonetalon Mountains. What stands there now is the wreckage of that forest.",
			full = "Windshear Crag was once old-growth forest, thick and green in its valley among the Stonetalon Mountains. What stands there now is the wreckage of that forest.\n\nThe Venture Company came with saws and steam, and the man who ran the operation was the leper gnome Gerenzo Wrenchwhistle. He built the Super Reaper 6000, a machine that could grind the crag's oldest and largest trees to sawdust, and he watched his work from a platform raised above Cragpool Lake, lord of a valley he was busy erasing. His efficiency did not save him. Director Riddlevox of the Tinkers' Union in Undermine wanted him gone, and sent the goblin Ziz Fizziks to do it. Gerenzo lived through the attempt, and held on to the water wheel, the one piece of the crag still his, until Professor Xakxak Gyromate sent someone to finish the job.\n\nBy the time the deforestation was complete, the crag was stumps and polluted water and machinery left creaking in the quiet.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Windshear Mine",
			short = "Windshear Mine lies at the end of Blackwolf River. The Venture Company once worked it, setting kobolds to dig the tin from its tunnels, until they abandoned the claim.",
			full = "Windshear Mine lies at the end of Blackwolf River. The Venture Company once worked it, setting kobolds to dig the tin from its tunnels, until they abandoned the claim. The Horde moved in after and holds the mine now.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Desolace: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Bolgan's Hole",
			short = "Bolgan's Hole, in Gelkis Village, shelters the clan's most prominent members, among them the khan -- once Shaka, now Shodo.",
			full = "Bolgan's Hole, in Gelkis Village, shelters the clan's most prominent members, among them the khan -- once Shaka, now Shodo.\n\nWithin grow blue crystals, tears of Theradras, hoarded by the Gelkis shaman, who believe the stones carry Princess Theradras' protection.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Beneath the waves in northwest Desolace lie the drowned stones of Ethel Rethor, a night elven ruin. Only a lone tower breaks the surface, reached by a bridge ending at a sealed door.",
			full = "Beneath the waves in northwest Desolace lie the drowned stones of Ethel Rethor, a night elven ruin. Only a lone tower breaks the surface, reached by a bridge ending at a sealed door. Naga have claimed the sunken halls below.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Gelkis Village",
			short = "Gelkis Village rings a deep ravine in southwestern Desolace, its huts and bridges strung across the cliffs and bluffs that fall away into the earth.",
			full = "Gelkis Village rings a deep ravine in southwestern Desolace, its huts and bridges strung across the cliffs and bluffs that fall away into the earth. Deepest within lies Bolgan's Hole, a cave cut into the southern mountain face where the Gelkis Khan makes his seat, ruling the clan from the dark.\n\nThe village sits hard against the main road running the length of Desolace, and travelers passing that way pass within reach of centaur spears. The Gelkis have pushed huts out along the eastern road toward Feralas as well, spreading their hold further over the land they claim.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Ghost Walker Post",
			short = "Ghost Walker Post stands beside the Kodo Graveyard in central Desolace, and the dead there shape everything about the place.",
			full = "Ghost Walker Post stands beside the Kodo Graveyard in central Desolace, and the dead there shape everything about the place. Tauren shamans keep watch over the bones, easing the great kodo beasts into their next lives and, when the wind is right, speaking with the spirits of those already gone.\n\nGurda Wildmane leads the post, and her burden is heavier than that of her counterpart at Shadowprey Village to the south. Where Shadowprey sits secure, Ghost Walker Post is exposed on all sides, and from it the Horde carries the fight against the Burning Blade and against the centaur tribes that range across Desolace. Thrall sent a contingent of orcs to stand alongside the tauren here, a sign of how much this war was thought to matter.\n\nThere is little comfort at the post itself, only what is needed to keep the shamans safe while they tend the dead and the tauren and orcs hold the line.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Kodo Graveyard",
			short = "The kodo of Desolace come here to die, until the ground lies thick with their bones.",
			full = "The kodo of Desolace come here to die, until the ground lies thick with their bones.\n\nReach for those bones and the dead do not stay still: apparitions of kodo rise from the dust to guard what was left behind.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Kolkar Village",
			short = "The village was the seat of the Kolkar clan, most prolific of Kalimdor's centaur, with outposts as far as the Barrens and Durotar. To break the Kolkars, an enemy needed only to take this place, the source of their power.",
			full = "The village was the seat of the Kolkar clan, most prolific of Kalimdor's centaur, with outposts as far as the Barrens and Durotar. To break the Kolkars, an enemy needed only to take this place, the source of their power.\n\nThe Magram clan did just that, conquering the village outright. It now stands between Sargeron to the north and Magram Village to the south, a captured seat rather than a ruling one.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Kormek's Hut",
			short = "The hut stands alone in north-central Desolace, its name a puzzle no one living can explain.",
			full = "The hut stands alone in north-central Desolace, its name a puzzle no one living can explain.\n\nInside dwells Willow, a friendly member of the Twilight's Hammer. Outside, amid a pen scattered with kodo bones, Bibbly F'utzbuckle dances gleefully, dreaming of the profit such bones might fetch. Of Kormek himself, nothing remains.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Magram Village",
			short = "Crude bridges link the islands of the yellow pools where the Magram centaurs make their home, huts rising above waters long since fouled to a sickly ochre.",
			full = "Crude bridges link the islands of the yellow pools where the Magram centaurs make their home, huts rising above waters long since fouled to a sickly ochre. The Magram are at war with the Gelkis clan, kin turned enemy, and the village stands as a camp footed for that fight.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Mannoroc Coven",
			short = "Among the night elf ruins of Desolace, the earth was already dead before something worse took root. Travelers still feel a pall settle over them the moment they cross into the coven's reach.",
			full = "Among the night elf ruins of Desolace, the earth was already dead before something worse took root. Travelers still feel a pall settle over them the moment they cross into the coven's reach. The place bears the name of Mannoroth, the Pit Lord whose fel taint has never left this ground.\n\nThe Burning Blade cultists called the horror here into being, tearing open portals through which demons poured into the world. Infernals, felhounds, felguards, succubi, and doomguards now answer to Lord Azrethoc, who commands the largest gathering of demons in central Kalimdor. The orc warlock Jugkar Grim'rod remains as the Burning Blade's voice in a coven that has long outgrown its makers.\n\nSome of the portals have since been sealed, but for every rift closed, another opens elsewhere among the ruins. The wound was never closed, only bandaged, and Desolace remains one portal away from becoming a stronghold of the Burning Legion.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Nijel's Point",
			short = "In the northern mountains of Desolace stands Nijel's Point, an outpost held by the Alliance and the Cenarion Circle.",
			full = "In the northern mountains of Desolace stands Nijel's Point, an outpost held by the Alliance and the Cenarion Circle.\n\nIn the twenty-fifth year after the Dark Portal, Keeper Marandis came here with his dryad sisters, using the outpost as their base while they sought to retrieve the body of Zaetar from the depths of Maraudon, so that it might be carried home to Stonetalon Mountains. Their true purpose was darker still: to see Princess Theradras slain for what she had done to her father.\n\nThe outpost's peace did not last. When Alliance soldiers shot down the blood elf Furien near Sargeron, the Horde claimed the Ancient Vortex Runestone there in his memory, then loosed a firestorm against Nijel's Point to avenge their fallen comrade. The scars of that vengeance mark the place still.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Ranazjar Isle",
			short = "Ranazjar Isle's naga lie slaughtered where they fell, cut down by Lord Hydronis.",
			full = "Ranazjar Isle's naga lie slaughtered where they fell, cut down by Lord Hydronis. Beneath their ruin lies an older one: night elven remnants that share their make with those of Ethel Rethor, fragments of the same drowned city.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "The city that stood here once had another name, lost now beyond recovery.",
			full = "The city that stood here once had another name, lost now beyond recovery. It fell in the War of the Ancients, and its ruins were claimed by the Hatefury satyrs, who renamed the place Sargeron in honor of Sargeras, the demon lord they serve.\n\nBefore its fall this was a place sacred to Elune, home to her Cathedral, Temple, and Sanctuary. Relics of that devotion remain among the broken stone, surrounded now by satyrs who hold the ruins in their master's name.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Sar'theris Strand",
			short = "The coast beneath Ethel Rethor breaks from the rest of Desolace, sunny and green where the land inland lies grey and scoured bare.",
			full = "The coast beneath Ethel Rethor breaks from the rest of Desolace, sunny and green where the land inland lies grey and scoured bare.\n\nThe sea has left its wreckage here. The Karnitol lies broken off the northern shore, and below Ethel Rethor a smaller boat sits smashed on the sand. Sea giants wade the shallows, naga coil through the wrecks, and makrura crowd the tideline.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Scrabblescrew's Camp",
			short = "Smeed Scrabblescrew's camp lies near the Kodo Graveyard in Desolace, where the enterprising goblin has built his trade from the beasts that die there, maintaining a caravan of kodos amid the bones.",
			full = "Smeed Scrabblescrew's camp lies near the Kodo Graveyard in Desolace, where the enterprising goblin has built his trade from the beasts that die there, maintaining a caravan of kodos amid the bones.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Shadowbreak Ravine",
			short = "Hidden in the mountains southeast of Shok'Thokar, Shadowbreak Ravine was a secret haven of the Burning Blade cult, its giant mushrooms growing beside a summoning circle bound in great chains, where demons were called forth.",
			full = "Hidden in the mountains southeast of Shok'Thokar, Shadowbreak Ravine was a secret haven of the Burning Blade cult, its giant mushrooms growing beside a summoning circle bound in great chains, where demons were called forth.\n\nFrom here the Burning Blade and their demon army, led by Agogridon, drove the centaur from Magram Village and seized the land, burning the ravine's own structures and renaming it Shok'Thokar.\n\nAgogridon's death broke the cult's hold. Only corpses remain among the ashes now.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Shadowprey Village",
			short = "Shadowprey Village sits on the Sar'theris Strand, south of the Valley of Spears, where troll fishermen have long worked the coastal waters.",
			full = "Shadowprey Village sits on the Sar'theris Strand, south of the Valley of Spears, where troll fishermen have long worked the coastal waters. Their catches feed not only the village but the Ghost Walker Post beyond it, a supply line the region depends on.\n\nThat line has grown thin. An orca called Blubbergut has taken to hunting the same waters, gorging himself on the shoals before the nets can find them, leaving the fishermen to scrape by on what little he leaves behind.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Ruined columns rise from northern Desolace, the last remains of Tethris Aran, a night elven settlement long emptied of its people. Only wild creatures move among the fallen stones now.",
			full = "Ruined columns rise from northern Desolace, the last remains of Tethris Aran, a night elven settlement long emptied of its people. Only wild creatures move among the fallen stones now. The settlement is thought to have fallen in the Great Sundering.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Thunder Axe Fortress",
			short = "Thunder Axe Fortress stands in northwestern Desolace, its stronghold, barracks, cave, and watchtowers held by the Burning Blade cult under Kohor's command.",
			full = "Thunder Axe Fortress stands in northwestern Desolace, its stronghold, barracks, cave, and watchtowers held by the Burning Blade cult under Kohor's command.\n\nThe cult once kept the Hand of Iruxos within these walls, an artifact that could tear open demon portals at Mannoroc Coven, though it has been lost to them for years now. In its place, they have found a way to call forth Nazargen, a demon of terrible power -- one that could be destroyed easily enough if summoned before its time, but which would grow into something far worse if left to gather strength.\n\nThe fortress also once held the Sceptre of Light, stolen by the Burning Blade from the naga, until Azore Aldamorthas recovered it for the Argent Dawn.\n\nAmong those who dwelt here was Tyranis Malem, a traitor to his own people and a devoted student of demonic magic.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Valley of Bones",
			short = "The Valley of Bones is a crag in southern Desolace choked with skeletons, centaur necromancers, and the restless ghosts of the Magram clan.",
			full = "The Valley of Bones is a crag in southern Desolace choked with skeletons, centaur necromancers, and the restless ghosts of the Magram clan.\n\nAgainst its cliff walls lie two colossal skeletons, the Dead Goliaths, their origin unknown.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Valley of Spears",
			short = "The Valley of Spears lies shut away in western Desolace, reachable only through narrow mountain passes to the south and east. It is Maraudine centaur ground, thick with their camps.",
			full = "The Valley of Spears lies shut away in western Desolace, reachable only through narrow mountain passes to the south and east. It is Maraudine centaur ground, thick with their camps. At its southwestern end the earth opens into Maraudon. Somewhere among the centaur, held captive, is Melizza Brimbuzzle.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Feralas: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Camp Mojache",
			short = "Camp Mojache sits astride the swift stream feeding Wildwind Lake, its braves known for thick hides and the protection they offer travelers through the dangers of Feralas.",
			full = "Camp Mojache sits astride the swift stream feeding Wildwind Lake, its braves known for thick hides and the protection they offer travelers through the dangers of Feralas.\n\nThe camp has swelled with refugees fleeing Thousand Needles, many from Freewind Post, driven out by the destruction that took their homes.\n\nCamp Mojache itself never fell, but its warriors marched away to fight in the retaking of Thunder Bluff, leaving the village to hold on its own while its braves bled for the high tribe elsewhere. The Horde Council did not forget the debt, sending Belgrom Rockmaul to bring the camp aid.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Dire Maul",
			short = "Twelve thousand years ago, a covert sect of night elf sorcerers raised the city of Eldre'Thalas to guard Queen Azshara's most prized arcane secrets.",
			full = "Twelve thousand years ago, a covert sect of night elf sorcerers raised the city of Eldre'Thalas to guard Queen Azshara's most prized arcane secrets. Among its Highborne, the Shen'dralar lived in peace, and the whole city flourished under the power of the Fruit of Fertility, a vine of protection and growth.\n\nWhen the Great Sundering tore the world apart, a shielding spell spared the city from destruction, but cut it off from the Well of Eternity. To survive, the Highborne imprisoned a demon, Immol'thar, and drew their power from his binding. It sustained them for thousands of years, until the cost of holding him grew greater than what he gave. Their leader, Prince Tortheldrin, slaughtered many of his own people to free enough power to keep the rest alive. The survivors retreated deeper into the ruins, abandoning the outer city to whatever crept in after them.\n\nImmol'thar was later found still bound in the deep vaults and banished from the world. Robbed of his power, Tortheldrin led the last of the Shen'dralar in one final attack, and was slain. Those who survived left the city they had murdered each other to save, and never returned.\n\nOnly their ghosts remain in Eldre'Thalas now.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Dream Bough",
			short = "On a small island in the heart of Jademir Lake, in northern Feralas, stands the great tree called Dream Bough.",
			full = "On a small island in the heart of Jademir Lake, in northern Feralas, stands the great tree called Dream Bough. It was planted by followers of Fandral Staghelm from a branch of Nordrassil, set there to hold back the saronite seeping up through the land. In time it became one of the places where the waking world touches the Emerald Dream, a portal opening at its roots, and the green dragonflight took up its guard.\n\nThe dragon Lethlas held that portal at the base of the tree, with dragonspawn watching the shores of the lake around it. It was from here that Taerar meant to pour the corruption of the Emerald Nightmare out across Feralas. Ysondre, who feared to be corrupted again herself, would not set foot near the island, and so it fell to others to close the way. The portal was sealed, and the tree's connection to the Dream was broken.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Feathermoon Stronghold",
			short = "Feathermoon Stronghold rises from Sardor Isle off the coast of Feralas, a night elf fortress built and named for General Shandris Feathermoon, who for ten thousand years has stood at Tyrande Whisperwind's side among the Sentinels.",
			full = "Feathermoon Stronghold rises from Sardor Isle off the coast of Feralas, a night elf fortress built and named for General Shandris Feathermoon, who for ten thousand years has stood at Tyrande Whisperwind's side among the Sentinels.\n\nThe stronghold has faced no shortage of enemies. The Gordok ogres of Dire Maul once threatened it as no other force did, until their king was slain and the invasion broken without further bloodshed. Later, when the Gordunni ogres were found taking magical orbs from Cho'gall and the Twilight's Hammer, the worgen Silvia rallied the Sentinels to march on Dire Maul itself. Under Shandris Feathermoon's own command, the night elf army drove the cultists from the ruins before they could carry off the Highborne artifacts hidden there.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Feral Scar Vale",
			short = "In the High Wilderness of western Feralas, the Feral Scar yeti hold a vale that carries their name, wild ground given over entirely to their kind.",
			full = "In the High Wilderness of western Feralas, the Feral Scar yeti hold a vale that carries their name, wild ground given over entirely to their kind.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "Forgotten Coast",
			short = "The Forgotten Coast runs where western Feralas meets the Veiled Sea, a shore given over to water elementals and sea giants that roam the tideline undisturbed.",
			full = "The Forgotten Coast runs where western Feralas meets the Veiled Sea, a shore given over to water elementals and sea giants that roam the tideline undisturbed. A murloc fishing village clings to this coast, and its people have known little peace. Birds have carried off their tadpoles, humans and gnolls have fallen upon the village, and for years the Gordunni ogres raided it hardest of all, dragging a dozen or so captives off into Dire Maul, among them two named Murrl and Murrgly.\n\nTheir freedom came at the hands of outsiders. Aramar Thorne and his companions broke into Dire Maul and pulled the captive murlocs out of that place, and it was Wuul Breezerider, together with an ogre girl who chose to help them, who escorted the freed murlocs back out of the ruins and saw them safely home to the coast.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Frayfeather Highlands",
			short = "The Frayfeather Highlands rise as the domain of the Frayfeather hippogryphs, who take their name from the land itself and hold it as their own.",
			full = "The Frayfeather Highlands rise as the domain of the Frayfeather hippogryphs, who take their name from the land itself and hold it as their own. Scattered through the high ground are their nests, cradling eggs left beneath watchful wings.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Gordunni Outpost",
			short = "The hills north of Lariss Pavilion once wore the same green as the rest of Feralas, before the Gordunni ogres settled here, withering the grass to brown wherever they hold ground.",
			full = "The hills north of Lariss Pavilion once wore the same green as the rest of Feralas, before the Gordunni ogres settled here, withering the grass to brown wherever they hold ground.\n\nHillguards, Channelers, and Tamers watch the slopes. Near the back cave, the ogres keep a captive sasquatch, Bigfist, bound fast among the rocks.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Grimtotem Compound",
			short = "East of Dire Maul, the Grimtotem Compound is split into two settlements, where the Grimtotem tauren make their home apart from Thunder Bluff.",
			full = "East of Dire Maul, the Grimtotem Compound is split into two settlements, where the Grimtotem tauren make their home apart from Thunder Bluff. In the southern half stands a great cage, where the Grimtotem keep captive sprite darters. Gnolls camp east of the northern settlement.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "High Wilderness",
			short = "The High Wilderness spreads between the Forgotten Coast and the Verdantis River, a deep forest thick enough to hide what lives within it.",
			full = "The High Wilderness spreads between the Forgotten Coast and the Verdantis River, a deep forest thick enough to hide what lives within it. Bears, wolves, hippogryphs, yetis, treants, and ogres all share its shadowed reaches.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Isle of Dread",
			short = "The Isle of Dread lies off the western coast of Feralas, south of Sardor Isle, walled in by cliffs on every side but the southeast, where a single narrow way opens into the central valley.",
			full = "The Isle of Dread lies off the western coast of Feralas, south of Sardor Isle, walled in by cliffs on every side but the southeast, where a single narrow way opens into the central valley.\n\nThe valley belongs to the chimaerok, monstrous chimaeras that gather there under their lord, Lakmaeran. Lesser chimaerok and their arcane and devouring kin roam the valley floor, and their tenderloin has been carried back to a chef named Dirge, who works it into a dish fit for hard travelers. Lakmaeran himself yields more than meat: a carcass whole enough to be reforged into a five-hundred-pound fowl, said to have been devoured entire by a gnome named Narain Soothfancy.\n\nAt the northern end of the isle a cave sinks deep into the rock, unlike any other passage on the island in its make. A naga lord, Shalzaru, holds it, set there against Feathermoon Stronghold's wishes. Deeper still, past a hidden underwater channel, an inner chamber houses Lady Szallah, alone in the dark water.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Jademir Lake",
			short = "On the island of Dream Bough, at the heart of Jademir Lake, lies a portal into the Emerald Dream, watched over by Lethlas and a company of green dragonspawn.",
			full = "On the island of Dream Bough, at the heart of Jademir Lake, lies a portal into the Emerald Dream, watched over by Lethlas and a company of green dragonspawn. Along the lake's northwestern shore, whelps twisted by infection still linger.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Lariss Pavilion",
			short = "The Lariss Pavilion, built in the old night elf style, stands north of Camp Mojache. Its dryads once kept peaceful watch here, but the Emerald Nightmare has twisted their minds, and now they attack anyone who comes near.",
			full = "The Lariss Pavilion, built in the old night elf style, stands north of Camp Mojache. Its dryads once kept peaceful watch here, but the Emerald Nightmare has twisted their minds, and now they attack anyone who comes near.\n\nThe Pavilion is also home to Azj'Tordin, a Highborne who broke with Prince Tortheldrin and fled Dire Maul through a hidden backdoor at the bottom of the Pavilion. He escaped the prince, but not cleanly: an imp named Pusillin stole his book of incantations before he got free.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Lower Wilds",
			short = "The Lower Wilds mark the eastern reach of Feralas, falling toward Thousand Needles. Treants and corrupted dryads haunt the paths here, while refugees from Freewind Post pass through toward Camp Mojache.",
			full = "The Lower Wilds mark the eastern reach of Feralas, falling toward Thousand Needles. Treants and corrupted dryads haunt the paths here, while refugees from Freewind Post pass through toward Camp Mojache. The Emerald Summit rises along the eastern road, where New Thalanaar stands.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "South of Jademir Lake, the ruins of Oneiros hold a small night elf camp, Dreamer's Rest.",
			full = "South of Jademir Lake, the ruins of Oneiros hold a small night elf camp, Dreamer's Rest. Within the Emerald Dream, the same ruins stand corrupted, held by Nightmare-twisted dragonkin under Tyrannikus, guarding clutches of dragon eggs.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Rage Scar Hold",
			short = "Rage Scar Hold is a dug-in cave holding the most vicious yetis in Feralas.",
			full = "Rage Scar Hold is a dug-in cave holding the most vicious yetis in Feralas. Among them lie scattered books and arcane symbols, as if the yetis study this magic themselves, or once took it from some unfortunate mage who met his end within the cave.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruins of Isildien",
			short = "Ten thousand years ago, Isildien fell, a night elven city broken into columns across southwestern Feralas. What destroyed it is forgotten.",
			full = "Ten thousand years ago, Isildien fell, a night elven city broken into columns across southwestern Feralas. What destroyed it is forgotten. Now Gordunni ogres squat among the ruins, having made a fallen city's bones their home.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruins of Ravenwind",
			short = "The Ruins of Ravenwind, in northern Feralas, are the remains of an ancient Highborne civilization, kin to the builders of Dire Maul.",
			full = "The Ruins of Ravenwind, in northern Feralas, are the remains of an ancient Highborne civilization, kin to the builders of Dire Maul. Northspring harpies now nest among the fallen stones. A mirrored ruin exists in the Emerald Dream, held there by the harpy queen Slirena.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruins of Solarsal",
			short = "Southwest of Feathermoon Stronghold, on Sardor Isle, the old night elven stones of Solarsal still stand broken. The naga of the Hatecrest have taken the ruins for their own, moving through what was once elven ground.",
			full = "Southwest of Feathermoon Stronghold, on Sardor Isle, the old night elven stones of Solarsal still stand broken. The naga of the Hatecrest have taken the ruins for their own, moving through what was once elven ground.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Sardor Isle",
			short = "Sardor Isle sits west of the Feralas mainland, its shores once home to Feathermoon Stronghold, the night elf village led by Shandris Feathermoon.",
			full = "Sardor Isle sits west of the Feralas mainland, its shores once home to Feathermoon Stronghold, the night elf village led by Shandris Feathermoon. Naga moved through its waters, and wolves ran wild across its ground, sharing the isle with those who kept watch there.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Shalzaru's Lair",
			short = "The lair twists south of Feathermoon Stronghold's island, at the northern end of the Isle of Dread, two caves joined by a dark waterway.",
			full = "The lair twists south of Feathermoon Stronghold's island, at the northern end of the Isle of Dread, two caves joined by a dark waterway. Hatecrest sorceresses and serpent guards hold its passages. Deep within dwells Shalzaru, master of the Hatecrest, who few reach and fewer face.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Thalanaar offers little to the traveler passing through, save Caryssia Moonhunter, who works hides and leather here in the manner of the tribes.",
			full = "Thalanaar offers little to the traveler passing through, save Caryssia Moonhunter, who works hides and leather here in the manner of the tribes.\n\nNew Thalanaar rose just to the west of it, built fresh alongside the old ground.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "Twin Colossals",
			short = "On the western edge of Feralas two mountains rise higher than anything else around them, twin walls of stone with the road to Desolace running in the gap between.",
			full = "On the western edge of Feralas two mountains rise higher than anything else around them, twin walls of stone with the road to Desolace running in the gap between. Travelers passing beneath them fall silent at the sight, for there is little else in the world so tall and so close together.\n\nGregan Brewspewer once stood below and watched something no one else claims to have seen: a giant makura, a creature he named Diamond Head, clawing its way up the face of the eastern mountain until it vanished over the summit. Gregan followed, and he is there still, sitting beside a small deep pond at the top of the peak the beast climbed, telling the tale to anyone who makes the same ascent. From that height the whole of the surrounding land can be seen spread out below, and the little pond yields fish to anyone patient enough to try.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Verdantis River",
			short = "The Verdantis River winds through central Feralas, southeast of Dire Maul, its waters cutting a quiet path through the wilds. Nowhere else in the world does the Feralas Ahi swim.",
			full = "The Verdantis River winds through central Feralas, southeast of Dire Maul, its waters cutting a quiet path through the wilds. Nowhere else in the world does the Feralas Ahi swim.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Wildwind Lake",
			short = "The waters of Wildwind Lake lie near Camp Mojache in Feralas, quiet and undisturbed, holding no history beyond the stillness of their own surface.",
			full = "The waters of Wildwind Lake lie near Camp Mojache in Feralas, quiet and undisturbed, holding no history beyond the stillness of their own surface.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Woodpaw Den",
			short = "The gnolls of the Woodpaw tribe have made their den here, ruled over by their alphas. South of it lie the Darkmist Ruins.",
			full = "The gnolls of the Woodpaw tribe have made their den here, ruled over by their alphas. South of it lie the Darkmist Ruins.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Woodpaw Hills",
			short = "The Woodpaw gnolls have long ruled these wooded hills from open camps, their alphas holding court in sight of all. That rule has narrowed.",
			full = "The Woodpaw gnolls have long ruled these wooded hills from open camps, their alphas holding court in sight of all. That rule has narrowed. In the southeasternmost reaches the ground has torn open into what is called the Writhing Deep, and swarming things bursting up from below have driven the clan back. The alphas can now be found only deep within the Woodpaw Den.\n\nMountain giants have also come down into the hills, and unlike the cliff giants to the west, they hold no goodwill toward the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Writhing Deep",
			short = "Beneath the Writhing Deep in southeastern Feralas, the silithid of Hive Zukk'ash burrow and breed. Their presence alone has driven nearby gnolls into a frenzy that sent them north against Camp Mojache.",
			full = "Beneath the Writhing Deep in southeastern Feralas, the silithid of Hive Zukk'ash burrow and breed. Their presence alone has driven nearby gnolls into a frenzy that sent them north against Camp Mojache.\n\nWarriors from the camp cut down the silithid at the surface, but the hive's eggs lie protected below, countless and undisturbed. Rexxar has warned that it is only a matter of time before the next generation hatches.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Dustwallow Marsh: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Alcaz Island",
			short = "Alcaz Island rises green and strange off Dustwallow Marsh, its tropical growth out of place beside the marsh's grey reeds, more kin to the Echo Isles than to anything around it.",
			full = "Alcaz Island rises green and strange off Dustwallow Marsh, its tropical growth out of place beside the marsh's grey reeds, more kin to the Echo Isles than to anything around it. Once the Strashaz naga held it. What walks there now are gnomes raised into undeath, servants of a mind called Doctor Weavil.\n\nThe island's darkest hour came years after the Third War, when King Varian Wrynn, travelling to Theramore for a diplomatic meeting, was seized by the Defias Brotherhood and brought here in chains. The black dragon Onyxia came to work a ritual upon him, meaning to sunder his spirit in two, tearing away his will and strength so that the strong-willed part of him, the one who would come to be called Lo'Gosh, might be destroyed, leaving only a hollow king behind for the Defias and their dragon mistress to command. The ritual was nearly finished when Morgala Darksquall arrived with her own naga and fell upon Onyxia's dragonspawn. In the chaos, Lo'Gosh was struck from a cliff into the sea and taken by the naga, while Onyxia, believing him slain, let the matter rest.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Beezil's Wreck",
			short = "A goblin zeppelin bound south with a shipment of supplies never finished its run.",
			full = "A goblin zeppelin bound south with a shipment of supplies never finished its run. It went down deep in Dustwallow Marsh, east of Tabetha's Farm, and its broken hull still lies there, cargo scattered through the wreckage, seaforium boosters still among it.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Bloodfen Burrow",
			short = "Bloodfen Burrow, in the marsh's southwest, holds a nest of Bloodfen raptors beyond ordinary numbers. Outside the cave mouth lie the remnants of a settlement, torn apart in their coming.",
			full = "Bloodfen Burrow, in the marsh's southwest, holds a nest of Bloodfen raptors beyond ordinary numbers. Outside the cave mouth lie the remnants of a settlement, torn apart in their coming. One part of Cortello's Riddle is hidden within.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Bluefen",
			short = "Bluefen lies between Brackenwall Village and Blackhoof Village, a stretch of marsh given over to spiders, birds, raptors, and crocolisks.",
			full = "Bluefen lies between Brackenwall Village and Blackhoof Village, a stretch of marsh given over to spiders, birds, raptors, and crocolisks. Theramore's infiltrators move through the reeds here as well, watching the ground between orc and tauren.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Brackenwall Village",
			short = "Brackenwall Village stands in the northwest of Dustwallow Marsh, a scatter of huts around an ogre mound, held by the Stonemaul.",
			full = "Brackenwall Village stands in the northwest of Dustwallow Marsh, a scatter of huts around an ogre mound, held by the Stonemaul.\n\nThey came here as refugees. The black dragonflight had burned Stonemaul Village to the south, and Overlord Mok'Morokk, who had taken up Rexxar's mantle, led what remained of his people north to build a new home. But when Draz'Zilb learned that Onyxia's brood had been responsible and brought the news to Mok'Morokk, the Overlord would not act. No black dragons dwelt at Brackenwall, and that was enough for him. Draz'Zilb would not let it rest there. He called on champions of the Horde to challenge Mok'Morokk directly, and when the Overlord was beaten, he fled into the marsh rather than face his own people again. Draz'Zilb declared the Stonemaul free to choose a leader who would fight to reclaim what they had lost, rather than settle for what remained.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Darkmist Cavern",
			short = "In the northwest reaches of Dustwallow Marsh, a small mine has passed entirely into the grip of spiders.",
			full = "In the northwest reaches of Dustwallow Marsh, a small mine has passed entirely into the grip of spiders. The Darkmist Spiders that fill its tunnels grow to a size that unsettles even those who have lived in the marsh all their lives, and no one can say for certain which came first, the cavern's name or the spiders' own. Outside the entrance stand the broken remains of small houses, the only sign that people once lived here before the webs took the place over.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Den of Flame",
			short = "The Den of Flame was raised by the Stonemaul ogres as their mound, its halls still bearing an ogre's hand in the stonework. Their banner yet stands within it, though the ogres are gone.",
			full = "The Den of Flame was raised by the Stonemaul ogres as their mound, its halls still bearing an ogre's hand in the stonework. Their banner yet stands within it, though the ogres are gone.\n\nBlack dragonkin hold the mound now, said to answer to Onyxia, the great black dragon who lairs nearby. Nothing remains of the Stonemaul but the walls and the banner they left behind.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "Dragonmurk",
			short = "The waters here run murky for a reason. Whelps and dragonspawn of the black flight breed thick through this stretch of the marsh, so numerous that the mire itself bears their name.",
			full = "The waters here run murky for a reason. Whelps and dragonspawn of the black flight breed thick through this stretch of the marsh, so numerous that the mire itself bears their name. The Den of Flame and Stonemaul Ruins nearby swarm with the same black-scaled brood.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Dreadmurk Shore",
			short = "The coastline and islands between Theramore Isle and Northwatch Hold take their name from what breeds along them: the Mirefin, a murloc tribe that claims this shore.",
			full = "The coastline and islands between Theramore Isle and Northwatch Hold take their name from what breeds along them: the Mirefin, a murloc tribe that claims this shore. Sea turtles and other creatures share the murky waters that lap against the beach and scattered islands.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Dustwallow Bay",
			short = "The waters west of Theramore Isle spread into Dustwallow Bay, where the marsh meets the Great Sea.",
			full = "The waters west of Theramore Isle spread into Dustwallow Bay, where the marsh meets the Great Sea. On a small island in Tidefury Cove sits Nat Pagle, a fisherman known well beyond these shores, content to cast his line where the bay's currents run quiet.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Emberstrife's Den",
			short = "Emberstrife's Den is a wide cave in Wyrmbog, southern Dustwallow Marsh.",
			full = "Emberstrife's Den is a wide cave in Wyrmbog, southern Dustwallow Marsh. Here the black drake Emberstrife tests young dragonlings, putting them through trials only the worthy survive, for only those who pass may enter Onyxia's Lair.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Foothold Citadel",
			short = "Foothold Citadel served as headquarters of the Theramore Guard, holding the island's soldiers under the Alliance banner.",
			full = "Foothold Citadel served as headquarters of the Theramore Guard, holding the island's soldiers under the Alliance banner.\n\nHere Daelin Proudmoore met his end, cut down when Thrall's forces stormed Theramore, led into the keep by Rexxar and his companions.\n\nYears later, the citadel was destroyed along with the rest of Theramore.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Lost Point",
			short = "Lost Point was raised as a scout tower by Theramore, now rotting in the marsh damp and held by deserters from that same city.",
			full = "Lost Point was raised as a scout tower by Theramore, now rotting in the marsh damp and held by deserters from that same city. Their leader, Balos Jacken, knows what became of Private Hendel, a man bound up in the kidnapping of someone of great importance to Theramore.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "North Point Tower",
			short = "North Point Tower stands at the northern edge of Dustwallow Marsh, raised by Theramore beside a well-traveled road. With deserters having seized Lost Point, it is now the farthest-flung of Theramore's outposts.",
			full = "North Point Tower stands at the northern edge of Dustwallow Marsh, raised by Theramore beside a well-traveled road. With deserters having seized Lost Point, it is now the farthest-flung of Theramore's outposts.\n\nTheramore Guards hold a blood elf prisoner here. In Brackenwall Village, a friend of hers begs any who pass to see her freed.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Onyxia's Lair",
			short = "Beneath the Dragonmurk, that dismal swamp within Dustwallow Marsh, the ground itself was carved into a mouth.",
			full = "Beneath the Dragonmurk, that dismal swamp within Dustwallow Marsh, the ground itself was carved into a mouth. Onyxia built her lair to resemble her own maw, its inner path lined with magma, the stone ceiling groaning and dropping rubble, the walls weeping fire where the heat cannot be held back.\n\nUnlike her kin, who favor brute force or twisted creation, Onyxia worked through charm. For years she moved through Stormwind's court under a stolen name, Katrana Prestor, bending the city's politics toward her own ends, until she was unmasked and fled back to this cave beneath the swamp.\n\nShe did not flee into safety. After she took Prince Anduin, King Varian Wrynn led an assault into the lair itself. In the fight that followed, an errant burst of her own magic undid the sorcery that had split him in two, making him whole again even as her whelps tore through the fighters at his side. Varian struck the killing blow himself, beheading her, and her head was carried back to hang from Stormwind's gates.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "Quagmire",
			short = "The Quagmire is the sodden heart of Dustwallow Marsh, stretching from Lost Point to Dustwallow Bay, and from Brackenwall Village down to the Dragonmurk.",
			full = "The Quagmire is the sodden heart of Dustwallow Marsh, stretching from Lost Point to Dustwallow Bay, and from Brackenwall Village down to the Dragonmurk.\n\nCrocolisks lurk in its black water, oozes creep through the reeds, and spiders web the twisted trees. Grimtotem tauren move through the bog as well.\n\nAmid the muck stand a few footholds: Beezil's Wreck, Direhorn Post, and Tabetha's Farm.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Sentry Point",
			short = "Sentry Point stands just across the bridge from Theramore, a scout tower raised to watch the road for anyone approaching the citadel.",
			full = "Sentry Point stands just across the bridge from Theramore, a scout tower raised to watch the road for anyone approaching the citadel.\n\nThe tower has not always stood quietly. Elementals sent by Cho'gall once fell upon it, testing the outpost's watch. It held.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Shady Rest Inn",
			short = "The Shady Rest Inn once stood near the border between Dustwallow Marsh and the Southern Barrens, a waystop built by human hands.",
			full = "The Shady Rest Inn once stood near the border between Dustwallow Marsh and the Southern Barrens, a waystop built by human hands.\n\nIt burned some time ago, and the fire took more than timber. James Hyal, who kept the inn, lost his wife and child in the blaze, and the man who survived it was never the same after.\n\nThe truth of who set the fire stayed buried for years, until it came out that the Grimtotem tauren were behind the burning.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Stonemaul Ruins",
			short = "Once these stones rang with the voice of Kor'gall, who took up the ancient orcish axe Serathil and made himself warlord of the Stonemaul by cruelty alone.",
			full = "Once these stones rang with the voice of Kor'gall, who took up the ancient orcish axe Serathil and made himself warlord of the Stonemaul by cruelty alone. He ruled so harshly that an ogre named Crol'ka, whose brothers Kor'gall had killed, fled the village half-dead rather than stay beneath him. It was Crol'ka's warning that first brought Rexxar to this place. Refused entry, Rexxar and his companions fought their way in; Kor'gall, grudgingly impressed, offered him a trial instead of a grave, a valley thick with killing beasts. Rexxar endured it and was named clan. When Kor'gall later refused to answer the Horde's call, Rexxar challenged him for the axe and the clan both, killed him, and led the Stonemaul to war.\n\nRexxar did not stay to rule. He gave the village to Mok'Morokk and departed, and Mok'Morokk let power spoil him. When Onyxia's brood descended and seized the village for their own, it was Mok'Morokk who led the survivors away, content to stay far from the black dragonflight while the ruin of his people's home became a breeding ground for dragonspawn.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Swamplight Manor",
			short = "Swamplight Manor sits on Witch Hill, home to \"Swamp Eye\" Jarl, a cook whose reputation has spread well beyond the marsh.",
			full = "Swamplight Manor sits on Witch Hill, home to \"Swamp Eye\" Jarl, a cook whose reputation has spread well beyond the marsh.\n\nIn the small garden outside, a pile of turned dirt marks where an orcish spy once buried a report, still hidden beneath the soil.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Theramore Isle",
			short = "Theramore Isle (a.k.a. Theramore Keep, Theramore City or simply Theramore) was a human city and port town located in a rocky island east of Dustwallow Marsh, as well as the capital of the eponymous city-state/kingdom.",
			full = "Theramore Isle (a.k.a. Theramore Keep, Theramore City or simply Theramore) was a human city and port town located in a rocky island east of Dustwallow Marsh, as well as the capital of the eponymous city-state/kingdom. Before its destruction, it was considered the Alliance's most martial presence in Kalimdor. Since its destruction, it is simply known as the Ruins of Theramore.\n\nThe bronze dragon Zidormi allows adventurers to see how the area appeared in the past and return to the present when asked. Dustwallow Marsh quests are still doable in the past Theramore. A mage with sufficient skill can use teleport and open portals into this city, although they will now be teleported midair over the crater where Jaina's mage tower once stood.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Tidefury Cove",
			short = "Tidefury Cove is thick with small islands and hidden reefs, water that ends voyages rather than merely testing them.",
			full = "Tidefury Cove is thick with small islands and hidden reefs, water that ends voyages rather than merely testing them. Two ships found that out the hard way, and their broken hulls still lie in the shallows, picked over now by roaming makrura.\n\nNot everyone here has met that fate. The fisherman Nat Pagle settled on one of the cove's islets, since called Nat's Landing.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Witch Hill",
			short = "Swamplight Manor stands at the heart of Witch Hill, home to Swamp Eye Jarl, and around it the Mirefin murlocs keep their camps among the wet ground.",
			full = "Swamplight Manor stands at the heart of Witch Hill, home to Swamp Eye Jarl, and around it the Mirefin murlocs keep their camps among the wet ground. But it is the hill's other tenant that gives the place its name: the demon Zelfrax haunts these grounds, and none who pass through forget it.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Wyrmbog",
			short = "The mire south of the Dragonmurk earns its name honestly: black dragons make their home in its murky waters, drawn to its hidden places.",
			full = "The mire south of the Dragonmurk earns its name honestly: black dragons make their home in its murky waters, drawn to its hidden places. Emberstrife lairs within the bog itself, and Onyxia's own den opens somewhere beneath its surface, sealed away from the marsh above.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Abyssal Sands",
			short = "The Abyssal Sands lie within the desert of Tanaris, a stretch of sand claimed for a time by the Burning Legion during its invasion.",
			full = "The Abyssal Sands lie within the desert of Tanaris, a stretch of sand claimed for a time by the Burning Legion during its invasion.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Broken Pillar",
			short = "Amid the ruins south of Gadgetzan, where broken troll stonework rises from the sand, Marvon Rivetseeker made his camp.",
			full = "Amid the ruins south of Gadgetzan, where broken troll stonework rises from the sand, Marvon Rivetseeker made his camp. The goblin scientist from Ratchet came seeking answers in the old carvings, and whatever he found there became fodder for study among later scholars who came only to examine what he had already examined.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Caverns of Time",
			short = "In the eastern reaches of Tanaris, a labyrinth winds down into the dark, and at its heart burns a great hourglass.",
			full = "In the eastern reaches of Tanaris, a labyrinth winds down into the dark, and at its heart burns a great hourglass. This is the lair of Nozdormu, the Dragon Aspect of Time, and the home of the bronze dragonflight he leads. Since the world was young the bronze dragons have kept this place sealed against mortal hands, for the titans charged them with a sacred duty: to guard the crossroads of the timeways, where every branching path of what-might-have-been forks away from the one true history. A single mortal footstep in the wrong moment of the past could unmake everything that followed, and so the dragons watch, and do not let anyone pass unchallenged.\n\nEven a guardian of time can be caught unaware. Nozdormu once awoke sensing a threat to the timeways he loved, and gathered heroes to his side to face it. While they meditated together in the caverns, an agent struck, killing Desharin where he sat. In the chaos, a bronze dragon flung Thrall bodily into one of the portals, casting him back along the corridors of history in a desperate journey that ended, at last, in Nozdormu's release.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Dunemaul Compound",
			short = "Sandscraper rules the Dunemaul ogres from his cave in the compound, the mound of stone and packed earth that gives the clan its ground.",
			full = "Sandscraper rules the Dunemaul ogres from his cave in the compound, the mound of stone and packed earth that gives the clan its ground. East of the compound, Megs Dreadshredder works to bend these ogres to the Horde's purpose, trying to talk them into service where strength alone has failed.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Eastmoon Ruins",
			short = "Stone terraces and broken columns rise west of the Gaping Chasm, all that remains of a troll settlement long since abandoned to the sands of Tanaris.",
			full = "Stone terraces and broken columns rise west of the Gaping Chasm, all that remains of a troll settlement long since abandoned to the sands of Tanaris. The Dunemaul ogres claimed the ruins first, squatting among the fallen pillars until the Wastewanders drove them out and took the stones for their own.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Gadgetzan rises out of the northern Tanaris desert under its own perpetual haze of black fumes, capital of the Steamwheedle Cartel, the largest of the goblin trading concerns.",
			full = "Gadgetzan rises out of the northern Tanaris desert under its own perpetual haze of black fumes, capital of the Steamwheedle Cartel, the largest of the goblin trading concerns. Here profit outranks loyalty, and that simple creed has made the city neutral ground in every quarrel between Horde and Alliance. Both governments recognize the arrangement, and goblin bruisers patrol the streets to see that anyone forgetting it is reminded with fists. Whoever carries a fat purse or has something to sell is welcome, whatever banner they fought under yesterday.\n\nThat neutrality was tested from outside more than once. The Wastewander bandits held the Waterspring Field and the Noonshade Ruins to the northeast, and while the goblins cared nothing for old ruins, the water field was another matter. The towers standing there, raised and tended by the Gadgetzan Water Company against the desert sun, supplied the liquid gold that let the city survive at all, and the goblins were not willing to lose them. Mercenaries from every corner of the world were drawn in to break the bandits' hold and keep the towers running.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Gaping Chasm",
			short = "The Gaping Chasm cuts into the ground of southeastern Tanaris, its walls riddled with hive tunnels where the Hazzali silithid swarm without end.",
			full = "The Gaping Chasm cuts into the ground of southeastern Tanaris, its walls riddled with hive tunnels where the Hazzali silithid swarm without end.\n\nSenior Surveyor Fizzledowser once sent a junior surveyor named Scrimshank down into the chasm to look it over. Scrimshank never came back. He died among the tunnels, and only later was his gear recovered and carried back to Fizzledowser, the man who had sent him.\n\nLater, goblins pitched the Bootlegger Outpost nearby, reckoning there was coin to be made off the silithid. Zeke Bootscuff ran the operation, and the chasm was not kind to his workers, several of whom ended up cocooned by the bugs before being cut free. Zeke never found his angle on the silithid, and in the end he gave up trying to exploit the chasm and simply had it blown apart instead.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Land's End Beach",
			short = "A ship out of Bilgewater ran aground on this stretch of coast, its crew bound for Durotar or Gadgetzan and never arriving at either.",
			full = "A ship out of Bilgewater ran aground on this stretch of coast, its crew bound for Durotar or Gadgetzan and never arriving at either. The survivors who dragged themselves ashore never learned they had washed up on Kalimdor at all. They took the beach for an uncharted island, cut off from everything they knew.\n\nNot long after the wreck, the survivors turned up a titan artifact half-buried in the sand, its light doing something to their minds. One by one they slid into delusion, then violence. When Gadgetzan sent goblins out in flying machines to bring them home, the survivors met them with the same madness they now turn on anyone who comes near, and killed their rescuers where they stood.\n\nThey never stopped. The Crazed Bilgewater Survivors still hold the beach, some among the wreckage at the waterline, others in a camp near the mountains. Their leader, a wreck of a man called Meatface, keeps the artifact locked in a chest beside the graveyard where the crew buries its own dead.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Lost Rigger Cove",
			short = "Hidden behind mountains on three sides, Lost Rigger Cove shelters the Southsea Pirates from the sands of Tanaris. A shipyard here has a new vessel under construction.",
			full = "Hidden behind mountains on three sides, Lost Rigger Cove shelters the Southsea Pirates from the sands of Tanaris. A shipyard here has a new vessel under construction.\n\nGnome and goblin speakers, seeking a deal with the baron of Gadgetzan, have camped outside the cove and turned to killing pirates to force it.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Noonshade Ruins",
			short = "The Noonshade Ruins lie east of Gadgetzan, half-buried in the sand of northeastern Tanaris. What stands there now is troll work, old beyond memory of the desert that has since swallowed it, silent stone left to the sun.",
			full = "The Noonshade Ruins lie east of Gadgetzan, half-buried in the sand of northeastern Tanaris. What stands there now is troll work, old beyond memory of the desert that has since swallowed it, silent stone left to the sun.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Noxious Lair",
			short = "The land here remembers water.",
			full = "The land here remembers water. The Noxious Lair, known also as the Centipaar Hive, sits sunken into the earth of southwestern Tanaris, its floor bowed in the shape of some broad river or shallow lake long since gone dry, still looking out over Un'Goro Crater as if waiting for the water to return.\n\nIt will not. The silithid came instead, digging down where the lake once stood, and Tanaris was left drier for it. Above ground, half-buried shapes still stir in the sand, great claws twitching up out of the earth, and around each one the soil is dark and wet with silithid goo, the only moisture left in a place that once held a river.\n\nBelow the surface the lair opens into tunnels coated in acid and studded with unborn insects waiting in the dark.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Sandsorrow Watch",
			short = "Sandsorrow Watch spreads west of Gadgetzan across the dunes of Tanaris, claimed by the Farraki tribe and the shambling dead they have raised among their own ranks.",
			full = "Sandsorrow Watch spreads west of Gadgetzan across the dunes of Tanaris, claimed by the Farraki tribe and the shambling dead they have raised among their own ranks.\n\nAt the eastern edge stands a watch tower, wrested from the Farraki and held now by Trenton Lighthammer's small camp, neutral ground amid the troll-haunted sand. Trenton keeps his people supplied out here, far from any real support, and his camp has caged a Sandfury Blood Drinker and a Sandfury Zombie, prisoners pulled from the tribe that surrounds them. They were not taken for cruelty's sake. Trenton had them held so they could be questioned, pressed for what they knew of the legend of Sul'thraze, a name the Farraki did not give up easily.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Between the two great continents, where the waters of the Great Sea run deep and warm, lies the tangle of islands and reefs known as the South Seas.",
			full = "Between the two great continents, where the waters of the Great Sea run deep and warm, lies the tangle of islands and reefs known as the South Seas. Zandalar rises here, ancient seat of the trolls. Tel'Abim breaks the water further off. Kezan sits apart, its own scarred and smoking rock.\n\nThe coasts nearest the mainland are known better than the deep water beyond them. Stranglethorn Vale marks where the Eastern Kingdoms give way to this sea. To the west, Tanaris, the Thousand Needles, and Uldum stand where Kalimdor's shore meets the same waters.\n\nBeyond those known shores the South Seas keep their own geography of scattered, half-charted places: shallows and coves, sunken ruins, isles named for sailors and wrecks that found them and never came back to say more. Somewhere within this water, it is said, lies the Maelstrom itself, the great churning wound at the world's heart, though few who study the South Seas can say so with certainty.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Southbreak Shore",
			short = "Southbreak Shore lies quiet along the southern sands below Lost Rigger Cove, its flatness broken only by the northern stretch where Captain Dreadbeard holds command over his pirates.",
			full = "Southbreak Shore lies quiet along the southern sands below Lost Rigger Cove, its flatness broken only by the northern stretch where Captain Dreadbeard holds command over his pirates. He has drawn aid from sea giants, though none can say how.\n\nThe turtles and giants that once haunted the surf here have since moved on, leaving the beach to Duneshore Crabs, skittering alone across the sand.\n\nA small island sits just off the coast, home to a lone gnome named Winkey.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Southmoon Ruins",
			short = "Ancient troll stonework rises from the sands of southern Tanaris at the Southmoon Ruins. Among the broken columns, tablets were uncovered, said to hold Titan knowledge.",
			full = "Ancient troll stonework rises from the sands of southern Tanaris at the Southmoon Ruins. Among the broken columns, tablets were uncovered, said to hold Titan knowledge. Their meaning is contested: the Reliquary and the Explorers' League both claim the ruins, neither willing to let the other walk away with what the tablets reveal.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Steamwheedle Port",
			short = "Steamwheedle Port sits on the eastern coast of Tanaris, tied by road to Gadgetzan, its mother city, and by dock to ships from Kezan.",
			full = "Steamwheedle Port sits on the eastern coast of Tanaris, tied by road to Gadgetzan, its mother city, and by dock to ships from Kezan. It belongs to the neutral goblin Steamwheedle Cartel, who take no side in others' wars and profit from all of them.\n\nThe port has emptied. Many who lived here are gone or dead, killed by forces that broke the place, and others took the cartel's fee to relocate to Gadgetzan rather than stay.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Thistleshrub Valley",
			short = "Thistleshrub Valley once earned its name from the desert-dwelling thistleshrubs that grew thick across it.",
			full = "Thistleshrub Valley once earned its name from the desert-dwelling thistleshrubs that grew thick across it. Little of that remains now; where they stood, Desert Blooms grow only sparsely, and giant cacti stand improbably alive for such dry ground.\n\nHere Budd's gang gathers, with Adarrah leading the charge, preparing to lead a caravan onward into Uldum.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Uldum is an ancient desert located on the southern coast of Kalimdor, surrounded by the Un'Goro Crater in the north, Tanaris in the east and Silithus in the northwest.",
			full = "Uldum is an ancient desert located on the southern coast of Kalimdor, surrounded by the Un'Goro Crater in the north, Tanaris in the east and Silithus in the northwest. It is the homeland of stone-cat people known as tol'vir and is rich with titan lore.\n\nThere is no super weapon, however; Uldum is the weapon, intended to wipe out all life on Azeroth in case Algalon the Observer's Reply-Code Omega went through to the titans.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Valley of the Watchers",
			short = "The Valley of the Watchers held a gate once thought impenetrable, sealing the way into Uldum. The tunnel behind it has since collapsed, the passage to the Cursed Landing lost beneath stone.",
			full = "The Valley of the Watchers held a gate once thought impenetrable, sealing the way into Uldum. The tunnel behind it has since collapsed, the passage to the Cursed Landing lost beneath stone. Sandstone golems now rampage through the valley where the Dune Smasher giants once stood.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Waterspring Field",
			short = "The water towers of Waterspring Field rise from the Tanaris sand, drawing water up from reserves buried deep underground.",
			full = "The water towers of Waterspring Field rise from the Tanaris sand, drawing water up from reserves buried deep underground. The goblins of Gadgetzan built them, hoping to wring enough water from the desert to keep their operations running.\n\nThat hope did not survive the Wastewanders. The nomadic bandits swept in and claimed the field outright, seizing the towers the goblins had raised and squatting on the land ever since. They have taken worse quarters before, an ogre camp among them, and do not care to speak of it.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Wavestrider Beach",
			short = "The shoreline of Wavestrider Beach runs between Steamwheedle Port and Lost Rigger Cove along eastern Tanaris. Desert crawlers scuttle across its sands, and steeljaw snappers lurk along the waterline among them.",
			full = "The shoreline of Wavestrider Beach runs between Steamwheedle Port and Lost Rigger Cove along eastern Tanaris. Desert crawlers scuttle across its sands, and steeljaw snappers lurk along the waterline among them.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Zalashji's Den",
			short = "Zalashji's Den bears the name of the creature that once made its home there. Whether Zalashji still lives, or perished long ago, no one can say with certainty.",
			full = "Zalashji's Den bears the name of the creature that once made its home there. Whether Zalashji still lives, or perished long ago, no one can say with certainty. The den remains, empty of answers, holding only the silence of its absent namesake.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Once Zul'Farrak stood in a jungle, part of the wide Gurubashi Empire.",
			full = "Once Zul'Farrak stood in a jungle, part of the wide Gurubashi Empire. When the Great Sundering broke the land apart, the jungle burned away into the desert now called Tanaris, and the trolls stranded there changed with it, becoming the Farraki, the sand trolls of the Sandfury tribe. Zul'Farrak became their city of sun-blasted stone, ruled by ruthlessness and dark mysticism.\n\nDeep in the city, at its heart, lies a sacred pool, and the trolls whisper of something ancient sleeping beneath its surface -- a demigod whose waking would bring ruin on anyone careless enough to stir it. Elsewhere in the ruins is said to lie a weapon out of Sandfury legend: Sul'thraze the Lasher, a blade once able to fill even great foes with weakness and fear, long ago broken into two halves. Both pieces are rumored still to be somewhere within these walls.\n\nThose Sandfury who survived the city's long decline went on to join the Zandalari.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 26 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Bay of Storms",
			short = "The waters east of Azshara churn with a violence that gives the bay its name. Along its edge lie Scalebeard's Cave, Hetaera's Clutch, and the Temple of Arkkoran, half-drowned reminders of something older than the storms.",
			full = "The waters east of Azshara churn with a violence that gives the bay its name. Along its edge lie Scalebeard's Cave, Hetaera's Clutch, and the Temple of Arkkoran, half-drowned reminders of something older than the storms.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Bear's Head",
			short = "Bear's Head takes its name from the furbolg villages scattered across its slopes, small outposts answering to Timbermaw Hold and Ursolan to the north.",
			full = "Bear's Head takes its name from the furbolg villages scattered across its slopes, small outposts answering to Timbermaw Hold and Ursolan to the north.\n\nOn the cliffs above stands Xylem's Tower, home to Archmage Xylem and his apprentices, among them the high elves Joy Ar'nareth and Rayan Dawnrisen.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Bitter Reaches",
			short = "The Bitter Reaches, in northeastern Azshara, are wild country. Hippogryphs, oozes, and chimaerae fill its crags and hollows, while mountain giants have driven off other creatures along the northern edge.",
			full = "The Bitter Reaches, in northeastern Azshara, are wild country. Hippogryphs, oozes, and chimaerae fill its crags and hollows, while mountain giants have driven off other creatures along the northern edge. Mountain silversage grows here too, though sparsely.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["forlorn ridge"] = {
			name = "Forlorn Ridge",
			short = "Forlorn Ridge once rose over southwestern Azshara, high enough that both the Alliance and the Horde built fortifications on its slopes, watching each other across the stone.",
			full = "Forlorn Ridge once rose over southwestern Azshara, high enough that both the Alliance and the Horde built fortifications on its slopes, watching each other across the stone.\n\nThe mountain does not stand there now. The Bilgewater goblins tore it from its footing and moved the whole mass north, leaving behind the Mountainfoot Strip Mine, where digging woke basilisks nesting in the deep rock and turned them on the miners.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Haldarr Encampment",
			short = "The Haldarr Encampment lies in western Azshara, thick with the satyr who bear its name. Among them, Sentinel Keldara Sunblade was found injured and held captive within their grounds.",
			full = "The Haldarr Encampment lies in western Azshara, thick with the satyr who bear its name. Among them, Sentinel Keldara Sunblade was found injured and held captive within their grounds.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Hetaera's Clutch",
			short = "Beneath the Bay of Storms off Azshara lies the sunken temple of Elune called Hetaera's Clutch, home to hydras known as the children of Hetaera.",
			full = "Beneath the Bay of Storms off Azshara lies the sunken temple of Elune called Hetaera's Clutch, home to hydras known as the children of Hetaera. Hetaera herself swims the waters north of the temple, sometimes resting on a small island there.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Jagged Reef",
			short = "The northern coast of Azshara breaks into sand and jagged stone, its inlets hiding shallows and broken rock that tear open hulls and legs alike.",
			full = "The northern coast of Azshara breaks into sand and jagged stone, its inlets hiding shallows and broken rock that tear open hulls and legs alike. No path along it is safe.\n\nMurlocs keep the shallows, hydras coil through the inlets, makrura drag across the sand hunting food. The reef never belonged to anyone gentler than this.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lake Mennar",
			short = "The waters of Lake Mennar lie still and untroubled, a rare calm at the heart of ground the dragonspawn hold on every side.",
			full = "The waters of Lake Mennar lie still and untroubled, a rare calm at the heart of ground the dragonspawn hold on every side. To reach the shore is to pass through their ranks, but the lake itself harms no one who comes to it.\n\nIt was once known for its whelplings, young blue dragons gathered near its waters, a sight found almost nowhere else outside of Northrend save Mazthoril in Winterspring. They no longer come. When Azuregos departed the lake, the whelplings followed him north to Winterspring, leaving Lake Mennar to the dragonspawn and its silence.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Legash Encampment",
			short = "At the Legash Encampment, in northern Azshara, the Legashi satyr hold their ground.",
			full = "At the Legash Encampment, in northern Azshara, the Legashi satyr hold their ground.\n\nHere Archmage Xylem once found a grimoire, left among the satyr's holdings.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "Ravencrest Monument",
			short = "The Ravencrest Monument stands where Azshara's southern point breaks against the Great Sea, southeast of the Ruins of Eldarath.",
			full = "The Ravencrest Monument stands where Azshara's southern point breaks against the Great Sea, southeast of the Ruins of Eldarath. Torg Twocrush called what remains an ancient night elven colossus, though only the broken legs still stand upright on the cliffs. The rest of the great figure lies scattered across the ground, or has slipped into the water below, buried or sunk beneath the waves.\n\nThe Spitelash naga have taken the ruins for their own. No boat can reach the monument; the only way in is over land, across a single bridge, so that whoever comes to stand before the ruined colossus arrives as a landbound thing before something that once must have looked out over the sea as if it owned it.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Rethress Sanctum",
			short = "The shrine at Rethress Sanctum lies broken among the Ruined Reaches, its purpose long since abandoned. No priesthood remains to tend it, no order claims it.",
			full = "The shrine at Rethress Sanctum lies broken among the Ruined Reaches, its purpose long since abandoned. No priesthood remains to tend it, no order claims it. Only stray murlocs and makrura wander through its fallen stones now, indifferent to whatever it once meant.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Ruined Reaches",
			short = "The southern coast of Azshara breaks apart here into beach and cliff, cut by inlets where the water runs still over hidden shallows.",
			full = "The southern coast of Azshara breaks apart here into beach and cliff, cut by inlets where the water runs still over hidden shallows. Wreckage lies scattered along the shore, and the ruins that dot the coastline give the place its name. The waters are unkind, hiding shallows that can tear open a hull, and the shore itself is claimed by murlocs, hydras, and makrura, quick to violence toward anything that strays too close.\n\nOn the western shores, above the beach, a gnomish house stands on a hill, reachable only by a steep path from inland. Blimo Gadgetspring and Jubie Gadgetspring keep their home and trade here. Upstairs, in their bedroom, sits a third bed, kept and unexplained. No one knows whose it is, or who, if anyone, still sleeps in it.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Ruins of Eldarath",
			short = "Once Eldarath stood as one of the great strongholds of the night elves, before the world broke apart beneath it.",
			full = "Once Eldarath stood as one of the great strongholds of the night elves, before the world broke apart beneath it. Its mages were among the most powerful of the Highborne, and they carved their findings into runes and tablets and left them standing in the open places of the city, so that any who came after might ponder the nature of the arcane. Many of those tablets still stand among the stones.\n\nIt was here, during the War of the Ancients, that the Kaldorei Resistance met the Burning Legion in battle. Jarod Shadowsong and Huln Highmountain stood against Tichondrius himself upon this ground. When the Great Sundering came, it tore the world apart, and most of Eldarath crumbled away into the Bay of Storms below, leaving only a cluster of ruins clinging to the eastern cliffs.\n\nNight elves have long shunned that remnant. Naga claimed it instead, ruling what was left of the city from the Temple of Zin-Malor.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Scalebeard's Cave",
			short = "On a small island in the western Bay of Storms sits a bare cave, home to Scalebeard, a great and rare turtle. He is seldom found within it, favoring the hunt out in the Great Sea over the shelter of his own den.",
			full = "On a small island in the western Bay of Storms sits a bare cave, home to Scalebeard, a great and rare turtle. He is seldom found within it, favoring the hunt out in the Great Sea over the shelter of his own den.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Shadowsong Shrine",
			short = "A hill of broken stone stands in western Azshara, its slopes thick with old ruin. The highborne who once walked here have not left.",
			full = "A hill of broken stone stands in western Azshara, its slopes thick with old ruin. The highborne who once walked here have not left. Their ghosts still wander the shrine and the land around it, hungry to snuff out any living thing that trespasses.\n\nThe hill bears the name Shadowsong, shared by Jarod Shadowsong, who led the resistance in the War of the Ancients, and his elder sister Maiev, the warden who caged Illidan Stormrage after his betrayal at Mount Hyjal. What binds either of them to this ruined place, no one now can say.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "Shattered Strand",
			short = "The Shattered Strand runs along the north side of the Bay of Storms, thick with hydras, sea giants, makrura, and murlocs.",
			full = "The Shattered Strand runs along the north side of the Bay of Storms, thick with hydras, sea giants, makrura, and murlocs. Two remnants of older builders rise above the sand: the Temple of Arkkoran and the Tower of Eldara.\n\nWhen the Burning Legion's invasion swept through, the strand fell under demonic control. Naga died on that sand as Horde troops pressed their battle against the Legion along the shore.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape.",
			full = "The Southfury River rises high on Mount Hyjal, spilling from a mountain lake into a cascade of waterfalls before widening into the swift, churning water that gives the land below its shape. It marks the boundary between Ashenvale and Azshara to the north, and further south divides the Northern Barrens from Durotar, before finally pouring itself into the Great Sea in one last waterfall near the goblin port of Ratchet.\n\nThree bridges cross it: one linking Azshara to Ashenvale, one carrying travelers into Orgrimmar itself, and one joining Durotar to the Northern Barrens. Just north of the western bridge into the orc capital, there is a single point where four lands touch at once, the water running between them all.\n\nAt the river's mouth, a goblin named Horton Hornblower keeps a riverboat tied at his dock, ferrying those who need passage upstream toward the Barrens.\n\nThe river still runs strong enough to water the fields along its banks, but its water can no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Southridge Beach",
			short = "Ruins litter this beach, all that remains of the once-great city of Eldarath.",
			full = "Ruins litter this beach, all that remains of the once-great city of Eldarath. Naga hold the sands in great numbers now, sharing the shallows with makrura, hydras, and murlocs, while sea giants sometimes wade among the wreckage.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Storm Cliffs",
			short = "The cliffs rise east of the terminus, claimed by the coiling Spitelash naga. At their far eastern edge stands the Ravencrest Monument, a lone marker watching over the stone long after those who raised it are gone.",
			full = "The cliffs rise east of the terminus, claimed by the coiling Spitelash naga. At their far eastern edge stands the Ravencrest Monument, a lone marker watching over the stone long after those who raised it are gone.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Talrendis Point",
			short = "Talrendis Point stands where a small night elven encampment once watched the border with Ashenvale, its two guard towers rising over ground that once held the Shadowsong Shrine, its moonwell kept in the southern reach of the camp.",
			full = "Talrendis Point stands where a small night elven encampment once watched the border with Ashenvale, its two guard towers rising over ground that once held the Shadowsong Shrine, its moonwell kept in the southern reach of the camp.\n\nThe Point grew into something more than a border watch through years of raiding back and forth with the forces massed at Valormok. It became the last defense the Alliance held at Ashenvale's very doorstep, and so it was struck at directly. Warriors out of Valormok fell upon the camp, cut down its guards, struck at its leadership, and tried to lay explosives in both guard towers and the command center, meaning to end it outright.\n\nIt did not end. Chawg, one of the orcish liaisons working with the goblins in the area, reported afterward that pockets of resistance still held around Valormok, but read the fighting there for what it was: a rearguard action covering a full retreat back into Ashenvale. The border had held.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Temple of Arkkoran",
			short = "The Temple of Arkkoran once belonged to Elune, standing on the northeastern shores of Azshara where the Shattered Strand meets the sea.",
			full = "The Temple of Arkkoran once belonged to Elune, standing on the northeastern shores of Azshara where the Shattered Strand meets the sea. Whatever worship was once carried out within its walls has long since been overtaken. The sea giant Arkkoroc now holds the temple's highest level as his own, and murlocs and makrura keep watch below him, falling on anything that draws near.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Temple of Zin-Malor",
			short = "The Temple of Zin-Malor rises among the Ruins of Eldarath, its lines echoing the nearby Temple of Arkkoran and, more distantly, the Temple of the Moon in Darnassus.",
			full = "The Temple of Zin-Malor rises among the Ruins of Eldarath, its lines echoing the nearby Temple of Arkkoran and, more distantly, the Temple of the Moon in Darnassus. Once it was a place of worship to Elune, and it held the Crystal of Zin-Malor, a gift to the Highborne that was itself a message: that they had no need of arcane magic at all.\n\nWhat holiness the temple once held has long since been overtaken. The Spitelash tribe of naga now occupy its halls, and Warlord Krellian has made it his own, claiming for himself the place of honor once kept for the goddess.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Thalassian Base Camp",
			short = "The hill of the Thalassian Base Camp rises among a scatter of small camps, held by blood elves under Magus Rimtori.",
			full = "The hill of the Thalassian Base Camp rises among a scatter of small camps, held by blood elves under Magus Rimtori. She had struck a bargain with the Horde, promising a share of whatever her expedition unearthed in exchange for coin and protection, then took what was given and gave nothing back. Word of the betrayal spread until it demanded answer in blood.\n\nWhile Rimtori herself ranged across Azshara under the watch of her bodyguards, the camp was left in the charge of Magister Hawkhelm. But the expedition's true purpose was not hidden so well as its leader might have wished. Upon one of the ridges above the camp lies a Kaldorei Tome of Summoning, a relic capable of calling demons into the world, and its presence there speaks plainly of what the blood elves were truly after beneath the pretense of exploration.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "Tower of Eldara",
			short = "The Tower of Eldara stands on the tip of land northeast of the Bay of Storms, a remnant of the night elven civilization that once spread across Azshara.",
			full = "The Tower of Eldara stands on the tip of land northeast of the Bay of Storms, a remnant of the night elven civilization that once spread across Azshara. Its beaches are patrolled by murlocs, makrura, and hydras.\n\nThe tower itself remains sealed. During the third invasion of the Burning Legion, one called Phloem sought to open it, but failed.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Ursolan takes its name from Ursol, the bear demigod the furbolgs of Kalimdor hold in reverence. A deep scar cuts through the middle of the land, and Talrendis Biologists work within it.",
			full = "Ursolan takes its name from Ursol, the bear demigod the furbolgs of Kalimdor hold in reverence. A deep scar cuts through the middle of the land, and Talrendis Biologists work within it. Around that scar spreads an extensive settlement of the Timbermaw furbolg, their holdings running south through the Hold as far as Bear's Head.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "The camp that once stood to the northwest was called Valormok too, in its first days, and it was a hard place even by the standards of Azshara.",
			full = "The camp that once stood to the northwest was called Valormok too, in its first days, and it was a hard place even by the standards of Azshara. Belgrom Rockmaul had sent the blood elf Magus Rimtori there with warriors of her own, to hunt down riches and artifacts said to lie in the region. She found them, and decided to keep them. Rimtori turned on the orcs who marched with her and slaughtered them for what they carried. Ag'tor Bloodfist, who led the camp, would not let the betrayal stand. War was made on the elves quartered at the nearby Thalassian camp, and Rimtori was hunted down and killed for what she had done to Rockmaul's warriors and his pride.\n\nThat old camp is mostly emptied now. Its warriors went back to Orgrimmar or followed Ag'tor to the city's new rear gate, and only Kroum remains of the original garrison. Chawg commands what stands in Ag'tor's place, a new outpost built up with goblin barricades, a bomb wagon, and grunts enough to hold the line. The Horde needs this ground cleared to open the way toward Ashenvale, and that means driving the night elves from Talrendis Point. The elves have not let this pass quietly.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Felwood: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Bloodvenom Falls",
			short = "The waters fall dark and fouled, corrupted at their source high in Felwood.",
			full = "The waters fall dark and fouled, corrupted at their source high in Felwood. From this poisoned height the Bloodvenom River is born, carrying the taint down through the mountains until it becomes the Wildbend River in Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Bloodvenom Post",
			short = "Bloodvenom Post stands on the high cliffs above Darkshore, where the Bloodvenom River cuts through Felwood. The stonework is tauren, and tauren guards once held it, a small Horde foothold set against the poisoned woods.",
			full = "Bloodvenom Post stands on the high cliffs above Darkshore, where the Bloodvenom River cuts through Felwood. The stonework is tauren, and tauren guards once held it, a small Horde foothold set against the poisoned woods.\n\nIt did not fall to axe or fire. Winna Hazzard came instead, with her slime experiments, and corrupted the garrison stationed there, twisting them into Bloodvenom Slimeslaves, servants of the very filth they had been posted to guard against.\n\nThe old architecture is gone now, replaced by something Hazzard's work reshaped in its own image. No one has taken the post back. It remains lost, a dark trail winding around the hillside to a place still held by what corrupted it.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Bloodvenom River",
			short = "The Bloodvenom River cuts through the heart of Felwood, its waters fouled by corruption that spreads on into Darkshore as the Wildbend River.",
			full = "The Bloodvenom River cuts through the heart of Felwood, its waters fouled by corruption that spreads on into Darkshore as the Wildbend River. Oozes and twisted wildlife crawl its banks. Nothing wholesome swims here, and nothing sane drinks from it.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Deadwood Village",
			short = "Deadwood Village stands behind walls of thick timber, its huts sturdier than most furbolg dwellings.",
			full = "Deadwood Village stands behind walls of thick timber, its huts sturdier than most furbolg dwellings. Corruption has taken the Deadwood tribe as it has taken so much of Felwood, and the furbolgs within answer any approach with hostility now.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Emerald Sanctuary",
			short = "At Emerald Sanctuary, in southeastern Felwood, the Emerald Circle keeps its watch.",
			full = "At Emerald Sanctuary, in southeastern Felwood, the Emerald Circle keeps its watch. The druids gathered here have turned their attention to Jaedenar, tracing the corruption that seeps from it and working to snuff it out before it spreads further through the tainted forest.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Felpaw Village",
			short = "The furbolgs of Felpaw Village once belonged to the Deadwood tribe.",
			full = "The furbolgs of Felpaw Village once belonged to the Deadwood tribe. Corruption took them, as it took much of Felwood itself, and the village standing near the entrance of Timbermaw Hold now shelters a people twisted from what they were.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Irontree Cavern",
			short = "Deep within Irontree Cavern the Warpwood dwell, shredders and moss flayers alike, their roots grown twisted and strange in the dark below the trees that give the place its name.",
			full = "Deep within Irontree Cavern the Warpwood dwell, shredders and moss flayers alike, their roots grown twisted and strange in the dark below the trees that give the place its name.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Irontree Woods",
			short = "The Irontree Woods once opened green and quiet in northern Felwood, before the taint of the Burning Legion crept through and blackened it.",
			full = "The Irontree Woods once opened green and quiet in northern Felwood, before the taint of the Burning Legion crept through and blackened it. Three of the great Ancients that stood here, Hastat, Stoma, and Vartrus, living trees grown wise with age, were turned to stone by the corruption. They remain entombed still, dead but unmoving, grey shapes among the poisoned undergrowth.\n\nYet the ground has not given up entirely. Where moonwell water was once poured between the petrified Ancients, a seedling took root. Tended a while, it blossomed, and when grown it returned to the place of its birth, to the ring of stone giants, where it remains small yet among the ruin of its elders, waiting to one day take their place.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Jadefire Glen",
			short = "In the corrupted woods of southern Felwood, the satyrs have made their camp at Jadefire Glen.",
			full = "In the corrupted woods of southern Felwood, the satyrs have made their camp at Jadefire Glen. Their presence marks the taint that runs through the whole forest, the corruption showing itself in the twisted creatures gathered there.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Jadefire Run",
			short = "In northern Felwood, Jadefire Run shelters the most powerful satyrs in the region, their camp built with a demonic architecture unlike anything of the night elves.",
			full = "In northern Felwood, Jadefire Run shelters the most powerful satyrs in the region, their camp built with a demonic architecture unlike anything of the night elves. The demon hunter Feronas Sindweller believed even the healers there were no healers at all, but demons hiding in disguise.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar rises from ground that was never meant for it. Beneath the black stone and demonic braziers lie ancient night elf ruins and two druidic barrow dens, holy ground once.",
			full = "Jaedenar rises from ground that was never meant for it. Beneath the black stone and demonic braziers lie ancient night elf ruins and two druidic barrow dens, holy ground once. The Shadow Council seized the site after the Third War, naming it in worship of Kil'jaeden, and raised the Shadow Hold and the Shrine of the Deceiver over the old dens. Lord Banehollow ruled it, his ranks orc and Forsaken warlocks bound alongside succubi, felhunters, felguards, and satyrs.\n\nThe druids of the Emerald Circle could not let it stand. Demonic braziers threw up wards around Shadow Hold that no blade could pass, so the druids turned to purified moonwell water to douse them. Only then could they breach the hold, and there Shadow Lord Fel'dan and Banehollow himself were struck down, the druids meaning to reclaim the barrow den beneath the ruin once the last cultists were driven out.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Long before the Great Sundering broke the world apart, Morlos'Aran was one of the night elves' great settlements, a place of the golden age before the seas rose.",
			full = "Long before the Great Sundering broke the world apart, Morlos'Aran was one of the night elves' great settlements, a place of the golden age before the seas rose. Now, at the southern edge of Felwood, only ruin remains, one among several such ruins scattered across the world, each a reminder of that lost age.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruins of Constellas",
			short = "Broken columns and a corrupted moonwell are all that remain of Constellas, once a night elven settlement in the shadow of Mount Hyjal.",
			full = "Broken columns and a corrupted moonwell are all that remain of Constellas, once a night elven settlement in the shadow of Mount Hyjal. The moonwell, foul now with fel energy, is tended by Xavathras and his Jadefire satyr on behalf of Xavaric, who cultivate its corruption where starlight once gathered. A wall of fire bars the way to Xavathras himself, guarding the heart of the ruins.\n\nThe corruption has not gone unanswered. Emerald Bearkin, druids turned to bear-shape, fall upon the demons that hold Constellas, fighting to reclaim ground that was once night elven soil.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Shadow Hold",
			short = "Beneath Jaedenar in western Felwood runs a warren the night elves once raised as a barrow den for their honored dead.",
			full = "Beneath Jaedenar in western Felwood runs a warren the night elves once raised as a barrow den for their honored dead. The Shadow Council took it for their own, and what was meant to hold the sleeping now holds warlocks and demons, with the dreadlord Lord Banehollow ruling from its depths alongside the satyr prince Xavalis.\n\nThe paladin Trey Lightforge and the night elf Arko'narin Starshade came here searching for signs of the Council's work. The cultists caught them both and caged them in the dark. Trey was tortured until he died. Arko'narin lived, carried out by one who broke the corrupted spirit her companion had become. That rescuer returned alone afterward, hunted down Trey's torturer Rakaiah, and killed him, then carried the paladin's remains out so they could be buried properly.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Shatter Scar Vale",
			short = "North of the Bloodvenom Falls, Shatter Scar Vale still bears the wounds of the Third War, when the Burning Legion's infernals rained down upon Felwood.",
			full = "North of the Bloodvenom Falls, Shatter Scar Vale still bears the wounds of the Third War, when the Burning Legion's infernals rained down upon Felwood. The craters they carved into the earth still smolder, and demons yet wander among the scars they left behind.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Shrine of the Deceiver",
			short = "At Jaedenar in Felwood stands the Shrine of the Deceiver, a barrow den corrupted to honor Kil'jaeden, the Burning Legion's deceiving lord.",
			full = "At Jaedenar in Felwood stands the Shrine of the Deceiver, a barrow den corrupted to honor Kil'jaeden, the Burning Legion's deceiving lord. The Shadow Council has filled it with its warlocks, and it remains a dangerous place for anyone unprepared to face them.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Talonbranch Glade",
			short = "Talonbranch Glade stands in the northern reaches of Felwood, an outpost the night elves once held alone.",
			full = "Talonbranch Glade stands in the northern reaches of Felwood, an outpost the night elves once held alone. Gilnean worgen were sent to help defend it against the Bilgewater Cartel's goblins, and in that fight the glade became a Gilnean stronghold in all but name.\n\nThose who hold it now do not call themselves a garrison. They call themselves a pack, the glade their home, and their leader, Denmother Ulrica, a mother to them rather than a commander. By her own account, several of the pack, herself perhaps included, have worn the curse since Velinde Starsong first summoned the worgen with the Scythe of Elune.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.",
			full = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under the corruptive influence of the Burning Legion. However, amidst the chaos and the madness, the Timbermaw tribe escaped the darkness that had fallen on Kalimdor. In the safety of Timbermaw Hold, the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. The corruption had sunk in deep, so that even long after Illidan had consumed the source of the corruption, a powerful warlock artifact called the Skull of Gul'dan, and vanquished the demons' leader Tichondrius, the taint on the woods still remained.\n\nThe furbolgs wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw tribe are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern Felwood and prove themselves as friends of the Timbermaw tribe will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing/resurrection knowledge with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Un'Goro Crater: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Fire Plume Ridge",
			short = "The mountain at the heart of Un'Goro Crater burns without ending.",
			full = "The mountain at the heart of Un'Goro Crater burns without ending. Lava threads down its slopes, and fire elementals walk where the rock has gone molten, born of shallow veins of magma that run beneath the crater floor, feeding the steam pools and geysers that hiss across the basin. Where the jungle meets this scorched earth, the border is unmistakable: green giving way to blackened stone and heat that shimmers the air.\n\nAt the ridge's peak, within a cave, lives Blazerunner, the strongest fire elemental in Un'Goro. Lesser spirits of flame speak of burning here for centuries beyond counting, guttering low and flaring back to life again and again, a cycle none of them can explain.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Fungal Rock",
			short = "In the northeastern wall of Un'Goro Crater opens a cavern known as Fungal Rock. Ghost mushrooms grow thick in its dark, and gorillas have made it their home.",
			full = "In the northeastern wall of Un'Goro Crater opens a cavern known as Fungal Rock. Ghost mushrooms grow thick in its dark, and gorillas have made it their home. Outside the entrance lies a pool fed by a waterfall, still and quiet beneath the stone.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Golakka Hot Springs",
			short = "The pools of Golakka steam in the shadow of the crater's volcano, fed by heat rising from beneath Fire Plume Ridge.",
			full = "The pools of Golakka steam in the shadow of the crater's volcano, fed by heat rising from beneath Fire Plume Ridge. Geysers burst along the shore, and Steaming Fury elementals prowl the banks, born of that same restless heat.\n\nThe link between the springs and the ridge once drew Krakle to study what fed the geysers their fire, before the search carried Krakle onward to Marshal's Stand, the question left unanswered.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Ironstone Plateau",
			short = "Bare rock rises along the northeastern wall of Un'Goro Crater at Ironstone Plateau, where young pterrordax find their footing away from the crater's fiercer predators.",
			full = "Bare rock rises along the northeastern wall of Un'Goro Crater at Ironstone Plateau, where young pterrordax find their footing away from the crater's fiercer predators. Few monsters trouble the stony ground here, leaving it unusually quiet for the crater.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Lakkari Tar Pits",
			short = "The tar pits lie in northern Un'Goro Crater, south of Marshal's Refuge, black and thick and reeking. The bones of hundreds of beasts jut through the crust, wanderers the tar swallowed and never released.",
			full = "The tar pits lie in northern Un'Goro Crater, south of Marshal's Refuge, black and thick and reeking. The bones of hundreds of beasts jut through the crust, wanderers the tar swallowed and never released. Anything caught in its grip is dragged down and slowed to a crawl, easy prey for the scavengers waiting at the edges. Tar beasts have made their home in the muck itself. At the bottom, beyond easy reach, grow tarblossom flowers, prized for their beauty and durability, and rare precisely because so few will wade in far enough to cut them free.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Marshal's Refuge",
			short = "Marshal's Refuge sits at the northern edge of Un'Goro Crater, a foothold clawed out by the Marshal Expeditions when the crater proved fiercer than Williden and Hol'anyee Marshal had reckoned.",
			full = "Marshal's Refuge sits at the northern edge of Un'Goro Crater, a foothold clawed out by the Marshal Expeditions when the crater proved fiercer than Williden and Hol'anyee Marshal had reckoned. Their base camps below were overrun by the savage beasts of Un'Goro, and what remained of the expedition fled upward to this high ground to survive.\n\nThe refuge's peace ended when the Stone Guardians came in force, pouring into the cave at the back of the camp and claiming it as their own. In the fighting the kodo Dadanga was killed. The expedition could not hold against them and abandoned the refuge, retreating southeast to raise Marshal's Stand instead.\n\nDadanga was laid to rest outside the cavern mouth, in a grave that still bears her name. The cave itself remains thick with power crystals, and the Stone Guardians linger there still, watchful over it, quick to turn on anyone who disturbs what they now guard.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "Marshlands",
			short = "The Marshlands spread across the southeastern reach of Un'Goro Crater, the first ground most travelers cross when climbing down from Tanaris, since any other way in tends to end badly.",
			full = "The Marshlands spread across the southeastern reach of Un'Goro Crater, the first ground most travelers cross when climbing down from Tanaris, since any other way in tends to end badly. Raptors range the reeds in numbers, some plain, some venomous, and when the Primalists loosed elementals upon the crater, that power settled into the marsh and worked its way into the raptors living there, leaving them changed by a violence not their own.\n\nOn a mound above the water, Torwa Pathfinder and Garl Stormclaw keep a small foothold, having come to it by canoe from elsewhere in the crater.\n\nThe marsh holds one thing found nowhere else in Un'Goro: blue power crystals, formed in no other ground but this.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
			name = "Slithering Scar",
			short = "The Slithering Scar spreads across southern Un'Goro Crater, home to the Gorishi sect of the silithid. Deep within, the Gorishi tend a colossus still growing in the dark, meant one day to be loosed upon the crater above.",
			full = "The Slithering Scar spreads across southern Un'Goro Crater, home to the Gorishi sect of the silithid. Deep within, the Gorishi tend a colossus still growing in the dark, meant one day to be loosed upon the crater above.\n\nThe hive once had a queen, summoned by disturbing the Gorishi Silithid Crystal kept within.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "Terror Run",
			short = "The Primalists' assault brought elementals into Terror Run, west of the Slithering Scar, and their touch never left. The beasts here still carry that imbuement.",
			full = "The Primalists' assault brought elementals into Terror Run, west of the Slithering Scar, and their touch never left. The beasts here still carry that imbuement. Among its stones, red power crystals form nowhere else in the crater.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
	},
	-- Moonglade: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lake Elune'ara",
			short = "Lake Elune'ara's waters lie crystal-clear at the heart of Moonglade.",
			full = "Lake Elune'ara's waters lie crystal-clear at the heart of Moonglade. Beneath them sleeps the mad demigod Omen, defeated centuries ago but never destroyed, only laid to rest under the still surface, where he remains to this day.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Nighthaven",
			short = "Nighthaven rests on the shores of Lake Elune'ara, its stone and timber halls built in the old night elvish way, twin moonwells glowing beside its streets.",
			full = "Nighthaven rests on the shores of Lake Elune'ara, its stone and timber halls built in the old night elvish way, twin moonwells glowing beside its streets. It is a druid's village before it is anything else, home to the Cenarion Circle, and it keeps itself apart from the wider world. Few outsiders ever see it.\n\nOnce a year that changes. During the Lunar Festival, Nighthaven opens its gates to Alliance and Horde alike, who come to celebrate Elune's power with fireworks lighting the lake and sky.\n\nThe village has not always known peace. It was here that the Nightmare took the dragon Eranikus, and nightmare creatures fell upon Nighthaven in force. The Keeper Remulos stood against him, but it was Tyrande Whisperwind who ended it, calling down the light of Elune to burn the corruption from Eranikus and cleanse him where he stood.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Shrine of Remulos",
			short = "The Shrine of Remulos stands in western Moonglade, raised in honor of Keeper Remulos. Within its grounds dwells the night elf Tajarri, who guides young druids seeking the aquatic form.",
			full = "The Shrine of Remulos stands in western Moonglade, raised in honor of Keeper Remulos. Within its grounds dwells the night elf Tajarri, who guides young druids seeking the aquatic form.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Stormrage Barrow Dens",
			short = "Beneath the quiet hills of Moonglade lie the barrow dens, where night elf druids have long entered the sleep that carries them into the Emerald Dream.",
			full = "Beneath the quiet hills of Moonglade lie the barrow dens, where night elf druids have long entered the sleep that carries them into the Emerald Dream. The place takes its name from Malfurion Stormrage, who slumbered here longer than any other. Clintar Dreamwalker sleeps here now, in the stillness the dens were made for.\n\nMalfurion returned here after the Third War, seeking only to meditate as the Cenarion Circle weighed the planting of a second World Tree. Tyrande Whisperwind came looking for him and found him fallen into a coma, his body unmoving in the den where he had lain down to think. No one could wake him, and in the end the Circle chose to leave him exactly where he had fallen, reasoning that his wandering spirit would only find its way home if his body stayed in the place it had left. For years the Sisterhood of Elune and the Circle kept careful watch over him there, until the Nightmare came at last and one of the dens was overrun by its creatures.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.",
			full = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under the corruptive influence of the Burning Legion. However, amidst the chaos and the madness, the Timbermaw tribe escaped the darkness that had fallen on Kalimdor. In the safety of Timbermaw Hold, the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. The corruption had sunk in deep, so that even long after Illidan had consumed the source of the corruption, a powerful warlock artifact called the Skull of Gul'dan, and vanquished the demons' leader Tichondrius, the taint on the woods still remained.\n\nThe furbolgs wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw tribe are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern Felwood and prove themselves as friends of the Timbermaw tribe will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing/resurrection knowledge with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Bones of Grakkarond",
			short = "In central Silithus lie the bones of Grakkarond, a bronze dragon slain by Ossirian the Unscarred during the War of the Shifting Sands.",
			full = "In central Silithus lie the bones of Grakkarond, a bronze dragon slain by Ossirian the Unscarred during the War of the Shifting Sands. The remains rise from the sand, ribs and skull half-buried, vast enough to mark the place from afar. The Anubisath hold these bones sacred, a monument to the dragon's fall beneath that ancient war.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Bronzebeard Encampment",
			short = "The Bronzebeard Encampment stood in southern Silithus, east of the Scarab Wall, until Sargeras's assault at the end of the Burning Legion's third invasion destroyed it, along with nearly every other settlement in that land.",
			full = "The Bronzebeard Encampment stood in southern Silithus, east of the Scarab Wall, until Sargeras's assault at the end of the Burning Legion's third invasion destroyed it, along with nearly every other settlement in that land.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Cenarion Hold",
			short = "Cenarion Hold stands where an ancient night elven settlement once stood, and it is the Cenarion Circle's answer to what lies buried beneath Silithus.",
			full = "Cenarion Hold stands where an ancient night elven settlement once stood, and it is the Cenarion Circle's answer to what lies buried beneath Silithus. After the War of the Shifting Sands, the druids raised the Hold to keep watch over ground that could not be trusted to stay quiet: somewhere beneath the sands the Old God C'Thun lies imprisoned, and its silithid broods have not stopped testing the seal.\n\nThe Hold is reached only by a hard climb, the track winding up out of Un'Goro Crater and switching back on itself along the cliffs before it opens into Silithus. Few travelers make that climb without purpose, and the merchants who keep shop within the walls know it -- trade is thin this far from anywhere, and they are glad of anyone who comes through with coin to spend.\n\nIt is one of the largest gatherings of druids outside Moonglade itself, a garrison built not for conquest but for containment, holding a line against something that was buried, not destroyed.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "Crystal Vale",
			short = "In the far northwestern corner of Silithus lies a vale of stone and crystal, where earth and air elementals move restlessly among rich seams of thorium.",
			full = "In the far northwestern corner of Silithus lies a vale of stone and crystal, where earth and air elementals move restlessly among rich seams of thorium. The Ravaged Twilight Camp sits within it, a scar left by those who once worked or warred there.\n\nThe elementals of the vale do not settle. They churn and rumble, chattering in tongues of wind and rock, telling over old griefs, the pains of Azeroth stretching back centuries and reaching into more recent days. To stand among them is to hear a restlessness that has no end, a sign that the spirits of earth and air here have not been quieted, and that whatever work might calm them remains undone.\n\nIt was in this vale that Thunderaan, the Windseeker, was once called forth and bound into a blade of storm and fury, a summoning that drew on the raw temper of the air itself.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "Hive'Ashi",
			short = "Hive'Ashi stood in northern Silithus, its silithid swarming out to infest the nearby Swarming Pillar.",
			full = "Hive'Ashi stood in northern Silithus, its silithid swarming out to infest the nearby Swarming Pillar. The hive was destroyed when Sargeras struck at Silithus during the third invasion of the Burning Legion, seeking to destroy Azeroth itself.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Hive'Regal",
			short = "Hive'Regal was a silithid nest in southern Silithus. When Sargeras turned his strength upon Azeroth through that land, the fires of that ruin swallowed most of the hive.",
			full = "Hive'Regal was a silithid nest in southern Silithus. When Sargeras turned his strength upon Azeroth through that land, the fires of that ruin swallowed most of the hive. Only a fragment of it remains today.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Hive'Zora",
			short = "Hive'Zora was a silithid nest burrowed into the sands of western Silithus.",
			full = "Hive'Zora was a silithid nest burrowed into the sands of western Silithus.\n\nIt was destroyed when Sargeras turned the Burning Legion's third invasion against Silithus, trying to end Azeroth itself. Only the broken hive remains.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "Ortell's Hideout",
			short = "Ortell's Hideout is a small cave in southeastern Silithus, home to Hermit Ortell. The mountains around it shifted when Sargeras tore through Silithus, and the cave's entrance vanished, likely buried beneath an avalanche.",
			full = "Ortell's Hideout is a small cave in southeastern Silithus, home to Hermit Ortell. The mountains around it shifted when Sargeras tore through Silithus, and the cave's entrance vanished, likely buried beneath an avalanche.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Ravaged Twilight Camp",
			short = "The Ravaged Twilight Camp lies in the Crystal Vale, in northwestern Silithus, already broken when Highlord Demitrian claimed it as his own.",
			full = "The Ravaged Twilight Camp lies in the Crystal Vale, in northwestern Silithus, already broken when Highlord Demitrian claimed it as his own. The cultists' own records, in State of the Cult, Volume 127, made note of it. The camp itself did not endure what came after, but Demitrian remains.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "Scarab Dais",
			short = "The Scarab Gong stands at the Scarab Dais, northwest of the Scarab Wall beyond Ahn'Qiraj, in southern Silithus.",
			full = "The Scarab Gong stands at the Scarab Dais, northwest of the Scarab Wall beyond Ahn'Qiraj, in southern Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Scarab Wall",
			short = "The Scarab Wall stands at the southern edge of Silithus, a hundred feet of sandstone rising from the desert floor and, above that height, a barrier of bronze dragonflight magic reaching many times taller still.",
			full = "The Scarab Wall stands at the southern edge of Silithus, a hundred feet of sandstone rising from the desert floor and, above that height, a barrier of bronze dragonflight magic reaching many times taller still. It was raised at the end of the War of the Shifting Sands, when night elves and bronze dragons joined their strength to seal away what lay beyond. Together they named it Irana'ethil, Shield against the Shadow. The wall does not merely mark a boundary between the silithid-held sands and the ruins of Ahn'Qiraj beyond it -- it holds something in. C'Thun and its crawling brood are sealed behind that stone and that light, kept from the world by a working that has never fully faded.\n\nTo stand before it is to stand at the edge of a containment centuries old, sand given shape and shape given purpose, the last barrier between the desert and whatever still moves in the dark beneath Ahn'Qiraj.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Southwind Village",
			short = "Southwind Village stood as a night elven base in Silithus, until the War of the Shifting Sands brought the qiraji swarming out of the sands against it.",
			full = "Southwind Village stood as a night elven base in Silithus, until the War of the Shifting Sands brought the qiraji swarming out of the sands against it.\n\nFandral Staghelm's son, Valstann, led a detachment sent to hold the village. His troops were slaughtered beneath the qiraji tide, the village fell, and Valstann himself was taken alive by General Rajaxx. What became of him afterward, no one at Southwind ever learned.\n\nFor centuries afterward the ruins lay given over to the silithid that infested the region, and to worse things. The dead of that first sundering did not rest: the spirits of druids and Sentinels who fell defending the village wandered the wreckage still, bound to the place by the horror of their deaths, and among them walked the Shade of Ambermoon, who led the tormented dead through the ruins she had died in.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Staghelm Point",
			short = "A night elven tower once crowned the peak in northeastern Silithus. When Sargeras struck at Azeroth, the fire that swept the region reduced most of its settlements to ash outright.",
			full = "A night elven tower once crowned the peak in northeastern Silithus. When Sargeras struck at Azeroth, the fire that swept the region reduced most of its settlements to ash outright. Staghelm Point endured, battered but standing, when nearly everything around it did not. That mercy came at a cost: Ralo'shan the Eternal Watcher, who had kept the tower and shared its skies with a bronze drake of Nozdormu's brood, was killed in the devastation.\n\nThe Alliance raised a base along the road below the ruin, and the Cenarion Circle came after to take up the work of rebuilding what fire had left standing. They planted and blessed the Sentinel Tree atop the point, a living memorial to Ralo'shan and the others who fell defending the tower. The ground here is unstable and the work is slow, but what remains of Staghelm Point still stands, unlike so much else in Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Swarming Pillar",
			short = "The Swarming Pillar rises south of Cenarion Hold, a peak riddled with silithid tunnels, one hive among the countless that honeycomb the sands of Silithus.",
			full = "The Swarming Pillar rises south of Cenarion Hold, a peak riddled with silithid tunnels, one hive among the countless that honeycomb the sands of Silithus. It takes its name from what surrounds it always: a dense, ceaseless swarm of small silithid circling the peak like a living haze.\n\nIt was the largest of the buried hives, though never the only one. It did not survive the Burning Legion's third invasion, when Sargeras sought to destroy Azeroth through Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Twilight Base Camp",
			short = "The Twilight Base Camp stood among the scattered holdings of the Twilight's Hammer in Silithus, one of four such camps the cult kept in that barren country.",
			full = "The Twilight Base Camp stood among the scattered holdings of the Twilight's Hammer in Silithus, one of four such camps the cult kept in that barren country.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Twilight Outpost",
			short = "The Twilight Outpost sits in the far southwestern corner of Silithus, west of the Bronzebeard Encampment, near the Scarab Wall.",
			full = "The Twilight Outpost sits in the far southwestern corner of Silithus, west of the Bronzebeard Encampment, near the Scarab Wall.\n\nThe place has died once already. When Sargeras hurled the Burning Legion against Azeroth in its third invasion, the fires swept nearly every settlement in Silithus away, the original outpost among them.\n\nWhat stands here now was raised afterward by the few survivors of the Twilight's Hammer, who crept back to the same burned ground under a leader named Michiel Voidstrider. He was killed before he could rally the cult into action.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Twilight Post",
			short = "Twilight Post stood in the northwest reaches of Silithus, a waypoint far from the shelter of Cenarion Hold, northwest of the larger camp the Twilight's Hammer kept nearby.",
			full = "Twilight Post stood in the northwest reaches of Silithus, a waypoint far from the shelter of Cenarion Hold, northwest of the larger camp the Twilight's Hammer kept nearby.\n\nIt did not last. When Sargeras turned his hand against Azeroth in the third invasion of the Burning Legion, the settlements of Silithus were swept away, and the Twilight Post was destroyed with them.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Twilight's Run",
			short = "At the base of Staghelm Point, in the northern reaches of Silithus, the ground opens into a cave the Twilight's Hammer Cult has claimed for its own.",
			full = "At the base of Staghelm Point, in the northern reaches of Silithus, the ground opens into a cave the Twilight's Hammer Cult has claimed for its own. Its members gather in the dark beneath the mountain, unseen by most who cross the sands above, working whatever purpose the cult holds sacred in a place so far from prying eyes.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Valor's Rest",
			short = "Valor's Rest is one of only two places in Silithus that survived Sargeras' destruction of the zone, the other being the Scarab Wall.",
			full = "Valor's Rest is one of only two places in Silithus that survived Sargeras' destruction of the zone, the other being the Scarab Wall. That survival is why its graveyard matters, ground that held when the rest of the land did not.\n\nThe camp now shelters both Alliance and Horde, along with members of the Cenarion Circle who keep watch over an insect infestation that looks unsettlingly familiar to anyone who knows what the Circle watches for.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Winterspring: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Ban'Thallow Barrow Den",
			short = "The Ban'Thallow Barrow Den lies behind Starfall Village in Winterspring, tunnels once kept by the village's druids and holding blessed relics precious to Starfall's people.",
			full = "The Ban'Thallow Barrow Den lies behind Starfall Village in Winterspring, tunnels once kept by the village's druids and holding blessed relics precious to Starfall's people.\n\nThe bugs came without warning, hatching overnight from eggs no one had seen laid, swarming through the den until it was theirs. Fortune spared Starfall a worse blow, for no druids were resting inside when the infestation broke.\n\nThe few druids left could do little more than hold the swarm back from spilling into the village itself, unable to clear the den on their own.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Darkwhisper Gorge",
			short = "When Archimonde fell at the base of the World Tree, his army did not vanish with him.",
			full = "When Archimonde fell at the base of the World Tree, his army did not vanish with him. The demonic remnants of the Burning Legion's host fled the battle and took refuge in this gorge in southeastern Mount Hyjal, retreating into its shadows rather than face destruction in the open.\n\nSince then the Twilight's Hammer has claimed the gorge, using it as a place of recruitment and training. The cult has redecorated the main entrance from Winterspring to match its own grim appearance. The back way in, Darkwhisper Pass, has become the path most now use to enter.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr sits above an icy cavern in south-eastern Winterspring, its name betraying dwarven hands. The dwarf Jaron Stoneshaper raised the camp, then took a blue-feathered amulet from the cave below.",
			full = "Dun Mandarr sits above an icy cavern in south-eastern Winterspring, its name betraying dwarven hands. The dwarf Jaron Stoneshaper raised the camp, then took a blue-feathered amulet from the cave below. The moonkin would not suffer its taking, and drove him off and tore his camp apart. They hold it still.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Everlook",
			short = "Everlook stands where Winterspring's trade routes cross, a goblin post of the Steamwheedle Cartel, its laboratory tucked among the buildings.",
			full = "Everlook stands where Winterspring's trade routes cross, a goblin post of the Steamwheedle Cartel, its laboratory tucked among the buildings.\n\nIn Year 25 ADP, the Argent Dawn sent Gregor Greystone to speak for their interests before the Cartel's local governance here.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Frostfire Hot Springs",
			short = "Steam rises where it has no right to, at the western edge of Winterspring's frozen reach. The Frostfire Hot Springs bubble against the snow, heat sunk into ice that should have long swallowed it cold.",
			full = "Steam rises where it has no right to, at the western edge of Winterspring's frozen reach. The Frostfire Hot Springs bubble against the snow, heat sunk into ice that should have long swallowed it cold.\n\nDonova Snowden has camped nearby, puzzling over the cause. She suspects the springs come not from nature but from demonic interference reaching up from Darkwhisper Gorge, far to the south.\n\nThe Winterfall tribe holds the springs still, gripping hardest to the pool nearest Timbermaw Hold.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Frostsaber Rock",
			short = "Atop Frostsaber Rock in Winterspring stands Rivern Frostwind, keeper of the wintersabers.",
			full = "Atop Frostsaber Rock in Winterspring stands Rivern Frostwind, keeper of the wintersabers. He offers friendship to those of the Alliance willing to labor for him, and to those who prove themselves he teaches the old way of taming a frostsaber and riding it.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Frostwhisper Gorge",
			short = "Frostwhisper Gorge cuts through southern Winterspring, its ruins of the night elves scattered along its floor and ridges.",
			full = "Frostwhisper Gorge cuts through southern Winterspring, its ruins of the night elves scattered along its floor and ridges. Frostmaul Giants and Preservers make their home here, and among the ice above, Ice Avatars gather under Frostilicus.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "Hidden Grove",
			short = "The Hidden Grove lies sealed within its own ring of cliffs in northeastern Winterspring, reachable only through a single cave cut into the southeastern ridge; elsewhere the walls simply drop away, too sheer and dangerous to climb.",
			full = "The Hidden Grove lies sealed within its own ring of cliffs in northeastern Winterspring, reachable only through a single cave cut into the southeastern ridge; elsewhere the walls simply drop away, too sheer and dangerous to climb.\n\nWhat the grove holds now are moonkin, hostile to anything that enters their hidden glade, and few care to test that hostility.\n\nIt was not always so guarded. Before the moonkin came, the crater belonged only to a thriving population of harmless white hares.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Ice Thistle Hills",
			short = "The Ice Thistle Hills rise southeast of Everlook, a cold country of stone and windblown snow, home to the yeti who take their name from this ground.",
			full = "The Ice Thistle Hills rise southeast of Everlook, a cold country of stone and windblown snow, home to the yeti who take their name from this ground. They den in a cave that climbs some way up the slope and range through the drifts around it, thick-furred and horned, holding the hills against all comers.\n\nIcecaps grow scattered through the outdoor snow, and deep in the cave thorium veins run through the rock. Rarest of all, a black lotus is sometimes found growing at the very lip of the cave mouth.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lake Kel'Theril",
			short = "The Highborne of Kel'Theril did not rest when their city fell. Their spirits linger still upon the frozen lake and its ruined shores, tormented remnants drifting as ectoplasm.",
			full = "The Highborne of Kel'Theril did not rest when their city fell. Their spirits linger still upon the frozen lake and its ruined shores, tormented remnants drifting as ectoplasm.\n\nWhen the elements rose against Winterspring, Princess Tempestria took shape upon these icy waters, a storm given form on a lake already thick with grief.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "Mazthoril is a vast, icy cavern sunk into the earth near the heart of Winterspring, close to Lake Kel'Theril and Everlook.",
			full = "Mazthoril is a vast, icy cavern sunk into the earth near the heart of Winterspring, close to Lake Kel'Theril and Everlook. At its peak, reachable only through a portal rune set into the cavern floor, dwells its matriarch.\n\nHer name is Haleh, and she is reclusive, showing herself in her high elven form only to those who reach that high place. It was Haleh who once completed the key that opened the way into Onyxia's Lair. She commands four powerful drakes that guard the cavern in her name, and beneath them a sizable host of sorcerous spawn and young whelps. Spellmaw, the brood's chief patrol, wanders a slow circuit around a good third of the lower reaches of Winterspring. Manaclaw and Scryer stand watch over the runes at the cavern's rear, while Azurous ranges the surrounding lands watching for threats against the forces of Malygos.\n\nThe blue dragons are gone from Mazthoril now. The caverns have fallen under the control of Umbranse the Spiritspeaker.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Moon Horror Den",
			short = "The Moon Horror Den lies a short walk northeast of Everlook, a cave hollowed into the mountainside. Raging Owlbeasts make their den within, though the cave does not always hold them.",
			full = "The Moon Horror Den lies a short walk northeast of Everlook, a cave hollowed into the mountainside. Raging Owlbeasts make their den within, though the cave does not always hold them. The mountain rising above the den blocks any direct path south toward Winterfall Village, so the only way there is a long ride around.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Owl Wing Thicket",
			short = "The caves of Owl Wing Thicket lie deep in southern Winterspring, home to owlbeasts gone berserk, moontouched, and crazed.",
			full = "The caves of Owl Wing Thicket lie deep in southern Winterspring, home to owlbeasts gone berserk, moontouched, and crazed. Here the ancient Guardians of Elune speak of how the moonkin first came into the world, a tale told under the guidance of Ranshalla.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Ruins of Kel'Theril",
			short = "The Ruins of Kel'Theril lie broken on the shores of the lake that bears their name, in central Winterspring, all that remains of a great city of the night elves.",
			full = "The Ruins of Kel'Theril lie broken on the shores of the lake that bears their name, in central Winterspring, all that remains of a great city of the night elves. The Great Sundering tore the world apart and tore this place apart with it, and the Highborne who lived here did not all escape what followed. Their spirits linger still in the northern ruins, unable to rest, caught somewhere between grief and rage. One remains behind, remorseful, drawn to speak of what was lost.\n\nThey are no longer alone. High elven ghosts now walk the eastern ruins, among them Betrayed Rangers and an archmage named Maenius. To the west drift the Wretched Spectres, blood elves undone by what they became. Three kinds of elf, three ages of the same fall, haunting the same stones.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Starfall Village",
			short = "Starfall Village stands along the main road of Winterspring, the only Alliance foothold in that cold country.",
			full = "Starfall Village stands along the main road of Winterspring, the only Alliance foothold in that cold country. A night elven lodge and a smaller house make up the settlement, and nearby the ground opens into the Ban'Thallow Barrow Den. Small against the white expanse around it, it remains alone here.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.",
			full = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under the corruptive influence of the Burning Legion. However, amidst the chaos and the madness, the Timbermaw tribe escaped the darkness that had fallen on Kalimdor. In the safety of Timbermaw Hold, the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. The corruption had sunk in deep, so that even long after Illidan had consumed the source of the corruption, a powerful warlock artifact called the Skull of Gul'dan, and vanquished the demons' leader Tichondrius, the taint on the woods still remained.\n\nThe furbolgs wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw tribe are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern Felwood and prove themselves as friends of the Timbermaw tribe will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing/resurrection knowledge with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Timbermaw Post",
			short = "The camp still bears the name of the furbolgs who once held it, though no Timbermaw remains to answer to it.",
			full = "The camp still bears the name of the furbolgs who once held it, though no Timbermaw remains to answer to it. The Winterfall tribe, twisted by corruption, now hold the post in full, and it is their fires that burn there now.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Winterfall Village",
			short = "Winterfall Village houses furbolgs turned corrupted. At the top of the settlement sits a small cave, once the seat of High Chief Winterfall.",
			full = "Winterfall Village houses furbolgs turned corrupted. At the top of the settlement sits a small cave, once the seat of High Chief Winterfall. That rule has since passed to Grolnar the Berserk, who now dwells in the same cave, having taken the old chieftain's place at the head of the tribe.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Stormwind City: 3 subzones
	[1453] = {
		["champions hall"] = {
			name = "Champions' Hall",
			short = "In the south of Old Town stands the Champions' Hall, the officers' barracks of the Alliance in Stormwind City.",
			full = "In the south of Old Town stands the Champions' Hall, the officers' barracks of the Alliance in Stormwind City.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "The tram runs beneath the earth between Ironforge and Stormwind, its double tracks carrying two trains of three wagons apiece through a passage that dips, for one long stretch, beneath a subterranean lake.",
			full = "The tram runs beneath the earth between Ironforge and Stormwind, its double tracks carrying two trains of three wagons apiece through a passage that dips, for one long stretch, beneath a subterranean lake. Gnomes tend it daily, and it has never once been allowed to fail its riders.\n\nIt was built in the years after the Second War, when Stormwind lay broken and the Alliance was still young and its bonds still strong. Dwarven aid was reaching the humans too slowly for King Magni Bronzebeard's liking, and he wanted besides a way to move soldiers quickly to Stormwind's defense if the need ever came. So he turned to High Tinker Gelbin Mekkatorque, Azeroth's foremost engineer, who drafted a railway to bind the two cities together beneath the earth itself.\n\nThe tram's worth was proven in its darkest hour. When Magni was turned to stone and his daughter Moira seized Ironforge, she sealed the tram shut, cutting the dwarves off from their allies. It was through that same tunnel that King Varian Wrynn later led a strike of agents into Ironforge to break the siege and free his son.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["valley of heroes"] = {
			name = "Valley of Heroes",
			short = "A stone bridge crosses the narrow moat before Stormwind's gate, the first sight of the city that any traveler receives.",
			full = "A stone bridge crosses the narrow moat before Stormwind's gate, the first sight of the city that any traveler receives. The valley beyond is lush and green, and along its path stand five statues raised after the Second War, when Stormwind was rebuilt.\n\nThey commemorate the leadership of the Alliance Expedition that passed through the Dark Portal to seal the rift into Draenor: Kurdran Wildhammer and Archmage Khadgar on one side, Force Commander Danath Trollbane and Ranger-Captain Alleria Windrunner on the other, and at the road's end, before it splits toward the city proper, General Turalyon, who led them.\n\nSome years after the statues were raised, Alleria and Turalyon's son Arator was carried through the valley on the shoulders of a Knight of the Silver Hand, looking up at the stone face of a mother he could not remember. Alleria, far off aboard the Xenedar, sent her feelings to him through the Light. The boy looked around, smiled, and reached toward her statue. He came back to the valley again and again after that, to look at her face and know she loved him.\n\nThe valley's guards answer to General Hammond Clay, who took command after General Marcus Jonathan fell at Theramore.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Hall of Legends",
			short = "In the Valley of Strength, within Orgrimmar, stands the Hall of Legends, the officer's barracks of the Horde.",
			full = "In the Valley of Strength, within Orgrimmar, stands the Hall of Legends, the officer's barracks of the Horde.\n\nAt its center is a table where four sit in council: Chieftain Earthbind of Thunder Bluff, Advisor Willington of the Undercity, Blood Guard Hini'wana of the Darkspear Trolls, and Councilor Arial D'Anastasis of Silvermoon City. Before them lie maps of Azeroth, and beside the maps rests an open book, Military Ranks of the Horde & Alliance, its pages set with the ranks and insignia by which the Horde's warriors know one another.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Ragefire Chasm",
			short = "Beneath Orgrimmar, where the rock runs hot with buried fire, the tunnels open into a chasm no city map admits to. Troggs came up first, out of the deep lava-lit passages, calling themselves the Ragefire clan.",
			full = "Beneath Orgrimmar, where the rock runs hot with buried fire, the tunnels open into a chasm no city map admits to. Troggs came up first, out of the deep lava-lit passages, calling themselves the Ragefire clan. Magatha the Seer went down among them to offer peace, tauren to trogg, and got only violence for her trouble. It was plain enough after that there would be no talking to them, and plain too that left to breed and dig they could rise through the tunnels and break over the Horde itself.\n\nThey were not alone down there. A sect of the Shadow Council called the Searing Blade had already made the chasm its refuge, led by Taragaman the Hungerer, a felguard, Jergosh the Invoker, a warlock, and Bazzalan, a satyr. From that hiding place they plotted the Horde's ruin.\n\nWhat gave them cover was one of the Horde's own. Neeru Fireblade, who led the Burning Blade in secret, used the chasm as a killing ground, sending Thrall's loyal followers down to die there, testing whether the Searing Blade were worth keeping as allies or only worth spending. Thrall learned of it, and those sent to answer for it cut down the cultist leaders and cleared the troggs from the tunnels.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Ironforge: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "The tram runs beneath the earth between Ironforge and Stormwind, its double tracks carrying two trains of three wagons apiece through a passage that dips, for one long stretch, beneath a subterranean lake.",
			full = "The tram runs beneath the earth between Ironforge and Stormwind, its double tracks carrying two trains of three wagons apiece through a passage that dips, for one long stretch, beneath a subterranean lake. Gnomes tend it daily, and it has never once been allowed to fail its riders.\n\nIt was built in the years after the Second War, when Stormwind lay broken and the Alliance was still young and its bonds still strong. Dwarven aid was reaching the humans too slowly for King Magni Bronzebeard's liking, and he wanted besides a way to move soldiers quickly to Stormwind's defense if the need ever came. So he turned to High Tinker Gelbin Mekkatorque, Azeroth's foremost engineer, who drafted a railway to bind the two cities together beneath the earth itself.\n\nThe tram's worth was proven in its darkest hour. When Magni was turned to stone and his daughter Moira seized Ironforge, she sealed the tram shut, cutting the dwarves off from their allies. It was through that same tunnel that King Varian Wrynn later led a strike of agents into Ironforge to break the siege and free his son.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge rise from the stone of Dun Morogh long before a traveler reaches them, visible across the valley.",
			full = "The Gates of Ironforge rise from the stone of Dun Morogh long before a traveler reaches them, visible across the valley. The great ramp climbs to them from the south, lesser paths wind up from the Commons, but every road ends the same way: at doors built to be seen from miles off.\n\nPass through and the first thing to greet a visitor is not a dwarf but a statue, High King Modimus Anvilmar carved huge, standing eternal watch just inside the threshold.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
	-- Thunder Bluff: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Elder Rise",
			short = "Elder Rise sits east of the central bluff, home to the Cenarion Circle's druids and priests and to the Council of Elders who govern the tauren people.",
			full = "Elder Rise sits east of the central bluff, home to the Cenarion Circle's druids and priests and to the Council of Elders who govern the tauren people. Hamuul Runetotem, Arch Druid, resides here among his order.\n\nThe hut between the two bridges once belonged to Magatha Grimtotem, leader of the Grimtotem tribe, before her exile drove her from these heights. It stands empty now, a marker of her absence.\n\nRope bridges carry the way from Elder Rise to High Rise and Middle Rise.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Hunter Rise",
			short = "Hunter Rise stands south of the main bluff of Thunder Bluff, home to the tauren hunters, warriors, and paladins, along with the trappers, trackers, and tanners who support them.",
			full = "Hunter Rise stands south of the main bluff of Thunder Bluff, home to the tauren hunters, warriors, and paladins, along with the trappers, trackers, and tanners who support them. The Hunter's Hall and the Sunwalker Lodge anchor the rise, where such skills are taught. Rope bridges link it to the lower and high rises beyond.\n\nIt was here that Rexxar was known to return, and tauren would gather around him, begging him for advice or for stories of his travels.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Pools of Vision",
			short = "Beneath the cap of Spirit Rise, in the tunnels that fall away below Thunder Bluff, still water gathers in the dark and gives back more than a reflection.",
			full = "Beneath the cap of Spirit Rise, in the tunnels that fall away below Thunder Bluff, still water gathers in the dark and gives back more than a reflection. It was here that the balance of the land itself went wrong, when something unseen disturbed the pools until they turned dangerous. Cairne Bloodhoof would not simply drive the disturbance out. He wanted to understand what had troubled it, believing the answer might explain a wrongness spreading through Azeroth beyond his own lands. His caution was mistaken for weakness. Where Cairne hesitated, the gladiator known as Lo'Gosh fought the elemental at the pools and cleansed them, and Magatha Grimtotem seized on that victory, holding it up beside Cairne's restraint to make the high chieftain look powerless in his own territory.\n\nThe Forsaken have since made the tunnels their own foothold here, and the pools remain still and fishable.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Spirit Rise",
			short = "Spirit Rise sits northwest of Thunder Bluff's central mesa, the home of shamanistic study. The Skychaser tribe holds great influence here.",
			full = "Spirit Rise sits northwest of Thunder Bluff's central mesa, the home of shamanistic study. The Skychaser tribe holds great influence here.\n\nBeneath the surface lie the Pools of Vision, their waters wrapped in rising steam. Rope bridges connect Spirit Rise down to the lower and middle rises.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Cenarion Enclave",
			short = "Within the northwest reaches of Darnassus, ringed by oaks and ashes, stands a grove where the city's druids keep their circle.",
			full = "Within the northwest reaches of Darnassus, ringed by oaks and ashes, stands a grove where the city's druids keep their circle. Every tree here bears runes worked directly into the living bark, and at the heart of the grove a handful of structures rise from wood and shaped stone alike, the traditional meeting place for druidic convocations. The greatest of these buildings, grown as much as built, is the residence of Archdruid Fandral Staghelm, who leads his followers and kin from its boughs.\n\nThe grove serves purposes beyond the druids' own councils. In the easternmost tree, Darnassus's hunters come to hone their craft. At the foot of the great tree itself, riders learn the skill and means to master nightsabers, the great cats that carry the city's warriors and messengers alike. And hidden beneath the westernmost bough, reachable only by those who already know the way, a secretive guild of rogues keeps its quarters out of sight of the druids overhead.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Craftsmen's Terrace",
			short = "The Craftsmen's Terrace lies in the north of Darnassus, given over to the makers and traders who keep the city clothed, armed, and fed, with one of the city's inns open to travelers here.",
			full = "The Craftsmen's Terrace lies in the north of Darnassus, given over to the makers and traders who keep the city clothed, armed, and fed, with one of the city's inns open to travelers here.\n\nWithin its halls stands an embassy of the Argent Dawn, a sign of the alliance struck between the night elves and that order in its war against the undead scourge.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Temple Gardens",
			short = "The Temple Gardens lie at the heart of Darnassus, holding the water, walkways, and small islands around which the city is built, named for the Temple of the Moon that stands just to the south.",
			full = "The Temple Gardens lie at the heart of Darnassus, holding the water, walkways, and small islands around which the city is built, named for the Temple of the Moon that stands just to the south. Bridges connect the gardens to the Cenarion Enclave, to the Craftsmen's, Warrior's, and Tradesmen's Terraces, and to the temple itself, so that every path through the city seems to pass this quiet center. A portal at the western edge leads down to Rut'theran Village at the foot of the World Tree.\n\nIt is a place built for stillness, water and stone beneath the long shadow of the temple, the ground a city keeps at its center so its people always have somewhere calm to return to.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Tradesmen's Terrace",
			short = "The Tradesmen's Terrace lies in the southern reaches of Darnassus, the center of the city's commerce, where shopkeepers and vendors gather around the auction house.",
			full = "The Tradesmen's Terrace lies in the southern reaches of Darnassus, the center of the city's commerce, where shopkeepers and vendors gather around the auction house. It opens north toward the Warrior's Terrace, and west toward the Temple of the Moon and the Temple Gardens.\n\nIts buildings are built of wood, in the manner of the night elves, and when Teldrassil burned, the terrace caught quickly, consumed almost at once.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Warrior's Terrace",
			short = "The Warrior's Terrace holds the eastern gate of Darnassus, where the city opens onto Teldrassil, and it is here that the night elves keep their strength close to the door.",
			full = "The Warrior's Terrace holds the eastern gate of Darnassus, where the city opens onto Teldrassil, and it is here that the night elves keep their strength close to the door. Sentinels mounted on nightsabers watch the threshold, and within the terrace the warrior trainers and battlemasters drill those who take up arms in the city's name, with target ranges and dueling grounds worn smooth by generations of practice. Smiths, too, keep their forges near the training yards, so that a warrior might arm and test themselves in the same breath.\n\nIt is a place built for readiness rather than ceremony, its purpose plain in every corner: to be the wall behind the gate, the last stretch of ground an enemy would cross before reaching the heart of Darnassus.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Undercity: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "The palace of Lordaeron still stands above the ruin, its gardens broken, its courtyard empty of the crowds that once filled it.",
			full = "The palace of Lordaeron still stands above the ruin, its gardens broken, its courtyard empty of the crowds that once filled it. Here Arthas Menethil returned from Northrend and slew his own father, King Terenas, before opening the gates to the Scourge and letting them put the city's people to the sword. Those who linger in the courtyard say they can still hear it: hushed voices before the killing, bells in the entryway, a cheer for the returning prince, murmurs from the throne room, and beneath it all Arthas's words after the deed was done, promising a new order risen from the ashes of the old. Those who can see beyond the veil say the citizens themselves still walk there, unaware they are dead.\n\nSylvanas Windrunner later turned on her own allies, the very forces she had fought beside to break the dreadlords holding the city, and claimed the ruin for herself. Beneath its stones now lies the Undercity, the buried capital of the Forsaken.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
}
